const PreparedBlockingRpcLifecycle = enum {
    pristine,
    prepared,
    executing,
    terminal,
};

/// Final-address owner for one encoded blocking RPC request. Preparation owns the complete frame
/// without consuming the Client request ID or touching the wire. Execute consumes that ID once and
/// settles this backing on every outcome; abort settles it without I/O.
const PreparedBlockingRpc = struct {
    self_addr: usize = 0,
    incarnation: u64 = 0,
    client_addr: usize = 0,
    request_id: u64 = 0,
    frame_digest: u64 = 0,
    frame: []u8 = &.{},
    allocator: std.mem.Allocator = undefined,
    lifecycle: PreparedBlockingRpcLifecycle = .pristine,

    fn validFor(self: *const PreparedBlockingRpc, client: *const Client) bool {
        return self.self_addr == @intFromPtr(self) and
            self.incarnation != 0 and
            self.client_addr == @intFromPtr(client) and
            self.request_id != 0 and
            self.frame_digest != 0 and
            self.frame.len >= protocol.header_size and
            self.lifecycle == .prepared;
    }

    fn frameIntact(self: *const PreparedBlockingRpc) bool {
        var digest = std.hash.Wyhash.hash(0, self.frame);
        if (digest == 0) digest = 1;
        return digest == self.frame_digest;
    }

    fn reusableTerminalFor(self: *const PreparedBlockingRpc, client: *const Client) bool {
        return preparedLifecycleRawValid(self) and self.self_addr == @intFromPtr(self) and
            self.incarnation != 0 and self.client_addr == 0 and self.request_id != 0 and
            self.frame_digest == 0 and self.frame.len == 0 and
            std.meta.eql(self.allocator, client.allocator) and self.lifecycle == .terminal;
    }

    fn settle(self: *PreparedBlockingRpc) void {
        const allocator = self.allocator;
        const frame = self.frame;
        self.settleCaptured(allocator, frame);
    }

    /// Callback-safe settlement consumes only the descriptor captured while the prepared owner
    /// was authenticated. The storage is tombstoned before allocator re-entry and is never read
    /// again to decide what to free.
    fn settleCaptured(
        self: *PreparedBlockingRpc,
        allocator: std.mem.Allocator,
        frame: []u8,
    ) void {
        self.frame = &.{};
        self.client_addr = 0;
        self.frame_digest = 0;
        self.lifecycle = .terminal;
        allocator.free(frame);
    }
};

/// Opaque final-address storage for one prepared blocking RPC. Callers can embed the storage but
/// cannot inspect or mutate Client's request-frame authority as a typed aggregate; only the
/// Client methods below may interpret these bytes.
pub const PreparedBlockingRpcStorage = struct {
    bytes: [@sizeOf(PreparedBlockingRpc)]u8 align(@alignOf(PreparedBlockingRpc)) =
        [_]u8{0} ** @sizeOf(PreparedBlockingRpc),
};

pub const PreparedRequestWireProgress = enum(u8) {
    request_zero_clean,
    prior_pending_ambiguous,
    request_maybe_written,
};

const PreparedRequestExecutionLeaseLifecycle = enum(u8) {
    pristine,
    active,
};

const PreparedRequestExecutionFenceMode = enum(u8) {
    unbound,
    acquired,
    upgraded_shared,
};

/// Caller-final lease that keeps the existing Client mutation fence held across the post-flush
/// registry revalidation and the first prepared-request write. Client is the only producer and
/// transition authority; callers may only pass the exact final address back to Client methods.
pub const PreparedRequestExecutionLease = struct {
    self_addr: usize = 0,
    client_addr: usize = 0,
    storage_addr: usize = 0,
    identity: PreparedBlockingRpcIdentity = std.mem.zeroes(PreparedBlockingRpcIdentity),
    allocator_ptr: usize = 0,
    allocator_vtable: usize = 0,
    fd: c.fd_t = -1,
    operation_fence_addr: usize = 0,
    operation_fence_generation: u64 = 0,
    operation_fence_incarnation: u64 = 0,
    operation_fence_lease_identity: u64 = 0,
    poison_capture_addr: usize = 0,
    poison_prepared_addr: usize = 0,
    poison_timestamp_ns: i128 = 0,
    poison_controller_generation: u64 = 0,
    poison_source_site_raw: u8 = 0,
    poison_allocator_source_site_raw: u8 = 0,
    ownership_raw: u8 = 0,
    io_mode_raw: u8 = 0,
    progress: PreparedRequestWireProgress = .request_zero_clean,
    lifecycle: PreparedRequestExecutionLeaseLifecycle = .pristine,
    fence_held: u8 = 0,
    fence_mode: PreparedRequestExecutionFenceMode = .unbound,
    cleanup_active: u8 = 0,
    response_read_started: u8 = 0,
    seal: u64 = 0,

    pub fn pristineExact(self: *const @This()) bool {
        if (!preparedExecutionLeaseRawValid(self)) return false;
        return self.self_addr == 0 and self.client_addr == 0 and self.storage_addr == 0 and
            std.meta.eql(self.identity, std.mem.zeroes(PreparedBlockingRpcIdentity)) and
            self.allocator_ptr == 0 and self.allocator_vtable == 0 and
            self.fd == -1 and self.operation_fence_addr == 0 and
            self.operation_fence_generation == 0 and self.operation_fence_incarnation == 0 and
            self.operation_fence_lease_identity == 0 and self.poison_capture_addr == 0 and
            self.poison_prepared_addr == 0 and self.poison_timestamp_ns == 0 and
            self.poison_controller_generation == 0 and self.poison_source_site_raw == 0 and
            self.poison_allocator_source_site_raw == 0 and
            self.ownership_raw == 0 and self.io_mode_raw == 0 and
            self.progress == .request_zero_clean and self.lifecycle == .pristine and
            self.fence_held == 0 and self.fence_mode == .unbound and
            self.cleanup_active == 0 and self.response_read_started == 0 and self.seal == 0;
    }

    pub fn wireProgress(self: *const @This()) ?PreparedRequestWireProgress {
        if (!preparedExecutionLeaseRawValid(self) or self.self_addr != @intFromPtr(self) or
            self.lifecycle != .active or self.seal != preparedExecutionLeaseSeal(self)) return null;
        return self.progress;
    }
};

fn preparedExecutionLeaseSeal(lease: *const PreparedRequestExecutionLease) u64 {
    var hash = std.hash.Wyhash.init(0xB303);
    inline for (.{
        lease.self_addr,
        lease.client_addr,
        lease.storage_addr,
        lease.identity.request_id,
        lease.identity.frame_digest,
        lease.identity.descriptor.storage_addr,
        lease.identity.descriptor.prepared_incarnation,
        lease.identity.descriptor.client_addr,
        lease.identity.descriptor.request_id,
        lease.identity.descriptor.request_digest,
        lease.identity.descriptor.frame_addr,
        lease.identity.descriptor.frame_len,
        lease.identity.descriptor.allocator_ptr,
        lease.identity.descriptor.allocator_vtable,
        lease.allocator_ptr,
        lease.allocator_vtable,
        lease.fd,
        lease.operation_fence_addr,
        lease.operation_fence_generation,
        lease.operation_fence_incarnation,
        lease.operation_fence_lease_identity,
        lease.poison_capture_addr,
        lease.poison_prepared_addr,
        lease.poison_timestamp_ns,
        lease.poison_controller_generation,
        lease.poison_source_site_raw,
        lease.poison_allocator_source_site_raw,
        lease.ownership_raw,
        lease.io_mode_raw,
        @as(usize, @intFromEnum(lease.progress)),
        @as(usize, @intFromEnum(lease.lifecycle)),
        @as(usize, lease.fence_held),
        @as(usize, @intFromEnum(lease.fence_mode)),
        @as(usize, lease.cleanup_active),
        @as(usize, lease.response_read_started),
    }) |value| hash.update(std.mem.asBytes(&value));
    const seal = hash.final();
    return if (seal == 0) 1 else seal;
}

fn preparedExecutionLeaseRawValid(lease: *const PreparedRequestExecutionLease) bool {
    const progress_raw = @as(*const u8, @ptrCast(&lease.progress)).*;
    const lifecycle_raw = @as(*const u8, @ptrCast(&lease.lifecycle)).*;
    const fence_mode_raw = @as(*const u8, @ptrCast(&lease.fence_mode)).*;
    return progress_raw <= @intFromEnum(PreparedRequestWireProgress.request_maybe_written) and
        lifecycle_raw <= @intFromEnum(PreparedRequestExecutionLeaseLifecycle.active) and
        fence_mode_raw <= @intFromEnum(PreparedRequestExecutionFenceMode.upgraded_shared) and
        lease.fence_held <= 1 and lease.cleanup_active <= 1 and lease.response_read_started <= 1;
}

fn preparedExecutionFenceLeaseIdentity(
    client_addr: usize,
    fence_addr: usize,
    generation: u64,
    incarnation: u64,
    lease_addr: usize,
) u64 {
    if (fence_addr == 0) return 0;
    var hash = std.hash.Wyhash.init(0xB303_FEC3);
    inline for (.{ client_addr, fence_addr, generation, incarnation, lease_addr }) |value|
        hash.update(std.mem.asBytes(&value));
    const identity = hash.final();
    return if (identity == 0) 1 else identity;
}

const PreparedExecutionWriteResult = union(enum) {
    interrupted,
    would_block,
    zero,
    failed,
    written: usize,
};

const PreparedExecutionWriteOps = struct {
    context: ?*anyopaque = null,
    writeFn: *const fn (?*anyopaque, c.fd_t, []const u8) PreparedExecutionWriteResult,

    const posix_ops: @This() = .{ .writeFn = posixWrite };

    fn posixWrite(_: ?*anyopaque, fd: c.fd_t, bytes: []const u8) PreparedExecutionWriteResult {
        const rc = c.write(fd, bytes.ptr, bytes.len);
        if (rc < 0) return switch (posix.errno(rc)) {
            .INTR => .interrupted,
            .AGAIN => .would_block,
            else => .failed,
        };
        if (rc == 0) return .zero;
        return .{ .written = @intCast(rc) };
    }
};

pub const PreparedBlockingRpcIdentity = struct {
    request_id: u64,
    frame_digest: u64,
    descriptor: prepared_request_authority.PreparedDescriptor,
};

fn preparedLifecycleRawValid(prepared: *const PreparedBlockingRpc) bool {
    const raw = @as(*const u8, @ptrCast(&prepared.lifecycle)).*;
    return raw <= @intFromEnum(PreparedBlockingRpcLifecycle.terminal);
}

fn preparedDescriptor(
    prepared: *const PreparedBlockingRpc,
    storage: *const PreparedBlockingRpcStorage,
) prepared_request_authority.PreparedDescriptor {
    return .{
        .storage_addr = @intFromPtr(storage),
        .prepared_incarnation = prepared.incarnation,
        .client_addr = prepared.client_addr,
        .request_id = prepared.request_id,
        .request_digest = prepared.frame_digest,
        .frame_addr = @intFromPtr(prepared.frame.ptr),
        .frame_len = prepared.frame.len,
        .allocator_ptr = @intFromPtr(prepared.allocator.ptr),
        .allocator_vtable = @intFromPtr(prepared.allocator.vtable),
    };
}

/// Scalar-only comparison. It must remain safe before frame hashing or allocator invocation when
/// opaque storage bytes have been restored or corrupted at the same address.
fn preparedDescriptorRawMatches(
    prepared: *const PreparedBlockingRpc,
    storage: *const PreparedBlockingRpcStorage,
    expected: prepared_request_authority.PreparedDescriptor,
) bool {
    return preparedLifecycleRawValid(prepared) and expected.valid() and
        preparedDescriptor(prepared, storage).matches(expected);
}

comptime {
    if (@sizeOf(PreparedBlockingRpcStorage) != @sizeOf(PreparedBlockingRpc) or
        @alignOf(PreparedBlockingRpcStorage) != @alignOf(PreparedBlockingRpc))
        @compileError("opaque prepared RPC storage must exactly preserve backing layout");
}

var prepared_rpc_issuer: std.atomic.Value(u64) = .init(1);

fn issuePreparedRpcIncarnation() error{OutOfMemory}!u64 {
    var observed = prepared_rpc_issuer.load(.acquire);
    while (true) {
        if (observed == 0 or observed == std.math.maxInt(u64)) return error.OutOfMemory;
        if (prepared_rpc_issuer.cmpxchgWeak(observed, observed + 1, .acq_rel, .acquire)) |actual| {
            observed = actual;
            continue;
        }
        return observed;
    }
}

