        try testing.expectError(error.ConnectionClosed, client.readStreamBatch(7));
    }
}

fn endpointError(err: posix.E) ClientError {
    return switch (classifyConnectErrno(err)) {
        .absent => error.EndpointAbsent,
        .denied, .other => error.EndpointDenied,
        .transient => error.EndpointTransient,
    };
}

fn deadlineConnectError(err: client_deadline.Error) DeadlineClientError {
    return switch (err) {
        error.EndpointAbsent => error.EndpointAbsent,
        error.EndpointDenied => error.EndpointDenied,
        error.EndpointTransient => error.EndpointTransient,
        error.Timeout => error.DeadlineExceeded,
        error.InvalidDeadline,
        error.ConnectFailed,
        error.Closed,
        error.ReadFailed,
        error.WriteFailed,
        error.FlagFailed,
        error.SocketOptionFailed,
        => error.HandshakeFailed,
    };
}

fn deadlineHelloError(err: client_deadline.Error) DeadlineClientError {
    return switch (err) {
        error.Timeout => error.DeadlineExceeded,
        error.WriteFailed => error.WriteFailed,
        error.Closed, error.ReadFailed => error.ConnectionClosed,
        error.InvalidDeadline,
        error.EndpointAbsent,
        error.EndpointDenied,
        error.EndpointTransient,
        error.ConnectFailed,
        error.FlagFailed,
        error.SocketOptionFailed,
        => error.HandshakeFailed,
    };
}

/// `readStreamBatch`가 돌려주는 한 화면 stream 배치. `is_snapshot`이면 fresh full snapshot(화면 리셋), 아니면 delta 증분이다
/// (§9 — host가 grid/alt 변화 시 delta 대신 snapshot을 push하므로 소비자는 둘 다 받는다). `bytes`는 `end_stream`까지 이은
/// record 바이트를 포함한 batch 전체가 caller 소유이며 반드시 `deinit()`한다. `stream_id`는 어느 runtime의 화면인지다
/// (멀티 runtime 라우팅). owning value이므로 Zig move-by-convention을 따르며 bitwise copy한 두 값을 각각
/// `deinit()`하는 사용은 지원하지 않는다.
pub const StreamBatch = struct {
    is_snapshot: bool,
    stream_id: u64,
    bytes: []u8,
    allocator: std.mem.Allocator,

    pub fn deinit(self: StreamBatch) void {
        self.allocator.free(self.bytes);
    }
};

/// RPC response와 sibling screen batch 사이에 도착한 CR4 catch-up barrier의 canonical
/// connection-local inbox row다. Wire payload owner는 decode 직후 회수하고 pointer-free
/// identity/frontier만 보존한다.
pub const BufferedCatchupBarrier = struct {
    stream_id: u64,
    barrier: catchup_barrier_contract.Barrier,
    preceding_screen_batches: u32 = 0,
};

const GenerationBatchAccounting = struct {
    ledger: ?*generation_batch_registry.AccountingLedger = null,
    last_transfer_id: u64 = 0,

    fn valid(self: *const GenerationBatchAccounting, client_addr: usize) bool {
        const ledger_valid = if (self.ledger) |ledger|
            ledger.matchesClient(client_addr)
        else
            true;
        return ledger_valid;
    }
};

fn rawRangesOverlap(a_start: usize, a_end: usize, b_start: usize, b_end: usize) bool {
    return a_start < b_end and b_start < a_end;
}

/// GUI ingress seals the allocation-free event preflight beside the exact owned frame so the
/// runtime consumer can bind identity/authority and materialize without parsing the payload twice.
/// Strict CLI adoption intentionally stores `preflight = null`; c3b classifies its complete FIFO.
pub const BufferedEvent = struct {
    header: protocol.Header,
    payload: []u8,
    preflight: ?runtime_event_wire.Verdict = null,
    admission_seal: ?AdmissionSeal = null,

    const AdmissionSeal = struct {
        header: protocol.Header,
        admission: Admission,
        payload_digest: runtime_event_wire.Digest,
        payload_addr: usize,
        payload_len: usize,
        allocator: std.mem.Allocator,
    };

    const Admission = union(enum) {
        accepted: runtime_event_wire.EventPreflight,
        unknown,
    };

    fn deinit(self: BufferedEvent, allocator: std.mem.Allocator) void {
        allocator.free(self.payload);
    }

    fn seal(
        header: protocol.Header,
        payload: []const u8,
        admission: Admission,
        allocator: std.mem.Allocator,
    ) AdmissionSeal {
        return .{
            .header = header,
            .admission = admission,
            .payload_digest = runtime_event_wire.payloadDigest(payload),
            .payload_addr = @intFromPtr(payload.ptr),
            .payload_len = payload.len,
            .allocator = allocator,
        };
    }

    fn sealMatches(self: BufferedEvent, canonical_allocator: std.mem.Allocator) bool {
        const preflight = self.preflight orelse return self.admission_seal == null;
        const admission: Admission = switch (preflight) {
            .accepted => |value| .{ .accepted = value },
            .unknown => .unknown,
            .foreign, .malformed, .resource_exhausted => return false,
        };
        const seal_value = self.admission_seal orelse return false;
        if (!std.meta.eql(seal_value.header, self.header)) return false;
        // `Allocator.ptr` may legally be undefined for stateless allocators; Zig explicitly
        // forbids using that field as comparable identity. The admission seal retains the typed
        // allocator that allocated this payload, while this comparison closes its implementation.
        if (seal_value.allocator.vtable != canonical_allocator.vtable) return false;
        if (seal_value.payload_addr != @intFromPtr(self.payload.ptr) or
            seal_value.payload_len != self.payload.len)
            return false;
        const digest = runtime_event_wire.payloadDigest(self.payload);
        if (!std.mem.eql(u8, &seal_value.payload_digest, &digest)) return false;
        if (std.meta.activeTag(seal_value.admission) != std.meta.activeTag(admission)) return false;
        return switch (admission) {
            .accepted => |accepted| runtime_event_wire.eventPreflightEql(
                seal_value.admission.accepted,
                accepted,
            ),
            .unknown => true,
        };
    }

    /// Fast ended classification intentionally validates only the independently sealed metadata.
    /// Payload bytes are covered by the slow all-owner transaction so a drift is reported as
    /// source corruption rather than changing the preflight hint contract.
    fn acceptedSealMetadataMatches(
        self: BufferedEvent,
        accepted: runtime_event_wire.EventPreflight,
        canonical_allocator: std.mem.Allocator,
    ) bool {
        const seal_value = self.admission_seal orelse return false;
        if (!std.meta.eql(seal_value.header, self.header) or
            seal_value.allocator.vtable != canonical_allocator.vtable or
            seal_value.payload_addr != @intFromPtr(self.payload.ptr) or
            seal_value.payload_len != self.payload.len or
            !std.mem.eql(u8, &seal_value.payload_digest, &accepted.raw_digest) or
            std.meta.activeTag(seal_value.admission) != .accepted)
            return false;
        return runtime_event_wire.eventPreflightEql(
            seal_value.admission.accepted,
            accepted,
        );
    }

    /// 알 수 없는 미래 event도 admission에서 봉인된 정상 queue owner다. ended 빠른 판별은
    /// payload를 다시 읽지 않고 이 메타데이터만 확인해야 후속 settlement가 원래 위반 사유를 소유한다.
    fn unknownSealMetadataMatches(
        self: BufferedEvent,
        canonical_allocator: std.mem.Allocator,
    ) bool {
        const seal_value = self.admission_seal orelse return false;
        return std.meta.eql(seal_value.header, self.header) and
            seal_value.allocator.vtable == canonical_allocator.vtable and
            seal_value.payload_addr == @intFromPtr(self.payload.ptr) and
            seal_value.payload_len == self.payload.len and
            std.meta.activeTag(seal_value.admission) == .unknown;
    }
};

test "CR3a-2c3d C1 event admission seal closes verdict and allocator provenance" {
    const accepted_payload = "{\"event\":\"runtime.ended\"}";
    const accepted = switch (runtime_event_wire.preflightEvent(accepted_payload, .{})) {
        .accepted => |value| value,
        else => return error.TestUnexpectedResult,
    };
    const accepted_header: protocol.Header = .{
        .kind = .event,
        .stream_id = 41,
        .payload_len = accepted_payload.len,
    };
    var event: BufferedEvent = .{
        .header = accepted_header,
        .payload = @constCast(accepted_payload),
        .preflight = .{ .accepted = accepted },
        .admission_seal = BufferedEvent.seal(
            accepted_header,
            accepted_payload,
            .{ .accepted = accepted },
            std.testing.allocator,
        ),
    };
    try std.testing.expect(event.sealMatches(std.testing.allocator));
    try std.testing.expect(!event.sealMatches(std.heap.page_allocator));

    // Stateless allocators may carry undefined/zero context bits. Provenance validation must not
    // compare or require that field; the typed allocator itself remains the cleanup authority.
    var stateless = event;
    stateless.admission_seal = BufferedEvent.seal(
        accepted_header,
        accepted_payload,
        .{ .accepted = accepted },
        std.heap.page_allocator,
    );
    try std.testing.expect(stateless.sealMatches(std.heap.page_allocator));
    try std.testing.expectEqual(
        std.heap.page_allocator.vtable,
        stateless.admission_seal.?.allocator.vtable,
    );

    event.preflight = .unknown;
    try std.testing.expect(!event.sealMatches(std.testing.allocator));
    event.admission_seal = BufferedEvent.seal(
        accepted_header,
        accepted_payload,
        .unknown,
        std.testing.allocator,
    );
    try std.testing.expect(event.sealMatches(std.testing.allocator));
    event.admission_seal.?.header.stream_id += 1;
    try std.testing.expect(!event.sealMatches(std.testing.allocator));
    event.admission_seal.?.header = accepted_header;
    event.admission_seal.?.payload_digest[0] ^= 1;
    try std.testing.expect(!event.sealMatches(std.testing.allocator));

    // Strict external adoption deliberately has neither a parsed verdict nor a GUI seal.
    event.preflight = null;
    event.admission_seal = null;
    try std.testing.expect(event.sealMatches(std.testing.allocator));
    event.admission_seal = BufferedEvent.seal(
        accepted_header,
        accepted_payload,
        .unknown,
        std.testing.allocator,
    );
    try std.testing.expect(!event.sealMatches(std.testing.allocator));
}

