/// ended purge의 빠른 판정 결과다. `event_index`는 느린 트랜잭션이 다시 검증할 힌트일 뿐
/// 소유권이나 commit 권위를 나타내지 않는다.
pub const EndedEventHint = struct {
    event_index: u32,
};

pub const EndedEventPeek = union(enum) {
    not_ended,
    candidate: EndedEventHint,
};

pub const GenerationEventTakeKind = enum(u8) {
    idle,
    ended_pending,
    ordinary,
};

const GenerationEventTakeLifecycle = enum(u8) { empty, prepared, consumed };

/// Internal two-phase queue token. The generation adapter reserves node authority between
/// prepare and commit; commit revalidates this frozen queue head before the no-fail remove.
pub const PreparedGenerationEventTake = struct {
    self_addr: usize = 0,
    client_addr: usize = 0,
    stream_id: u64 = 0,
    event_index: u32 = 0,
    queue_addr: usize = 0,
    queue_len: usize = 0,
    queue_capacity: usize = 0,
    queue_bytes: usize = 0,
    payload_addr: usize = 0,
    payload_len: usize = 0,
    header: protocol.Header = .{ .kind = .hello },
    payload_digest: runtime_event_wire.Digest = [_]u8{0} ** 32,
    kind: GenerationEventTakeKind = .idle,
    lifecycle: GenerationEventTakeLifecycle = .empty,

    fn pristine(self: *const PreparedGenerationEventTake) bool {
        return self.self_addr == 0 and self.client_addr == 0 and self.stream_id == 0 and
            self.event_index == 0 and self.queue_addr == 0 and self.queue_len == 0 and
            self.queue_capacity == 0 and self.queue_bytes == 0 and
            self.payload_addr == 0 and self.payload_len == 0 and
            std.meta.eql(self.header, protocol.Header{ .kind = .hello }) and
            std.mem.allEqual(u8, &self.payload_digest, 0) and
            self.kind == .idle and self.lifecycle == .empty;
    }
};

pub const OwnedGenerationEvent = struct {
    header: protocol.Header,
    payload: []u8,
    payload_allocator: std.mem.Allocator,
    preflight: runtime_event_wire.Verdict,
};

pub const ValidatedGenerationEventTake = struct {
    event_index: u32,
    payload: []const u8,
    preflight: runtime_event_wire.Verdict,
    payload_digest: runtime_event_wire.Digest,
};

pub const GenerationEventPrepareError = error{ Busy, Corrupt, Terminal, DestinationOccupied };
pub const GenerationEventCommitError = error{ Busy, Corrupt, Terminal, InvalidPrepared };
pub const GenerationEventHeldError = error{ Corrupt, Terminal, InvalidPrepared };

const buffered_event_source_schema_field_allowlist = [_][]const u8{
    "header",
    "payload",
    "preflight",
    "admission_seal",
};
comptime {
    const fields = std.meta.fields(BufferedEvent);
    if (fields.len != buffered_event_source_schema_field_allowlist.len)
        @compileError("update ClientSourceSealSchema.v1 for every BufferedEvent field change");
    for (fields, buffered_event_source_schema_field_allowlist) |field, expected|
        if (!std.mem.eql(u8, field.name, expected))
            @compileError("BufferedEvent field order drifted from ClientSourceSealSchema.v1");
}

pub const InventoryUnavailable = enum {
    unsupported,
    authority_changed,
    generation_changed,
    lifecycle_changed,
    cap_exceeded,
    unauthorized,
    host_rejected,
    protocol_rejected,
    malformed,
};

pub const RuntimeInventory = union(enum) {
    unavailable: struct {
        reason: InventoryUnavailable,
        page_count: u8,
    },
    complete: Complete,

    pub const Complete = struct {
        membership_generation: u64,
        upgrade_epoch: u64,
        authority_generation: u64,
        /// 전체 recovery collector가 host별 ceiling 합계를 31 page로 제한하기 위한 실제 소비량.
        page_count: u8,
        runtime_ids: []u128,

        pub fn deinit(self: *Complete, allocator: std.mem.Allocator) void {
            allocator.free(self.runtime_ids);
            self.* = undefined;
        }
    };
};

pub const AttachmentCapabilities = struct {
    peer_attach_generation: bool = false,
    negotiated_controller_transfer: bool = false,
};

/// Hello identity and capability policy are one closed profile. A caller cannot advertise
/// controller transfer without selecting a consumer that owns the corresponding revoke fence.
pub const ConnectionProfile = enum {
    gui,
    cli_probe,
    cli_attach,
    admin,

    fn wireKind(self: ConnectionProfile) []const u8 {
        return switch (self) {
            .gui => "gui",
            .cli_probe, .cli_attach => "cli",
            .admin => "admin",
        };
    }

    fn advertisesControllerTransfer(self: ConnectionProfile) bool {
        return switch (self) {
            .gui, .cli_attach => true,
            .cli_probe, .admin => false,
        };
    }

    pub fn requiresStrictExternalEvents(self: ConnectionProfile) bool {
        return self == .cli_attach;
    }
};

pub const ExternalTransferProfile = struct {
    wire_major: u16,
    connection_profile: ConnectionProfile,
    compatibility_kind: compatibility.Kind,
    screen_codec_version: u16,
    attach_schema: compatibility.AttachSchema,
    fingerprint_present: bool,
    fingerprint_digest: runtime_event_wire.Digest,
    attachment_capabilities: AttachmentCapabilities,
    metadata_support: runtime_metadata_wire.MetadataSupport,
};

test "external transfer profile field inventory seals every compatibility input" {
    const expected = [_][]const u8{
        "wire_major",
        "connection_profile",
        "compatibility_kind",
        "screen_codec_version",
        "attach_schema",
        "fingerprint_present",
        "fingerprint_digest",
        "attachment_capabilities",
        "metadata_support",
    };
    const fields = @typeInfo(ExternalTransferProfile).@"struct".fields;
    try testing.expectEqual(expected.len, fields.len);
    inline for (fields, expected) |field, name|
        try testing.expectEqualStrings(name, field.name);
    try testing.expectEqual(
        @as(usize, 2),
        @typeInfo(AttachmentCapabilities).@"struct".fields.len,
    );
    try testing.expectEqual(
        @as(usize, 6),
        @typeInfo(compatibility.Profile).@"struct".fields.len,
    );
}

