/// Final-address owner prepared before the ledger commit barrier.
///
/// `.prepared` contains only non-owning mirrors of the Client queues and sealed disarm inventory.
/// `commitExternalAdoptionTakeUnchecked` changes the tag and tombstones the source headers without
/// allocating or freeing. Only `.committed` cleanup owns and releases the captured allocations.
pub const ExternalAdoptionTake = struct {
    saved_self_address: usize = 0,
    client_address: usize = 0,
    plan_address: usize = 0,
    mirror_owner_address: usize = 0,
    mirror_cleanup_owner_address: usize = 0,
    allocator: std.mem.Allocator = std.heap.page_allocator,
    cleanup_allocator: std.mem.Allocator = std.heap.page_allocator,
    allocator_ptr_addr: usize = 0,
    allocator_vtable_addr: usize = 0,
    pending_batches: std.ArrayListUnmanaged(StreamBatch) = .empty,
    cleanup_pending_batches: std.ArrayListUnmanaged(StreamBatch) = .empty,
    pending_batches_seal: ExternalArrayDescriptor = .{ .address = 0, .len = 0, .capacity = 0 },
    pending_stream: std.ArrayListUnmanaged(framing.Frame) = .empty,
    cleanup_pending_stream: std.ArrayListUnmanaged(framing.Frame) = .empty,
    pending_stream_seal: ExternalArrayDescriptor = .{ .address = 0, .len = 0, .capacity = 0 },
    pending_events: std.ArrayListUnmanaged(BufferedEvent) = .empty,
    cleanup_pending_events: std.ArrayListUnmanaged(BufferedEvent) = .empty,
    pending_events_seal: ExternalArrayDescriptor = .{ .address = 0, .len = 0, .capacity = 0 },
    partial: ?ExternalAdoptionTakenPartial = null,
    cleanup_partial: ?ExternalAdoptionTakenPartial = null,
    partial_seal: ?ExternalPartialDescriptor = null,
    plan_inventory: ?ExternalAdoptionInventory = null,
    cleanup_plan_inventory: ?ExternalAdoptionInventory = null,
    inventory_cleanup_seal: [32]u8 = [_]u8{0} ** 32,
    cleanup_inventory_cleanup_seal: [32]u8 = [_]u8{0} ** 32,
    inventory_backing_seal: [32]u8 = [_]u8{0} ** 32,
    cleanup_inventory_backing_seal: [32]u8 = [_]u8{0} ** 32,
    lifecycle: ExternalAdoptionTakeLifecycle = .empty,

    pub fn isEmpty(self: *const ExternalAdoptionTake) bool {
        return self.lifecycle == .empty;
    }

    pub fn validate(
        self: *const ExternalAdoptionTake,
        client: *const Client,
        plan: *const PreparedClientDisarm,
        mirror_owner: *const ?ExternalAdoptionInventory,
        mirror_cleanup_owner: *const ?ExternalAdoptionInventory,
    ) bool {
        if (self.lifecycle != .prepared or
            self.saved_self_address != @intFromPtr(self) or
            self.client_address != @intFromPtr(client) or
            self.plan_address != @intFromPtr(plan) or
            self.mirror_owner_address != @intFromPtr(mirror_owner) or
            self.mirror_cleanup_owner_address !=
                @intFromPtr(mirror_cleanup_owner) or
            !std.meta.eql(self.allocator, client.allocator) or
            !std.meta.eql(self.cleanup_allocator, client.allocator) or
            @intFromPtr(self.allocator.ptr) != self.allocator_ptr_addr or
            @intFromPtr(self.allocator.vtable) != self.allocator_vtable_addr or
            !client.validateSealedExternalAdoptionPlan(plan))
            return false;
        if (!externalListMatchesSeal(
            StreamBatch,
            self.pending_batches,
            self.cleanup_pending_batches,
            self.pending_batches_seal,
        ) or !externalListMatchesClient(
            StreamBatch,
            self.pending_batches,
            client.pending_batches,
        ) or !externalListMatchesSeal(
            framing.Frame,
            self.pending_stream,
            self.cleanup_pending_stream,
            self.pending_stream_seal,
        ) or !externalListMatchesClient(
            framing.Frame,
            self.pending_stream,
            client.pending_stream,
        ) or !externalListMatchesSeal(
            BufferedEvent,
            self.pending_events,
            self.cleanup_pending_events,
            self.pending_events_seal,
        ) or !externalListMatchesClient(
            BufferedEvent,
            self.pending_events,
            client.pending_events,
        )) return false;
        if (!externalTakenPartialMatches(
            self.partial,
            self.cleanup_partial,
            self.partial_seal,
            client.partial_batch,
        )) return false;
        const stored_inventory = &(self.plan_inventory orelse return false);
        const cleanup_inventory = &(self.cleanup_plan_inventory orelse return false);
        const live_inventory = &(plan.inventory orelse return false);
        const live_mirror = &(mirror_owner.* orelse return false);
        const live_mirror_cleanup =
            &(mirror_cleanup_owner.* orelse return false);
        const primary_seal =
            externalInventoryCleanupSeal(stored_inventory);
        const mirror_seal =
            externalInventoryCleanupSeal(cleanup_inventory);
        const primary_backing_seal =
            externalInventoryBackingSeal(stored_inventory);
        const mirror_backing_seal =
            externalInventoryBackingSeal(cleanup_inventory);
        return externalInventoriesEqual(stored_inventory, cleanup_inventory) and
            externalInventoriesEqual(stored_inventory, live_inventory) and
            externalInventoriesEqual(cleanup_inventory, live_mirror) and
            externalInventoriesEqual(cleanup_inventory, live_mirror_cleanup) and
            std.mem.eql(u8, &primary_seal, &self.inventory_cleanup_seal) and
            std.mem.eql(
                u8,
                &mirror_seal,
                &self.cleanup_inventory_cleanup_seal,
            ) and
            std.mem.eql(
                u8,
                &primary_backing_seal,
                &self.inventory_backing_seal,
            ) and
            std.mem.eql(
                u8,
                &mirror_backing_seal,
                &self.cleanup_inventory_backing_seal,
            ) and
            externalInventoriesHaveIndependentStorage(
                stored_inventory,
                cleanup_inventory,
            );
    }

    pub fn isCommitted(self: *const ExternalAdoptionTake) bool {
        return self.lifecycle == .committed and
            self.saved_self_address == @intFromPtr(self);
    }

    pub fn requiresTypedCleanup(self: *const ExternalAdoptionTake) bool {
        return self.lifecycle == .committed;
    }

    pub fn lifecycleCode(self: *const ExternalAdoptionTake) u8 {
        return @intFromEnum(self.lifecycle);
    }

    /// Deep snapshot of the committed cleanup graph. Canonicalization is the memory-safety gate:
    /// only sealed list/inventory storage is traversed, and owned payload bytes are never read.
    pub fn projectionAuthorityDigest(self: *const ExternalAdoptionTake) ?owner_seal.Digest {
        if (!self.isCommitted()) return null;
        const batches = canonicalExternalList(
            StreamBatch,
            self.pending_batches,
            self.cleanup_pending_batches,
            self.pending_batches_seal,
        ) orelse return null;
        const stream = canonicalExternalList(
            framing.Frame,
            self.pending_stream,
            self.cleanup_pending_stream,
            self.pending_stream_seal,
        ) orelse return null;
        const events = canonicalExternalList(
            BufferedEvent,
            self.pending_events,
            self.cleanup_pending_events,
            self.pending_events_seal,
        ) orelse return null;
        const primary = canonicalExternalInventory(
            self.plan_inventory orelse return null,
        ) orelse return null;
        const mirror = canonicalExternalInventory(
            self.cleanup_plan_inventory orelse return null,
        ) orelse return null;
        var writer = owner_seal.Writer.init("maru.client-take.projection.v1");
        writer.writeUsize(self.saved_self_address);
        writer.writeUsize(self.client_address);
        writer.writeUsize(self.allocator_ptr_addr);
        writer.writeUsize(self.allocator_vtable_addr);
        writeProjectionBatches(&writer, batches);
        writeProjectionFrames(&writer, stream);
        writeProjectionEvents(&writer, events);
        writeProjectionInventory(&writer, &primary);
        writeProjectionInventory(&writer, &mirror);
        return writer.finish();
    }

    /// Validate the committed cleanup graph and report whether an arbitrary caller range aliases
    /// any header, container, inventory, or payload allocation that this take may later free.
    pub fn overlapsCommittedOwnedRange(
        self: *const ExternalAdoptionTake,
        address: usize,
        len: usize,
    ) ?bool {
        const target = checkedExternalRange(address, len) catch return null;
        const present_target = target orelse return null;
        if (self.projectionAuthorityDigest() == null) return null;
        const batches = canonicalExternalList(
            StreamBatch,
            self.pending_batches,
            self.cleanup_pending_batches,
            self.pending_batches_seal,
        ) orelse return null;
        const stream = canonicalExternalList(
            framing.Frame,
            self.pending_stream,
            self.cleanup_pending_stream,
            self.pending_stream_seal,
        ) orelse return null;
        const events = canonicalExternalList(
            BufferedEvent,
            self.pending_events,
            self.cleanup_pending_events,
            self.pending_events_seal,
        ) orelse return null;
        const primary = canonicalExternalInventory(
            self.plan_inventory orelse return null,
        ) orelse return null;
        const mirror = canonicalExternalInventory(
            self.cleanup_plan_inventory orelse return null,
        ) orelse return null;
        return externalTakeTargetAliases(
            present_target,
            self,
            batches,
            stream,
            events,
            &primary,
            &primary,
            &mirror,
        );
    }

    pub fn prepareFrozenCleanup(
        self: *const ExternalAdoptionTake,
        cleanup_scratch: *ExternalAdoptionCleanupScratch,
        out: *PreparedExternalAdoptionTakeCleanup,
        frozen_out: *const FrozenExternalAdoptionTakeCleanup,
    ) bool {
        const self_addr = @intFromPtr(self);
        const out_range = externalRangeOfValue(out);
        const frozen_range = externalRangeOfValue(frozen_out);
        if (externalRangesOverlap(out_range, externalRangeOfValue(self)) or
            externalRangesOverlap(frozen_range, externalRangeOfValue(self)) or
            externalRangesOverlap(out_range, frozen_range) or
            out.saved_self_addr != 0 or out.lifecycle != .empty or
            frozen_out.saved_self_addr != 0 or frozen_out.lifecycle != .empty or
            self.lifecycle != .committed or self.saved_self_address != self_addr)
            return false;
        const captured = self.*;
        const allocator = externalTakeCleanupAllocator(&captured) orelse return false;
        const batches = canonicalExternalList(
            StreamBatch,
            captured.pending_batches,
            captured.cleanup_pending_batches,
            captured.pending_batches_seal,
        ) orelse return false;
        const stream = canonicalExternalList(
            framing.Frame,
            captured.pending_stream,
            captured.cleanup_pending_stream,
            captured.pending_stream_seal,
        ) orelse return false;
        const events = canonicalExternalList(
            BufferedEvent,
            captured.pending_events,
            captured.cleanup_pending_events,
            captured.pending_events_seal,
        ) orelse return false;
        const primary_inventory = canonicalExternalInventory(
            captured.plan_inventory orelse return false,
        ) orelse return false;
        const mirror_inventory = canonicalExternalInventory(
            captured.cleanup_plan_inventory orelse return false,
        ) orelse return false;
        if (!externalInventoriesHaveIndependentStorage(
            &primary_inventory,
            &mirror_inventory,
        )) return false;
        const primary_backing_matches = externalInventoryBackingSealMatches(
            &primary_inventory,
            captured.inventory_backing_seal,
        );
        const mirror_backing_matches = externalInventoryBackingSealMatches(
            &mirror_inventory,
            captured.cleanup_inventory_backing_seal,
        );
        const primary_matches = primary_backing_matches and blk: {
            const digest = externalInventoryCleanupSeal(&primary_inventory);
            break :blk std.mem.eql(
                u8,
                &digest,
                &captured.inventory_cleanup_seal,
            );
        };
        const mirror_matches = mirror_backing_matches and blk: {
            const digest = externalInventoryCleanupSeal(&mirror_inventory);
            break :blk std.mem.eql(
                u8,
                &digest,
                &captured.cleanup_inventory_cleanup_seal,
            );
        };
        const payload_inventory_is_primary = primary_matches;
        const payload_inventory = if (payload_inventory_is_primary)
            primary_inventory
        else if (mirror_matches)
            mirror_inventory
        else
            return false;
        if (!externalTakeContainersMatchInventory(
            batches,
            stream,
            events,
            captured.partial,
            captured.cleanup_partial,
            captured.partial_seal,
            &payload_inventory,
        )) return false;
        if (payload_inventory.batch_descriptors.len >
            protocol.max_client_screen_items or
            payload_inventory.stream_descriptors.len >
                protocol.max_client_screen_items or
            payload_inventory.event_descriptors.len >
                max_pending_event_count)
            return false;
        if (externalCleanupScratchAliases(
            cleanup_scratch,
            &captured,
            batches,
            stream,
            events,
            &payload_inventory,
            if (primary_backing_matches) &primary_inventory else null,
            if (mirror_backing_matches) &mirror_inventory else null,
        ) or externalRangesOverlap(
            out_range,
            externalRangeOfValue(cleanup_scratch),
        ) or externalRangesOverlap(
            frozen_range,
            externalRangeOfValue(cleanup_scratch),
        )) return false;
        @memcpy(
            cleanup_scratch.batches[0..payload_inventory.batch_descriptors.len],
            payload_inventory.batch_descriptors,
        );
        @memcpy(
            cleanup_scratch.stream[0..payload_inventory.stream_descriptors.len],
            payload_inventory.stream_descriptors,
        );
        @memcpy(
            cleanup_scratch.events[0..payload_inventory.event_descriptors.len],
            payload_inventory.event_descriptors,
        );
        cleanup_scratch.partial = payload_inventory.snapshot.partial;
        out.* = .{
            .saved_self_addr = @intFromPtr(out),
            .take_addr = self_addr,
            .scratch_addr = @intFromPtr(cleanup_scratch),
            .frozen_out_addr = @intFromPtr(frozen_out),
            .allocator = allocator,
            .batches = batches,
            .stream = stream,
            .events = events,
            .partial = payload_inventory.snapshot.partial,
            .primary_inventory = primary_inventory,
            .mirror_inventory = mirror_inventory,
            .payload_inventory_is_primary = payload_inventory_is_primary,
            .free_primary_inventory = primary_backing_matches,
            .free_mirror_inventory = mirror_backing_matches,
            .batch_count = payload_inventory.batch_descriptors.len,
            .stream_count = payload_inventory.stream_descriptors.len,
            .event_count = payload_inventory.event_descriptors.len,
            .lifecycle = .prepared,
        };
        return true;
    }

    fn commitFrozenCleanupImpl(
        self: *ExternalAdoptionTake,
        prepared: *PreparedExternalAdoptionTakeCleanup,
        out: *FrozenExternalAdoptionTakeCleanup,
    ) void {
        std.debug.assert(prepared.saved_self_addr == @intFromPtr(prepared));
        std.debug.assert(prepared.take_addr == @intFromPtr(self));
        std.debug.assert(prepared.frozen_out_addr == @intFromPtr(out));
        std.debug.assert(prepared.lifecycle == .prepared);
        std.debug.assert(out.saved_self_addr == 0 and out.lifecycle == .empty);
        out.* = .{
            .saved_self_addr = @intFromPtr(out),
            .allocator = prepared.allocator,
            .batches = prepared.batches,
            .stream = prepared.stream,
            .events = prepared.events,
            .partial = prepared.partial,
            .primary_inventory = prepared.primary_inventory,
            .mirror_inventory = prepared.mirror_inventory,
            .free_primary_inventory = prepared.free_primary_inventory,
            .free_mirror_inventory = prepared.free_mirror_inventory,
            .batch_count = prepared.batch_count,
            .stream_count = prepared.stream_count,
            .event_count = prepared.event_count,
            .lifecycle = .frozen,
        };
        self.* = .{ .lifecycle = .aborted };
        prepared.lifecycle = .consumed;
    }

    pub fn appendPreparedFrozenCleanupRanges(
        self: *const ExternalAdoptionTake,
        prepared: *const PreparedExternalAdoptionTakeCleanup,
        out: *owner_range.Scratch,
    ) owner_range.Error!void {
        if (prepared.saved_self_addr != @intFromPtr(prepared) or
            prepared.take_addr != @intFromPtr(self) or
            prepared.lifecycle != .prepared)
            return error.InvalidRange;
        try appendExternalListOwnerRange(StreamBatch, prepared.batches, out);
        try appendExternalListOwnerRange(framing.Frame, prepared.stream, out);
        try appendExternalListOwnerRange(BufferedEvent, prepared.events, out);
        const payload_inventory = if (prepared.payload_inventory_is_primary)
            &prepared.primary_inventory.?
        else
            &prepared.mirror_inventory.?;
        for (payload_inventory.batch_descriptors) |descriptor|
            try out.append(descriptor.bytes_address, descriptor.bytes_len);
        for (payload_inventory.stream_descriptors) |descriptor|
            try out.append(descriptor.payload_address, descriptor.payload_len);
        for (payload_inventory.event_descriptors) |descriptor|
            try out.append(descriptor.payload_address, descriptor.payload_len);
        if (prepared.partial) |partial|
            try out.append(partial.bytes.address, partial.bytes.capacity);
        if (prepared.free_primary_inventory)
            try appendExternalInventoryBackingRanges(
                &prepared.primary_inventory.?,
                out,
            );
        if (prepared.free_mirror_inventory)
            try appendExternalInventoryBackingRanges(
                &prepared.mirror_inventory.?,
                out,
            );
    }

    pub fn deinit(self: *ExternalAdoptionTake) void {
        self.deinitWithScratch(null);
    }

    pub fn deinitCommitted(
        self: *ExternalAdoptionTake,
        scratch: *ExternalAdoptionCleanupScratch,
    ) void {
        self.deinitWithScratch(scratch);
    }

    fn deinitWithScratch(
        self: *ExternalAdoptionTake,
        scratch: ?*ExternalAdoptionCleanupScratch,
    ) void {
        if (self.saved_self_address != 0 and
            self.saved_self_address != @intFromPtr(self))
            return;
        if (self.lifecycle == .committed) {
            const cleanup_scratch = scratch orelse
                @panic("committed external adoption take requires cleanup scratch");
            var prepared: PreparedExternalAdoptionTakeCleanup = .{};
            var frozen: FrozenExternalAdoptionTakeCleanup = .{};
            if (!self.prepareFrozenCleanup(
                cleanup_scratch,
                &prepared,
                &frozen,
            )) {
                self.* = .{ .lifecycle = .aborted };
                return;
            }
            commitExternalAdoptionTakeFrozenCleanupUnchecked(
                self,
                &prepared,
                &frozen,
            );
            _ = finishFrozenCleanup(&frozen, cleanup_scratch);
            return;
        }
        self.* = .{ .lifecycle = .aborted };
    }
};

fn appendExternalListOwnerRange(
    comptime T: type,
    list: std.ArrayListUnmanaged(T),
    out: *owner_range.Scratch,
) owner_range.Error!void {
    const bytes = std.math.mul(usize, list.capacity, @sizeOf(T)) catch
        return error.ArithmeticOverflow;
    try out.append(if (list.capacity == 0) 0 else @intFromPtr(list.items.ptr), bytes);
}

fn appendExternalInventoryBackingRanges(
    inventory: *const ExternalAdoptionInventory,
    out: *owner_range.Scratch,
) owner_range.Error!void {
    inline for (.{
        inventory.batch_descriptors,
        inventory.stream_descriptors,
        inventory.event_descriptors,
        inventory.build_id_copy,
        inventory.lifecycle_copy,
    }) |slice| {
        const bytes = std.math.mul(
            usize,
            slice.len,
            @sizeOf(std.meta.Child(@TypeOf(slice))),
        ) catch return error.ArithmeticOverflow;
        try out.append(if (slice.len == 0) 0 else @intFromPtr(slice.ptr), bytes);
    }
}

pub fn finishFrozenCleanup(
    frozen: *FrozenExternalAdoptionTakeCleanup,
    scratch: *ExternalAdoptionCleanupScratch,
) FrozenTakeCleanupFinishResult {
    var hidden_scratch = scratch.*;
    return finishFrozenCleanupWithHiddenScratch(frozen, &hidden_scratch);
}

/// Aggregate-only finish leaf. `scratch` must already be a callback-hidden local snapshot; keeping
/// this separate avoids copying the 512 KiB descriptor bank a second time inside pump teardown.
pub fn finishFrozenCleanupWithHiddenScratch(
    frozen: *FrozenExternalAdoptionTakeCleanup,
    scratch: *ExternalAdoptionCleanupScratch,
) FrozenTakeCleanupFinishResult {
    const address = @intFromPtr(frozen);
    if (frozen.lifecycle == .cleaned_tombstone) return .already_cleaned;
    if (frozen.saved_self_addr != address or frozen.lifecycle != .frozen or
        frozen.batch_count > protocol.max_client_screen_items or
        frozen.stream_count > protocol.max_client_screen_items or
        frozen.event_count > max_pending_event_count)
        return .invalid;
    if (!frozen_cleanup_guard.enter()) return .invalid;
    defer frozen_cleanup_guard.leave();
    defer frozen.* = .{ .lifecycle = .cleaned_tombstone };
    var local = frozen.*;
    frozen.* = .{ .lifecycle = .cleaned_tombstone };
    for (scratch.batches[0..local.batch_count]) |descriptor|
        descriptor.allocator.free(externalOwnedBytes(
            descriptor.bytes_address,
            descriptor.bytes_len,
        ));
    for (scratch.stream[0..local.stream_count]) |descriptor|
        local.allocator.free(externalOwnedBytes(
            descriptor.payload_address,
            descriptor.payload_len,
        ));
    for (scratch.events[0..local.event_count]) |descriptor|
        local.allocator.free(externalOwnedBytes(
            descriptor.payload_address,
            descriptor.payload_len,
        ));
    if (local.partial) |partial|
        local.allocator.free(externalOwnedBytes(
            partial.bytes.address,
            partial.bytes.capacity,
        ));
    local.batches.deinit(local.allocator);
    local.stream.deinit(local.allocator);
    local.events.deinit(local.allocator);
    if (local.primary_inventory) |inventory| {
        if (local.free_primary_inventory) {
            var owned = inventory;
            owned.deinit();
        }
    }
    if (local.mirror_inventory) |inventory| {
        if (local.free_mirror_inventory) {
            var owned = inventory;
            owned.deinit();
        }
    }
    return .cleaned;
}

const ExternalPumpTransferLifecycle = enum {
    empty,
    prepared,
    owners_moved,
    committed,
    aborted,
};

pub const ExternalPumpFinishOutcome = enum { ready, quarantined };

/// Address-bound capability for moving one Client into one final optional slot.
///
/// Parser normalization is staged in separate storage; preparation never mutates either owner.
/// The token is intentionally not returnable by value and validates its three bound addresses.
pub const PreparedExternalPumpTransfer = struct {
    saved_self_addr: usize = 0,
    source_addr: usize = 0,
    destination_addr: usize = 0,
    fd: c.fd_t = -1,
    host_id: u128 = 0,
    allocator_ptr_addr: usize = 0,
    allocator_vtable_addr: usize = 0,
    profile: ?ExternalTransferProfile = null,
    parser_replacement: framing.PreparedNormalizeExact = .{},
    rx_bind: client_external_mode.PreparedRxBind = .{},
    lifecycle: ExternalPumpTransferLifecycle = .empty,

    pub fn deinit(self: *PreparedExternalPumpTransfer) void {
        if (self.saved_self_addr != 0 and self.saved_self_addr != @intFromPtr(self)) return;
        self.rx_bind.deinit();
        self.parser_replacement.deinit();
        self.lifecycle = .aborted;
    }

    pub fn validate(
        self: *const PreparedExternalPumpTransfer,
        source: *const Client,
        destination: *const ?Client,
    ) bool {
        const external_state = switch (source.io_mode) {
            .external => |*state| state,
            .blocking => return false,
        };
        return self.lifecycle == .prepared and
            self.saved_self_addr == @intFromPtr(self) and
            self.source_addr == @intFromPtr(source) and
            self.destination_addr == @intFromPtr(destination) and
            destination.* == null and
            self.fd == source.fd and
            self.host_id == source.host_id and
            self.allocator_ptr_addr == @intFromPtr(source.allocator.ptr) and
            self.allocator_vtable_addr == @intFromPtr(source.allocator.vtable) and
            std.meta.eql(self.profile orelse return false, source.externalTransferProfile() orelse return false) and
            source.ownership == .standalone and
            !source.unusable and source.fd >= 0 and
            self.parser_replacement.validate(&source.parser) and
            self.rx_bind.validate(
                external_state,
                source.attach_instance_id,
                &self.parser_replacement,
                @intFromPtr(destination),
                @sizeOf(?Client),
            );
    }
};

fn externalOwnedSliceAddress(comptime T: type, slice: []const T) usize {
    return if (slice.len == 0) 0 else @intFromPtr(slice.ptr);
}

fn canonicalExternalSlice(
    comptime T: type,
    primary: []T,
    cleanup: []T,
    sealed_addr: usize,
    sealed_len: usize,
) ?[]T {
    if (sameExternalSlice(T, primary, cleanup)) return primary;
    if (externalOwnedSliceAddress(T, primary) == sealed_addr and primary.len == sealed_len)
        return primary;
    if (externalOwnedSliceAddress(T, cleanup) == sealed_addr and cleanup.len == sealed_len)
        return cleanup;
    return null;
}

fn externalAllocatorMatchesSeal(
    allocator: std.mem.Allocator,
    ptr_addr: usize,
    vtable_addr: usize,
) bool {
    return @intFromPtr(allocator.ptr) == ptr_addr and
        @intFromPtr(allocator.vtable) == vtable_addr;
}

const ExternalValidatedAdoption = struct {
    screen_source_count: usize,
    screen_payload_bytes: usize,
    event_payload_bytes: usize,
};

const ExternalValidatedScreenSource = struct {
    screen_source_count: usize,
    screen_payload_bytes: usize,
};

const ExternalRange = struct { start: usize, len: usize };

fn externalRangeOfValue(value: anytype) ExternalRange {
    return .{ .start = @intFromPtr(value), .len = @sizeOf(@TypeOf(value.*)) };
}

fn externalRangesOverlap(a: ExternalRange, b: ExternalRange) bool {
    if (a.len == 0 or b.len == 0) return false;
    const a_end = std.math.add(usize, a.start, a.len) catch return true;
    const b_end = std.math.add(usize, b.start, b.len) catch return true;
    return a.start < b_end and b.start < a_end;
}

fn checkedExternalRange(
    start: usize,
    len: usize,
) ExternalAdoptionInspectError!?ExternalRange {
    if (len == 0) return null;
    if (start == 0) return error.InvalidAlias;
    _ = std.math.add(usize, start, len) catch return error.ArithmeticOverflow;
    return .{ .start = start, .len = len };
}

fn externalRangeForSlice(bytes: []const u8, capacity: usize) ExternalAdoptionInspectError!?ExternalRange {
    return checkedExternalRange(@intFromPtr(bytes.ptr), capacity);
}

fn externalRangeForTypedSlice(
    comptime Entry: type,
    entries: []const Entry,
) ExternalAdoptionInspectError!?ExternalRange {
    const bytes = std.math.mul(usize, entries.len, @sizeOf(Entry)) catch
        return error.ArithmeticOverflow;
    return checkedExternalRange(@intFromPtr(entries.ptr), bytes);
}

fn externalDestinationOverlapsInventory(
    inventory: *const ExternalAdoptionInventory,
    target: ExternalRange,
) ExternalAdoptionInspectError!bool {
    if (externalRangesOverlap(target, externalRangeOfValue(inventory))) return true;
    inline for (.{
        try externalRangeForTypedSlice(ExternalBatchDescriptor, inventory.batch_descriptors),
        try externalRangeForTypedSlice(ExternalFrameDescriptor, inventory.stream_descriptors),
        try externalRangeForTypedSlice(ExternalFrameDescriptor, inventory.event_descriptors),
        try externalRangeForTypedSlice(u8, inventory.build_id_copy),
        try externalRangeForTypedSlice(u8, inventory.lifecycle_copy),
        try externalRangeForTypedSlice(
            ExternalBatchDescriptor,
            inventory.cleanup_batch_descriptors,
        ),
        try externalRangeForTypedSlice(
            ExternalFrameDescriptor,
            inventory.cleanup_stream_descriptors,
        ),
        try externalRangeForTypedSlice(
            ExternalFrameDescriptor,
            inventory.cleanup_event_descriptors,
        ),
        try externalRangeForTypedSlice(u8, inventory.cleanup_build_id_copy),
        try externalRangeForTypedSlice(u8, inventory.cleanup_lifecycle_copy),
    }) |range| if (range) |present|
        if (externalRangesOverlap(target, present)) return true;
    return false;
}

fn externalRangeForList(
    list: anytype,
    comptime Entry: type,
) ExternalAdoptionInspectError!?ExternalRange {
    const bytes = std.math.mul(usize, list.capacity, @sizeOf(Entry)) catch
        return error.ArithmeticOverflow;
    return checkedExternalRange(@intFromPtr(list.items.ptr), bytes);
}

fn externalOwnerRangeCount(self: *const Client) ExternalAdoptionInspectError!usize {
    var count: usize = 7;
    const tx_count = switch (self.io_mode) {
        .blocking => 0,
        .external => |state| state.external_tx.items.len,
    };
    inline for (.{
        @as(usize, @intFromBool(self.build_id != null)),
        @as(usize, @intFromBool(self.pending_outbound != null)),
        @as(usize, @intFromBool(self.partial_batch != null)),
        self.pending_batches.items.len,
        self.pending_stream.items.len,
        self.pending_events.items.len,
        tx_count,
    }) |part| count = std.math.add(usize, count, part) catch
        return error.ArithmeticOverflow;
    return count;
}

const max_external_owner_range_scratch_bytes =
    max_external_owner_range_count * @sizeOf(ExternalRange);
const max_external_outer_owner_range_count = 8;

pub const ExternalSourceOwnerRangeScratch = struct {
    ranges: [max_external_owner_range_count]ExternalRange = undefined,
};
comptime {
    if (@sizeOf(ExternalSourceOwnerRangeScratch) !=
        max_external_owner_range_scratch_bytes or
        @sizeOf(ExternalSourceOwnerRangeScratch) > 160 * 1024)
        @compileError("source owner-range scratch exceeds the c3b fixed-buffer budget");
}

fn appendExternalRange(
    ranges: []ExternalRange,
    used: *usize,
    range: ?ExternalRange,
) ExternalAdoptionInspectError!void {
    const present = range orelse return;
    if (used.* >= ranges.len) return error.InvalidClientState;
    ranges[used.*] = present;
    used.* += 1;
}

fn fillExternalOuterOwnerRanges(
    self: *const Client,
    ranges: []ExternalRange,
) ExternalAdoptionInspectError!usize {
    var used: usize = 0;
    if (self.build_id) |bytes|
        try appendExternalRange(ranges, &used, try externalRangeForSlice(bytes, bytes.len));
    const fixed = [_]?ExternalRange{
        try externalRangeForSlice(self.lifecycle, self.lifecycle.len),
        try externalRangeForList(self.parser.buf, u8),
        try externalRangeForList(self.pending_batches, StreamBatch),
        try externalRangeForList(self.pending_stream, framing.Frame),
        try externalRangeForList(self.pending_events, BufferedEvent),
        try externalRangeForList(self.pending_catchup_barriers, BufferedCatchupBarrier),
        if (self.pending_outbound) |pending|
            try externalRangeForSlice(pending.frame, pending.frame.len)
        else
            null,
        switch (self.io_mode) {
            .blocking => null,
            .external => |state| try externalRangeForList(
                state.external_tx,
                client_external_mode.ExternalTxFrame,
            ),
        },
    };
    for (fixed) |range| try appendExternalRange(ranges, &used, range);
    if (used > ranges.len) return error.InvalidClientState;
    return used;
}

fn appendExternalNestedOwnerRanges(
    self: *const Client,
    ranges: []ExternalRange,
    used: *usize,
) ExternalAdoptionInspectError!void {
    const count = try externalNestedOwnerRangeCount(self);
    for (0..count) |index|
        try appendExternalRange(ranges, used, try externalNestedOwnerRangeAt(self, index));
    if (used.* > ranges.len) return error.InvalidClientState;
}

fn externalNestedOwnerRangeCount(
    self: *const Client,
) ExternalAdoptionInspectError!usize {
    var count: usize = @intFromBool(self.partial_batch != null);
    inline for (.{
        self.pending_batches.items.len,
        self.pending_stream.items.len,
        self.pending_events.items.len,
        switch (self.io_mode) {
            .blocking => 0,
            .external => |state| state.external_tx.items.len,
        },
    }) |part| count = std.math.add(usize, count, part) catch
        return error.ArithmeticOverflow;
    return count;
}

fn externalNestedOwnerRangeAt(
    self: *const Client,
    ordinal: usize,
) ExternalAdoptionInspectError!?ExternalRange {
    var index = ordinal;
    if (self.partial_batch) |partial| {
        if (index == 0)
            return externalRangeForSlice(partial.bytes.items, partial.bytes.capacity);
        index -= 1;
    }
    if (index < self.pending_batches.items.len) {
        const batch = self.pending_batches.items[index];
        return externalRangeForSlice(batch.bytes, batch.bytes.len);
    }
    index -= self.pending_batches.items.len;
    if (index < self.pending_stream.items.len) {
        const frame = self.pending_stream.items[index];
        return externalRangeForSlice(frame.payload, frame.payload.len);
    }
    index -= self.pending_stream.items.len;
    if (index < self.pending_events.items.len) {
        const frame = self.pending_events.items[index];
        return externalRangeForSlice(frame.payload, frame.payload.len);
    }
    index -= self.pending_events.items.len;
    switch (self.io_mode) {
        .blocking => {},
        .external => |state| {
            if (index < state.external_tx.items.len) {
                const frame = state.external_tx.items[index];
                return externalRangeForSlice(frame.bytes, frame.bytes.len);
            }
        },
    }
    return error.InvalidClientState;
}

/// Allocation-free stable ordinal view over the complete Client-owned range graph. Keep this as
/// the single random-access projection of the outer+nested SSOT used by fixed-buffer proofs.
fn externalOwnerRangeAt(
    self: *const Client,
    ordinal: usize,
) ExternalAdoptionInspectError!?ExternalRange {
    var outer: [max_external_outer_owner_range_count]ExternalRange = undefined;
    const outer_count = try fillExternalOuterOwnerRanges(self, &outer);
    if (ordinal < outer_count) return outer[ordinal];
    return externalNestedOwnerRangeAt(self, ordinal - outer_count);
}

// Compile-time wiring gate: ended purge must consume the complete Client owner-graph ordinal SSOT
// rather than introducing a queue-specific owner enumeration.
const ended_purge_owner_range_ssot: *const fn (
    *const Client,
    usize,
) ExternalAdoptionInspectError!?ExternalRange = externalOwnerRangeAt;

fn collectExternalOwnerRanges(
    self: *const Client,
) ExternalAdoptionInspectError![]ExternalRange {
    const count = try externalOwnerRangeCount(self);
    const ranges = try self.allocator.alloc(ExternalRange, count);
    errdefer self.allocator.free(ranges);
    const used = try fillExternalOwnerRanges(self, ranges);
    return ranges[0..used];
}

fn fillExternalOwnerRanges(
    self: *const Client,
    ranges: []ExternalRange,
) ExternalAdoptionInspectError!usize {
    const count = try externalOwnerRangeCount(self);
    if (ranges.len < count) return error.InvalidClientState;
    @memset(ranges, .{ .start = 0, .len = 0 });
    var used = try fillExternalOuterOwnerRanges(self, ranges);
    try appendExternalNestedOwnerRanges(self, ranges, &used);
    if (used > count) return error.InvalidClientState;
    return used;
}

fn externalRangeLessThan(comparisons: *usize, left: ExternalRange, right: ExternalRange) bool {
    comparisons.* += 1;
    return left.start < right.start;
}

fn validateExternalOwnerRangesAgainst(
    self: *const Client,
    target: ?ExternalRange,
) ExternalAdoptionInspectError!usize {
    const allocation_count = try externalOwnerRangeCount(self);
    const ranges = try collectExternalOwnerRanges(self);
    defer self.allocator.free(ranges.ptr[0..allocation_count]);
    var comparisons: usize = 0;
    std.mem.sort(ExternalRange, ranges, &comparisons, externalRangeLessThan);
    const client_range = externalRangeOfValue(self);
    for (ranges, 0..) |range, index| {
        if (externalRangesOverlap(range, client_range) or
            (target != null and externalRangesOverlap(range, target.?)))
            return error.InvalidAlias;
        if (index != 0 and externalRangesOverlap(ranges[index - 1], range))
            return error.InvalidAlias;
    }
    return comparisons;
}

fn validateExternalOwnerRanges(self: *const Client) ExternalAdoptionInspectError!void {
    _ = try validateExternalOwnerRangesAgainst(self, null);
}

/// Generation guarded allocator가 parent allocation 결과를 첫 write 전에 검사하는
/// callback-free owner-range query다. 오류나 overflow는 alias로 취급해 fail-close한다.
pub fn generationAllocationAliasesOwnedBacking(
    self: *const Client,
    ptr: [*]u8,
    len: usize,
) bool {
    const target = (externalRangeForSlice(ptr[0..len], len) catch return true) orelse
        return false;
    var outer: [max_external_outer_owner_range_count]ExternalRange = undefined;
    const outer_count = fillExternalOuterOwnerRanges(self, &outer) catch return true;
    for (outer[0..outer_count]) |range|
        if (externalRangesOverlap(range, target)) return true;
    const nested_count = externalNestedOwnerRangeCount(self) catch return true;
    for (0..nested_count) |index| {
        const range = externalNestedOwnerRangeAt(self, index) catch return true;
        if (range) |present| if (externalRangesOverlap(present, target)) return true;
    }
    return false;
}

const ExternalSourceOwnerRangeProofStats = struct {
    outer_ranges: usize,
    total_ranges: usize,
    comparisons: usize,
};

fn validateExternalRangeSet(
    ranges: []ExternalRange,
    client_range: ExternalRange,
    forbidden: ?ExternalRange,
    comparisons: *usize,
) ExternalAdoptionInspectError!void {
    std.mem.sort(ExternalRange, ranges, comparisons, externalRangeLessThan);
    for (ranges, 0..) |range, index| {
        if (externalRangesOverlap(range, client_range) or
            (forbidden != null and externalRangesOverlap(range, forbidden.?)))
            return error.InvalidAlias;
        if (index != 0 and externalRangesOverlap(ranges[index - 1], range))
            return error.InvalidAlias;
    }
}

/// Allocation/callback-free c3 source proof. The first sort validates every outer backing before
/// any list element is read; only then may the second pass enumerate nested payload owners.
fn validateExternalSourceOwnerRangesWithPolicy(
    self: *const Client,
    scratch: *ExternalSourceOwnerRangeScratch,
    catchup_barrier_policy: ExternalCatchupBarrierPolicy,
) ExternalAdoptionInspectError!ExternalSourceOwnerRangeProofStats {
    try validateExternalAdoptionStructure(self, catchup_barrier_policy);
    const client_range = externalRangeOfValue(self);
    const scratch_range = externalRangeOfValue(scratch);
    if (externalRangesOverlap(scratch_range, client_range)) return error.InvalidAlias;

    var outer_scratch: [max_external_outer_owner_range_count]ExternalRange = undefined;
    const outer_count = try fillExternalOuterOwnerRanges(self, &outer_scratch);
    var comparisons: usize = 0;
    try validateExternalRangeSet(
        outer_scratch[0..outer_count],
        client_range,
        scratch_range,
        &comparisons,
    );

    const nested_count = try externalNestedOwnerRangeCount(self);
    for (0..nested_count) |index| {
        const range = (try externalNestedOwnerRangeAt(self, index)) orelse continue;
        if (externalRangesOverlap(range, scratch_range)) return error.InvalidAlias;
    }

    var total_count = try fillExternalOuterOwnerRanges(self, &scratch.ranges);
    try appendExternalNestedOwnerRanges(self, &scratch.ranges, &total_count);
    try validateExternalRangeSet(
        scratch.ranges[0..total_count],
        client_range,
        null,
        &comparisons,
    );
    return .{
        .outer_ranges = outer_count,
        .total_ranges = total_count,
        .comparisons = comparisons,
    };
}

fn validateExternalSourceOwnerRanges(
    self: *const Client,
    scratch: *ExternalSourceOwnerRangeScratch,
) ExternalAdoptionInspectError!ExternalSourceOwnerRangeProofStats {
    return validateExternalSourceOwnerRangesWithPolicy(self, scratch, .require_empty);
}

pub const ExternalSourceSealError = client_source_transcript.Error || error{
    IneligibleProfile,
    InvalidCompatibilityProvenance,
    InvalidClientState,
    InvalidCounter,
    InvalidStream,
    InvalidHeader,
    InvalidPartial,
    InvalidAllocator,
    InvalidAlias,
    InvalidRequestId,
    InvalidScreenSemantic,
    ArithmeticOverflow,
};

fn narrowExternalSourceSealError(
    err: ExternalAdoptionInspectError,
) ExternalSourceSealError {
    return switch (err) {
        // Source sealing is allocation-free today. If a future validation leaf accidentally
        // exposes allocation failure through the broad legacy inspect error set, fail closed
        // instead of turning that maintenance drift into a runtime trap.
        error.OutOfMemory => error.InvalidClientState,
        else => |source_err| source_err,
    };
}

pub const ClientSourceSeal = struct {
    client_address: usize,
    target_stream: u64,
    attach_instance_id: u64,
    raw_next_request_id: u64,
    raw_last_success_request_id: u64,
    screen_source_count: usize,
    screen_payload_bytes: usize,
    event_count: usize,
    event_payload_bytes: usize,
    digest: client_source_transcript.Digest,
};

pub const InitialMetadataBinding = union(enum) {
    unsupported,
    unavailable,
    current: struct {
        seed: *const runtime_metadata_wire.InitialMetadataSeed,
        seal: runtime_metadata_wire.MetadataSeedSeal,
    },
};

pub const ExternalAdoptionFoldInput = struct {
    identity: runtime_event_types.EventIdentity,
    authority: FoldAuthority,
    initial_metadata: InitialMetadataBinding,
};

pub const FoldAuthority = runtime_event_reducer.Authority;

pub const InitialMetadataBindingSeal = union(enum) {
    unsupported,
    unavailable,
    current: struct {
        seed_address: usize,
        seal: runtime_metadata_wire.MetadataSeedSeal,
    },
};

pub const ExternalAdoptionFoldBindingSeal = struct {
    client_address: usize,
    attach_instance_id: u64,
    identity: runtime_event_types.EventIdentity,
    initial_authority: FoldAuthority,
    initial_metadata: InitialMetadataBindingSeal,
};

pub const ExternalAdoptionFoldResult = struct {
    binding_seal: ExternalAdoptionFoldBindingSeal,
    source_seal: ClientSourceSeal,
    outcome: runtime_event_reducer.Outcome,
};

pub const ExternalAdoptionFoldError = ExternalSourceSealError || error{
    InvalidInitialBinding,
};

pub const ExternalMetadataMaterializeError =
    runtime_metadata_wire.DecodeError || error{
        InvalidAllocator,
        InvalidCandidate,
        StaleSource,
    };

const ExternalSourceSealEncoding = enum {
    process_identity,
    canonical_test,

    fn address(self: ExternalSourceSealEncoding, actual: usize, token: usize) usize {
        return switch (self) {
            .process_identity => actual,
            .canonical_test => if (actual == 0) 0 else token,
        };
    }

    fn fd(self: ExternalSourceSealEncoding, actual: c.fd_t) i32 {
        return switch (self) {
            .process_identity => @intCast(actual),
            .canonical_test => 42,
        };
    }
};

const ExternalSourceSealEncoder = struct {
    writer: client_source_transcript.Writer,
    encoding: ExternalSourceSealEncoding,
    client_address: usize,
    target_stream: u64,
    attach_instance_id: u64,
    raw_next_request_id: u64,
    raw_last_success_request_id: u64,
    screen_source_count: usize,
    screen_payload_bytes: usize,
    event_payload_bytes: usize,
    batch_count: usize,
    stream_count: usize,
    event_count: usize,
    next_batch: usize = 0,
    next_stream: usize = 0,
    next_event: usize = 0,
    finished: bool = false,

    fn init(
        self: *ExternalSourceSealEncoder,
        client: *const Client,
        target_stream: u64,
        validated: ExternalValidatedAdoption,
        encoding: ExternalSourceSealEncoding,
    ) ExternalSourceSealError!void {
        if (!client.terminalReasonInvariant()) return error.InvalidClientState;
        var writer = client_source_transcript.Writer.init(.client_source_v1);
        try writer.writeUsize(encoding.address(@intFromPtr(client), 0x1000));
        writer.writeU64(target_stream);
        try writeSourceAllocator(&writer, client.allocator, encoding, 0x1100);
        writer.writeI32(encoding.fd(client.fd));
        writer.writeU128(client.host_id);

        writer.writePresence(client.build_id != null);
        if (client.build_id) |build_id| {
            try writer.writeAddressLenCapacity(
                encoding.address(@intFromPtr(build_id.ptr), 0x1200),
                build_id.len,
                build_id.len,
                1,
            );
            try writer.writeBytes(build_id);
        }
        writer.writeU64(client.upgrade_epoch);
        writer.writeU64(client.authority_generation);
        try writer.writeAddressLenCapacity(
            encoding.address(externalSliceAddress(client.lifecycle), 0x1300),
            client.lifecycle.len,
            client.lifecycle.len,
            1,
        );
        try writer.writeBytes(client.lifecycle);

        writer.writeBool(client.host_manifest_v1);
        writer.writeBool(client.host_exec_upgrade_v1);
        writer.writeBool(client.runtime_inventory_v1);
        writer.writeBool(client.runtime_catchup_barrier_v1);
        writer.writeBool(client.attachment_capabilities.peer_attach_generation);
        writer.writeBool(client.attachment_capabilities.negotiated_controller_transfer);
        writer.writeTag(@intFromEnum(client.metadata_support));
        writer.writeBool(client.admin_one_shot_v1);
        writer.writeBool(client.admin_runtime_end_v1);
        writer.writeU16(client.wire_major);
        writer.writeU16(client.screen_codec_version);
        writer.writeBool(client.screen_viewport_scrolled_v1);
        writer.writeBool(client.async_scroll_to_bottom_v1);
        writer.writeBool(client.runtime_core_command_v1);
        writer.writeBool(client.runtime_clear_screen_v1);
        writer.writeBool(client.runtime_selected_text_v1);
        writer.writeBool(client.runtime_selection_state_v1);
        writer.writeBool(client.notification_stream_auth_v1);
        writer.writeBool(client.notification_delivery_v1);
        writer.writeBool(client.runtime_link_at_v1);
        writer.writeBool(client.runtime_clipboard_v1);
        writer.writeTag(@intFromEnum(client.connection_profile.?));
        try writeSourceCompatibilityProfile(&writer, client.compatibility_profile.?);
        writer.writeU64(client.attach_instance_id);
        writer.writeU64(client.incident_binding.client_addr);
        writer.writeU128(client.incident_binding.host_id);
        writer.writeU64(client.incident_binding.host_adapter_generation);
        writer.writeU64(client.incident_binding.connection_generation);
        writer.writeU16(client.incident_binding.wire_major);
        writer.writeU8(client.incident_binding.host_class_raw);
        try writer.writeBytes(&client.incident_binding.seal);
        writer.writeTag(@intFromEnum(client.ownership));
        writer.writeBool(client.unusable);
        writer.writeBool(client.first_poison_reason != null);
        if (client.first_poison_reason) |reason| writer.writeTag(@intFromEnum(reason));
        writer.writeU128(client.first_incident_id.app_instance_nonce);
        writer.writeU64(client.first_incident_id.sequence);
        try writer.writeBytes(std.mem.asBytes(&client.incident_repeat_key));
        writer.writeU64(client.next_request_id);
        writer.writeU64(client.last_success_request_id);

        try writeSourceAllocator(&writer, client.parser.allocator, encoding, 0x1400);
        writer.writeU16(client.parser.expected_major);
        try writeSourceArrayDescriptor(
            &writer,
            externalArrayDescriptor(client.parser.buf),
            @sizeOf(u8),
            encoding,
            0x1500,
        );
        try writer.writeUsize(client.parser.head);
        try writer.writeBytes(client.parser.buf.items);

        try writeSourceArrayDescriptor(
            &writer,
            externalArrayDescriptor(client.pending_batches),
            @sizeOf(StreamBatch),
            encoding,
            0x1600,
        );
        try writer.writeUsize(client.pending_batch_bytes);
        try writeSourceArrayDescriptor(
            &writer,
            externalArrayDescriptor(client.pending_stream),
            @sizeOf(framing.Frame),
            encoding,
            0x1700,
        );
        try writer.writeUsize(client.pending_stream_bytes);
        try writeSourceArrayDescriptor(
            &writer,
            externalArrayDescriptor(client.pending_events),
            @sizeOf(BufferedEvent),
            encoding,
            0x1800,
        );
        try writer.writeUsize(client.pending_event_bytes);

        writer.writePresence(client.partial_batch != null);
        if (client.partial_batch) |partial| {
            writer.writeU64(partial.stream_id);
            writer.writeBool(partial.is_snapshot);
            try writeSourceArrayDescriptor(
                &writer,
                externalArrayDescriptor(partial.bytes),
                @sizeOf(u8),
                encoding,
                0x1900,
            );
            try writer.writeUsize(partial.chunk_count);
            try writer.writeBytes(partial.bytes.items);
        }

        const external = client.io_mode.external;
        writer.writeTag(1);
        writer.writeI32(external.saved_flags);
        try writeSourceArrayDescriptor(
            &writer,
            externalArrayDescriptor(external.external_tx),
            @sizeOf(client_external_mode.ExternalTxFrame),
            encoding,
            0x1a00,
        );
        try writer.writeUsize(external.external_tx_bytes);
        try writer.writeUsize(external.external_tx_retiring_bytes);
        try writer.writeUsize(external.external_tx_quarantined_bytes);
        writer.writeU64(external.tx_queue_generation);
        writer.writePresence(external.tx_head_progress_baseline_ns != null);
        if (external.tx_head_progress_baseline_ns) |value|
            writer.writeU128(@bitCast(value));
        writer.writePresence(external.tx_last_observed_now_ns != null);
        if (external.tx_last_observed_now_ns) |value|
            writer.writeU128(@bitCast(value));
        writer.writeBool(external.tx_immediate_pending);

        try writer.writeUsize(validated.screen_source_count);
        try writer.writeUsize(validated.screen_payload_bytes);
        try writer.writeUsize(client.pending_events.items.len);
        try writer.writeUsize(validated.event_payload_bytes);
        try writer.writeUsize(client.pending_batches.items.len);
        try writer.writeUsize(client.pending_stream.items.len);
        try writer.writeUsize(client.pending_events.items.len);

        self.* = .{
            .writer = writer,
            .encoding = encoding,
            .client_address = @intFromPtr(client),
            .target_stream = target_stream,
            .attach_instance_id = client.attach_instance_id,
            .raw_next_request_id = client.next_request_id,
            .raw_last_success_request_id = client.last_success_request_id,
            .screen_source_count = validated.screen_source_count,
            .screen_payload_bytes = validated.screen_payload_bytes,
            .event_payload_bytes = validated.event_payload_bytes,
            .batch_count = client.pending_batches.items.len,
            .stream_count = client.pending_stream.items.len,
            .event_count = client.pending_events.items.len,
        };
    }

    fn writeBatch(
        self: *ExternalSourceSealEncoder,
        client: *const Client,
        ordinal: usize,
        batch: *const StreamBatch,
    ) ExternalSourceSealError!void {
        if (self.finished) return error.InvalidClientState;
        if (@intFromPtr(client) != self.client_address or
            ordinal != self.next_batch or ordinal >= self.batch_count or
            batch != &client.pending_batches.items[ordinal] or
            self.next_stream != 0 or self.next_event != 0)
            return error.InvalidClientState;
        try self.writer.writeUsize(ordinal);
        self.writer.writeU64(batch.stream_id);
        self.writer.writeBool(batch.is_snapshot);
        const token_base = 0x2000 + ordinal * 0x10;
        try writeSourceAllocator(
            &self.writer,
            batch.allocator,
            self.encoding,
            token_base,
        );
        try self.writer.writeAddressLenCapacity(
            self.encoding.address(externalSliceAddress(batch.bytes), token_base + 2),
            batch.bytes.len,
            batch.bytes.len,
            1,
        );
        try self.writer.writeBytes(batch.bytes);
        self.next_batch += 1;
    }

    fn writeStream(
        self: *ExternalSourceSealEncoder,
        client: *const Client,
        ordinal: usize,
        frame: *const framing.Frame,
    ) ExternalSourceSealError!void {
        if (self.finished) return error.InvalidClientState;
        if (@intFromPtr(client) != self.client_address or
            self.next_batch != self.batch_count or ordinal != self.next_stream or
            ordinal >= self.stream_count or
            frame != &client.pending_stream.items[ordinal] or self.next_event != 0)
            return error.InvalidClientState;
        try self.writer.writeUsize(ordinal);
        try writeSourceFrame(
            &self.writer,
            frame.header,
            frame.payload,
            self.encoding,
            0x4000 + ordinal,
        );
        self.next_stream += 1;
    }

    fn writeEvent(
        self: *ExternalSourceSealEncoder,
        client: *const Client,
        ordinal: usize,
        frame: *const BufferedEvent,
    ) ExternalSourceSealError!void {
        if (self.finished) return error.InvalidClientState;
        if (@intFromPtr(client) != self.client_address or
            self.next_batch != self.batch_count or
            self.next_stream != self.stream_count or ordinal != self.next_event or
            ordinal >= self.event_count or
            frame != &client.pending_events.items[ordinal])
            return error.InvalidClientState;
        try self.writer.writeUsize(ordinal);
        try writeSourceFrame(
            &self.writer,
            frame.header,
            frame.payload,
            self.encoding,
            0x6000 + ordinal,
        );
        self.next_event += 1;
    }

    fn finish(
        self: *ExternalSourceSealEncoder,
    ) ExternalSourceSealError!ClientSourceSeal {
        if (self.finished) return error.InvalidClientState;
        if (self.next_batch != self.batch_count or
            self.next_stream != self.stream_count or
            self.next_event != self.event_count)
            return error.InvalidClientState;
        self.finished = true;
        return .{
            .client_address = self.client_address,
            .target_stream = self.target_stream,
            .attach_instance_id = self.attach_instance_id,
            .raw_next_request_id = self.raw_next_request_id,
            .raw_last_success_request_id = self.raw_last_success_request_id,
            .screen_source_count = self.screen_source_count,
            .screen_payload_bytes = self.screen_payload_bytes,
            .event_count = self.event_count,
            .event_payload_bytes = self.event_payload_bytes,
            .digest = self.writer.finish(),
        };
    }
};

fn writeSourceAllocator(
    writer: *client_source_transcript.Writer,
    allocator: std.mem.Allocator,
    encoding: ExternalSourceSealEncoding,
    token_base: usize,
) client_source_transcript.Error!void {
    try writer.writeUsize(encoding.address(@intFromPtr(allocator.ptr), token_base));
    try writer.writeUsize(encoding.address(@intFromPtr(allocator.vtable), token_base + 1));
}

fn writeSourceArrayDescriptor(
    writer: *client_source_transcript.Writer,
    descriptor: ExternalArrayDescriptor,
    element_size: usize,
    encoding: ExternalSourceSealEncoding,
    token: usize,
) client_source_transcript.Error!void {
    try writer.writeAddressLenCapacity(
        encoding.address(descriptor.address, token),
        descriptor.len,
        descriptor.capacity,
        element_size,
    );
}

fn writeSourceCompatibilityProfile(
    writer: *client_source_transcript.Writer,
    profile: compatibility.Profile,
) client_source_transcript.Error!void {
    writer.writeTag(@intFromEnum(profile.kind));
    writer.writeU16(profile.wire_major);
    writer.writeU16(profile.screen_codec_version);
    writer.writePresence(profile.required_fingerprint != null);
    if (profile.required_fingerprint) |fingerprint|
        try writer.writeBytes(fingerprint);
    writer.writeTag(@intFromEnum(profile.attach_schema));
}

fn writeSourceFrame(
    writer: *client_source_transcript.Writer,
    header: protocol.Header,
    payload: []const u8,
    encoding: ExternalSourceSealEncoding,
    token: usize,
) client_source_transcript.Error!void {
    writer.writeU16(header.major);
    writer.writeU16(@intFromEnum(header.kind));
    writer.writeU32(header.flags);
    writer.writeU64(header.request_id);
    writer.writeU64(header.stream_id);
    writer.writeU32(header.payload_len);
    try writer.writeAddressLenCapacity(
        encoding.address(externalSliceAddress(payload), token),
        payload.len,
        payload.len,
        1,
    );
    try writer.writeBytes(payload);
}

fn encodeExternalSourceForTest(
    client: *const Client,
    target_stream: u64,
    scratch: *ExternalSourceOwnerRangeScratch,
) ExternalSourceSealError!ClientSourceSeal {
    return encodeExternalSourceWithEncodingForTest(
        client,
        target_stream,
        scratch,
        .process_identity,
    );
}

fn encodeExternalSourceWithEncodingForTest(
    client: *const Client,
    target_stream: u64,
    scratch: *ExternalSourceOwnerRangeScratch,
    encoding: ExternalSourceSealEncoding,
) ExternalSourceSealError!ClientSourceSeal {
    validateExternalAdoptionSourceEligibility(
        client,
        target_stream,
        .allow_zero,
        .require_empty,
    ) catch |err|
        return narrowExternalSourceSealError(err);
    if (client.event_parse_observer != null or client.attach_instance_id == 0)
        return error.InvalidClientState;
    _ = validateExternalSourceOwnerRanges(client, scratch) catch |err|
        return narrowExternalSourceSealError(err);
    const validated = validateExternalAdoptionSourceQueues(client, target_stream) catch |err|
        return narrowExternalSourceSealError(err);
    var encoder: ExternalSourceSealEncoder = undefined;
    try encoder.init(client, target_stream, validated, encoding);
    for (client.pending_batches.items, 0..) |*batch, ordinal|
        try encoder.writeBatch(client, ordinal, batch);
    for (client.pending_stream.items, 0..) |*frame, ordinal|
        try encoder.writeStream(client, ordinal, frame);
    for (client.pending_events.items, 0..) |*frame, ordinal|
        try encoder.writeEvent(client, ordinal, frame);
    return encoder.finish();
}

fn externalSourceSealMatches(
    client: *const Client,
    target_stream: u64,
    expected: ClientSourceSeal,
    scratch: *ExternalSourceOwnerRangeScratch,
) bool {
    const actual = encodeExternalSourceForTest(client, target_stream, scratch) catch return false;
    return std.meta.eql(expected, actual);
}

const FoldMetadataSources = struct {
    client: *const Client,
    identity: runtime_event_types.EventIdentity,
    initial: ?struct {
        seed: *const runtime_metadata_wire.InitialMetadataSeed,
        seal: runtime_metadata_wire.MetadataSeedSeal,
    } = null,
    current_ordinal: u32 = 0,

    fn validateInitial(
        self: *const FoldMetadataSources,
        expected: runtime_event_reducer.InitialMetadataSeed,
    ) bool {
        const initial = self.initial orelse return false;
        return runtime_metadata_wire.validateMetadataSeedSeal(
            initial.seal,
            initial.seed,
        ) and initial.seal.tag == .current and
            expected.revision == initial.seal.revision and
            std.mem.eql(u8, &expected.raw_digest, &initial.seal.raw_digest) and
            std.mem.eql(
                u8,
                &expected.semantic_digest,
                &initial.seal.semantic_digest,
            );
    }

    fn compareMetadata(
        self: *const FoldMetadataSources,
        current: runtime_event_reducer.MetadataCandidate,
        next_payload: []const u8,
        next_preflight: runtime_event_wire.EventPreflight,
    ) runtime_event_reducer.MetadataComparison {
        return switch (current.origin) {
            .initial => {
                const initial = self.initial orelse return .stale;
                if (!runtime_metadata_wire.metadataSeedSemanticEqlEvent(
                    initial.seed,
                    initial.seal,
                    next_payload,
                    next_preflight,
                )) return .different;
                return .equal;
            },
            .event => |ordinal| {
                if (ordinal >= self.current_ordinal or
                    ordinal >= self.client.pending_events.items.len)
                    return .stale;
                const frame = self.client.pending_events.items[ordinal];
                if (frame.preflight != null or frame.admission_seal != null or
                    frame.header.major != self.client.wire_major or
                    frame.header.kind != .event or
                    frame.header.stream_id != self.identity.stream_id or
                    frame.header.request_id != 0 or frame.header.flags != 0 or
                    frame.header.payload_len != frame.payload.len or
                    frame.payload.len > protocol.max_control_json)
                    return .stale;
                const rebound = switch (runtime_event_wire.preflightEvent(
                    frame.payload,
                    .{
                        .runtime_id = self.identity.runtime_id,
                        .stream_id = self.identity.stream_id,
                    },
                )) {
                    .accepted => |value| value,
                    else => return .stale,
                };
                const proof = switch (current.proof) {
                    .event => |value| value,
                    .initial => return .stale,
                };
                if (!runtime_event_wire.eventPreflightEql(rebound, proof) or
                    !std.mem.eql(u8, &rebound.raw_digest, &current.raw_digest))
                    return .stale;
                const current_view = switch (rebound.event) {
                    .metadata => |value| value,
                    else => return .stale,
                };
                const next_view = switch (next_preflight.event) {
                    .metadata => |value| value,
                    else => return .stale,
                };
                return if (runtime_event_wire.metadataSemanticEqlExact(
                    frame.payload,
                    &current_view,
                    next_payload,
                    &next_view,
                )) .equal else .different;
            },
        };
    }
};

fn sourceRangeOverlapsProvenOwners(
    scratch: *const ExternalSourceOwnerRangeScratch,
    range_count: usize,
    target: ExternalRange,
) bool {
    for (scratch.ranges[0..range_count]) |range|
        if (externalRangesOverlap(target, range)) return true;
    return false;
}

fn validateFoldInputBeforeScratch(
    client: *const Client,
    input: ExternalAdoptionFoldInput,
    scratch: *ExternalSourceOwnerRangeScratch,
) ExternalAdoptionFoldError!FoldMetadataSources {
    if (input.identity.runtime_id == 0 or input.identity.stream_id == 0)
        return error.InvalidInitialBinding;
    const profile = client.compatibility_profile orelse
        return error.InvalidCompatibilityProvenance;
    switch (profile.attach_schema) {
        .frozen_controller_only => if (input.authority.role != .controller or
            input.authority.generation != .untracked)
            return error.InvalidInitialBinding,
        .granted_roles => if (client.attachment_capabilities.peer_attach_generation) {
            const generation = switch (input.authority.generation) {
                .untracked => return error.InvalidInitialBinding,
                .tracked => |value| value,
            };
            if (input.authority.role == .controller and generation == 0)
                return error.InvalidInitialBinding;
        } else if (input.authority.role != .observer or
            input.authority.generation != .untracked)
            return error.InvalidInitialBinding,
    }

    var sources = FoldMetadataSources{
        .client = client,
        .identity = input.identity,
    };
    switch (input.initial_metadata) {
        .unsupported => if (client.metadata_support != .unsupported)
            return error.InvalidInitialBinding,
        .unavailable => if (client.metadata_support != .supported)
            return error.InvalidInitialBinding,
        .current => |current| {
            if (client.metadata_support != .supported)
                return error.InvalidInitialBinding;
            const seed_range = externalRangeOfValue(current.seed);
            const scratch_range = externalRangeOfValue(scratch);
            if (externalRangesOverlap(seed_range, scratch_range) or
                externalRangesOverlap(seed_range, externalRangeOfValue(client)))
                return error.InvalidAlias;
            // Do not dereference `current.seed` until every nested Client owner has been
            // enumerated and proven disjoint below. The seal itself is scalar evidence.
            if (current.seal.seed_addr != @intFromPtr(current.seed) or
                current.seal.tag != .current)
                return error.InvalidInitialBinding;
            if (current.seal.backing_len != 0) {
                const backing = checkedExternalRange(
                    current.seal.backing_addr,
                    current.seal.backing_len,
                ) catch |err| return narrowExternalSourceSealError(err);
                if (backing == null or
                    externalRangesOverlap(backing.?, scratch_range) or
                    externalRangesOverlap(
                        backing.?,
                        externalRangeOfValue(client),
                    ))
                    return error.InvalidAlias;
            }
            sources.initial = .{
                .seed = current.seed,
                .seal = current.seal,
            };
        },
    }
    return sources;
}

fn validateFoldInitialAgainstProvenOwners(
    sources: FoldMetadataSources,
    scratch: *const ExternalSourceOwnerRangeScratch,
    range_count: usize,
) ExternalAdoptionFoldError!void {
    const initial = sources.initial orelse return;
    const seed_range = externalRangeOfValue(initial.seed);
    if (sourceRangeOverlapsProvenOwners(scratch, range_count, seed_range))
        return error.InvalidAlias;
    if (initial.seal.backing_len != 0) {
        const backing = checkedExternalRange(
            initial.seal.backing_addr,
            initial.seal.backing_len,
        ) catch |err| return narrowExternalSourceSealError(err);
        if (backing == null or
            sourceRangeOverlapsProvenOwners(scratch, range_count, backing.?))
            return error.InvalidAlias;
    }
}

fn foldBindingSeal(
    client: *const Client,
    input: ExternalAdoptionFoldInput,
    sources: FoldMetadataSources,
) ExternalAdoptionFoldBindingSeal {
    return .{
        .client_address = @intFromPtr(client),
        .attach_instance_id = client.attach_instance_id,
        .identity = input.identity,
        .initial_authority = input.authority,
        .initial_metadata = if (sources.initial) |initial|
            .{ .current = .{
                .seed_address = @intFromPtr(initial.seed),
                .seal = initial.seal,
            } }
        else switch (input.initial_metadata) {
            .unsupported => .unsupported,
            .unavailable => .unavailable,
            .current => unreachable,
        },
    };
}

fn eventFrameView(frame: BufferedEvent) runtime_event_types.EventFrameView {
    return .{
        .major = frame.header.major,
        .kind = frame.header.kind,
        .stream_id = frame.header.stream_id,
        .request_id = frame.header.request_id,
        .flags = frame.header.flags,
        .payload_len = frame.header.payload_len,
        .payload = frame.payload,
    };
}

fn rawExternalScreenMetrics(
    client: *const Client,
) ExternalSourceSealError!ExternalValidatedScreenSource {
    var count = std.math.add(
        usize,
        client.pending_batches.items.len,
        client.pending_stream.items.len,
    ) catch return error.ArithmeticOverflow;
    var bytes: usize = 0;
    for (client.pending_batches.items) |batch|
        bytes = std.math.add(usize, bytes, batch.bytes.len) catch
            return error.ArithmeticOverflow;
    for (client.pending_stream.items) |frame|
        bytes = std.math.add(usize, bytes, frame.payload.len) catch
            return error.ArithmeticOverflow;
    if (client.partial_batch) |partial| {
        count = std.math.add(usize, count, 1) catch
            return error.ArithmeticOverflow;
        bytes = std.math.add(usize, bytes, partial.bytes.items.len) catch
            return error.ArithmeticOverflow;
    }
    return .{
        .screen_source_count = count,
        .screen_payload_bytes = bytes,
    };
}

fn foldExternalAdoptionSourceWithEncoding(
    client: *const Client,
    input: ExternalAdoptionFoldInput,
    scratch: *ExternalSourceOwnerRangeScratch,
    encoding: ExternalSourceSealEncoding,
) ExternalAdoptionFoldError!ExternalAdoptionFoldResult {
    validateExternalAdoptionSourceEligibility(
        client,
        input.identity.stream_id,
        .allow_zero,
        .require_empty,
    ) catch |err| return narrowExternalSourceSealError(err);
    if (client.event_parse_observer != null or client.attach_instance_id == 0)
        return error.InvalidClientState;
    var sources = try validateFoldInputBeforeScratch(client, input, scratch);
    const source_stats = validateExternalSourceOwnerRanges(client, scratch) catch |err|
        return narrowExternalSourceSealError(err);
    try validateFoldInitialAgainstProvenOwners(
        sources,
        scratch,
        source_stats.total_ranges,
    );
    if (sources.initial) |initial|
        if (!runtime_metadata_wire.validateMetadataSeedSeal(
            initial.seal,
            initial.seed,
        ))
            return error.InvalidInitialBinding;

    const screen = try rawExternalScreenMetrics(client);
    const screen_structure_valid = if (validateExternalAdoptionScreenSourceQueues(
        client,
        input.identity.stream_id,
    )) |_| true else |_| false;
    const claimed = ExternalValidatedAdoption{
        .screen_source_count = screen.screen_source_count,
        .screen_payload_bytes = screen.screen_payload_bytes,
        .event_payload_bytes = client.pending_event_bytes,
    };
    var encoder: ExternalSourceSealEncoder = undefined;
    try encoder.init(client, input.identity.stream_id, claimed, encoding);
    var reducer: runtime_event_reducer.Accumulator = .{};
    if (sources.initial) |initial| {
        const seed = runtime_event_reducer.InitialMetadataSeed{
            .revision = initial.seal.revision,
            .raw_digest = initial.seal.raw_digest,
            .semantic_digest = initial.seal.semantic_digest,
        };
        runtime_event_reducer.Accumulator.initWithMetadataInPlace(
            &reducer,
            input.authority,
            seed,
            &sources,
            FoldMetadataSources.validateInitial,
        );
    } else {
        runtime_event_reducer.Accumulator.initInPlace(
            &reducer,
            input.authority,
        );
    }
    if (!screen_structure_valid)
        reducer.recordTransportViolation(.screen_structure);

    for (client.pending_batches.items, 0..) |*batch, ordinal|
        try encoder.writeBatch(client, ordinal, batch);
    for (client.pending_stream.items, 0..) |*frame, ordinal|
        try encoder.writeStream(client, ordinal, frame);

    var event_bytes: usize = 0;
    var event_counter_overflow = false;
    for (client.pending_events.items, 0..) |*frame, ordinal| {
        const event_ordinal = std.math.cast(u32, ordinal) orelse
            return error.InvalidCounter;
        try encoder.writeEvent(client, ordinal, frame);
        if (frame.preflight != null or frame.admission_seal != null)
            reducer.recordTransportViolation(.event_cache_contamination);
        const verdict = runtime_event_wire.preflightEvent(
            frame.payload,
            .{
                .runtime_id = input.identity.runtime_id,
                .stream_id = input.identity.stream_id,
            },
        );
        sources.current_ordinal = event_ordinal;
        reducer.stepAt(
            &sources,
            FoldMetadataSources.compareMetadata,
            event_ordinal,
            .{
                .identity = input.identity,
                .preflight = .{
                    .expected_major = client.wire_major,
                    .metadata_support = client.metadata_support,
                    .verdict = verdict,
                },
                .frame = eventFrameView(frame.*),
            },
        );
        event_bytes = std.math.add(
            usize,
            event_bytes,
            frame.payload.len,
        ) catch blk: {
            event_counter_overflow = true;
            break :blk event_bytes;
        };
    }
    if (event_counter_overflow or event_bytes != client.pending_event_bytes)
        reducer.recordTransportViolation(.event_counter_mismatch);
    return .{
        .binding_seal = foldBindingSeal(client, input, sources),
        .source_seal = try encoder.finish(),
        .outcome = reducer.finalize(),
    };
}

const ExternalOwnerRangeProofLifecycle = enum { empty, prepared, aborted };

/// Retains the last whole-Client alias-proof scratch allocation across the paired ownership take.
///
/// Preparing this token performs the final allocator callback. Validation after preparation is
/// allocation-free, and deinit is intentionally delayed until the source Client has become a
/// tombstone. This closes the otherwise unavoidable `free` callback window between the last
/// owner-range proof and the no-callback ownership suffix.
pub const PreparedExternalOwnerRangeProof = struct {
    saved_self_addr: usize = 0,
    client_addr: usize = 0,
    allocator: std.mem.Allocator = std.heap.page_allocator,
    cleanup_allocator: std.mem.Allocator = std.heap.page_allocator,
    allocator_ptr_addr: usize = 0,
    allocator_vtable_addr: usize = 0,
    snapshot: ?ExternalAdoptionSnapshot = null,
    first_target: ExternalRange = .{ .start = 0, .len = 0 },
    second_target: ExternalRange = .{ .start = 0, .len = 0 },
    ranges: []ExternalRange = &.{},
    cleanup_ranges: []ExternalRange = &.{},
    ranges_addr: usize = 0,
    ranges_len: usize = 0,
    lifecycle: ExternalOwnerRangeProofLifecycle = .empty,

    pub fn deinit(self: *PreparedExternalOwnerRangeProof) void {
        if (self.lifecycle != .prepared or
            self.saved_self_addr != @intFromPtr(self))
            return;
        const allocator = if (externalAllocatorMatchesSeal(
            self.allocator,
            self.allocator_ptr_addr,
            self.allocator_vtable_addr,
        ))
            self.allocator
        else if (externalAllocatorMatchesSeal(
            self.cleanup_allocator,
            self.allocator_ptr_addr,
            self.allocator_vtable_addr,
        ))
            self.cleanup_allocator
        else
            return;
        const ranges = if (externalOwnedSliceAddress(ExternalRange, self.ranges) ==
            self.ranges_addr and self.ranges.len == self.ranges_len)
            self.ranges
        else if (externalOwnedSliceAddress(ExternalRange, self.cleanup_ranges) ==
            self.ranges_addr and self.cleanup_ranges.len == self.ranges_len)
            self.cleanup_ranges
        else
            return;
        allocator.free(ranges);
        self.ranges = &.{};
        self.cleanup_ranges = &.{};
        self.snapshot = null;
        self.lifecycle = .aborted;
    }

    pub fn validate(
        self: *PreparedExternalOwnerRangeProof,
        client: *const Client,
        first_target_ptr: *const anyopaque,
        first_target_len: usize,
        second_target_ptr: *const anyopaque,
        second_target_len: usize,
    ) bool {
        if (self.lifecycle != .prepared or
            self.saved_self_addr != @intFromPtr(self) or
            self.client_addr != @intFromPtr(client) or
            !std.meta.eql(self.allocator, client.allocator) or
            !std.meta.eql(self.cleanup_allocator, client.allocator) or
            self.first_target.start != @intFromPtr(first_target_ptr) or
            self.first_target.len != first_target_len or
            self.second_target.start != @intFromPtr(second_target_ptr) or
            self.second_target.len != second_target_len or
            self.ranges_addr != externalOwnedSliceAddress(
                ExternalRange,
                self.ranges,
            ) or
            self.ranges_len != self.ranges.len or
            !sameExternalSlice(ExternalRange, self.ranges, self.cleanup_ranges) or
            !std.meta.eql(
                self.snapshot orelse return false,
                externalAdoptionSnapshotForProof(client) orelse return false,
            ))
            return false;
        _ = fillExternalOwnerRanges(client, self.ranges) catch return false;
        var comparisons: usize = 0;
        std.mem.sort(ExternalRange, self.ranges, &comparisons, externalRangeLessThan);
        const client_range = externalRangeOfValue(client);
        for (self.ranges, 0..) |range, index| {
            if (externalRangesOverlap(range, client_range) or
                externalRangesOverlap(range, self.first_target) or
                externalRangesOverlap(range, self.second_target))
                return false;
            if (index != 0 and externalRangesOverlap(self.ranges[index - 1], range))
                return false;
        }
        return true;
    }
};

fn externalSliceAddress(bytes: []const u8) usize {
    return if (bytes.len == 0) 0 else @intFromPtr(bytes.ptr);
}

fn sameExternalSlice(comptime T: type, left: []const T, right: []const T) bool {
    const left_address = if (left.len == 0) 0 else @intFromPtr(left.ptr);
    const right_address = if (right.len == 0) 0 else @intFromPtr(right.ptr);
    return left.len == right.len and left_address == right_address;
}

fn externalArrayDescriptor(list: anytype) ExternalArrayDescriptor {
    return .{
        .address = if (list.capacity == 0) 0 else @intFromPtr(list.items.ptr),
        .len = list.items.len,
        .capacity = list.capacity,
    };
}

fn externalListMatchesClient(
    comptime T: type,
    stored: std.ArrayListUnmanaged(T),
    live: std.ArrayListUnmanaged(T),
) bool {
    return stored.items.ptr == live.items.ptr and
        stored.items.len == live.items.len and
        stored.capacity == live.capacity;
}

fn externalListMatchesSeal(
    comptime T: type,
    primary: std.ArrayListUnmanaged(T),
    cleanup: std.ArrayListUnmanaged(T),
    seal: ExternalArrayDescriptor,
) bool {
    return externalListMatchesDescriptor(T, primary, seal) and
        externalListMatchesDescriptor(T, cleanup, seal);
}

fn externalListMatchesDescriptor(
    comptime T: type,
    list: std.ArrayListUnmanaged(T),
    seal: ExternalArrayDescriptor,
) bool {
    const descriptor = externalArrayDescriptor(list);
    return std.meta.eql(descriptor, seal);
}

fn canonicalExternalList(
    comptime T: type,
    primary: std.ArrayListUnmanaged(T),
    cleanup: std.ArrayListUnmanaged(T),
    seal: ExternalArrayDescriptor,
) ?std.ArrayListUnmanaged(T) {
    if (externalListMatchesClient(T, primary, cleanup) and
        externalListMatchesDescriptor(T, primary, seal))
        return primary;
    if (externalListMatchesDescriptor(T, primary, seal)) return primary;
    if (externalListMatchesDescriptor(T, cleanup, seal)) return cleanup;
    return null;
}

fn externalTakenPartialMatches(
    primary: ?ExternalAdoptionTakenPartial,
    cleanup: ?ExternalAdoptionTakenPartial,
    seal: ?ExternalPartialDescriptor,
    live: anytype,
) bool {
    if ((primary == null) != (seal == null) or
        (cleanup == null) != (seal == null) or
        (live == null) != (seal == null))
        return false;
    const expected = seal orelse return true;
    const a = primary.?;
    const b = cleanup.?;
    const current = live.?;
    return externalTakenPartialMatchesSeal(a, expected) and
        externalTakenPartialMatchesSeal(b, expected) and
        a.stream_id == current.stream_id and
        a.is_snapshot == current.is_snapshot and
        a.chunk_count == current.chunk_count and
        externalListMatchesClient(u8, a.bytes, current.bytes);
}

fn externalTakenPartialMatchesSeal(
    partial: ExternalAdoptionTakenPartial,
    seal: ExternalPartialDescriptor,
) bool {
    return partial.stream_id == seal.stream_id and
        partial.is_snapshot == seal.is_snapshot and
        partial.chunk_count == seal.chunk_count and
        externalListMatchesDescriptor(u8, partial.bytes, seal.bytes);
}

fn canonicalExternalTakenPartial(
    primary: ?ExternalAdoptionTakenPartial,
    cleanup: ?ExternalAdoptionTakenPartial,
    seal: ?ExternalPartialDescriptor,
) ?ExternalAdoptionTakenPartial {
    const expected = seal orelse return null;
    if (primary) |value|
        if (externalTakenPartialMatchesSeal(value, expected)) return value;
    if (cleanup) |value|
        if (externalTakenPartialMatchesSeal(value, expected)) return value;
    return null;
}

fn externalTakeCleanupAllocator(
    take: *const ExternalAdoptionTake,
) ?std.mem.Allocator {
    if (@intFromPtr(take.allocator.ptr) == take.allocator_ptr_addr and
        @intFromPtr(take.allocator.vtable) == take.allocator_vtable_addr)
        return take.allocator;
    if (@intFromPtr(take.cleanup_allocator.ptr) == take.allocator_ptr_addr and
        @intFromPtr(take.cleanup_allocator.vtable) == take.allocator_vtable_addr)
        return take.cleanup_allocator;
    return null;
}

fn externalOwnedBytes(address: usize, len: usize) []u8 {
    if (len == 0) return &.{};
    return @as([*]u8, @ptrFromInt(address))[0..len];
}

fn externalInventoryBackingSeal(
    inventory: *const ExternalAdoptionInventory,
) [32]u8 {
    var hasher = std.crypto.hash.Blake3.init(.{});
    hasher.update("maru.external-adoption-backing-seal.v1\x00");
    hasher.update("inventory-allocator\x00");
    externalDigestU64(&hasher, @intFromPtr(inventory.allocator.ptr));
    externalDigestU64(&hasher, @intFromPtr(inventory.allocator.vtable));
    hasher.update("inventory-backing\x00");
    inline for (.{
        inventory.batch_descriptors,
        inventory.stream_descriptors,
        inventory.event_descriptors,
        inventory.build_id_copy,
        inventory.lifecycle_copy,
    }) |backing| {
        externalDigestU64(
            &hasher,
            if (backing.len == 0) 0 else @intFromPtr(backing.ptr),
        );
        externalDigestU64(&hasher, backing.len);
    }
    var digest: [32]u8 = undefined;
    hasher.final(&digest);
    return digest;
}

fn externalInventoryCleanupSeal(
    inventory: *const ExternalAdoptionInventory,
) [32]u8 {
    // Ephemeral, process-local corruption seal; it is never persisted or sent on the wire. The
    // transcript is nevertheless explicitly versioned and self-delimiting because this digest
    // selects which mirror may supply allocator/pointer descriptors during teardown.
    var hasher = std.crypto.hash.Blake3.init(.{});
    hasher.update("maru.external-adoption-cleanup-seal.v1\x00");
    const backing_seal = externalInventoryBackingSeal(inventory);
    hasher.update("backing-seal\x00");
    hasher.update(&backing_seal);
    hasher.update("containers\x00");
    inline for (.{
        inventory.snapshot.pending_batches,
        inventory.snapshot.pending_stream,
        inventory.snapshot.pending_events,
    }) |descriptor| {
        externalDigestU64(&hasher, descriptor.address);
        externalDigestU64(&hasher, descriptor.len);
        externalDigestU64(&hasher, descriptor.capacity);
    }
    hasher.update("partial\x00");
    if (inventory.snapshot.partial) |partial| {
        hasher.update(&.{1});
        externalDigestU64(&hasher, partial.stream_id);
        hasher.update(&.{@intFromBool(partial.is_snapshot)});
        externalDigestU64(&hasher, partial.bytes.address);
        externalDigestU64(&hasher, partial.bytes.len);
        externalDigestU64(&hasher, partial.bytes.capacity);
        externalDigestU64(&hasher, partial.chunk_count);
    } else hasher.update(&.{0});
    hasher.update("batches\x00");
    externalDigestU64(&hasher, inventory.batch_descriptors.len);
    for (inventory.batch_descriptors) |descriptor| {
        externalDigestU64(&hasher, descriptor.stream_id);
        hasher.update(&.{@intFromBool(descriptor.is_snapshot)});
        externalDigestU64(&hasher, descriptor.bytes_address);
        externalDigestU64(&hasher, descriptor.bytes_len);
        externalDigestU64(&hasher, @intFromPtr(descriptor.allocator.ptr));
        externalDigestU64(&hasher, @intFromPtr(descriptor.allocator.vtable));
    }
    hasher.update("stream\x00");
    externalDigestU64(&hasher, inventory.stream_descriptors.len);
    for (inventory.stream_descriptors) |descriptor| {
        const encoded = descriptor.header.encode();
        hasher.update(&encoded);
        externalDigestU64(&hasher, descriptor.payload_address);
        externalDigestU64(&hasher, descriptor.payload_len);
    }
    hasher.update("events\x00");
    externalDigestU64(&hasher, inventory.event_descriptors.len);
    for (inventory.event_descriptors) |descriptor| {
        const encoded = descriptor.header.encode();
        hasher.update(&encoded);
        externalDigestU64(&hasher, descriptor.payload_address);
        externalDigestU64(&hasher, descriptor.payload_len);
    }
    hasher.update("build-id\x00");
    externalDigestU64(&hasher, inventory.build_id_copy.len);
    hasher.update(inventory.build_id_copy);
    hasher.update("lifecycle\x00");
    externalDigestU64(&hasher, inventory.lifecycle_copy.len);
    hasher.update(inventory.lifecycle_copy);
    var digest: [32]u8 = undefined;
    hasher.final(&digest);
    return digest;
}

fn writeProjectionBatches(
    writer: *owner_seal.Writer,
    batches: std.ArrayListUnmanaged(StreamBatch),
) void {
    writer.writeUsize(if (batches.capacity == 0) 0 else @intFromPtr(batches.items.ptr));
    writer.writeUsize(batches.items.len);
    writer.writeUsize(batches.capacity);
    for (batches.items) |batch| {
        writer.writeBool(batch.is_snapshot);
        writer.writeU64(batch.stream_id);
        writer.writeUsize(if (batch.bytes.len == 0) 0 else @intFromPtr(batch.bytes.ptr));
        writer.writeUsize(batch.bytes.len);
        writer.writeUsize(@intFromPtr(batch.allocator.ptr));
        writer.writeUsize(@intFromPtr(batch.allocator.vtable));
    }
}

fn writeProjectionFrames(
    writer: *owner_seal.Writer,
    frames: std.ArrayListUnmanaged(framing.Frame),
) void {
    writer.writeUsize(if (frames.capacity == 0) 0 else @intFromPtr(frames.items.ptr));
    writer.writeUsize(frames.items.len);
    writer.writeUsize(frames.capacity);
    for (frames.items) |frame| {
        writer.writeBytes(&frame.header.encode());
        writer.writeUsize(if (frame.payload.len == 0) 0 else @intFromPtr(frame.payload.ptr));
        writer.writeUsize(frame.payload.len);
    }
}

fn writeProjectionEvents(
    writer: *owner_seal.Writer,
    events: std.ArrayListUnmanaged(BufferedEvent),
) void {
    writer.writeUsize(if (events.capacity == 0) 0 else @intFromPtr(events.items.ptr));
    writer.writeUsize(events.items.len);
    writer.writeUsize(events.capacity);
    for (events.items) |event| {
        writer.writeBytes(&event.header.encode());
        writer.writeUsize(if (event.payload.len == 0) 0 else @intFromPtr(event.payload.ptr));
        writer.writeUsize(event.payload.len);
        writer.writeBool(event.preflight != null);
        writer.writeBool(event.admission_seal != null);
    }
}

fn writeProjectionCatchupBarriers(
    writer: *owner_seal.Writer,
    barriers: std.ArrayListUnmanaged(BufferedCatchupBarrier),
) void {
    writer.writeUsize(if (barriers.capacity == 0) 0 else @intFromPtr(barriers.items.ptr));
    writer.writeUsize(barriers.items.len);
    writer.writeUsize(barriers.capacity);
    for (barriers.items) |buffered| {
        writer.writeU64(buffered.stream_id);
        writer.writeU64(buffered.barrier.identity.subscription.value);
        writer.writeU128(buffered.barrier.identity.runtime_id);
        writer.writeU64(buffered.barrier.identity.connection.monotonic_id);
        writer.writeU64(buffered.barrier.identity.connection.slot_generation);
        writer.writeU128(buffered.barrier.identity.host_id);
        writer.writeU128(buffered.barrier.identity.request_nonce);
        writer.writeU64(buffered.barrier.target.generation);
        writer.writeU64(buffered.barrier.target.sequence);
    }
}

fn writeProjectionInventory(
    writer: *owner_seal.Writer,
    inventory: *const ExternalAdoptionInventory,
) void {
    writer.writeUsize(@intFromPtr(inventory.allocator.ptr));
    writer.writeUsize(@intFromPtr(inventory.allocator.vtable));
    writer.writeUsize(inventory.client_address);
    writer.writeU64(inventory.target_stream);
    writer.writeUsize(inventory.screen_source_count);
    writer.writeUsize(inventory.screen_payload_bytes);
    writer.writeUsize(inventory.event_count);
    writer.writeUsize(inventory.event_payload_bytes);
    writer.writeU64(inventory.next_request_id);
    const cleanup = externalInventoryCleanupSeal(inventory);
    writer.writeBytes(&cleanup);
}

fn externalInventoryBackingSealMatches(
    inventory: *const ExternalAdoptionInventory,
    expected: [32]u8,
) bool {
    const actual = externalInventoryBackingSeal(inventory);
    return std.mem.eql(u8, &actual, &expected);
}

fn externalDigestU64(hasher: anytype, value: anytype) void {
    var encoded: [8]u8 = undefined;
    std.mem.writeInt(u64, &encoded, @intCast(value), .little);
    hasher.update(&encoded);
}

fn canonicalExternalInventory(
    source: ExternalAdoptionInventory,
) ?ExternalAdoptionInventory {
    var result = source;
    const allocator = source.canonicalCleanupAllocator() orelse return null;
    result.allocator = allocator;
    result.sealed_allocator = allocator;
    inline for (.{
        .{
            ExternalBatchDescriptor,
            "batch_descriptors",
            "cleanup_batch_descriptors",
            "batch_descriptors_addr",
            "batch_descriptors_len",
        },
        .{
            ExternalFrameDescriptor,
            "stream_descriptors",
            "cleanup_stream_descriptors",
            "stream_descriptors_addr",
            "stream_descriptors_len",
        },
        .{
            ExternalFrameDescriptor,
            "event_descriptors",
            "cleanup_event_descriptors",
            "event_descriptors_addr",
            "event_descriptors_len",
        },
        .{
            u8,
            "build_id_copy",
            "cleanup_build_id_copy",
            "build_id_copy_addr",
            "build_id_copy_len",
        },
        .{
            u8,
            "lifecycle_copy",
            "cleanup_lifecycle_copy",
            "lifecycle_copy_addr",
            "lifecycle_copy_len",
        },
    }) |entry| {
        const canonical = canonicalExternalSlice(
            entry[0],
            @field(source, entry[1]),
            @field(source, entry[2]),
            @field(source, entry[3]),
            @field(source, entry[4]),
        ) orelse return null;
        @field(result, entry[1]) = canonical;
        @field(result, entry[2]) = canonical;
    }
    return if (result.hasSealedStorage()) result else null;
}

fn externalInventoriesHaveIndependentStorage(
    a: *const ExternalAdoptionInventory,
    b: *const ExternalAdoptionInventory,
) bool {
    inline for (.{
        .{ ExternalBatchDescriptor, a.batch_descriptors, b.batch_descriptors },
        .{ ExternalFrameDescriptor, a.stream_descriptors, b.stream_descriptors },
        .{ ExternalFrameDescriptor, a.event_descriptors, b.event_descriptors },
        .{ u8, a.build_id_copy, b.build_id_copy },
        .{ u8, a.lifecycle_copy, b.lifecycle_copy },
    }) |entry| {
        if (entry[1].len != 0 and
            externalRangesOverlap(
                .{
                    .start = @intFromPtr(entry[1].ptr),
                    .len = entry[1].len * @sizeOf(entry[0]),
                },
                .{
                    .start = @intFromPtr(entry[2].ptr),
                    .len = entry[2].len * @sizeOf(entry[0]),
                },
            ))
            return false;
    }
    return true;
}

fn externalTakeContainersMatchInventory(
    batches: std.ArrayListUnmanaged(StreamBatch),
    stream: std.ArrayListUnmanaged(framing.Frame),
    events: std.ArrayListUnmanaged(BufferedEvent),
    partial: ?ExternalAdoptionTakenPartial,
    cleanup_partial: ?ExternalAdoptionTakenPartial,
    partial_seal: ?ExternalPartialDescriptor,
    inventory: *const ExternalAdoptionInventory,
) bool {
    if (!std.meta.eql(externalArrayDescriptor(batches), inventory.snapshot.pending_batches) or
        !std.meta.eql(externalArrayDescriptor(stream), inventory.snapshot.pending_stream) or
        !std.meta.eql(externalArrayDescriptor(events), inventory.snapshot.pending_events) or
        batches.items.len != inventory.batch_descriptors.len or
        stream.items.len != inventory.stream_descriptors.len or
        events.items.len != inventory.event_descriptors.len or
        !std.meta.eql(partial_seal, inventory.snapshot.partial))
        return false;
    if (partial_seal == null)
        return partial == null and cleanup_partial == null;
    return canonicalExternalTakenPartial(
        partial,
        cleanup_partial,
        partial_seal,
    ) != null;
}

fn externalCleanupScratchAliases(
    scratch: *ExternalAdoptionCleanupScratch,
    take: *const ExternalAdoptionTake,
    batches: std.ArrayListUnmanaged(StreamBatch),
    stream: std.ArrayListUnmanaged(framing.Frame),
    events: std.ArrayListUnmanaged(BufferedEvent),
    payload_inventory: *const ExternalAdoptionInventory,
    primary_inventory: ?*const ExternalAdoptionInventory,
    mirror_inventory: ?*const ExternalAdoptionInventory,
) bool {
    const target = externalRangeOfValue(scratch);
    return externalTakeTargetAliases(
        target,
        take,
        batches,
        stream,
        events,
        payload_inventory,
        primary_inventory,
        mirror_inventory,
    );
}

fn externalTakeTargetAliases(
    target: ExternalRange,
    take: *const ExternalAdoptionTake,
    batches: std.ArrayListUnmanaged(StreamBatch),
    stream: std.ArrayListUnmanaged(framing.Frame),
    events: std.ArrayListUnmanaged(BufferedEvent),
    payload_inventory: *const ExternalAdoptionInventory,
    primary_inventory: ?*const ExternalAdoptionInventory,
    mirror_inventory: ?*const ExternalAdoptionInventory,
) bool {
    inline for (.{
        checkedExternalRange(
            take.saved_self_address,
            @sizeOf(ExternalAdoptionTake),
        ) catch return true,
        checkedExternalRange(take.client_address, @sizeOf(Client)) catch return true,
        checkedExternalRange(take.plan_address, @sizeOf(PreparedClientDisarm)) catch return true,
        checkedExternalRange(
            take.mirror_owner_address,
            @sizeOf(?ExternalAdoptionInventory),
        ) catch return true,
        checkedExternalRange(
            take.mirror_cleanup_owner_address,
            @sizeOf(?ExternalAdoptionInventory),
        ) catch return true,
        externalRangeForList(batches, StreamBatch) catch return true,
        externalRangeForList(stream, framing.Frame) catch return true,
        externalRangeForList(events, BufferedEvent) catch return true,
    }) |range| if (range) |present|
        if (externalRangesOverlap(target, present)) return true;
    if (payload_inventory.snapshot.partial) |partial| {
        const range = checkedExternalRange(
            partial.bytes.address,
            partial.bytes.capacity,
        ) catch return true;
        if (range) |present|
            if (externalRangesOverlap(target, present)) return true;
    }
    for (payload_inventory.batch_descriptors) |descriptor| {
        const range = checkedExternalRange(
            descriptor.bytes_address,
            descriptor.bytes_len,
        ) catch return true;
        if (range) |present|
            if (externalRangesOverlap(target, present)) return true;
    }
    for (payload_inventory.stream_descriptors) |descriptor| {
        const range = checkedExternalRange(
            descriptor.payload_address,
            descriptor.payload_len,
        ) catch return true;
        if (range) |present|
            if (externalRangesOverlap(target, present)) return true;
    }
    for (payload_inventory.event_descriptors) |descriptor| {
        const range = checkedExternalRange(
            descriptor.payload_address,
            descriptor.payload_len,
        ) catch return true;
        if (range) |present|
            if (externalRangesOverlap(target, present)) return true;
    }
    inline for (.{ primary_inventory, mirror_inventory }) |inventory|
        if (inventory) |present|
            if (externalDestinationOverlapsInventory(present, target) catch return true)
                return true;
    return false;
}

fn externalInventoryMetadataBytesForClient(
    self: *const Client,
) ExternalAdoptionInspectError!usize {
    var total: usize = 0;
    inline for (.{
        .{ self.pending_batches.items.len, @sizeOf(ExternalBatchDescriptor) },
        .{ self.pending_stream.items.len, @sizeOf(ExternalFrameDescriptor) },
        .{ self.pending_events.items.len, @sizeOf(ExternalFrameDescriptor) },
    }) |entry| {
        const bytes = std.math.mul(usize, entry[0], entry[1]) catch
            return error.ArithmeticOverflow;
        total = std.math.add(usize, total, bytes) catch return error.ArithmeticOverflow;
    }
    total = std.math.add(usize, total, if (self.build_id) |bytes| bytes.len else 0) catch
        return error.ArithmeticOverflow;
    total = std.math.add(usize, total, self.lifecycle.len) catch
        return error.ArithmeticOverflow;
    return total;
}

fn externalBatchDescriptor(batch: StreamBatch) ExternalBatchDescriptor {
    return .{
        .stream_id = batch.stream_id,
        .is_snapshot = batch.is_snapshot,
        .bytes_address = externalSliceAddress(batch.bytes),
        .bytes_len = batch.bytes.len,
        .allocator = batch.allocator,
    };
}

fn externalFrameDescriptor(frame: anytype) ExternalFrameDescriptor {
    return .{
        .header = frame.header,
        .payload_address = externalSliceAddress(frame.payload),
        .payload_len = frame.payload.len,
    };
}

fn writeEndedPurgeHeaderSeal(writer: *owner_seal.Writer, header: protocol.Header) void {
    const encoded = header.encode();
    writer.writeBytes(&encoded);
}

fn writeEndedPurgeBatchSeal(
    writer: *owner_seal.Writer,
    descriptor: ExternalBatchDescriptor,
    bytes: []const u8,
) void {
    writer.writeU64(descriptor.stream_id);
    writer.writeBool(descriptor.is_snapshot);
    writer.writeUsize(descriptor.bytes_address);
    writer.writeUsize(descriptor.bytes_len);
    writer.writeUsize(@intFromPtr(descriptor.allocator.ptr));
    writer.writeUsize(@intFromPtr(descriptor.allocator.vtable));
    writer.writeBytes(bytes);
}

fn writeEndedPurgeFrameSeal(
    writer: *owner_seal.Writer,
    descriptor: ExternalFrameDescriptor,
    payload: []const u8,
) void {
    writeEndedPurgeHeaderSeal(writer, descriptor.header);
    writer.writeUsize(descriptor.payload_address);
    writer.writeUsize(descriptor.payload_len);
    writer.writeBytes(payload);
}

fn writeEndedPurgePartialSeal(
    writer: *owner_seal.Writer,
    descriptor: ExternalPartialDescriptor,
    bytes: []const u8,
) void {
    writer.writeU64(descriptor.stream_id);
    writer.writeBool(descriptor.is_snapshot);
    writer.writeUsize(descriptor.bytes.address);
    writer.writeUsize(descriptor.bytes.len);
    writer.writeUsize(descriptor.bytes.capacity);
    writer.writeUsize(descriptor.chunk_count);
    writer.writeBytes(bytes);
}

fn endedPurgeTargetMapSeal(scratch: *const EndedPurgeScratch) owner_seal.Digest {
    var writer = owner_seal.Writer.init("maru.ended-purge.target-map.v1");
    inline for (.{
        &scratch.batch_targets,
        &scratch.stream_targets,
        &scratch.event_targets,
    }) |set| {
        var iterator = set.iterator(.{});
        while (iterator.next()) |index| writer.writeUsize(index);
        writer.writeUsize(std.math.maxInt(usize));
    }
    writer.writeBool(scratch.partial_target);
    return writer.finish();
}

const EndedPurgeRangeContext = struct {
    client: *const Client,
    comparisons: *usize,
    owner_lookups: *usize,
};

fn endedPurgeRangeForId(context: EndedPurgeRangeContext, id: u16) ExternalRange {
    context.owner_lookups.* += 1;
    return (ended_purge_owner_range_ssot(context.client, id) catch unreachable).?;
}

fn endedPurgeRangeLessThan(
    context: EndedPurgeRangeContext,
    left: u16,
    right: u16,
) bool {
    context.comparisons.* += 1;
    return endedPurgeRangeForId(context, left).start <
        endedPurgeRangeForId(context, right).start;
}

fn appendEndedPurgeRangeId(
    range_order: []u16,
    used: *usize,
    id: usize,
    range: ?ExternalRange,
) EndedPurgePrepareError!void {
    if (range == null) return;
    if (used.* >= range_order.len or id > std.math.maxInt(u16))
        return error.InvalidSource;
    range_order[used.*] = @intCast(id);
    used.* += 1;
}

fn endedPurgeCheckedDescriptorRange(
    descriptor: ExternalArrayDescriptor,
    element_size: usize,
) EndedPurgePrepareError!?ExternalRange {
    const bytes = std.math.mul(usize, descriptor.capacity, element_size) catch
        return error.ArithmeticOverflow;
    return checkedExternalRange(descriptor.address, bytes) catch |err| switch (err) {
        error.ArithmeticOverflow => error.ArithmeticOverflow,
        else => error.InvalidAlias,
    };
}

fn endedPurgeCheckedPayloadRange(
    address: usize,
    len: usize,
) EndedPurgePrepareError!?ExternalRange {
    return checkedExternalRange(address, len) catch |err| switch (err) {
        error.ArithmeticOverflow => error.ArithmeticOverflow,
        else => error.InvalidAlias,
    };
}

fn endedPurgeRangeOutsideProtected(
    range: ?ExternalRange,
    self: *const Client,
    scratch: *const EndedPurgeScratch,
    out: *const PreparedEndedPurgeInventory,
    additional_protected: ?ExternalRange,
) EndedPurgePrepareError!void {
    const present = range orelse return;
    inline for (.{ self, scratch, out }) |owner|
        if (externalRangesOverlap(present, externalRangeOfValue(owner)))
            return error.InvalidAlias;
    if (additional_protected) |protected|
        if (externalRangesOverlap(present, protected)) return error.InvalidAlias;
}

fn validateEndedPurgeOuterRanges(
    self: *const Client,
    scratch: *const EndedPurgeScratch,
    out: *const PreparedEndedPurgeInventory,
    additional_protected: ?ExternalRange,
) EndedPurgePrepareError!void {
    var ranges: [max_external_outer_owner_range_count]ExternalRange = undefined;
    const used = fillExternalOuterOwnerRanges(self, &ranges) catch |err| return switch (err) {
        error.ArithmeticOverflow => error.ArithmeticOverflow,
        else => error.InvalidSource,
    };
    for (ranges[0..used], 0..) |range, index| {
        try endedPurgeRangeOutsideProtected(range, self, scratch, out, additional_protected);
        for (ranges[0..index]) |prior|
            if (externalRangesOverlap(range, prior)) return error.InvalidAlias;
    }
}

const EndedPurgeOwnerRangeProofStats = struct {
    total_ranges: usize,
    comparisons: usize,
    owner_lookups: usize,
};

fn validateEndedPurgeOwnerRanges(
    self: *const Client,
    scratch: *EndedPurgeScratch,
    out: *const PreparedEndedPurgeInventory,
    additional_protected: ?ExternalRange,
    range_order: []u16,
) EndedPurgePrepareError!EndedPurgeOwnerRangeProofStats {
    var outer: [max_external_outer_owner_range_count]ExternalRange = undefined;
    const outer_count = fillExternalOuterOwnerRanges(self, &outer) catch |err| return switch (err) {
        error.ArithmeticOverflow => error.ArithmeticOverflow,
        else => error.InvalidSource,
    };
    const nested_count = externalNestedOwnerRangeCount(self) catch |err| return switch (err) {
        error.ArithmeticOverflow => error.ArithmeticOverflow,
        else => error.InvalidSource,
    };
    const count = std.math.add(usize, outer_count, nested_count) catch
        return error.ArithmeticOverflow;
    if (count > range_order.len) return error.InvalidSource;
    var used: usize = 0;
    for (0..count) |id| {
        const range = ended_purge_owner_range_ssot(self, id) catch |err| return switch (err) {
            error.ArithmeticOverflow => error.ArithmeticOverflow,
            else => error.InvalidSource,
        };
        try endedPurgeRangeOutsideProtected(range, self, scratch, out, additional_protected);
        try appendEndedPurgeRangeId(range_order, &used, id, range);
    }

    var comparisons: usize = 0;
    var owner_lookups: usize = 0;
    const context = EndedPurgeRangeContext{
        .client = self,
        .comparisons = &comparisons,
        .owner_lookups = &owner_lookups,
    };
    std.mem.sort(u16, range_order[0..used], context, endedPurgeRangeLessThan);
    for (range_order[0..used], 0..) |id, index| {
        const range = endedPurgeRangeForId(context, id);
        try endedPurgeRangeOutsideProtected(range, self, scratch, out, additional_protected);
        if (index != 0 and externalRangesOverlap(
            endedPurgeRangeForId(context, range_order[index - 1]),
            range,
        )) return error.InvalidAlias;
    }
    return .{
        .total_ranges = used,
        .comparisons = comparisons,
        .owner_lookups = owner_lookups,
    };
}

fn compatibilityProfilesEqual(a: compatibility.Profile, b: compatibility.Profile) bool {
    if (a.kind != b.kind or a.wire_major != b.wire_major or
        a.screen_codec_version != b.screen_codec_version or
        a.attach_schema != b.attach_schema)
        return false;
    if (a.required_fingerprint == null or b.required_fingerprint == null)
        return a.required_fingerprint == null and b.required_fingerprint == null;
    return std.mem.eql(u8, a.required_fingerprint.?, b.required_fingerprint.?);
}

const ExternalRequestIdPolicy = enum {
    require_nonzero,
    allow_zero,
};

const ExternalCatchupBarrierPolicy = enum {
    require_empty,
    allow_bounded,
};

const ExternalAdoptionValidationOptions = struct {
    owner_aliases: enum { skip, validate } = .skip,
    request_id: ExternalRequestIdPolicy = .require_nonzero,
    catchup_barriers: ExternalCatchupBarrierPolicy = .require_empty,
};

fn validateExternalAdoptionSourceEligibility(
    self: *const Client,
    target_stream: u64,
    request_id_policy: ExternalRequestIdPolicy,
    catchup_barrier_policy: ExternalCatchupBarrierPolicy,
) ExternalAdoptionInspectError!void {
    if (target_stream == 0) return error.InvalidStream;
    if (self.ownership != .external_pump or self.unusable or self.fd < 0)
        return error.InvalidClientState;
    const connection_profile = self.connection_profile orelse return error.IneligibleProfile;
    if (connection_profile != .cli_attach) return error.IneligibleProfile;
    const selected = self.compatibility_profile orelse
        return error.InvalidCompatibilityProvenance;
    const expected = compatibility.profileForMajor(self.wire_major) orelse
        return error.InvalidCompatibilityProvenance;
    if (!compatibilityProfilesEqual(selected, expected) or
        self.screen_codec_version != selected.screen_codec_version)
        return error.InvalidCompatibilityProvenance;
    try validateExternalAdoptionStructure(self, catchup_barrier_policy);
    if (!std.meta.eql(self.parser.allocator, self.allocator) or
        self.parser.expected_major != self.wire_major or
        self.parser.head > self.parser.buf.items.len)
        return error.InvalidClientState;
    if (request_id_policy == .require_nonzero and self.next_request_id == 0)
        return error.InvalidRequestId;
    if (self.pending_outbound != null) return error.InvalidClientState;
    switch (self.io_mode) {
        .blocking => return error.InvalidClientState,
        .external => |state| if (state.external_tx.items.len != 0 or
            state.external_tx_bytes != 0 or
            state.external_tx_retiring_bytes != 0 or
            state.external_tx_quarantined_bytes != 0 or
            state.tx_queue_generation != 1 or
            state.tx_head_progress_baseline_ns != null or
            state.tx_last_observed_now_ns != null or
            state.tx_immediate_pending or
            state.tx_cleanup_id != 0 or
            state.tx_cleanup_owner_addr != 0 or
            state.external_tx.items.len > state.external_tx.capacity or
            state.external_tx.capacity != client_external_mode.max_tx_frames)
            return error.InvalidClientState,
    }
}

fn validateExternalAdoptionSourceQueues(
    self: *const Client,
    target_stream: u64,
) ExternalAdoptionInspectError!ExternalValidatedAdoption {
    const screen = try validateExternalAdoptionScreenSourceQueues(self, target_stream);
    const event_payload_bytes = try validateExternalAdoptionEventSourceQueues(
        self,
        target_stream,
    );
    return .{
        .screen_source_count = screen.screen_source_count,
        .screen_payload_bytes = screen.screen_payload_bytes,
        .event_payload_bytes = event_payload_bytes,
    };
}

fn validateExternalAdoptionScreenSourceQueues(
    self: *const Client,
    target_stream: u64,
) ExternalAdoptionInspectError!ExternalValidatedScreenSource {
    var screen_count: usize = 0;
    var screen_bytes: usize = 0;
    var batch_bytes: usize = 0;
    for (self.pending_batches.items) |batch| {
        if (!std.meta.eql(batch.allocator, self.allocator)) return error.InvalidAllocator;
        if (batch.stream_id != target_stream) return error.InvalidStream;
        if (batch.bytes.len > protocol.max_viewport_snapshot)
            return error.InvalidScreenSemantic;
        batch_bytes = std.math.add(usize, batch_bytes, batch.bytes.len) catch
            return error.ArithmeticOverflow;
        screen_bytes = std.math.add(usize, screen_bytes, batch.bytes.len) catch
            return error.ArithmeticOverflow;
        screen_count = std.math.add(usize, screen_count, 1) catch
            return error.ArithmeticOverflow;
    }
    if (batch_bytes != self.pending_batch_bytes) return error.InvalidCounter;

    const max_chunks = protocol.max_viewport_snapshot / protocol.max_binary_chunk;
    var active_batch = false;
    var active_snapshot = false;
    var active_stream: u64 = 0;
    var active_chunks: usize = 0;
    var active_bytes: usize = 0;
    if (self.partial_batch) |partial| {
        if (partial.stream_id != target_stream) return error.InvalidStream;
        if (partial.chunk_count == 0 or partial.chunk_count > max_chunks or
            partial.bytes.items.len > protocol.max_viewport_snapshot)
            return error.InvalidPartial;
        active_batch = true;
        active_snapshot = partial.is_snapshot;
        active_stream = partial.stream_id;
        active_chunks = partial.chunk_count;
        active_bytes = partial.bytes.items.len;
        screen_bytes = std.math.add(usize, screen_bytes, active_bytes) catch
            return error.ArithmeticOverflow;
        screen_count = std.math.add(usize, screen_count, 1) catch
            return error.ArithmeticOverflow;
    }

    var stream_bytes: usize = 0;
    for (self.pending_stream.items) |frame| {
        if (frame.header.kind != .snapshot_chunk and frame.header.kind != .delta_chunk)
            return error.InvalidHeader;
        if (frame.header.major != self.wire_major or
            frame.header.stream_id != target_stream or frame.header.request_id != 0 or
            frame.header.flags & ~protocol.Flags.end_stream != 0 or
            frame.header.payload_len != frame.payload.len or
            frame.payload.len > protocol.max_binary_chunk)
            return error.InvalidHeader;
        const is_snapshot = frame.header.kind == .snapshot_chunk;
        if (active_batch) {
            if (frame.header.stream_id != active_stream or is_snapshot != active_snapshot)
                return error.InvalidPartial;
        } else {
            active_batch = true;
            active_stream = frame.header.stream_id;
            active_snapshot = is_snapshot;
            active_chunks = 0;
            active_bytes = 0;
        }
        active_chunks = std.math.add(usize, active_chunks, 1) catch
            return error.ArithmeticOverflow;
        active_bytes = std.math.add(usize, active_bytes, frame.payload.len) catch
            return error.ArithmeticOverflow;
        if (active_chunks > max_chunks or active_bytes > protocol.max_viewport_snapshot)
            return error.InvalidPartial;
        stream_bytes = std.math.add(usize, stream_bytes, frame.payload.len) catch
            return error.ArithmeticOverflow;
        screen_bytes = std.math.add(usize, screen_bytes, frame.payload.len) catch
            return error.ArithmeticOverflow;
        screen_count = std.math.add(usize, screen_count, 1) catch
            return error.ArithmeticOverflow;
        if (frame.header.flags & protocol.Flags.end_stream != 0) active_batch = false;
    }
    if (stream_bytes != self.pending_stream_bytes) return error.InvalidCounter;

    return .{
        .screen_source_count = screen_count,
        .screen_payload_bytes = screen_bytes,
    };
}

fn validateExternalAdoptionEventSourceQueues(
    self: *const Client,
    target_stream: u64,
) ExternalAdoptionInspectError!usize {
    var event_bytes: usize = 0;
    for (self.pending_events.items) |frame| {
        if (frame.preflight != null or frame.admission_seal != null)
            return error.InvalidClientState;
        if (frame.header.major != self.wire_major or frame.header.kind != .event or
            frame.header.stream_id != target_stream or
            frame.header.request_id != 0 or frame.header.flags != 0 or
            frame.header.payload_len != frame.payload.len or
            frame.payload.len > protocol.max_control_json)
            return error.InvalidHeader;
        event_bytes = std.math.add(usize, event_bytes, frame.payload.len) catch
            return error.ArithmeticOverflow;
    }
    if (event_bytes != self.pending_event_bytes) return error.InvalidCounter;
    return event_bytes;
}

/// Validates source eligibility and queue semantics without allocating, invoking callbacks, or
/// mutating `self`. Callers that can receive aliased owners must run their descriptor-first alias
/// gate between `validateExternalAdoptionSourceEligibility` and
/// `validateExternalAdoptionSourceQueues` instead.
fn preflightExternalAdoptionSource(
    self: *const Client,
    target_stream: u64,
    request_id_policy: ExternalRequestIdPolicy,
    catchup_barrier_policy: ExternalCatchupBarrierPolicy,
) ExternalAdoptionInspectError!ExternalValidatedAdoption {
    try validateExternalAdoptionSourceEligibility(
        self,
        target_stream,
        request_id_policy,
        catchup_barrier_policy,
    );
    return validateExternalAdoptionSourceQueues(self, target_stream);
}

fn validateExternalAdoptionClient(
    self: *const Client,
    target_stream: u64,
    options: ExternalAdoptionValidationOptions,
) ExternalAdoptionInspectError!ExternalValidatedAdoption {
    if (options.owner_aliases == .skip)
        return preflightExternalAdoptionSource(
            self,
            target_stream,
            options.request_id,
            options.catchup_barriers,
        );
    try validateExternalAdoptionSourceEligibility(
        self,
        target_stream,
        options.request_id,
        options.catchup_barriers,
    );
    try validateExternalOwnerRanges(self);
    return validateExternalAdoptionSourceQueues(self, target_stream);
}

fn validateExternalAdoptionStructure(
    self: *const Client,
    catchup_barrier_policy: ExternalCatchupBarrierPolicy,
) ExternalAdoptionInspectError!void {
    if (self.parser.buf.items.len > self.parser.buf.capacity or
        self.pending_batches.items.len > self.pending_batches.capacity or
        self.pending_stream.items.len > self.pending_stream.capacity or
        self.pending_events.items.len > self.pending_events.capacity or
        self.pending_catchup_barriers.items.len > self.pending_catchup_barriers.capacity or
        self.pending_batches.items.len > protocol.max_client_screen_items or
        self.pending_stream.items.len > protocol.max_client_screen_items or
        self.pending_events.items.len > max_pending_event_count or
        self.pending_catchup_barriers.items.len > protocol.max_client_screen_items or
        (catchup_barrier_policy == .require_empty and
            (self.pending_catchup_barriers.items.len != 0 or
                self.pending_catchup_barriers.capacity != 0)))
        return error.InvalidClientState;
    if (self.partial_batch) |partial|
        if (partial.bytes.items.len > partial.bytes.capacity)
            return error.InvalidClientState;
}

fn externalAdoptionSnapshot(self: *const Client) ExternalAdoptionSnapshot {
    const external = self.io_mode.external;
    return .{
        .allocator = self.allocator,
        .fd = self.fd,
        .host_id = self.host_id,
        .build_id_address = if (self.build_id) |bytes| externalSliceAddress(bytes) else 0,
        .build_id_len = if (self.build_id) |bytes| bytes.len else 0,
        .build_id_present = self.build_id != null,
        .upgrade_epoch = self.upgrade_epoch,
        .authority_generation = self.authority_generation,
        .lifecycle_address = externalSliceAddress(self.lifecycle),
        .lifecycle_len = self.lifecycle.len,
        .wire_major = self.wire_major,
        .screen_codec_version = self.screen_codec_version,
        .attachment_capabilities = self.attachment_capabilities,
        .metadata_support = self.metadata_support,
        .host_manifest_v1 = self.host_manifest_v1,
        .host_exec_upgrade_v1 = self.host_exec_upgrade_v1,
        .runtime_inventory_v1 = self.runtime_inventory_v1,
        .runtime_catchup_barrier_v1 = self.runtime_catchup_barrier_v1,
        .admin_one_shot_v1 = self.admin_one_shot_v1,
        .admin_runtime_end_v1 = self.admin_runtime_end_v1,
        .screen_viewport_scrolled_v1 = self.screen_viewport_scrolled_v1,
        .async_scroll_to_bottom_v1 = self.async_scroll_to_bottom_v1,
        .runtime_core_command_v1 = self.runtime_core_command_v1,
        .runtime_clear_screen_v1 = self.runtime_clear_screen_v1,
        .runtime_selected_text_v1 = self.runtime_selected_text_v1,
        .runtime_selection_state_v1 = self.runtime_selection_state_v1,
        .notification_stream_auth_v1 = self.notification_stream_auth_v1,
        .notification_delivery_v1 = self.notification_delivery_v1,
        .runtime_link_at_v1 = self.runtime_link_at_v1,
        .runtime_clipboard_v1 = self.runtime_clipboard_v1,
        .connection_profile = self.connection_profile.?,
        .compatibility_profile = self.compatibility_profile.?,
        .ownership = self.ownership,
        .unusable = self.unusable,
        .first_poison_reason = self.first_poison_reason,
        .first_incident_id = self.first_incident_id,
        .incident_repeat_key = self.incident_repeat_key,
        .next_request_id = self.next_request_id,
        .parser_allocator = self.parser.allocator,
        .parser_expected_major = self.parser.expected_major,
        .parser = externalArrayDescriptor(self.parser.buf),
        .parser_head = self.parser.head,
        .pending_stream = externalArrayDescriptor(self.pending_stream),
        .pending_stream_bytes = self.pending_stream_bytes,
        .pending_events = externalArrayDescriptor(self.pending_events),
        .pending_event_bytes = self.pending_event_bytes,
        .pending_batches = externalArrayDescriptor(self.pending_batches),
        .pending_batch_bytes = self.pending_batch_bytes,
        .pending_catchup_barriers = externalArrayDescriptor(self.pending_catchup_barriers),
        .partial = if (self.partial_batch) |partial| .{
            .stream_id = partial.stream_id,
            .is_snapshot = partial.is_snapshot,
            .bytes = externalArrayDescriptor(partial.bytes),
            .chunk_count = partial.chunk_count,
        } else null,
        .external_saved_flags = external.saved_flags,
        .external_tx = externalArrayDescriptor(external.external_tx),
        .external_tx_bytes = external.external_tx_bytes,
        .external_tx_retiring_bytes = external.external_tx_retiring_bytes,
        .external_tx_quarantined_bytes = external.external_tx_quarantined_bytes,
        .tx_queue_generation = external.tx_queue_generation,
        .tx_head_progress_baseline_ns = external.tx_head_progress_baseline_ns,
        .tx_last_observed_now_ns = external.tx_last_observed_now_ns,
        .tx_immediate_pending = external.tx_immediate_pending,
    };
}

fn externalAdoptionSnapshotForProof(self: *const Client) ?ExternalAdoptionSnapshot {
    if (!self.terminalReasonInvariant()) return null;
    switch (self.io_mode) {
        .blocking => return null,
        .external => {},
    }
    if (self.connection_profile == null or self.compatibility_profile == null)
        return null;
    return externalAdoptionSnapshot(self);
}

fn externalInventoriesEqual(
    a: *const ExternalAdoptionInventory,
    b: *const ExternalAdoptionInventory,
) bool {
    return a.hasSealedStorage() and b.hasSealedStorage() and
        std.meta.eql(a.allocator, b.allocator) and
        a.client_address == b.client_address and
        a.target_stream == b.target_stream and
        a.screen_source_count == b.screen_source_count and
        a.screen_payload_bytes == b.screen_payload_bytes and
        a.event_count == b.event_count and
        a.event_payload_bytes == b.event_payload_bytes and
        a.next_request_id == b.next_request_id and
        a.validation_scratch_peak_bytes == b.validation_scratch_peak_bytes and
        std.meta.eql(a.snapshot, b.snapshot) and
        externalDescriptorSlicesEqual(ExternalBatchDescriptor, a.batch_descriptors, b.batch_descriptors) and
        externalDescriptorSlicesEqual(ExternalFrameDescriptor, a.stream_descriptors, b.stream_descriptors) and
        externalDescriptorSlicesEqual(ExternalFrameDescriptor, a.event_descriptors, b.event_descriptors) and
        std.mem.eql(u8, a.build_id_copy, b.build_id_copy) and
        std.mem.eql(u8, a.lifecycle_copy, b.lifecycle_copy);
}

fn externalDescriptorSlicesEqual(
    comptime T: type,
    a: []const T,
    b: []const T,
) bool {
    if (a.len != b.len) return false;
    for (a, b) |left, right| if (!std.meta.eql(left, right)) return false;
    return true;
}

fn externalInventoryMatchesClientExact(
    inventory: *const ExternalAdoptionInventory,
    self: *const Client,
) bool {
    const screen_count = std.math.add(
        usize,
        self.pending_batches.items.len,
        self.pending_stream.items.len,
    ) catch return false;
    const expected_screen_count = std.math.add(
        usize,
        screen_count,
        @as(usize, @intFromBool(self.partial_batch != null)),
    ) catch return false;
    const batch_and_stream_bytes = std.math.add(
        usize,
        self.pending_batch_bytes,
        self.pending_stream_bytes,
    ) catch return false;
    const expected_screen_bytes = std.math.add(
        usize,
        batch_and_stream_bytes,
        if (self.partial_batch) |partial| partial.bytes.items.len else 0,
    ) catch return false;
    const expected_scratch = std.math.mul(
        usize,
        externalOwnerRangeCount(self) catch return false,
        @sizeOf(ExternalRange),
    ) catch return false;
    if (!inventory.hasSealedStorage() or
        !std.meta.eql(inventory.allocator, self.allocator) or
        inventory.client_address != @intFromPtr(self) or
        inventory.target_stream == 0 or
        inventory.screen_source_count != expected_screen_count or
        inventory.screen_payload_bytes != expected_screen_bytes or
        inventory.event_count != self.pending_events.items.len or
        inventory.event_payload_bytes != self.pending_event_bytes or
        inventory.next_request_id != self.next_request_id or
        inventory.validation_scratch_peak_bytes != expected_scratch or
        !std.meta.eql(inventory.snapshot, externalAdoptionSnapshot(self)))
        return false;
    if (!std.mem.eql(u8, inventory.build_id_copy, self.build_id orelse &.{}) or
        !std.mem.eql(u8, inventory.lifecycle_copy, self.lifecycle) or
        inventory.batch_descriptors.len != self.pending_batches.items.len or
        inventory.stream_descriptors.len != self.pending_stream.items.len or
        inventory.event_descriptors.len != self.pending_events.items.len)
        return false;
    for (inventory.batch_descriptors, self.pending_batches.items) |expected, actual|
        if (!std.meta.eql(expected, externalBatchDescriptor(actual)) or
            actual.stream_id != inventory.target_stream)
            return false;
    for (inventory.stream_descriptors, self.pending_stream.items) |expected, actual|
        if (!std.meta.eql(expected, externalFrameDescriptor(actual)) or
            actual.header.stream_id != inventory.target_stream)
            return false;
    for (inventory.event_descriptors, self.pending_events.items) |expected, actual|
        if (!std.meta.eql(expected, externalFrameDescriptor(actual)) or
            actual.header.stream_id != inventory.target_stream)
            return false;
    if (self.partial_batch) |partial|
        if (partial.stream_id != inventory.target_stream) return false;
    return true;
}

fn externalPlanRangeOverlapsClient(
    self: *const Client,
    out: *const PreparedClientDisarm,
) ExternalAdoptionInspectError!bool {
    return externalRangeOverlapsClient(self, externalRangeOfValue(out));
}

fn externalRangeOverlapsClient(
    self: *const Client,
    target: ExternalRange,
) ExternalAdoptionInspectError!bool {
    if (externalRangesOverlap(target, externalRangeOfValue(self))) return true;
    if (self.build_id) |bytes|
        if (externalRangesOverlap(target, (try externalRangeForSlice(bytes, bytes.len)).?))
            return true;
    const fixed = [_]?ExternalRange{
        try externalRangeForSlice(self.lifecycle, self.lifecycle.len),
        try externalRangeForList(self.parser.buf, u8),
        try externalRangeForList(self.pending_batches, StreamBatch),
        try externalRangeForList(self.pending_stream, framing.Frame),
        try externalRangeForList(self.pending_events, BufferedEvent),
        switch (self.io_mode) {
            .blocking => null,
            .external => |state| try externalRangeForList(
                state.external_tx,
                client_external_mode.ExternalTxFrame,
            ),
        },
    };
    for (fixed) |range| if (range) |present|
        if (externalRangesOverlap(target, present)) return true;
    if (self.partial_batch) |partial|
        if (try externalRangeForSlice(partial.bytes.items, partial.bytes.capacity)) |range|
            if (externalRangesOverlap(target, range)) return true;
    for (self.pending_batches.items) |batch|
        if (try externalRangeForSlice(batch.bytes, batch.bytes.len)) |range|
            if (externalRangesOverlap(target, range)) return true;
    for (self.pending_stream.items) |frame|
        if (try externalRangeForSlice(frame.payload, frame.payload.len)) |range|
            if (externalRangesOverlap(target, range)) return true;
    for (self.pending_events.items) |frame|
        if (try externalRangeForSlice(frame.payload, frame.payload.len)) |range|
            if (externalRangesOverlap(target, range)) return true;
    if (self.pending_outbound) |pending|
        if (try externalRangeForSlice(pending.frame, pending.frame.len)) |range|
            if (externalRangesOverlap(target, range)) return true;
    return false;
}

/// host와의 한 connection. `host_id`는 hello_ack로 받은 값이다(§4 stale handle 판정에 쓴다). `call`은 read-only
/// command를 왕복한다.
pub fn commitExternalRecoveryDiscardUnchecked(
    client: *Client,
    seal: *ExternalRecoveryDiscardSeal,
    cleanup_scratch: *ExternalAdoptionCleanupScratch,
) void {
    client.commitExternalRecoveryDiscardImpl(seal, cleanup_scratch);
}

pub fn commitExternalAdoptionTakeUnchecked(
    client: *Client,
    plan: *PreparedClientDisarm,
    mirror_owner: *?ExternalAdoptionInventory,
    mirror_cleanup_owner: *?ExternalAdoptionInventory,
    take: *ExternalAdoptionTake,
) void {
    client.commitExternalAdoptionTakeImpl(
        plan,
        mirror_owner,
        mirror_cleanup_owner,
        take,
    );
}

pub fn commitExternalAdoptionTakeFrozenCleanupUnchecked(
    take: *ExternalAdoptionTake,
    prepared: *PreparedExternalAdoptionTakeCleanup,
    out: *FrozenExternalAdoptionTakeCleanup,
) void {
    take.commitFrozenCleanupImpl(prepared, out);
}

/// Heap-pinned generation Client의 public mutation과 ended-purge commit callback을 직렬화한다.
///
/// Stream/attachment 의미 권위는 계속 ClientSlot의 StreamOperationPermit가 소유한다. 이 작은
/// substrate는 direct Client API가 다른 thread에서 callback cleanup과 겹치는 것만 막는다.
var next_client_operation_fence_incarnation: std.atomic.Value(u64) = .init(1);

fn issueClientOperationFenceIncarnation() u64 {
    var observed = next_client_operation_fence_incarnation.load(.acquire);
    while (true) {
        if (observed == 0 or observed == std.math.maxInt(u64))
            @panic("Client operation fence incarnation exhausted");
        if (next_client_operation_fence_incarnation.cmpxchgWeak(
            observed,
            observed + 1,
            .acq_rel,
            .acquire,
        )) |actual| {
            observed = actual;
            continue;
        }
        return observed;
    }
}

pub const RegisteredOperationExecutionMintReceipt = operation_thread_identity.MintReceipt;

pub const RegisteredOperationExecutionCapability = struct {
    self_addr: usize = 0,
    client_addr: usize = 0,
    fence_generation: u64 = 0,
    fence_incarnation: u64 = 0,
    lease_identity: u64 = 0,
    owner_process_id: u32 = 0,
    owner_process_nonce: u64 = 0,
    owner_thread_id: u64 = 0,
    owner_thread_incarnation: u64 = 0,
    operation_identity: u64 = 0,
    live: bool = false,
    seal: owner_seal.Digest = [_]u8{0} ** 32,
    publication_identity: std.atomic.Value(u64) = .init(0),

    fn digest(self: *const @This()) owner_seal.Digest {
        var writer = owner_seal.Writer.init("maru.registered-operation-execution-capability.v1");
        writer.writeUsize(self.self_addr);
        writer.writeUsize(self.client_addr);
        writer.writeU64(self.fence_generation);
        writer.writeU64(self.fence_incarnation);
        writer.writeU64(self.lease_identity);
        writer.writeU64(self.owner_process_id);
        writer.writeU64(self.owner_process_nonce);
        writer.writeU64(self.owner_thread_id);
        writer.writeU64(self.owner_thread_incarnation);
        writer.writeU64(self.operation_identity);
        writer.writeU8(@intFromBool(self.live));
        return writer.finish();
    }

    pub fn pristineExact(self: *const @This()) bool {
        return self.self_addr == 0 and self.client_addr == 0 and self.fence_generation == 0 and
            self.fence_incarnation == 0 and self.lease_identity == 0 and
            self.owner_process_id == 0 and self.owner_process_nonce == 0 and
            self.owner_thread_id == 0 and self.owner_thread_incarnation == 0 and
            self.operation_identity == 0 and !self.live and
            std.mem.allEqual(u8, &self.seal, 0) and
            self.publication_identity.load(.acquire) == 0;
    }

    fn resetPristine(self: *@This()) void {
        self.self_addr = 0;
        self.client_addr = 0;
        self.fence_generation = 0;
        self.fence_incarnation = 0;
        self.lease_identity = 0;
        self.owner_process_id = 0;
        self.owner_process_nonce = 0;
        self.owner_thread_id = 0;
        self.owner_thread_incarnation = 0;
        self.operation_identity = 0;
        self.live = false;
        self.seal = [_]u8{0} ** 32;
        self.publication_identity.store(0, .release);
    }
};

pub const RegisteredOperationExecutionHandle = operation_thread_identity.CapabilityHandle;

const PinnedExecutionCapabilityGuard = struct {
    capability: ?*const RegisteredOperationExecutionCapability = null,
    pin: operation_thread_identity.CapabilityPin = .{},

    fn deinit(self: *@This()) void {
        if (!self.pin.live) return;
        if (!operation_thread_identity.unpinCapability(&self.pin))
            @panic("execution capability registry unpin failed");
    }

    fn close(self: *@This()) bool {
        return operation_thread_identity.closeCapability(&self.pin);
    }
};

fn initRegisteredOperationExecutionCapabilityGuard(
    out: *PinnedExecutionCapabilityGuard,
    handle: RegisteredOperationExecutionHandle,
    expected_client_addr: usize,
) bool {
    out.* = .{};
    if (!operation_thread_identity.pinCapability(handle, &out.pin)) return false;
    out.capability = @ptrFromInt(out.pin.fields.capability_addr);
    var transfer_pin = false;
    defer if (!transfer_pin) out.deinit();
    const capability = out.capability.?;
    const published_identity = capability.publication_identity.load(.acquire);
    if (published_identity == 0 or published_identity != out.pin.fields.publication_identity) return false;
    if (builtin.is_test and execution_capability_read_test_hook.armed.swap(false, .acq_rel)) {
        execution_capability_read_test_hook.reached.store(true, .release);
        if (!ExecutionCapabilityPublicationTestHook.waitUntil(
            &execution_capability_read_test_hook.proceed,
        )) @panic("execution capability reader test hook timed out");
    }
    const current_pid = operation_thread_identity.currentProcessId();
    const owner_thread_id: u64 = @intCast(std.Thread.getCurrentId());
    if (!(capability.self_addr == @intFromPtr(capability) and capability.live and
        capability.client_addr == expected_client_addr and
        capability.client_addr == out.pin.fields.client_addr and
        capability.fence_generation == out.pin.fields.fence_generation and
        capability.fence_incarnation == out.pin.fields.fence_incarnation and
        current_pid != 0 and capability.owner_process_id == current_pid and
        capability.owner_process_id == out.pin.fields.owner_process_id and
        capability.owner_process_nonce == out.pin.fields.owner_process_nonce and
        capability.lease_identity == published_identity and
        capability.owner_thread_id == owner_thread_id and
        capability.owner_thread_id == out.pin.fields.owner_thread_id and
        capability.owner_thread_incarnation == out.pin.fields.owner_thread_incarnation and
        operation_thread_identity.matches(capability.owner_thread_incarnation) and
        capability.operation_identity == out.pin.fields.operation_identity and
        std.mem.eql(u8, &capability.seal, &capability.digest()))) return false;
    transfer_pin = true;
    return true;
}

pub const ClientOperationFence = struct {
    const shared_count_mask: u64 = (@as(u64, 1) << 31) - 1;
    const execution_lease_bit: u64 = @as(u64, 1) << 59;
    const reserved_mask: u64 = ((@as(u64, 1) << 60) - 1) & ~shared_count_mask;
    const publication_bit: u64 = @as(u64, 1) << 60;
    const terminal_bit: u64 = @as(u64, 1) << 61;
    const intrusion_bit: u64 = @as(u64, 1) << 62;
    const exclusive_bit: u64 = @as(u64, 1) << 63;

    self_addr: usize = 0,
    client_addr: usize = 0,
    owner_process_id: u32 = 0,
    owner_process_nonce: u64 = 0,
    slot_incarnation: u64 = 0,
    node_incarnation: u64 = 0,
    fence_generation: u64 = 0,
    fence_incarnation: u64 = 0,
    state: std.atomic.Value(u64) = .init(0),
    execution_capability_addr: std.atomic.Value(usize) = .init(0),
    execution_capability_identity: std.atomic.Value(u64) = .init(0),
    execution_owner_thread_id: std.atomic.Value(u64) = .init(0),
    execution_owner_thread_incarnation: std.atomic.Value(u64) = .init(0),
    next_execution_capability_identity: std.atomic.Value(u64) = .init(1),

    pub fn initInPlace(
        self: *ClientOperationFence,
        client_addr: usize,
        owner_process_id: u32,
        owner_process_nonce: u64,
        slot_incarnation: u64,
        node_incarnation: u64,
        fence_generation: u64,
    ) void {
        if (client_addr == 0 or owner_process_id == 0 or owner_process_nonce == 0 or slot_incarnation == 0 or
            node_incarnation == 0 or fence_generation == 0)
            @panic("invalid Client operation fence identity");
        self.* = .{
            .self_addr = @intFromPtr(self),
            .client_addr = client_addr,
            .owner_process_id = owner_process_id,
            .owner_process_nonce = owner_process_nonce,
            .slot_incarnation = slot_incarnation,
            .node_incarnation = node_incarnation,
            .fence_generation = fence_generation,
            .fence_incarnation = issueClientOperationFenceIncarnation(),
        };
    }

    fn tryEnterShared(
        self: *ClientOperationFence,
        client_addr: usize,
        fence_generation: u64,
    ) error{ InvalidOwner, InvalidState, AdminBusy, CounterOverflow }!void {
        if (!self.identityMatches(client_addr, fence_generation)) return error.InvalidOwner;
        var observed = self.state.load(.acquire);
        while (true) {
            if (observed & execution_lease_bit != 0) return error.AdminBusy;
            if (observed & reserved_mask != 0 or observed & terminal_bit != 0)
                return error.InvalidState;
            if (observed & publication_bit != 0) return error.AdminBusy;
            if (observed & exclusive_bit != 0) {
                self.recordIntrusionIfExactExclusive(observed);
                return error.AdminBusy;
            }
            const count = observed & shared_count_mask;
            if (count == shared_count_mask) return error.CounterOverflow;
            if (self.state.cmpxchgWeak(observed, observed + 1, .acq_rel, .acquire)) |actual| {
                observed = actual;
                continue;
            }
            return;
        }
    }

    fn leaveShared(
        self: *ClientOperationFence,
        client_addr: usize,
        fence_generation: u64,
    ) bool {
        if (!self.identityMatches(client_addr, fence_generation)) return false;
        var observed = self.state.load(.acquire);
        while (true) {
            if (observed & ~shared_count_mask != 0 or observed & shared_count_mask == 0)
                return false;
            if (self.state.cmpxchgWeak(observed, observed - 1, .acq_rel, .acquire)) |actual| {
                observed = actual;
                continue;
            }
            return true;
        }
    }

    fn tryAcquireExclusive(
        self: *ClientOperationFence,
        client_addr: usize,
        fence_generation: u64,
    ) error{ InvalidOwner, InvalidState, AdminBusy }!void {
        if (!self.identityMatches(client_addr, fence_generation)) return error.InvalidOwner;
        if (self.state.cmpxchgStrong(0, exclusive_bit, .acq_rel, .acquire)) |observed| {
            if (observed & execution_lease_bit != 0) return error.AdminBusy;
            if (observed & (reserved_mask | publication_bit | terminal_bit) != 0)
                return error.InvalidState;
            if (observed & exclusive_bit != 0)
                self.recordIntrusionIfExactExclusive(observed);
            return error.AdminBusy;
        }
    }

    fn tryAcquireExecutionLease(
        self: *ClientOperationFence,
        client_addr: usize,
        fence_generation: u64,
    ) error{ InvalidOwner, InvalidState, AdminBusy }!void {
        if (!self.identityMatches(client_addr, fence_generation)) return error.InvalidOwner;
        if (self.state.cmpxchgStrong(0, execution_lease_bit, .acq_rel, .acquire)) |observed| {
            if (observed & (reserved_mask & ~execution_lease_bit) != 0 or
                observed & (publication_bit | terminal_bit) != 0)
                return error.InvalidState;
            return error.AdminBusy;
        }
    }

    fn releaseExecutionLease(
        self: *ClientOperationFence,
        client_addr: usize,
        fence_generation: u64,
    ) bool {
        if (!self.identityMatches(client_addr, fence_generation)) return false;
        return self.state.cmpxchgStrong(
            execution_lease_bit,
            0,
            .acq_rel,
            .acquire,
        ) == null;
    }

    fn upgradeSingleSharedToExecutionLease(
        self: *ClientOperationFence,
        client_addr: usize,
        fence_generation: u64,
    ) error{ InvalidOwner, InvalidState, AdminBusy }!void {
        if (!self.identityMatches(client_addr, fence_generation)) return error.InvalidOwner;
        if (self.state.cmpxchgStrong(1, execution_lease_bit, .acq_rel, .acquire)) |observed| {
            if (observed & (reserved_mask & ~execution_lease_bit) != 0 or
                observed & (publication_bit | terminal_bit) != 0)
                return error.InvalidState;
            return error.AdminBusy;
        }
    }

    fn downgradeExecutionLeaseToSingleShared(
        self: *ClientOperationFence,
        client_addr: usize,
        fence_generation: u64,
    ) bool {
        if (!self.identityMatches(client_addr, fence_generation)) return false;
        return self.state.cmpxchgStrong(
            execution_lease_bit,
            1,
            .acq_rel,
            .acquire,
        ) == null;
    }

    fn executionLeaseHeld(
        self: *const ClientOperationFence,
        client_addr: usize,
        fence_generation: u64,
    ) bool {
        return self.identityMatches(client_addr, fence_generation) and
            self.state.load(.acquire) == execution_lease_bit;
    }

    fn issueExecutionCapabilityIdentity(self: *ClientOperationFence) ?u64 {
        var observed = self.next_execution_capability_identity.load(.acquire);
        while (true) {
            if (observed == 0 or observed == std.math.maxInt(u64)) return null;
            if (self.next_execution_capability_identity.cmpxchgWeak(
                observed,
                observed + 1,
                .acq_rel,
                .acquire,
            )) |actual| {
                observed = actual;
                continue;
            }
            return observed;
        }
    }

    fn executionCapabilityMatches(
        self: *const ClientOperationFence,
        client_addr: usize,
        fence_generation: u64,
        capability: *const RegisteredOperationExecutionCapability,
    ) bool {
        if (generationAllocatorCallbackActive()) return false;
        const published_identity = capability.publication_identity.load(.acquire);
        if (published_identity == 0) return false;
        const thread_id: u64 = @intCast(std.Thread.getCurrentId());
        return capability.self_addr == @intFromPtr(capability) and capability.live and
            capability.client_addr == client_addr and
            capability.owner_process_id == self.owner_process_id and
            capability.owner_process_nonce == self.owner_process_nonce and
            capability.fence_generation == fence_generation and
            capability.fence_incarnation == self.fence_incarnation and
            capability.lease_identity != 0 and capability.owner_thread_id == thread_id and
            capability.owner_thread_incarnation != 0 and capability.operation_identity != 0 and
            operation_thread_identity.matches(capability.owner_thread_incarnation) and
            std.mem.eql(u8, &capability.seal, &capability.digest()) and
            self.executionLeaseHeld(client_addr, fence_generation) and
            self.execution_capability_addr.load(.acquire) == @intFromPtr(capability) and
            published_identity == capability.lease_identity and
            self.execution_capability_identity.load(.acquire) == published_identity and
            self.execution_owner_thread_id.load(.acquire) == thread_id and
            self.execution_owner_thread_incarnation.load(.acquire) ==
                capability.owner_thread_incarnation;
    }

    fn recordIntrusionIfExactExclusive(self: *ClientOperationFence, observed: u64) void {
        if (observed != exclusive_bit) return;
        _ = self.state.cmpxchgStrong(
            exclusive_bit,
            exclusive_bit | intrusion_bit,
            .acq_rel,
            .acquire,
        );
    }

    fn sealExclusiveForPublication(
        self: *ClientOperationFence,
        client_addr: usize,
        fence_generation: u64,
    ) bool {
        if (!self.identityMatches(client_addr, fence_generation)) return false;
        return self.state.cmpxchgStrong(
            exclusive_bit,
            exclusive_bit | publication_bit,
            .acq_rel,
            .acquire,
        ) == null;
    }

    fn intruded(
        self: *const ClientOperationFence,
        client_addr: usize,
        fence_generation: u64,
    ) bool {
        if (!self.identityMatches(client_addr, fence_generation)) return true;
        const observed = self.state.load(.acquire);
        return observed & exclusive_bit == 0 or observed & intrusion_bit != 0;
    }

    /// Retired Client seal projection. Atomic members are acquired explicitly so a rejected stale
    /// public call cannot race a raw-byte node digest while it records exclusive intrusion.
    pub fn retirementAuthorityDigest(self: *const ClientOperationFence) owner_seal.Digest {
        var writer = owner_seal.Writer.init("maru.client-operation-fence.retirement.v1");
        writer.writeUsize(self.self_addr);
        writer.writeUsize(self.client_addr);
        writer.writeU64(self.owner_process_id);
        writer.writeU64(self.owner_process_nonce);
        writer.writeU64(self.slot_incarnation);
        writer.writeU64(self.node_incarnation);
        writer.writeU64(self.fence_generation);
        writer.writeU64(self.fence_incarnation);
        writer.writeU64(self.state.load(.acquire));
        writer.writeUsize(self.execution_capability_addr.load(.acquire));
        writer.writeU64(self.execution_capability_identity.load(.acquire));
        writer.writeU64(self.execution_owner_thread_id.load(.acquire));
        writer.writeU64(self.execution_owner_thread_incarnation.load(.acquire));
        writer.writeU64(self.next_execution_capability_identity.load(.acquire));
        return writer.finish();
    }

    fn abortExclusive(
        self: *ClientOperationFence,
        client_addr: usize,
        fence_generation: u64,
    ) bool {
        if (!self.identityMatches(client_addr, fence_generation)) return false;
        var observed = self.state.load(.acquire);
        while (true) {
            if (observed & exclusive_bit == 0 or observed & (publication_bit | terminal_bit) != 0 or
                observed & shared_count_mask != 0 or observed & reserved_mask != 0)
                return false;
            if (self.state.cmpxchgWeak(observed, 0, .acq_rel, .acquire)) |actual| {
                observed = actual;
                continue;
            }
            return true;
        }
    }

    fn releaseExclusiveClean(
        self: *ClientOperationFence,
        client_addr: usize,
        fence_generation: u64,
    ) bool {
        if (!self.identityMatches(client_addr, fence_generation)) return false;
        var observed = self.state.load(.acquire);
        while (observed == exclusive_bit or observed == exclusive_bit | publication_bit) {
            if (self.state.cmpxchgWeak(observed, 0, .acq_rel, .acquire)) |actual| {
                observed = actual;
                continue;
            }
            return true;
        }
        return false;
    }

    fn commitExclusiveTerminal(
        self: *ClientOperationFence,
        client_addr: usize,
        fence_generation: u64,
    ) bool {
        if (!self.identityMatches(client_addr, fence_generation)) return false;
        var observed = self.state.load(.acquire);
        while (true) {
            if (observed & exclusive_bit == 0 or observed & terminal_bit != 0 or
                observed & shared_count_mask != 0 or observed & reserved_mask != 0)
                return false;
            const terminal = observed | terminal_bit;
            if (self.state.cmpxchgWeak(observed, terminal, .acq_rel, .acquire)) |actual| {
                observed = actual;
                continue;
            }
            return true;
        }
    }

    fn identityMatches(
        self: *const ClientOperationFence,
        client_addr: usize,
        fence_generation: u64,
    ) bool {
        const pid = operation_thread_identity.currentProcessId();
        if (pid == 0 or self.owner_process_id != pid) return false;
        return self.self_addr == @intFromPtr(self) and self.client_addr == client_addr and
            self.slot_incarnation != 0 and self.node_incarnation != 0 and
            self.fence_generation != 0 and self.fence_generation == fence_generation;
    }
};

pub const ExecutionCapabilityPublicationTestHook = struct {
    armed: std.atomic.Value(bool) = .init(false),
    reached: std.atomic.Value(bool) = .init(false),
    proceed: std.atomic.Value(bool) = .init(false),

    pub fn waitUntil(flag: *const std.atomic.Value(bool)) bool {
        const deadline = std.Io.Clock.awake.now(std.testing.io).nanoseconds +
            10 * std.time.ns_per_s;
        while (!flag.load(.acquire)) {
            if (std.Io.Clock.awake.now(std.testing.io).nanoseconds >= deadline) return false;
            std.Thread.yield() catch {};
        }
        return true;
    }
};
pub var execution_capability_publication_test_hook: if (builtin.is_test)
    ExecutionCapabilityPublicationTestHook
else
    void = if (builtin.is_test) .{} else {};
pub var execution_capability_read_test_hook: if (builtin.is_test)
    ExecutionCapabilityPublicationTestHook
else
    void = if (builtin.is_test) .{} else {};

test "CR3a B3b-F operation fence linearizes shared and exclusive ownership" {
    var client_storage: u8 = 0;
    var fence: ClientOperationFence = undefined;
    const pid = operation_thread_identity.currentProcessId();
    fence.initInPlace(@intFromPtr(&client_storage), pid, 5, 11, 13, 17);

    try fence.tryEnterShared(@intFromPtr(&client_storage), 17);
    try std.testing.expectError(
        error.AdminBusy,
        fence.tryAcquireExclusive(@intFromPtr(&client_storage), 17),
    );
    try std.testing.expect(fence.leaveShared(@intFromPtr(&client_storage), 17));

    try fence.tryAcquireExclusive(@intFromPtr(&client_storage), 17);
    try std.testing.expectError(
        error.AdminBusy,
        fence.tryEnterShared(@intFromPtr(&client_storage), 17),
    );
    try std.testing.expect(fence.intruded(@intFromPtr(&client_storage), 17));
    try std.testing.expect(!fence.releaseExclusiveClean(@intFromPtr(&client_storage), 17));
    try std.testing.expect(fence.commitExclusiveTerminal(@intFromPtr(&client_storage), 17));
    try std.testing.expectError(
        error.InvalidState,
        fence.tryEnterShared(@intFromPtr(&client_storage), 17),
    );
}

test "CR3a B3b-F operation fence rejects copied and stale identities before state mutation" {
    var client_storage: u8 = 0;
    var fence: ClientOperationFence = undefined;
    const pid = operation_thread_identity.currentProcessId();
    fence.initInPlace(@intFromPtr(&client_storage), pid, 5, 19, 23, 29);
    var copied = fence;

    try std.testing.expectError(
        error.InvalidOwner,
        copied.tryEnterShared(@intFromPtr(&client_storage), 29),
    );
    try std.testing.expectError(
        error.InvalidOwner,
        fence.tryEnterShared(@intFromPtr(&client_storage), 31),
    );
    try std.testing.expectEqual(@as(u64, 0), fence.state.load(.acquire));
}

test "B3-3 operation execution lease atomically blocks shared and teardown entry" {
    var client_storage: u8 = 0;
    var fence: ClientOperationFence = undefined;
    const pid = operation_thread_identity.currentProcessId();
    fence.initInPlace(@intFromPtr(&client_storage), pid, 5, 31, 37, 41);

    try fence.tryAcquireExecutionLease(@intFromPtr(&client_storage), 41);
    try std.testing.expectError(
        error.AdminBusy,
        fence.tryEnterShared(@intFromPtr(&client_storage), 41),
    );
    try std.testing.expectError(
        error.AdminBusy,
        fence.tryAcquireExclusive(@intFromPtr(&client_storage), 41),
    );
    try std.testing.expect(fence.releaseExecutionLease(@intFromPtr(&client_storage), 41));
    try fence.tryEnterShared(@intFromPtr(&client_storage), 41);
    try std.testing.expect(fence.leaveShared(@intFromPtr(&client_storage), 41));
    try std.testing.expect(!fence.releaseExecutionLease(@intFromPtr(&client_storage), 41));
}

test "B3-3 operation execution lease upgrades and restores one registered shared pin" {
    var client_storage: u8 = 0;
    var fence: ClientOperationFence = undefined;
    const pid = operation_thread_identity.currentProcessId();
    fence.initInPlace(@intFromPtr(&client_storage), pid, 5, 71, 73, 79);
    try fence.tryEnterShared(@intFromPtr(&client_storage), 79);
    try fence.upgradeSingleSharedToExecutionLease(@intFromPtr(&client_storage), 79);
    try std.testing.expectError(
        error.AdminBusy,
        fence.tryEnterShared(@intFromPtr(&client_storage), 79),
    );
    try std.testing.expect(fence.downgradeExecutionLeaseToSingleShared(
        @intFromPtr(&client_storage),
        79,
    ));
    try std.testing.expect(fence.leaveShared(@intFromPtr(&client_storage), 79));
}

test "CR3a B3b-F nested count overflow and reserved states fail closed" {
    var client_storage: u8 = 0;
    var fence: ClientOperationFence = undefined;
    const pid = operation_thread_identity.currentProcessId();
    fence.initInPlace(@intFromPtr(&client_storage), pid, 5, 32, 33, 34);

    try fence.tryEnterShared(@intFromPtr(&client_storage), 34);
    try fence.tryEnterShared(@intFromPtr(&client_storage), 34);
    try std.testing.expectEqual(@as(u64, 2), fence.state.load(.acquire));
    try std.testing.expect(fence.leaveShared(@intFromPtr(&client_storage), 34));
    try std.testing.expect(fence.leaveShared(@intFromPtr(&client_storage), 34));

    fence.state.store(ClientOperationFence.shared_count_mask, .release);
    try std.testing.expectError(
        error.CounterOverflow,
        fence.tryEnterShared(@intFromPtr(&client_storage), 34),
    );
    fence.state.store(@as(u64, 1) << 31, .release);
    try std.testing.expectError(
        error.InvalidState,
        fence.tryEnterShared(@intFromPtr(&client_storage), 34),
    );
    fence.state.store(0, .release);
}

test "CR3a B3b-F Client rejects rebind and same-address generation ABA" {
    var client: Client = .{
        .allocator = std.testing.allocator,
        .fd = -1,
        .host_id = 35,
        .parser = framing.FrameParser.init(std.testing.allocator),
    };
    defer client.parser.deinit();
    var fence: ClientOperationFence = undefined;
    const pid = operation_thread_identity.currentProcessId();
    fence.initInPlace(@intFromPtr(&client), pid, 5, 36, 37, 38);
    try std.testing.expect(client.bindOperationFence(&fence, 38));
    try std.testing.expect(!client.bindOperationFence(&fence, 38));

    // Reincarnating the same storage cannot make the old Client generation authoritative.
    fence.initInPlace(@intFromPtr(&client), pid, 5, 39, 40, 41);
    try std.testing.expectError(error.ConnectionClosed, client.call("host.info", null));
    try std.testing.expectEqual(@as(u64, 0), fence.state.load(.acquire));
}

test "CR3a B3b-F exclusive fence rejects public Client mutation before graph access" {
    var client: Client = .{
        .allocator = std.testing.allocator,
        .fd = -1,
        .host_id = 37,
        .parser = framing.FrameParser.init(std.testing.allocator),
    };
