test "CR3a B3b-F fork child rejects an inherited fence before atomic state access" {
    if (builtin.os.tag != .macos and builtin.os.tag != .linux)
        return error.SkipZigTest;
    const ChildCleanup = struct {
        fn terminateAndReap(child_pid: c.pid_t) void {
            _ = c.kill(child_pid, c.SIG.KILL);
            var child_status: c_int = 0;
            while (true) {
                const waited = c.waitpid(child_pid, &child_status, 0);
                if (waited == child_pid or
                    (waited < 0 and posix.errno(waited) == .CHILD)) return;
                if (waited < 0 and posix.errno(waited) == .INTR) continue;
                return;
            }
        }
    };
    var client_storage: u8 = 0;
    var fence: ClientOperationFence = undefined;
    const pid: u32 = @intCast(c.getpid());
    fence.initInPlace(@intFromPtr(&client_storage), pid, 5, 79, 83, 89);
    try fence.tryAcquireExclusive(@intFromPtr(&client_storage), 89);

    const child = c.fork();
    try std.testing.expect(child >= 0);
    if (child == 0) {
        const rejected = if (fence.tryEnterShared(@intFromPtr(&client_storage), 89)) |_| false else |err| err == error.InvalidOwner;
        c._exit(if (rejected) 0 else 1);
    }
    var child_live = true;
    defer {
        if (child_live) ChildCleanup.terminateAndReap(child);
    }
    var status: c_int = 0;
    var attempts: usize = 0;
    while (attempts < 2_000) : (attempts += 1) {
        const waited = c.waitpid(child, &status, c.W.NOHANG);
        if (waited == child) {
            child_live = false;
            break;
        }
        if (waited < 0 and posix.errno(waited) != .INTR)
            return error.TestUnexpectedResult;
        var delay_fd = c.pollfd{ .fd = -1, .events = 0, .revents = 0 };
        _ = c.poll(@ptrCast(&delay_fd), 0, 1);
    }
    try std.testing.expect(!child_live);
    const wait_status: u32 = @bitCast(status);
    try std.testing.expect(c.W.IFEXITED(wait_status));
    try std.testing.expectEqual(@as(u8, 0), c.W.EXITSTATUS(wait_status));
    try std.testing.expectEqual(ClientOperationFence.exclusive_bit, fence.state.load(.acquire));
    try std.testing.expect(fence.releaseExclusiveClean(@intFromPtr(&client_storage), 89));
}

pub const Client = struct {
    allocator: std.mem.Allocator,
    fd: c.fd_t,
    host_id: u128,
    /// Exact host manifest ABA 검증용 hello identity. 과거 manifest 없는 peer는 null/0/empty일 수 있다.
    build_id: ?[]u8 = null,
    upgrade_epoch: u64 = 0,
    authority_generation: u64 = 0,
    lifecycle: []u8 = &.{},
    /// host-id manifest를 publish하는 peer인지. 이 capability가 있으면 hello identity 필드는 전부 필수이며 legacy
    /// endpoint 추측 경로에서 받아들이지 않는다.
    host_manifest_v1: bool = false,
    host_exec_upgrade_v1: bool = false,
    runtime_inventory_v1: bool = false,
    /// Host와 fixed binary catch-up barrier v1을 명시 협상했는가. 이 bit가 없으면
    /// barrier frame을 정상 out-of-band traffic으로 받아들이지 않는다.
    runtime_catchup_barrier_v1: bool = false,
    /// Attached stream의 controller status/takeover/release generation-CAS protocol을 양쪽이 협상했는가.
    /// public attach는 false인 same-major 구 host에서 observer만 허용하고 takeover method를 보내지 않는다.
    /// Peer reply schema and our revoke/fencing promise are different facts. Keep them in one
    /// typed capability value so call sites cannot accidentally pass the promise bit as a decoder
    /// schema bit.
    attachment_capabilities: AttachmentCapabilities = .{},
    /// Runtime metadata schema support is immutable hello provenance, not observation
    /// availability. Frozen N-1 is always unsupported; a current peer is supported only when its
    /// ACK advertises the capability we requested.
    metadata_support: runtime_metadata_wire.MetadataSupport = .unsupported,
    /// Optional parse observability used by deterministic product-path gates. It does not receive
    /// payload bytes and cannot alter classification; normal clients leave it null.
    event_parse_observer: ?runtime_event_wire.ParseObserver = null,
    /// Hidden one-shot admin role을 host가 명시적으로 지원하는가. CLI는 이 값 없이 read method를 추측하지 않는다.
    admin_one_shot_v1: bool = false,
    /// Public `runtime end`를 exact one-shot admin mutation으로 지원하는가.
    admin_runtime_end_v1: bool = false,
    /// 이 connection이 협상한 MRSH header major. current GUI는 current와 frozen N-1 adapter를 별도
    /// connection으로 유지하므로 모든 outbound/inbound frame이 이 값을 사용한다.
    wire_major: u16 = protocol.version_major,
    /// 이 MRSH adapter가 받아야 하는 exact screen record version. current major는 current codec,
    /// capability-tagged N-1 adapter는 직전 codec만 받는다. 두 버전을 전역 reader 범위로 섞지 않는다.
    screen_codec_version: u16 = @import("maru").session.screen_stream.codec_version,
    /// hello_ack에서 host가 `screen_viewport_scrolled_v1` mode bit을 신뢰할 수 있다고 광고했는가. 구 host ACK에는
    /// capability가 없으므로 false로 남겨 remote preedit가 숨은 live cursor에 그려지지 않게 한다.
    screen_viewport_scrolled_v1: bool = false,
    /// host가 응답 없는 `scroll_to_bottom` stream frame을 지원하는가. false인 구 host에서는
    /// AppKit callback이 동기 RPC로 fallback하지 않고 scrolled preedit를 fail-closed한다.
    async_scroll_to_bottom_v1: bool = false,
    /// host가 scroll 외 focus/config/prompt를 포함한 bounded `runtime.core_command` v1 집합을 지원하는가.
    /// false인 구 host에는 기존 scroll만 보내고 새 명령은 degraded no-op으로 남긴다.
    runtime_core_command_v1: bool = false,
    /// host가 clear의 권위 core 판정과 조건부 ^L 주입을 같은 reader turn에서 지원하는가.
    /// 별도 capability라 current GUI가 이 op를 모르는 N-1 host 연결을 끊지 않는다.
    runtime_clear_screen_v1: bool = false,
    /// host가 `runtime.selected_text`로 자기 TerminalCore에서 선택 의미론을 해석할 수 있는가. false인 구 host는
    /// 앱 업데이트보다 먼저 떠 계속 살아 있을 수 있으므로, client의 현재 화면 projection에서 보이는 선택만 추출한다.
    runtime_selected_text_v1: bool = false,
    /// host가 controller의 selection start/extend/clear와 scroll_and_extend를 core-command FIFO에 미러링하고,
    /// 뒤따르는 authoritative copy까지 권위 anchor/head를 보존하는가.
    runtime_selection_state_v1: bool = false,
    /// host가 consumptive notification RPC를 exact attached stream으로 인가하는가. false인 same-major 구 host에는
    /// legacy runtime selector를 보내되, 새 host도 그 connection의 live controller만 fallback으로 허용한다.
    notification_stream_auth_v1: bool = false,
    notification_delivery_v1: bool = false,
    /// host가 `runtime.link_at`으로 자기 core의 `extractUrlAt`(추출 + cwd resolve + 존재 stat)을 실행할 수 있는가.
    /// 없으면 client는 이 RPC를 보내지 않고 원격 링크 열기를 비활성한다(docs/link-detection.md §원격(host-backed) 세션).
    runtime_link_at_v1: bool = false,
    /// host가 `runtime.clipboard_write`로 OSC 52 write 텍스트를 넘길 수 있는가. 없으면 원격 클립보드가 비활성이다.
    runtime_clipboard_v1: bool = false,
    /// The hello profile is immutable connection policy. `null` exists only for manually
    /// constructed fixtures and is rejected by external adoption instead of being guessed as GUI.
    connection_profile: ?ConnectionProfile = null,
    /// Set only after `finishHello` has verified the selected current/N-1 schema and any required
    /// frozen fingerprint. External adoption must not infer this proof from `wire_major`.
    compatibility_profile: ?compatibility.Profile = null,
    /// Process-local provenance of the one external attach that published this Client. Adoption
    /// evidence seals the same value, so two semantically identical attaches cannot be swapped even
    /// when the second `Prepared` reuses the first one's address. `0` means "not published by
    /// `external_attach.prepare`" and is rejected by external adoption rather than trusted.
    attach_instance_id: u64 = 0,
    /// managed HostAdapter publication이 final heap address에 봉인한 incident identity다.
    incident_binding: incident_binding_contract.IncidentBinding = .{},
    parser: framing.FrameParser,
    // A Client may be transferred only once into the stable external-pump address. The moved-from
    // value remains deinit-safe, but is not a second transport owner.
    ownership: ClientOwnership = .standalone,
    // async full-state를 하나라도 수용하지 못하면 server subscription base는 이미 전진했을 수 있다. 그 뒤 같은 socket을
    // 계속 쓰면 어떤 shared stream이 누락됐는지 복구할 수 없으므로 connection 전체를 poison/close한다.
    unusable: bool = false,
    /// 최초 connection poison만 보존한다. 후속 EOF/cleanup 실패는 원인을 덮지 않는다.
    first_poison_reason: ?client_poison.ConnectionReason = null,
    /// 최초 reason과 같은 held operation에서 게시되는 correlation이다. sequence 0은 아직 미게시 상태다.
    first_incident_id: connection_incident.IncidentId = .{ .app_instance_nonce = 0, .sequence = 0 },
    /// repeat는 raw incident ID 대신 final-address Client에 봉인된 이 권위만 소비한다.
    incident_repeat_key: incident_publication_contract.IncidentRepeatKey = .{},
    next_request_id: u64 = 1,
    /// Correlated response frame가 deadline과 request-id 검증을 모두 통과한 뒤에만 게시한다.
    /// `next_request_id - 1`은 write 시도일 뿐 성공 증거가 아니므로 incident projection이 추측하지 않는다.
    last_success_request_id: u64 = 0,
    // 응답을 기다리는 `call` 중에 host가 비동기로 push한 stream frame(delta_chunk/snapshot_chunk)을 여기 버퍼한다 — 드롭하면
    // 화면 갱신이 유실되므로(§9 delta는 증분이라 하나만 놓쳐도 desync), 다음 `readStreamBatch`가 소켓보다 먼저 이걸 비운다.
    pending_stream: std.ArrayListUnmanaged(framing.Frame) = .empty,
    pending_stream_bytes: usize = 0,
    // screen batch와 별개인 full-state runtime metadata/resize event. 종류별로 최신 한 건을 coalesce한다.
    pending_events: std.ArrayListUnmanaged(BufferedEvent) = .empty,
    pending_event_bytes: usize = 0,
    // 멀티 runtime demux(§9): 여러 원격 runtime이 이 connection **하나**를 공유하므로, `readStreamBatch(want)`가 소켓에서 읽은
    // 완성 배치가 **다른** stream의 것이면 버리지 않고 여기 도착 순서대로 쌓아, 그 stream의 runtime pump가 나중에 소비한다(예전엔
    // pumpDelta가 남의 배치를 free해 두 번째 이후 터미널 화면이 영구 유실됐다 — code-review #1). host는 배치를 stream별로 연속
    // write하므로(프레임 인터리브 없음) 각 원소는 완결된 한 배치다. 모든 원격 runtime이 **단일 app-전역 backend**를 공유해 한
    // allocator로 이 배치들을 만들고/소비/해제하므로(불변식) 버퍼-소비 간 allocator가 일치한다. deinit이 잔여를 회수한다.
    pending_batches: std.ArrayListUnmanaged(StreamBatch) = .empty,
    pending_batch_bytes: usize = 0,
    /// Catch-up barrier는 screen batch와 같은 socket을 공유하지만 screen record가 아니다.
    /// 기존 demux가 sibling barrier를 잃지 않도록 connection-local bounded inbox가 소유한다.
    pending_catchup_barriers: std.ArrayListUnmanaged(BufferedCatchupBarrier) = .empty,
    // Generation GUI로 넘긴 payload도 실제 free callback이 반환할 때까지 같은 18 MiB/4,096 resident budget에 남는다.
    generation_batch_accounting: GenerationBatchAccounting = .{},
    partial_batch: ?PartialBatch = null,
    // UI의 non-blocking input/viewport-command 경로가 socket backpressure를 만났을 때 소유하는 **단 하나의 완성 wire
    // frame**. offset은 이미 kernel이 수락한 prefix 뒤를 가리킨다. frame을 이 슬롯에 넣는 순간 payload/command는 caller
    // 관점에서 accepted이므로 재전송하지 않는다. 한 슬롯 + RemoteRuntime의 stream별 sticky intent로 메모리가 고정 상한이다.
    pending_outbound: ?PendingOutbound = null,
    io_mode: client_external_mode.Mode = .blocking,
    operation_fence: ?*ClientOperationFence = null,
    operation_fence_generation: u64 = 0,
    prepared_request_execution_lease_addr: usize = 0,
    prepared_request_execution_fence_addr: usize = 0,
    prepared_request_execution_fence_incarnation: u64 = 0,
    prepared_request_execution_fence_lease_identity: u64 = 0,
    prepared_request_execution_fence_mode: PreparedRequestExecutionFenceMode = .unbound,
    generation_allocator_scope_epoch: u64 = 0,
    active_generation_allocator_scope: ?GenerationAllocatorScopeIdentity = null,

    const PendingOutbound = struct {
        frame: []u8,
        stream_id: u64,
        offset: usize = 0,
    };

    const PartialBatch = struct {
        stream_id: u64,
        is_snapshot: bool,
        bytes: std.ArrayListUnmanaged(u8) = .empty,
        chunk_count: usize = 0,
    };

    /// host socket에 connect하고 hello를 왕복한다. 성공하면 `host_id`가 채워진 Client다. host가 없으면 EndpointAbsent
    /// (discovery가 이 신호로 spawn/host_unavailable을 가른다, P3-d2b). version 불일치는 IncompatibleVersion.
    pub fn connect(allocator: std.mem.Allocator, socket_path: [:0]const u8, profile: ConnectionProfile) ClientError!Client {
        return connectMajor(allocator, socket_path, profile, protocol.version_major);
    }

    /// P5c3c external attach transport. The caller creates one absolute deadline at phase entry;
    /// connect readiness and the complete hello exchange consume that same non-resettable budget.
    pub fn connectUntil(
        allocator: std.mem.Allocator,
        socket_path: [:0]const u8,
        connection_profile: ConnectionProfile,
        wire_major: u16,
        deadline: client_deadline.AbsoluteDeadline,
    ) DeadlineClientError!Client {
        return connectMajorUntilWithOps(
            allocator,
            socket_path,
            connection_profile,
            wire_major,
            deadline,
            client_deadline.posix_ops,
        );
    }

    pub fn connectAdmin(
        allocator: std.mem.Allocator,
        socket_path: [:0]const u8,
    ) ClientError!Client {
        return requireAdminCapability(try connect(allocator, socket_path, .admin));
    }

    pub fn connectAdminUntil(
        allocator: std.mem.Allocator,
        socket_path: [:0]const u8,
        deadline: client_deadline.AbsoluteDeadline,
    ) DeadlineClientError!Client {
        return requireAdminCapability(try connectUntil(
            allocator,
            socket_path,
            .admin,
            protocol.version_major,
            deadline,
        ));
    }

    /// exact artifact manifest로 먼저 인증한 frozen N-1 종료 연결만 legacy hello의 screen fingerprint 부재를
    /// 허용한다. 일반 attach와 current admin은 이 경로를 호출할 수 없고 기존 fingerprint 검증을 유지한다.
    pub fn connectFrozenShutdownUntil(
        allocator: std.mem.Allocator,
        socket_path: [:0]const u8,
        wire_major: u16,
        artifact_sha256: [32]u8,
        deadline: client_deadline.AbsoluteDeadline,
    ) DeadlineClientError!Client {
        const profile = compatibility.profileForMajor(wire_major) orelse return error.IncompatibleVersion;
        const shutdown = profile.shutdown_profile orelse return error.IncompatibleVersion;
        if (profile.kind != .previous or !shutdown.complete() or
            !std.mem.eql(u8, &shutdown.artifact_sha256, &artifact_sha256))
            return error.IncompatibleVersion;
        return connectMajorUntilWithOpsPolicy(
            allocator,
            socket_path,
            .gui,
            wire_major,
            deadline,
            client_deadline.posix_ops,
            true,
        );
    }

    fn requireAdminCapability(candidate: Client) ClientError!Client {
        var client = candidate;
        if (!client.admin_one_shot_v1) {
            client.deinit();
            return error.IncompatibleVersion;
        }
        return client;
    }

    pub fn requireAdminRuntimeEnd(self: *Client) ClientError!void {
        const operation_fence_held = try self.requireBlockingMode();
        defer if (operation_fence_held) self.endPublicMutation();
        if (self.admin_runtime_end_v1) return;
        self.poison(.capability_incompatible);
        return error.IncompatibleVersion;
    }

    /// Frozen N-1 adapter 전용 연결점. 범위 협상처럼 보이게 여러 major를 한 connection에 광고하지 않고,
    /// 선택한 wire major의 header와 hello 범위를 정확히 하나로 고정한다.
    pub fn connectMajor(
        allocator: std.mem.Allocator,
        socket_path: [:0]const u8,
        connection_profile: ConnectionProfile,
        wire_major: u16,
    ) ClientError!Client {
        const profile = compatibility.profileForMajor(wire_major) orelse return error.IncompatibleVersion;
        // over-long path는 sun_path(104B)를 넘겨 slice-bounds panic이 되므로 syscall 전에 거부한다(bind의 socketPathFits 대칭).
        if (!socket_server.socketPathFits(socket_path.len)) return error.EndpointDenied;
        const fd = c.socket(posix.AF.UNIX, posix.SOCK.STREAM, 0);
        if (fd < 0) return endpointError(posix.errno(fd));
        errdefer _ = c.close(fd);
        socket_server.setCloseOnExec(fd) catch return error.HandshakeFailed;
        // host가 죽은 socket에 write하면 SIGPIPE로 **프로세스가 죽는다** — EPIPE로 바꿔 catchable하게 한다(server accept 경로와 대칭).
        socket_server.setNoSigPipe(fd);
        // host가 연결만 받고(backlog) 응답하지 않으면 read가 영원히 막힌다 — recv timeout으로 ConnectionClosed로 빠져나온다.
        setReadTimeoutMs(fd, 5000);
        var addr = posix.sockaddr.un{ .family = posix.AF.UNIX, .path = undefined };
        @memset(&addr.path, 0);
        @memcpy(addr.path[0..socket_path.len], socket_path);
        const connect_rc = c.connect(fd, @ptrCast(&addr), @sizeOf(posix.sockaddr.un));
        if (connect_rc != 0) return endpointError(posix.errno(connect_rc));

        var self = Client{
            .allocator = allocator,
            .fd = fd,
            .host_id = 0,
            .wire_major = wire_major,
            .parser = framing.FrameParser.initForMajor(allocator, wire_major),
        };
        errdefer self.parser.deinit();

        // hello 전송.
        const hello = buildHelloMajorFeatures(
            allocator,
            connection_profile.wireKind(),
            wire_major,
            connection_profile.advertisesControllerTransfer(),
        ) catch return error.OutOfMemory;
        defer allocator.free(hello);
        const hello_frame = framing.encodeFrame(
            allocator,
            .{ .kind = .hello, .request_id = 0, .major = wire_major },
            hello,
        ) catch return error.OutOfMemory;
        defer allocator.free(hello_frame);
        socket_server.writeAll(fd, hello_frame) catch return error.WriteFailed;

        // hello_ack 수신.
        const ack = try self.readFrame();
        defer ack.deinit(allocator);
        try self.finishHello(connection_profile, profile, ack);
        return self;
    }

    fn connectMajorUntilWithOps(
        allocator: std.mem.Allocator,
        socket_path: [:0]const u8,
        connection_profile: ConnectionProfile,
        wire_major: u16,
        deadline: client_deadline.AbsoluteDeadline,
        ops: client_deadline.Ops,
    ) DeadlineClientError!Client {
        return connectMajorUntilWithOpsPolicy(
            allocator,
            socket_path,
            connection_profile,
            wire_major,
            deadline,
            ops,
            false,
        );
    }

    fn connectMajorUntilWithOpsPolicy(
        allocator: std.mem.Allocator,
        socket_path: [:0]const u8,
        connection_profile: ConnectionProfile,
        wire_major: u16,
        deadline: client_deadline.AbsoluteDeadline,
        ops: client_deadline.Ops,
        allow_attested_legacy_hello: bool,
    ) DeadlineClientError!Client {
        const profile = compatibility.profileForMajor(wire_major) orelse return error.IncompatibleVersion;
        const connected = client_deadline.connectUnixUntil(
            ops,
            socket_path,
            deadline,
        ) catch |err| return deadlineConnectError(err);
        var fd_transferred = false;
        errdefer if (!fd_transferred)
            ops.close(
                ops.context,
                connected.fd,
            );

        var self = Client{
            .allocator = allocator,
            .fd = connected.fd,
            .host_id = 0,
            .wire_major = wire_major,
            .parser = framing.FrameParser.initForMajor(allocator, wire_major),
        };
        fd_transferred = true;
        errdefer self.deinitHandshakeAttempt(ops);

        const hello = buildHelloMajorFeatures(
            allocator,
            connection_profile.wireKind(),
            wire_major,
            connection_profile.advertisesControllerTransfer(),
        ) catch return error.OutOfMemory;
        defer allocator.free(hello);
        const hello_frame = framing.encodeFrame(
            allocator,
            .{ .kind = .hello, .request_id = 0, .major = wire_major },
            hello,
        ) catch return error.OutOfMemory;
        defer allocator.free(hello_frame);
        client_deadline.writeAllUntil(
            ops,
            connected.fd,
            hello_frame,
            deadline,
        ) catch |err| return deadlineHelloError(err);

        const ack = try self.readFrameUntil(deadline, ops);
        defer ack.deinit(allocator);
        connected.restoreBlocking(ops) catch return error.ConnectionClosed;
        try self.finishHelloWithPolicy(connection_profile, profile, ack, allow_attested_legacy_hello);
        if (deadline.remainingNs() <= 0) return error.DeadlineExceeded;
        return self;
    }

    fn deinitHandshakeAttempt(self: *Client, ops: client_deadline.Ops) void {
        // The injected connector owns close observability until a successful Client is returned.
        ops.close(ops.context, self.fd);
        self.fd = -1;
        // Reuse the one Client destructor so future hello-owned fields cannot create a second,
        // incomplete cleanup inventory in this transport seam.
        self.deinit();
    }

    fn finishHello(
        self: *Client,
        connection_profile: ConnectionProfile,
        profile: compatibility.Profile,
        ack: framing.Frame,
    ) ClientError!void {
        return self.finishHelloWithPolicy(connection_profile, profile, ack, false);
    }

    fn finishHelloWithPolicy(
        self: *Client,
        connection_profile: ConnectionProfile,
        profile: compatibility.Profile,
        ack: framing.Frame,
        allow_attested_legacy_hello: bool,
    ) ClientError!void {
        if (ack.header.kind != .hello_ack) return error.HandshakeFailed;
        if (std.mem.indexOf(u8, ack.payload, "incompatible_version") != null) return error.IncompatibleVersion;
        if (std.mem.indexOf(u8, ack.payload, "\"error\":\"resource_exhausted\"") != null)
            return error.AdminBusy;
        if (std.mem.indexOf(u8, ack.payload, "\"error\":\"unauthorized\"") != null)
            return error.Unauthorized;
        if (parseSelectedVersion(ack.payload) != self.wire_major) return error.HandshakeFailed;
        // 과거 개발 중 같은 MRSH v1 아래 screen body 의미가 여러 번 바뀌었다. build identity가 없는 untagged v1을
        // current body로 추측하면 structurally-valid silent misrender가 가능하므로, frozen release가 명시한
        // capability가 있는 직전 major만 연다. current major는 major bump 자체가 screen v2 경계다.
        if (profile.required_fingerprint) |fingerprint| if (!payloadHasCapability(ack.payload, fingerprint)) {
            const shutdown = profile.shutdown_profile orelse return error.IncompatibleVersion;
            if (!allow_attested_legacy_hello or connection_profile != .gui or
                profile.kind != .previous or !shutdown.complete())
                return error.IncompatibleVersion;
        };
        self.host_id = parseHostId(ack.payload) orelse return error.HandshakeFailed;
        const build_id = try parseStringFieldAlloc(self.allocator, ack.payload, "build_id");
        errdefer if (build_id) |owned| self.allocator.free(owned);
        const lifecycle = try parseStringFieldAlloc(self.allocator, ack.payload, "lifecycle");
        errdefer if (lifecycle) |owned| self.allocator.free(owned);
        const upgrade_epoch = parseUnsignedField(ack.payload, "upgrade_epoch");
        const authority_generation = parseUnsignedField(ack.payload, "authority_generation");
        const peer_screen_codec = parseUnsignedField(ack.payload, "screen_codec_version");
        const manifest_capable = payloadHasCapability(ack.payload, "host_manifest_v1");
        const inventory_capable = payloadHasCapability(ack.payload, "runtime_inventory_v1");
        if (manifest_capable and
            (build_id == null or lifecycle == null or upgrade_epoch == null or peer_screen_codec == null))
            return error.HandshakeFailed;
        if (inventory_capable and
            (authority_generation == null or authority_generation.? == 0 or !manifest_capable))
            return error.HandshakeFailed;
        if (peer_screen_codec) |codec| {
            if (codec > std.math.maxInt(u16)) return error.HandshakeFailed;
            self.screen_codec_version = @intCast(codec);
        } else {
            self.screen_codec_version = profile.screen_codec_version;
        }
        self.build_id = build_id;
        self.upgrade_epoch = upgrade_epoch orelse 0;
        self.authority_generation = authority_generation orelse 0;
        self.lifecycle = lifecycle orelse &.{};
        self.host_manifest_v1 = manifest_capable;
        self.host_exec_upgrade_v1 = payloadHasCapability(ack.payload, "host_exec_upgrade_v1");
        self.runtime_inventory_v1 = inventory_capable;
        self.runtime_catchup_barrier_v1 =
            payloadHasCapability(ack.payload, catchup_barrier_contract.capability);
        // Capability request is a promise that the selected profile consumes revoke and fences
        // queued mutation; unsolicited host support alone never enables transfer.
        self.attachment_capabilities.peer_attach_generation =
            payloadHasCapability(ack.payload, "controller_transfer_v1");
        self.attachment_capabilities.negotiated_controller_transfer =
            connection_profile.advertisesControllerTransfer() and
            self.attachment_capabilities.peer_attach_generation;
        self.metadata_support = if (profile.kind == .current and
            payloadHasCapability(ack.payload, "runtime_metadata_v1"))
            .supported
        else
            .unsupported;
        self.admin_one_shot_v1 = payloadHasCapability(ack.payload, "admin_one_shot_v1");
        self.admin_runtime_end_v1 = payloadHasCapability(ack.payload, "admin_runtime_end_v1");
        self.screen_viewport_scrolled_v1 = payloadHasCapability(ack.payload, "screen_viewport_scrolled_v1");
        self.async_scroll_to_bottom_v1 = payloadHasCapability(ack.payload, "async_scroll_to_bottom_v1");
        self.runtime_core_command_v1 = payloadHasCapability(ack.payload, "runtime_core_command_v1");
        self.runtime_clear_screen_v1 = payloadHasCapability(ack.payload, "runtime_clear_screen_v1");
        self.runtime_selected_text_v1 = payloadHasCapability(ack.payload, "runtime_selected_text_v1");
        self.runtime_selection_state_v1 = payloadHasCapability(ack.payload, "runtime_selection_state_v1");
        if (self.runtime_selection_state_v1 and
            (!self.runtime_core_command_v1 or !self.runtime_selected_text_v1))
            return error.HandshakeFailed;
        self.notification_stream_auth_v1 = payloadHasCapability(
            ack.payload,
            "notification_stream_auth_v1",
        );
        self.notification_delivery_v1 = payloadHasCapability(
            ack.payload,
            "notification_delivery_v1",
        );
        if (self.notification_delivery_v1 and !self.notification_stream_auth_v1)
            return error.HandshakeFailed;
        self.runtime_link_at_v1 = payloadHasCapability(ack.payload, "runtime_link_at_v1");
        self.runtime_clipboard_v1 = payloadHasCapability(ack.payload, "runtime_clipboard_v1");
        // This is the sole proof publication point: all schema/fingerprint checks above succeeded.
        self.connection_profile = connection_profile;
        self.compatibility_profile = profile;
    }

    pub fn deinit(self: *Client) void {
        _ = self.tryDeinit();
    }

    pub fn tryDeinit(self: *Client) bool {
        const operation_fence = self.operation_fence;
        var operation_fence_exclusive = false;
        if (operation_fence) |fence| {
            fence.tryAcquireExclusive(@intFromPtr(self), self.operation_fence_generation) catch
                return false;
            operation_fence_exclusive = true;
        } else if (self.operation_fence_generation != 0) return false;
        defer if (operation_fence_exclusive) {
            const fence = operation_fence.?;
            if (!fence.abortExclusive(@intFromPtr(self), self.operation_fence_generation))
                @panic("Client deinit operation fence abort failed");
        };
        if (checkedAllocatorReentry(self)) return false;
        if (self.ownership == .moved) return true;
        if (!self.prepareDeinitGraph(operation_fence != null)) return false;
        self.finishDeinitGraph();
        const client_addr = @intFromPtr(self);
        const operation_fence_generation = self.operation_fence_generation;
        if (operation_fence) |fence| {
            if (!fence.commitExclusiveTerminal(client_addr, operation_fence_generation))
                @panic("Client deinit operation fence commit failed");
            operation_fence_exclusive = false;
        }
        self.* = undefined;
        return true;
    }

    fn prepareDeinitGraph(self: *Client, bound_client: bool) bool {
        if (checkedAllocatorReentry(self)) return false;
        if (self.ownership == .moved) return false;
        if (self.pending_events.items.len != 0 and
            !(self.connection_profile != null and
                self.connection_profile.?.requiresStrictExternalEvents()) and
            !self.validateGenerationEventQueue())
        {
            self.poison(.local_invariant_violation);
            return false;
        }
        if (self.prepared_request_execution_lease_addr != 0 or
            self.prepared_request_execution_fence_addr != 0 or
            self.prepared_request_execution_fence_incarnation != 0 or
            self.prepared_request_execution_fence_lease_identity != 0 or
            self.prepared_request_execution_fence_mode != .unbound) return false;
        if (self.active_generation_allocator_scope != null) return false;
        if (!self.generation_batch_accounting.valid(@intFromPtr(self)) or
            (self.generation_batch_accounting.ledger != null and
                self.generation_batch_accounting.ledger.?.preflightDeinit() != .cleaned))
            return false;
        if (bound_client) {
            // A generation-node Client is admitted only in blocking mode and the public external
            // transition participates in this fence. Any external state here is pre-callback
            // invariant drift, so the exclusive owner may abort without erasing mutation effects.
            switch (self.io_mode) {
                .blocking => {},
                .external => return false,
            }
        } else if (!self.prepareExternalModeDeinit()) return false;
        return true;
    }

    /// CR3b R3의 retired generation owner가 destroy 전 사용하는 pure preflight다.
    /// callback, free, poison publication과 fence mutation을 수행하지 않는다.
    pub fn canRetireFromGenerationNode(self: *const Client) bool {
        if (checkedAllocatorReentry(self) or self.ownership == .moved or
            self.fd != -1 or !self.unusable or self.pending_outbound != null or
            self.io_mode != .blocking)
            return false;
        const fence = self.operation_fence orelse return false;
        if (fence.intruded(@intFromPtr(self), self.operation_fence_generation)) return false;
        if (self.pending_stream.items.len != 0 or self.pending_stream_bytes != 0 or
            self.pending_events.items.len != 0 or self.pending_event_bytes != 0 or
            self.pending_batches.items.len != 0 or self.pending_batch_bytes != 0 or
            self.partial_batch != null or self.parser.bufferedBytes() != 0)
            return false;
        if (self.prepared_request_execution_lease_addr != 0 or
            self.prepared_request_execution_fence_addr != 0 or
            self.prepared_request_execution_fence_incarnation != 0 or
            self.prepared_request_execution_fence_lease_identity != 0 or
            self.prepared_request_execution_fence_mode != .unbound or
            self.active_generation_allocator_scope != null)
            return false;
        return self.generation_batch_accounting.valid(@intFromPtr(self)) and
            (self.generation_batch_accounting.ledger == null or
                self.generation_batch_accounting.ledger.?.preflightDeinit() == .cleaned);
    }

    /// R3 prepared destination/source ranges must not alias any backing that Client deinit owns.
    /// Malformed range metadata fails closed and this projection never allocates or mutates.
    pub fn retirementRangeAliasesOwnedBacking(
        self: *const Client,
        start: usize,
        len: usize,
    ) bool {
        const target = checkedExternalRange(start, len) catch return true;
        return externalRangeOverlapsClient(self, target orelse return false) catch true;
    }

    fn finishDeinitGraph(self: *Client) void {
        if (self.fd >= 0) _ = c.close(self.fd);
        if (self.build_id) |build_id| self.allocator.free(build_id);
        if (self.lifecycle.len != 0) self.allocator.free(self.lifecycle);
        self.clearPendingOutbound();
        for (self.pending_stream.items) |f| f.deinit(self.allocator); // 미소비 버퍼 stream frame 회수.
        self.pending_stream.deinit(self.allocator);
        for (self.pending_events.items) |f| f.deinit(self.allocator);
        self.pending_events.deinit(self.allocator);
        for (self.pending_batches.items) |b| b.deinit(); // 미소비 demux 배치 회수(§9 멀티 runtime).
        self.pending_batches.deinit(self.allocator);
        self.pending_catchup_barriers.deinit(self.allocator);
        if (self.partial_batch) |*partial| partial.bytes.deinit(self.allocator);
        self.parser.deinit();
    }

    /// CR3a generation-node ownership move.  This is intentionally narrower than external-pump
    /// adoption: only a standalone, blocking Client may enter the heap-pinned ClientSlot node.
    /// The caller allocates and validates the final destination before invoking this no-fail
    /// suffix, so a failed HostAdapter initialization never partially moves socket ownership.
    pub fn canMoveToGenerationNode(self: *const Client) bool {
        if (self.operation_fence != null or self.operation_fence_generation != 0) return false;
        if (self.prepared_request_execution_lease_addr != 0 or
            self.prepared_request_execution_fence_addr != 0 or
            self.prepared_request_execution_fence_incarnation != 0 or
            self.prepared_request_execution_fence_lease_identity != 0 or
            self.prepared_request_execution_fence_mode != .unbound) return false;
        if (self.active_generation_allocator_scope != null) return false;
        return self.ownership == .standalone and self.io_mode == .blocking and !self.unusable and
            self.generation_batch_accounting.valid(@intFromPtr(self)) and
            (self.generation_batch_accounting.ledger == null or
                self.generation_batch_accounting.ledger.?.preflightDeinit() == .cleaned) and
            self.generationBatchSourceRangesValid();
    }

    fn generationBatchSourceRangesValid(self: *const Client) bool {
        const client_start = @intFromPtr(self);
        const client_end = std.math.add(usize, client_start, @sizeOf(Client)) catch return false;
        for (self.pending_batches.items, 0..) |batch, index| {
            if (batch.bytes.len == 0) return false;
            const start = @intFromPtr(batch.bytes.ptr);
            const end = std.math.add(usize, start, batch.bytes.len) catch return false;
            if (rawRangesOverlap(start, end, client_start, client_end)) return false;
            for (self.pending_batches.items[index + 1 ..]) |sibling| {
                const sibling_start = @intFromPtr(sibling.bytes.ptr);
                const sibling_end = std.math.add(
                    usize,
                    sibling_start,
                    sibling.bytes.len,
                ) catch return false;
                if (rawRangesOverlap(start, end, sibling_start, sibling_end)) return false;
            }
            if (self.partial_batch) |partial| {
                const partial_start = @intFromPtr(partial.bytes.items.ptr);
                const partial_end = std.math.add(
                    usize,
                    partial_start,
                    partial.bytes.capacity,
                ) catch return false;
                if (partial.bytes.capacity != 0 and
                    rawRangesOverlap(start, end, partial_start, partial_end)) return false;
            }
        }
        return true;
    }

    pub fn bindGenerationAccountingLedger(
        self: *Client,
        ledger: *generation_batch_registry.AccountingLedger,
    ) generation_batch_registry.Error!void {
        if (self.generation_batch_accounting.ledger != null)
            return error.InvalidState;
        try ledger.bindClient(@intFromPtr(self));
        self.generation_batch_accounting.ledger = ledger;
    }

    pub const GenerationAllocatorPurpose = generation_batch_registry.AllocatorScopePurpose;

    pub const GenerationAllocatorScopeLifecycle = enum {
        pristine,
        active,
        restored,
    };

    /// generation allocator scope 가 무효가 되는 축. 닫힌 집합이라 새 축을 더하면 여기부터 손댄다.
    pub const ScopeInvalidAxis = enum {
        ledger_absent,
        purpose_out_of_range,
        token_addr_zero,
        client_addr_mismatch,
        epoch_zero,
        ledger_mismatch,
        installed_allocator_mismatch,
        parser_allocator_mismatch,
    };

    const GenerationAllocatorScopeIdentity = struct {
        token_addr: usize,
        client_addr: usize,
        epoch: u64,
        purpose: GenerationAllocatorPurpose,
        previous_allocator: std.mem.Allocator,
        installed_allocator: std.mem.Allocator,

        /// scope 가 이 Client 에 유효하지 않게 만드는 **첫 축**. 유효하면 null.
        ///
        /// 판정 자체는 `validForClient` 와 완전히 같다(같은 순서·같은 조건). 나눠 둔 이유는 진단이다 —
        /// 2026-08-26 에 이 검사가 실패해 read pump 가 연결을 poison 했고 incident 10 건이 남았는데,
        /// 전부 `local_invariant_violation` 한 값뿐이라 **일곱 축 중 무엇이 깨졌는지 알 길이 없었다.**
        /// 원인 추적이 정확히 여기서 막혔다.
        fn firstInvalidAxis(self: GenerationAllocatorScopeIdentity, client: *const Client) ?ScopeInvalidAxis {
            const purpose_raw = @as(*const u8, @ptrCast(&self.purpose)).*;
            const ledger = client.generation_batch_accounting.ledger orelse return .ledger_absent;
            if (purpose_raw > @intFromEnum(GenerationAllocatorPurpose.rpc_execute)) return .purpose_out_of_range;
            if (self.token_addr == 0) return .token_addr_zero;
            if (self.client_addr != @intFromPtr(client)) return .client_addr_mismatch;
            if (self.epoch == 0) return .epoch_zero;
            if (!ledger.allocatorScopeMatches(
                self.client_addr,
                self.token_addr,
                self.epoch,
                purpose_raw,
                self.previous_allocator,
                self.installed_allocator,
            )) return .ledger_mismatch;
            if (!allocatorEql(client.allocator, self.installed_allocator)) return .installed_allocator_mismatch;
            if (!client.parser.usesAllocator(self.installed_allocator)) return .parser_allocator_mismatch;
            return null;
        }

        fn validForClient(self: GenerationAllocatorScopeIdentity, client: *const Client) bool {
            return self.firstInvalidAxis(client) == null;
        }

        fn matchesToken(
            self: GenerationAllocatorScopeIdentity,
            token: *const GenerationAllocatorScope,
        ) bool {
            return self.token_addr == @intFromPtr(token) and token.self_addr == @intFromPtr(token) and
                self.client_addr == token.client_addr and self.epoch == token.epoch and
                self.purpose == token.purpose and
                @intFromPtr(self.previous_allocator.ptr) == token.previous_allocator_ptr and
                @intFromPtr(self.previous_allocator.vtable) == token.previous_allocator_vtable and
                @intFromPtr(self.installed_allocator.ptr) == token.installed_allocator_ptr and
                @intFromPtr(self.installed_allocator.vtable) == token.installed_allocator_vtable;
        }
    };

    pub const GenerationAllocatorScope = struct {
        self_addr: usize = 0,
        client_addr: usize = 0,
        epoch: u64 = 0,
        purpose: GenerationAllocatorPurpose = .attachment_batch,
        previous_allocator_ptr: usize = 0,
        previous_allocator_vtable: usize = 0,
        installed_allocator_ptr: usize = 0,
        installed_allocator_vtable: usize = 0,
        lifecycle: GenerationAllocatorScopeLifecycle = .pristine,

        fn rawDiscriminatorsValid(self: *const GenerationAllocatorScope) bool {
            const purpose_raw = @as(*const u8, @ptrCast(&self.purpose)).*;
            const lifecycle_raw = @as(*const u8, @ptrCast(&self.lifecycle)).*;
            return purpose_raw <= @intFromEnum(GenerationAllocatorPurpose.rpc_execute) and
                lifecycle_raw <= @intFromEnum(GenerationAllocatorScopeLifecycle.restored);
        }
    };

    fn allocatorEql(left: std.mem.Allocator, right: std.mem.Allocator) bool {
        return left.ptr == right.ptr and left.vtable == right.vtable;
    }

    /// canonical event allocator scope 가 깨진 **축**을 남긴다.
    ///
    /// incident 는 `local_invariant_violation` 이라는 **결론**만 담는다 — DTO 의 scalar 집합이 고정이라
    /// 그 결론에 이른 축은 실을 자리가 없다. 2026-08-26 에 이 경로로 incident 10 건이 쌓였는데 전부 같은
    /// 값이라 일곱 축 중 무엇이 깨졌는지 못 좁혔고, 추적이 거기서 멈췄다. GUI 진단이
    /// `<cache>/maru/app.log` 로 남게 된 지금은 이 한 줄이 다음 재발의 출발점이 된다.
    ///
    /// 판정에는 관여하지 않는다 — fail-closed 는 그대로이고 사유만 적는다.
    fn logCanonicalScopeInvalid(axis: ScopeInvalidAxis) void {
        if (builtin.is_test) return;
        std.log.err("canonical event allocator scope invalid: axis={s}", .{@tagName(axis)});
    }

    /// Event ownership outlives a blocking generation allocator scope. While the parser uses the
    /// installed allocator, event publication remains anchored to the pre-scope Client domain.
    fn canonicalEventAllocator(self: *const Client) error{InvalidState}!std.mem.Allocator {
        if (self.active_generation_allocator_scope) |scope| {
            if (scope.firstInvalidAxis(self)) |axis| {
                logCanonicalScopeInvalid(axis);
                return error.InvalidState;
            }
            return scope.previous_allocator;
        }
        return self.allocator;
    }

    pub fn beginGenerationAllocatorScope(
        self: *Client,
        allocator: std.mem.Allocator,
        purpose: GenerationAllocatorPurpose,
        out: *GenerationAllocatorScope,
    ) (ClientError || generation_batch_registry.Error)!void {
        const operation_fence_held = try self.ensureUsable();
        defer if (operation_fence_held) self.endPublicMutation();
        const client_start = @intFromPtr(self);
        const client_end = std.math.add(usize, client_start, @sizeOf(Client)) catch
            return error.InvalidState;
        const out_start = @intFromPtr(out);
        const out_end = std.math.add(usize, out_start, @sizeOf(GenerationAllocatorScope)) catch
            return error.InvalidState;
        if (self.generation_batch_accounting.ledger == null or self.io_mode != .blocking or
            self.ownership != .standalone or !self.parser.usesAllocator(self.allocator) or
            self.active_generation_allocator_scope != null or
            !out.rawDiscriminatorsValid() or out.self_addr != 0 or
            out.client_addr != 0 or out.epoch != 0 or
            out.purpose != .attachment_batch or
            out.previous_allocator_ptr != 0 or out.previous_allocator_vtable != 0 or
            out.installed_allocator_ptr != 0 or out.installed_allocator_vtable != 0 or
            out.lifecycle != .pristine or
            rawRangesOverlap(client_start, client_end, out_start, out_end))
            return error.InvalidState;
        const epoch = std.math.add(u64, self.generation_allocator_scope_epoch, 1) catch
            return error.IdentityExhausted;
        if (epoch == 0) return error.IdentityExhausted;
        const active_identity: GenerationAllocatorScopeIdentity = .{
            .token_addr = out_start,
            .client_addr = @intFromPtr(self),
            .epoch = epoch,
            .purpose = purpose,
            .previous_allocator = self.allocator,
            .installed_allocator = allocator,
        };
        try self.generation_batch_accounting.ledger.?.beginAllocatorScope(
            @intFromPtr(self),
            out_start,
            epoch,
            @intFromEnum(purpose),
            self.allocator,
            allocator,
        );
        out.* = .{
            .self_addr = out_start,
            .client_addr = @intFromPtr(self),
            .epoch = epoch,
            .purpose = purpose,
            .previous_allocator_ptr = @intFromPtr(self.allocator.ptr),
            .previous_allocator_vtable = @intFromPtr(self.allocator.vtable),
            .installed_allocator_ptr = @intFromPtr(allocator.ptr),
            .installed_allocator_vtable = @intFromPtr(allocator.vtable),
            .lifecycle = .active,
        };
        self.generation_allocator_scope_epoch = epoch;
        self.active_generation_allocator_scope = active_identity;
        self.allocator = allocator;
        self.parser.restoreAllocatorAfterDrift(allocator);
    }

    pub fn requireBufferedGenerationBatch(self: *const Client, stream_id: u64) ClientError!void {
        const operation_fence_held = try self.ensureUsable();
        defer if (operation_fence_held) self.endPublicMutation();
        for (self.pending_batches.items) |pending| {
            if (pending.stream_id == stream_id) return;
        }
        return error.AdminBusy;
    }

    pub fn restoreGenerationAllocatorScope(
        self: *Client,
        scope: *GenerationAllocatorScope,
    ) (ClientError || generation_batch_registry.Error)!void {
        const operation_fence_held = try self.beginPublicMutation();
        defer if (operation_fence_held) self.endPublicMutation();
        return self.restoreGenerationAllocatorScopeUnchecked(scope);
    }

    pub fn restoreGenerationAllocatorScopeUnderExecutionLease(
        self: *Client,
        scope: *GenerationAllocatorScope,
        lease: *PreparedRequestExecutionLease,
    ) (ClientError || generation_batch_registry.Error)!void {
        if (!self.preparedRequestExecutionLeaseAuthorityMatches(lease))
            return error.InvalidState;
        try self.restoreGenerationAllocatorScopeUnchecked(scope);
        // The allocator domain is part of the sealed execution authority. Keep the still-held
        // lease synchronized so terminal settlement can authenticate it after publication cleanup.
        lease.allocator_ptr = @intFromPtr(self.allocator.ptr);
        lease.allocator_vtable = @intFromPtr(self.allocator.vtable);
        lease.seal = preparedExecutionLeaseSeal(lease);
    }

    fn restoreGenerationAllocatorScopeUnchecked(
        self: *Client,
        scope: *GenerationAllocatorScope,
    ) (ClientError || generation_batch_registry.Error)!void {
        const active = self.active_generation_allocator_scope orelse return error.InvalidState;
        if (!scope.rawDiscriminatorsValid() or scope.lifecycle != .active or
            !active.validForClient(self) or
            !active.matchesToken(scope) or
            active.client_addr != @intFromPtr(self) or
            !allocatorEql(self.allocator, active.installed_allocator) or
            !self.parser.usesAllocator(active.installed_allocator))
            return error.InvalidState;
        try self.generation_batch_accounting.ledger.?.endAllocatorScope(
            active.client_addr,
            active.token_addr,
            active.epoch,
            @intFromEnum(active.purpose),
            active.previous_allocator,
            active.installed_allocator,
        );
        self.allocator = active.previous_allocator;
        self.parser.restoreAllocatorAfterDrift(active.previous_allocator);
        self.active_generation_allocator_scope = null;
        scope.self_addr = 0;
        scope.lifecycle = .restored;
    }

    pub fn moveToGenerationNode(self: *Client, destination: *Client) void {
        if (!self.canMoveToGenerationNode()) @panic("invalid Client generation-node move");
        const source_start = @intFromPtr(self);
        const destination_start = @intFromPtr(destination);
        const source_end = std.math.add(usize, source_start, @sizeOf(Client)) catch
            @panic("invalid Client generation-node source range");
        const destination_end = std.math.add(usize, destination_start, @sizeOf(Client)) catch
            @panic("invalid Client generation-node destination range");
        if (source_start < destination_end and destination_start < source_end)
            @panic("aliased Client generation-node move");
        const allocator = self.allocator;
        const expected_major = self.parser.expected_major;
        destination.* = self.*;
        // Rebuild from defaults rather than clearing selected fields.  New Client-owned fields
        // must therefore opt into the destination copy above and cannot silently leave a second
        // owner in the moved-from tombstone.
        self.* = .{
            .allocator = allocator,
            .fd = -1,
            .host_id = 0,
            .parser = framing.FrameParser.initForMajor(allocator, expected_major),
            .ownership = .moved,
            .unusable = true,
        };
    }

    /// Deep snapshot of the descriptors and descriptor elements consumed by `deinit`. This is
    /// process-local authority evidence; payload contents are intentionally excluded.
    pub fn clientProjectionAuthorityDigest(self: *const Client) owner_seal.Digest {
        var writer = owner_seal.Writer.init("maru.client-owner.projection.v1");
        writer.writeBool(self.terminalReasonInvariant());
        writer.writeUsize(@intFromPtr(self));
        writer.writeUsize(@intFromPtr(self.allocator.ptr));
        writer.writeUsize(@intFromPtr(self.allocator.vtable));
        writer.writeU64(@bitCast(@as(i64, self.fd)));
        writer.writeU128(self.host_id);
        writer.writeUsize(if (self.build_id) |bytes|
            if (bytes.len == 0) 0 else @intFromPtr(bytes.ptr)
        else
            0);
        writer.writeUsize(if (self.build_id) |bytes| bytes.len else 0);
        writer.writeUsize(if (self.lifecycle.len == 0) 0 else @intFromPtr(self.lifecycle.ptr));
        writer.writeUsize(self.lifecycle.len);
        writer.writeU8(@intFromEnum(self.ownership));
        writer.writeBool(self.unusable);
        writer.writeBool(self.first_poison_reason != null);
        if (self.first_poison_reason) |reason| writer.writeU8(@intFromEnum(reason));
        writer.writeU64(self.next_request_id);
        writer.writeUsize(if (self.parser.buf.capacity == 0)
            0
        else
            @intFromPtr(self.parser.buf.items.ptr));
        writer.writeUsize(self.parser.buf.items.len);
        writer.writeUsize(self.parser.buf.capacity);
        writer.writeUsize(self.parser.head);
        writeProjectionBatches(&writer, self.pending_batches);
        writeProjectionFrames(&writer, self.pending_stream);
        writeProjectionEvents(&writer, self.pending_events);
        writeProjectionCatchupBarriers(&writer, self.pending_catchup_barriers);
        writer.writeUsize(self.pending_batch_bytes);
        const generation_ledger = self.generation_batch_accounting.ledger;
        writer.writeUsize(if (generation_ledger) |ledger| ledger.item_count else 0);
        writer.writeUsize(if (generation_ledger) |ledger| ledger.byte_count else 0);
        writer.writeU64(self.generation_batch_accounting.last_transfer_id);
        writer.writeUsize(if (generation_ledger) |ledger| ledger.releasing_item_count else 0);
        writer.writeUsize(if (generation_ledger) |ledger| ledger.releasing_byte_count else 0);
        writer.writeUsize(self.pending_stream_bytes);
        writer.writeUsize(self.pending_event_bytes);
        if (self.partial_batch) |partial| {
            writer.writeBool(true);
            writer.writeU64(partial.stream_id);
            writer.writeBool(partial.is_snapshot);
            writer.writeUsize(if (partial.bytes.capacity == 0)
                0
            else
                @intFromPtr(partial.bytes.items.ptr));
            writer.writeUsize(partial.bytes.items.len);
            writer.writeUsize(partial.bytes.capacity);
            writer.writeUsize(partial.chunk_count);
        } else writer.writeBool(false);
        if (self.pending_outbound) |outbound| {
            writer.writeBool(true);
            writer.writeUsize(if (outbound.frame.len == 0)
                0
            else
                @intFromPtr(outbound.frame.ptr));
            writer.writeUsize(outbound.frame.len);
            writer.writeU64(outbound.stream_id);
            writer.writeUsize(outbound.offset);
        } else writer.writeBool(false);
        writer.writeU64(self.generation_allocator_scope_epoch);
        if (self.active_generation_allocator_scope) |scope| {
            writer.writeBool(true);
            writer.writeUsize(scope.token_addr);
            writer.writeUsize(scope.client_addr);
            writer.writeU64(scope.epoch);
            writer.writeU8(@intFromEnum(scope.purpose));
            writer.writeUsize(@intFromPtr(scope.previous_allocator.ptr));
            writer.writeUsize(@intFromPtr(scope.previous_allocator.vtable));
            writer.writeUsize(@intFromPtr(scope.installed_allocator.ptr));
            writer.writeUsize(@intFromPtr(scope.installed_allocator.vtable));
        } else writer.writeBool(false);
        return writer.finish();
    }

    pub fn externalTransferProfile(self: *const Client) ?ExternalTransferProfile {
        if (self.operation_fence != null or self.operation_fence_generation != 0) return null;
        const connection_profile = self.connection_profile orelse return null;
        if (connection_profile != .cli_attach) return null;
        const selected = self.compatibility_profile orelse return null;
        const canonical = compatibility.profileForMajor(self.wire_major) orelse return null;
        // One rule, one implementation: `validateExternalAdoptionClient` decides the same
        // "selected profile is the canonical profile for this major" question, so a future
        // `compatibility.Profile` field must not be honoured by one path and ignored by the other.
        if (self.screen_codec_version != canonical.screen_codec_version or
            !compatibilityProfilesEqual(selected, canonical))
            return null;
        const fingerprint = selected.required_fingerprint orelse "";
        return .{
            .wire_major = self.wire_major,
            .connection_profile = connection_profile,
            .compatibility_kind = selected.kind,
            .screen_codec_version = selected.screen_codec_version,
            .attach_schema = selected.attach_schema,
            .fingerprint_present = selected.required_fingerprint != null,
            .fingerprint_digest = runtime_event_wire.payloadDigest(fingerprint),
            .attachment_capabilities = self.attachment_capabilities,
            .metadata_support = self.metadata_support,
        };
    }

    /// Freezes every inherited queue payload into caller-owned fixed scratch without allocating,
    /// invoking callbacks, or mutating the Client.
    pub fn prepareExternalRecoveryDiscard(
        self: *const Client,
        target_stream: u64,
        cleanup_scratch: *ExternalAdoptionCleanupScratch,
        source_scratch: *ExternalSourceOwnerRangeScratch,
        out: *ExternalRecoveryDiscardSeal,
    ) ExternalSourceSealError!void {
        if (!out.isEmpty() or
            externalRangesOverlap(
                externalRangeOfValue(out),
                externalRangeOfValue(cleanup_scratch),
            ))
            return error.InvalidAlias;
        try self.preflightExternalAdoptionDestinationWithScratchPolicy(
            cleanup_scratch,
            @sizeOf(ExternalAdoptionCleanupScratch),
            source_scratch,
            .allow_bounded,
        );
        try self.preflightExternalAdoptionDestinationWithScratchPolicy(
            out,
            @sizeOf(ExternalRecoveryDiscardSeal),
            source_scratch,
            .allow_bounded,
        );
        _ = validateExternalAdoptionClient(
            self,
            target_stream,
            .{
                .owner_aliases = .skip,
                .request_id = .allow_zero,
                .catchup_barriers = .allow_bounded,
            },
        ) catch |err| return narrowExternalSourceSealError(err);
        if (self.pending_batches.items.len > cleanup_scratch.batches.len or
            self.pending_stream.items.len > cleanup_scratch.stream.len or
            self.pending_events.items.len > cleanup_scratch.events.len)
            return error.InvalidClientState;

        for (self.pending_batches.items, 0..) |batch, index| {
            cleanup_scratch.batches[index] = .{
                .stream_id = batch.stream_id,
                .is_snapshot = batch.is_snapshot,
                .bytes_address = externalSliceAddress(batch.bytes),
                .bytes_len = batch.bytes.len,
                .allocator = batch.allocator,
            };
        }
        for (self.pending_stream.items, 0..) |frame, index| {
            cleanup_scratch.stream[index] = .{
                .header = frame.header,
                .payload_address = externalSliceAddress(frame.payload),
                .payload_len = frame.payload.len,
            };
        }
        for (self.pending_events.items, 0..) |frame, index| {
            cleanup_scratch.events[index] = .{
                .header = frame.header,
                .payload_address = externalSliceAddress(frame.payload),
                .payload_len = frame.payload.len,
            };
        }
        cleanup_scratch.partial = if (self.partial_batch) |partial| .{
            .stream_id = partial.stream_id,
            .is_snapshot = partial.is_snapshot,
            .bytes = externalArrayDescriptor(partial.bytes),
            .chunk_count = partial.chunk_count,
        } else null;
        out.* = .{
            .saved_self_addr = @intFromPtr(out),
            .client_addr = @intFromPtr(self),
            .scratch_addr = @intFromPtr(cleanup_scratch),
            .allocator = self.allocator,
            .batches = self.pending_batches,
            .stream = self.pending_stream,
            .events = self.pending_events,
            .catchup_barriers = self.pending_catchup_barriers,
            .partial = if (self.partial_batch) |partial| .{
                .stream_id = partial.stream_id,
                .is_snapshot = partial.is_snapshot,
                .bytes = partial.bytes,
                .chunk_count = partial.chunk_count,
            } else null,
            .pending_batch_bytes = self.pending_batch_bytes,
            .pending_stream_bytes = self.pending_stream_bytes,
            .pending_event_bytes = self.pending_event_bytes,
            .next_request_id = self.next_request_id,
            .lifecycle = .prepared,
        };
    }

    pub fn validateExternalRecoveryDiscard(
        self: *const Client,
        seal: *const ExternalRecoveryDiscardSeal,
        cleanup_scratch: *const ExternalAdoptionCleanupScratch,
    ) bool {
        if (seal.lifecycle != .prepared or
            seal.saved_self_addr != @intFromPtr(seal) or
            seal.client_addr != @intFromPtr(self) or
            seal.scratch_addr != @intFromPtr(cleanup_scratch) or
            !std.meta.eql(seal.allocator, self.allocator) or
            !std.meta.eql(seal.batches, self.pending_batches) or
            !std.meta.eql(seal.stream, self.pending_stream) or
            !std.meta.eql(seal.events, self.pending_events) or
            !std.meta.eql(seal.catchup_barriers, self.pending_catchup_barriers) or
            seal.pending_batch_bytes != self.pending_batch_bytes or
            seal.pending_stream_bytes != self.pending_stream_bytes or
            seal.pending_event_bytes != self.pending_event_bytes or
            seal.next_request_id != self.next_request_id or
            self.pending_batches.items.len > cleanup_scratch.batches.len or
            self.pending_stream.items.len > cleanup_scratch.stream.len or
            self.pending_events.items.len > cleanup_scratch.events.len)
            return false;
        if (!std.meta.eql(seal.partial, if (self.partial_batch) |partial|
            ExternalAdoptionTakenPartial{
                .stream_id = partial.stream_id,
                .is_snapshot = partial.is_snapshot,
                .bytes = partial.bytes,
                .chunk_count = partial.chunk_count,
            }
        else
            null) or
            !std.meta.eql(cleanup_scratch.partial, if (self.partial_batch) |partial|
                ExternalPartialDescriptor{
                    .stream_id = partial.stream_id,
                    .is_snapshot = partial.is_snapshot,
                    .bytes = externalArrayDescriptor(partial.bytes),
                    .chunk_count = partial.chunk_count,
                }
            else
                null))
            return false;
        for (self.pending_batches.items, 0..) |batch, index| {
            if (!std.meta.eql(cleanup_scratch.batches[index], ExternalBatchDescriptor{
                .stream_id = batch.stream_id,
                .is_snapshot = batch.is_snapshot,
                .bytes_address = externalSliceAddress(batch.bytes),
                .bytes_len = batch.bytes.len,
                .allocator = batch.allocator,
            })) return false;
        }
        for (self.pending_stream.items, 0..) |frame, index| {
            if (!std.meta.eql(cleanup_scratch.stream[index], ExternalFrameDescriptor{
                .header = frame.header,
                .payload_address = externalSliceAddress(frame.payload),
                .payload_len = frame.payload.len,
            })) return false;
        }
        for (self.pending_events.items, 0..) |frame, index| {
            if (!std.meta.eql(cleanup_scratch.events[index], ExternalFrameDescriptor{
                .header = frame.header,
                .payload_address = externalSliceAddress(frame.payload),
                .payload_len = frame.payload.len,
            })) return false;
        }
        return true;
    }

    /// Requires a successful adjacent `validateExternalRecoveryDiscard`. This suffix tombstones
    /// every mutable queue header before the first allocator callback and never rereads an element.
    fn commitExternalRecoveryDiscardImpl(
        self: *Client,
        seal: *ExternalRecoveryDiscardSeal,
        cleanup_scratch: *ExternalAdoptionCleanupScratch,
    ) void {
        // Copy every payload descriptor before the first allocator callback. Callbacks may know
        // and mutate the caller-owned scratch address; the suffix therefore never rereads that
        // memory after cleanup begins.
        const frozen = cleanup_scratch.*;
        const allocator = seal.allocator;
        var batches = seal.batches;
        var stream = seal.stream;
        var events = seal.events;
        var catchup_barriers = seal.catchup_barriers;
        const partial = frozen.partial;
        const batch_count = batches.items.len;
        const stream_count = stream.items.len;
        const event_count = events.items.len;
        seal.* = .{ .lifecycle = .consumed_tombstone };
        self.pending_batches = .empty;
        self.pending_stream = .empty;
        self.pending_events = .empty;
        self.pending_catchup_barriers = .empty;
        self.partial_batch = null;
        self.pending_batch_bytes = 0;
        self.pending_stream_bytes = 0;
        self.pending_event_bytes = 0;
        self.next_request_id = 0;

        for (frozen.batches[0..batch_count]) |descriptor|
            descriptor.allocator.free(externalOwnedBytes(
                descriptor.bytes_address,
                descriptor.bytes_len,
            ));
        for (frozen.stream[0..stream_count]) |descriptor|
            allocator.free(externalOwnedBytes(
                descriptor.payload_address,
                descriptor.payload_len,
            ));
        for (frozen.events[0..event_count]) |descriptor|
            allocator.free(externalOwnedBytes(
                descriptor.payload_address,
                descriptor.payload_len,
            ));
        if (partial) |descriptor|
            allocator.free(externalOwnedBytes(
                descriptor.bytes.address,
                descriptor.bytes.capacity,
            ));
        batches.deinit(allocator);
        stream.deinit(allocator);
        events.deinit(allocator);
        catchup_barriers.deinit(allocator);
        cleanup_scratch.partial = null;
    }

    /// Complete every fallible operation without mutating the source Client or destination slot.
    pub fn prepareExternalPumpTransfer(
        self: *Client,
        out: *PreparedExternalPumpTransfer,
        destination: *?Client,
        resident_cap: usize,
    ) ExternalPumpTransferError!void {
        if (self.operation_fence != null or self.operation_fence_generation != 0)
            return error.AlreadyBound;
        const source_range = externalRangeOfValue(self);
        const out_range = externalRangeOfValue(out);
        const destination_range = externalRangeOfValue(destination);
        if (externalRangesOverlap(source_range, out_range) or
            externalRangesOverlap(source_range, destination_range) or
            externalRangesOverlap(out_range, destination_range))
            return error.MalformedParser;
        self.preflightExternalAdoptionDestination(
            out,
            @sizeOf(PreparedExternalPumpTransfer),
        ) catch |err| return switch (err) {
            error.OutOfMemory => error.OutOfMemory,
            else => error.MalformedParser,
        };
        self.preflightExternalAdoptionDestination(
            destination,
            @sizeOf(?Client),
        ) catch |err| return switch (err) {
            error.OutOfMemory => error.OutOfMemory,
            else => error.MalformedParser,
        };
        if (out.lifecycle != .empty or
            out.saved_self_addr != 0 or
            out.parser_replacement.saved_self_addr != 0 or
            out.rx_bind.saved_self_addr != 0)
            return error.MalformedParser;
        if (destination.* != null) return error.DestinationOccupied;
        if (self.ownership == .external_pump) return error.AlreadyBound;
        if (self.ownership == .moved or self.unusable or self.fd < 0)
            return error.ConnectionClosed;
        if (self.io_mode != .external) return error.NotExternal;
        const profile = self.externalTransferProfile() orelse return error.MalformedParser;
        self.parser.prepareNormalizeExact(
            &out.parser_replacement,
            resident_cap,
        ) catch |err| return switch (err) {
            error.ResidentTooLarge => error.ResidentTooLarge,
            error.MalformedState => error.MalformedParser,
            error.OutOfMemory => error.OutOfMemory,
        };
        const external_state = switch (self.io_mode) {
            .external => |*state| state,
            .blocking => unreachable,
        };
        client_external_mode.prepareRxBind(
            external_state,
            self.attach_instance_id,
            &out.parser_replacement,
            resident_cap,
            @intFromPtr(destination),
            @sizeOf(?Client),
            &out.rx_bind,
        ) catch {
            out.parser_replacement.deinit();
            return error.MalformedParser;
        };
        out.saved_self_addr = @intFromPtr(out);
        out.source_addr = @intFromPtr(self);
        out.destination_addr = @intFromPtr(destination);
        out.fd = self.fd;
        out.host_id = self.host_id;
        out.allocator_ptr_addr = @intFromPtr(self.allocator.ptr);
        out.allocator_vtable_addr = @intFromPtr(self.allocator.vtable);
        out.profile = profile;
        out.lifecycle = .prepared;
    }

    /// Typed public entry to the no-callback Client ownership move. Parser cleanup is deliberately
    /// deferred until the paired metadata owner has also moved into storage.
    pub fn commitExternalPumpTransfer(
        self: *Client,
        prepared: *PreparedExternalPumpTransfer,
        destination: *?Client,
    ) error{StaleTransfer}!void {
        if (!prepared.validate(self, destination)) return error.StaleTransfer;
        const allocator = self.allocator;
        const expected_major = self.parser.expected_major;
        destination.* = self.*;
        destination.*.?.ownership = .external_pump;
        self.parser.rebindPreparedNormalizeExact(
            &prepared.parser_replacement,
            &destination.*.?.parser,
        );
        // Rebuild from Client defaults so any future owned field must opt into the tombstone.
        self.* = .{
            .allocator = allocator,
            .fd = -1,
            .host_id = 0,
            .parser = framing.FrameParser.initForMajor(allocator, expected_major),
            .ownership = .moved,
            .unusable = true,
        };
        prepared.lifecycle = .owners_moved;
    }

    /// Runs only after Client and metadata evidence are both owned by final storage. The allocator
    /// free callback for the old parser backing is intentionally outside the paired-take suffix.
    pub fn finishExternalPumpTransfer(
        prepared: *PreparedExternalPumpTransfer,
        destination: *?Client,
    ) ExternalPumpFinishOutcome {
        if (prepared.lifecycle != .owners_moved or
            prepared.saved_self_addr != @intFromPtr(prepared) or
            prepared.destination_addr != @intFromPtr(destination) or
            destination.* == null)
            @panic("invalid external pump transfer finish");
        const external_state = switch (destination.*.?.io_mode) {
            .external => |*state| state,
            .blocking => @panic("external pump destination lost RX state"),
        };
        if (external_state.rx_operation_busy)
            @panic("external pump destination RX bind is already busy");
        external_state.rx_operation_busy = true;
        const normalize_outcome = destination.*.?.parser.commitPreparedNormalizeExact(
            &prepared.parser_replacement,
        );
        if (normalize_outcome == .quarantined) {
            external_state.rx_provenance = .{ .lifecycle = .terminal };
            external_state.rx_operation_busy = false;
            destination.*.?.markPoisonedForDeferredCleanup(.external_transfer_quarantined);
            std.debug.assert(destination.*.?.terminalReasonInvariant());
            prepared.source_addr = 0;
            prepared.profile = null;
            prepared.lifecycle = .committed;
            return .quarantined;
        }
        client_external_mode.commitPreparedRxBind(
            external_state,
            &destination.*.?.parser,
            &prepared.rx_bind,
            @intFromPtr(destination),
            @sizeOf(?Client),
        );
        // The source Client is a tombstone its caller may already have reused. Drop the staging
        // copies so nothing downstream can mistake this spent token for a description of it.
        prepared.source_addr = 0;
        prepared.profile = null;
        prepared.lifecycle = .committed;
        return .ready;
    }

    /// Allocation-free P5c3 Phase A fold. The reducer and source encoder are initialized inside
    /// this call and share the one ordered semantic traversal of `pending_events`.
    pub fn foldExternalAdoptionSource(
        self: *const Client,
        input: ExternalAdoptionFoldInput,
        scratch: *ExternalSourceOwnerRangeScratch,
    ) ExternalAdoptionFoldError!ExternalAdoptionFoldResult {
        return foldExternalAdoptionSourceWithEncoding(
            self,
            input,
            scratch,
            .process_identity,
        );
    }

    /// Re-folds the live source and verifies that a retained result belongs to this exact
    /// Client/attach/identity/authority/initial-metadata binding. Callers must reject a false
    /// result before pairing an older fold outcome with a later adoption transaction.
    pub fn externalAdoptionFoldResultMatches(
        self: *const Client,
        input: ExternalAdoptionFoldInput,
        expected: ExternalAdoptionFoldResult,
        scratch: *ExternalSourceOwnerRangeScratch,
    ) bool {
        const actual = self.foldExternalAdoptionSource(input, scratch) catch return false;
        return std.meta.eql(actual.binding_seal, expected.binding_seal) and
            std.meta.eql(actual.source_seal, expected.source_seal) and
            runtime_event_reducer.outcomeEql(actual.outcome, expected.outcome);
    }

    pub fn materializeExternalMetadataEvent(
        self: *const Client,
        allocator: std.mem.Allocator,
        input: ExternalAdoptionFoldInput,
        expected_fold: ExternalAdoptionFoldResult,
        candidate: runtime_event_reducer.MetadataCandidate,
        scratch: *ExternalSourceOwnerRangeScratch,
    ) ExternalMetadataMaterializeError!runtime_metadata_wire.OwnedMetadataDto {
        if (!std.meta.eql(allocator, self.allocator))
            return error.InvalidAllocator;
        if (!self.externalAdoptionFoldResultMatches(input, expected_fold, scratch))
            return error.StaleSource;
        const state = switch (expected_fold.outcome) {
            .adopted => |state| state,
            else => return error.InvalidCandidate,
        };
        const expected_candidate = state.metadata orelse
            return error.InvalidCandidate;
        if (!runtime_event_reducer.metadataCandidateEql(
            candidate,
            expected_candidate,
        )) return error.InvalidCandidate;
        const ordinal = switch (candidate.origin) {
            .initial => return error.InvalidCandidate,
            .event => |ordinal| ordinal,
        };
        if (ordinal >= self.pending_events.items.len or
            ordinal >= expected_fold.source_seal.event_count)
            return error.InvalidCandidate;
        const frame = self.pending_events.items[ordinal];
        if (frame.preflight != null or frame.admission_seal != null or
            frame.header.major != self.wire_major or
            frame.header.kind != .event or
            frame.header.stream_id != input.identity.stream_id or
            frame.header.request_id != 0 or frame.header.flags != 0 or
            frame.header.payload_len != frame.payload.len or
            frame.payload.len > protocol.max_control_json)
            return error.InvalidCandidate;
        const accepted = switch (runtime_event_wire.preflightEvent(
            frame.payload,
            .{
                .runtime_id = input.identity.runtime_id,
                .stream_id = input.identity.stream_id,
            },
        )) {
            .accepted => |accepted| accepted,
            else => return error.InvalidCandidate,
        };
        const proof = switch (candidate.proof) {
            .initial => return error.InvalidCandidate,
            .event => |proof| proof,
        };
        if (!runtime_event_wire.eventPreflightEql(accepted, proof))
            return error.InvalidCandidate;
        _ = try runtime_metadata_wire.preflightEventMaterialization(
            frame.payload,
            accepted,
        );
        var dto = try runtime_metadata_wire.materializeExactEventMetadata(
            allocator,
            frame.payload,
            .{
                .runtime_id = input.identity.runtime_id,
                .stream_id = input.identity.stream_id,
            },
            accepted,
        );
        errdefer dto.deinit();
        if (!self.externalAdoptionFoldResultMatches(input, expected_fold, scratch))
            return error.StaleSource;
        return dto;
    }

    pub fn externalMetadataDtoMatchesEventCandidate(
        self: *const Client,
        input: ExternalAdoptionFoldInput,
        expected_fold: ExternalAdoptionFoldResult,
        candidate: runtime_event_reducer.MetadataCandidate,
        dto: *const runtime_metadata_wire.OwnedMetadataDto,
        scratch: *ExternalSourceOwnerRangeScratch,
    ) bool {
        if (!self.externalAdoptionFoldResultMatches(input, expected_fold, scratch))
            return false;
        const state = switch (expected_fold.outcome) {
            .adopted => |state| state,
            else => return false,
        };
        if (!runtime_event_reducer.metadataCandidateEql(
            candidate,
            state.metadata orelse return false,
        )) return false;
        const ordinal = switch (candidate.origin) {
            .initial => return false,
            .event => |ordinal| ordinal,
        };
        if (ordinal >= self.pending_events.items.len or
            ordinal >= expected_fold.source_seal.event_count)
            return false;
        const frame = self.pending_events.items[ordinal];
        if (frame.preflight != null or frame.admission_seal != null or
            frame.header.major != self.wire_major or
            frame.header.kind != .event or
            frame.header.stream_id != input.identity.stream_id or
            frame.header.request_id != 0 or frame.header.flags != 0 or
            frame.header.payload_len != frame.payload.len or
            frame.payload.len > protocol.max_control_json)
            return false;
        const accepted = switch (runtime_event_wire.preflightEvent(
            frame.payload,
            .{
                .runtime_id = input.identity.runtime_id,
                .stream_id = input.identity.stream_id,
            },
        )) {
            .accepted => |accepted| accepted,
            else => return false,
        };
        const proof = switch (candidate.proof) {
            .initial => return false,
            .event => |proof| proof,
        };
        return runtime_event_wire.eventPreflightEql(accepted, proof) and
            runtime_metadata_wire.ownedMetadataSemanticEqlEvent(
                dto,
                frame.payload,
                accepted,
            );
    }

    pub fn previewExternalAdoption(
        self: *const Client,
        target_stream: u64,
    ) ExternalAdoptionInspectError!ExternalAdoptionPreview {
        const validated = try validateExternalAdoptionClient(
            self,
            target_stream,
            .{},
        );
        return .{
            .screen_source_count = validated.screen_source_count,
            .screen_payload_bytes = validated.screen_payload_bytes,
            .inventory_metadata_bytes = try externalInventoryMetadataBytesForClient(self),
            .validation_scratch_peak_bytes = std.math.mul(
                usize,
                try externalOwnerRangeCount(self),
                @sizeOf(ExternalRange),
            ) catch return error.ArithmeticOverflow,
        };
    }

    pub fn inspectExternalAdoption(
        self: *const Client,
        target_stream: u64,
    ) ExternalAdoptionInspectError!ExternalAdoptionInventory {
        const validated = try validateExternalAdoptionClient(
            self,
            target_stream,
            .{ .owner_aliases = .validate },
        );
        const allocator = self.allocator;
        const batches = try allocator.alloc(
            ExternalBatchDescriptor,
            self.pending_batches.items.len,
        );
        errdefer allocator.free(batches);
        const stream = try allocator.alloc(
            ExternalFrameDescriptor,
            self.pending_stream.items.len,
        );
        errdefer allocator.free(stream);
        const events = try allocator.alloc(
            ExternalFrameDescriptor,
            self.pending_events.items.len,
        );
        errdefer allocator.free(events);
        const build_id_copy = try allocator.dupe(u8, self.build_id orelse &.{});
        errdefer allocator.free(build_id_copy);
        const lifecycle_copy = try allocator.dupe(u8, self.lifecycle);
        errdefer allocator.free(lifecycle_copy);

        for (self.pending_batches.items, batches) |batch, *descriptor|
            descriptor.* = externalBatchDescriptor(batch);
        for (self.pending_stream.items, stream) |frame, *descriptor|
            descriptor.* = externalFrameDescriptor(frame);
        for (self.pending_events.items, events) |frame, *descriptor|
            descriptor.* = externalFrameDescriptor(frame);

        const inventory: ExternalAdoptionInventory = .{
            .allocator = allocator,
            .sealed_allocator = allocator,
            .allocator_ptr_addr = @intFromPtr(allocator.ptr),
            .allocator_vtable_addr = @intFromPtr(allocator.vtable),
            .client_address = @intFromPtr(self),
            .target_stream = target_stream,
            .screen_source_count = validated.screen_source_count,
            .screen_payload_bytes = validated.screen_payload_bytes,
            .event_count = self.pending_events.items.len,
            .event_payload_bytes = validated.event_payload_bytes,
            .next_request_id = self.next_request_id,
            .validation_scratch_peak_bytes = std.math.mul(
                usize,
                try externalOwnerRangeCount(self),
                @sizeOf(ExternalRange),
            ) catch return error.ArithmeticOverflow,
            .snapshot = externalAdoptionSnapshot(self),
            .batch_descriptors = batches,
            .stream_descriptors = stream,
            .event_descriptors = events,
            .build_id_copy = build_id_copy,
            .lifecycle_copy = lifecycle_copy,
            .cleanup_batch_descriptors = batches,
            .cleanup_stream_descriptors = stream,
            .cleanup_event_descriptors = events,
            .cleanup_build_id_copy = build_id_copy,
            .cleanup_lifecycle_copy = lifecycle_copy,
            .batch_descriptors_addr = externalOwnedSliceAddress(ExternalBatchDescriptor, batches),
            .batch_descriptors_len = batches.len,
            .stream_descriptors_addr = externalOwnedSliceAddress(ExternalFrameDescriptor, stream),
            .stream_descriptors_len = stream.len,
            .event_descriptors_addr = externalOwnedSliceAddress(ExternalFrameDescriptor, events),
            .event_descriptors_len = events.len,
            .build_id_copy_addr = externalOwnedSliceAddress(u8, build_id_copy),
            .build_id_copy_len = build_id_copy.len,
            .lifecycle_copy_addr = externalOwnedSliceAddress(u8, lifecycle_copy),
            .lifecycle_copy_len = lifecycle_copy.len,
        };
        return inventory;
    }

    /// Validates every Client-owned allocation and proves that a caller-provided destination can
    /// be initialized without overwriting any source backing. This must run before the caller
    /// writes even the first byte of that destination.
    pub fn preflightExternalAdoptionDestination(
        self: *const Client,
        destination: *const anyopaque,
        destination_len: usize,
    ) ExternalAdoptionInspectError!void {
        try validateExternalAdoptionStructure(self, .require_empty);
        _ = try validateExternalOwnerRangesAgainst(self, .{
            .start = @intFromPtr(destination),
            .len = destination_len,
        });
    }

    /// Allocation-free destination proof for c3b preparation. The source scratch is already part
    /// of the fold contract, so using it avoids an allocator callback before scalar winners.
    pub fn preflightExternalAdoptionDestinationWithScratch(
        self: *const Client,
        destination: *const anyopaque,
        destination_len: usize,
        scratch: *ExternalSourceOwnerRangeScratch,
    ) ExternalSourceSealError!void {
        return self.preflightExternalAdoptionDestinationWithScratchPolicy(
            destination,
            destination_len,
            scratch,
            .require_empty,
        );
    }

    fn preflightExternalAdoptionDestinationWithScratchPolicy(
        self: *const Client,
        destination: *const anyopaque,
        destination_len: usize,
        scratch: *ExternalSourceOwnerRangeScratch,
        catchup_barrier_policy: ExternalCatchupBarrierPolicy,
    ) ExternalSourceSealError!void {
        const destination_range = (checkedExternalRange(
            @intFromPtr(destination),
            destination_len,
        ) catch |err| return narrowExternalSourceSealError(err)) orelse return;
        const stats = validateExternalSourceOwnerRangesWithPolicy(
            self,
            scratch,
            catchup_barrier_policy,
        ) catch |err|
            return narrowExternalSourceSealError(err);
        if (externalRangesOverlap(externalRangeOfValue(self), destination_range))
            return error.InvalidAlias;
        for (scratch.ranges[0..stats.total_ranges]) |range|
            if (externalRangesOverlap(range, destination_range))
                return error.InvalidAlias;
    }

    pub fn appendExternalOwnerRangesForTeardown(
        self: *const Client,
        source_scratch: *ExternalSourceOwnerRangeScratch,
        out: *owner_range.Scratch,
    ) (ExternalAdoptionInspectError || owner_range.Error)!void {
        const stats = try validateExternalSourceOwnerRanges(
            self,
            source_scratch,
        );
        for (source_scratch.ranges[0..stats.total_ranges]) |range|
            try out.append(range.start, range.len);
    }

    /// Performs the final whole-owner proof for the paired Client/evidence move.
    ///
    /// Unlike `preflightExternalAdoptionDestination`, this retains its scratch allocation. The
    /// caller must validate it immediately before the no-callback ownership suffix and deinit it
    /// only after the source Client has been tombstoned.
    pub fn prepareExternalOwnerRangeProof(
        self: *const Client,
        out: *PreparedExternalOwnerRangeProof,
        first_target: *const anyopaque,
        first_target_len: usize,
        second_target: *const anyopaque,
        second_target_len: usize,
    ) ExternalAdoptionInspectError!void {
        if (out.lifecycle != .empty or
            externalRangesOverlap(externalRangeOfValue(out), externalRangeOfValue(self)))
            return error.InvalidAlias;
        const allocator = self.allocator;
        const count = try externalOwnerRangeCount(self);
        const snapshot = externalAdoptionSnapshotForProof(self) orelse
            return error.InvalidClientState;
        const ranges = try allocator.alloc(ExternalRange, count);
        errdefer allocator.free(ranges);
        out.* = .{
            .saved_self_addr = @intFromPtr(out),
            .client_addr = @intFromPtr(self),
            .allocator = allocator,
            .cleanup_allocator = allocator,
            .allocator_ptr_addr = @intFromPtr(allocator.ptr),
            .allocator_vtable_addr = @intFromPtr(allocator.vtable),
            .snapshot = snapshot,
            .first_target = .{
                .start = @intFromPtr(first_target),
                .len = first_target_len,
            },
            .second_target = .{
                .start = @intFromPtr(second_target),
                .len = second_target_len,
            },
            .ranges = ranges,
            .cleanup_ranges = ranges,
            .ranges_addr = externalOwnedSliceAddress(ExternalRange, ranges),
            .ranges_len = ranges.len,
            .lifecycle = .prepared,
        };
        errdefer out.* = .{};
        if (!out.validate(
            self,
            first_target,
            first_target_len,
            second_target,
            second_target_len,
        )) return error.InvalidAlias;
    }

    pub fn preflightExternalAdoption(
        self: *const Client,
        expected: *const ExternalAdoptionInventory,
        out: *PreparedClientDisarm,
    ) ExternalAdoptionPreflightError!void {
        // Validate every source descriptor before reading the caller-provided destination.
        // The destination may alias Client-owned bytes, and malformed list lengths must not
        // reach the range walker before the structural guard has proved them safe to iterate.
        try validateExternalAdoptionStructure(self, .require_empty);
        if (externalRangesOverlap(
            externalRangeOfValue(self),
            externalRangeOfValue(out),
        ) or try externalPlanRangeOverlapsClient(self, out))
            return error.InvalidAlias;
        if (try externalDestinationOverlapsInventory(
            expected,
            externalRangeOfValue(out),
        )) return error.InvalidAlias;
        if (out.lifecycle != .empty or out.inventory != null or out.cleanup_inventory != null)
            return error.InvalidPlan;
        if (expected.client_address != @intFromPtr(self)) return error.StaleInventory;

        var current = try self.inspectExternalAdoption(expected.target_stream);
        errdefer current.deinit();
        if (!externalInventoriesEqual(expected, &current)) return error.StaleInventory;

        out.* = .{
            .saved_self_address = @intFromPtr(out),
            .client_address = @intFromPtr(self),
            .inventory = current,
            .cleanup_inventory = current,
            .lifecycle = .prepared,
        };
    }

    pub fn stageExternalScreenCopies(
        self: *const Client,
        allocator: std.mem.Allocator,
        expected: *const ExternalAdoptionInventory,
        out: []ExternalScreenCopy,
    ) ExternalAdoptionInspectError!void {
        _ = try validateExternalAdoptionClient(
            self,
            expected.target_stream,
            .{},
        );
        const out_bytes = std.math.mul(
            usize,
            out.len,
            @sizeOf(ExternalScreenCopy),
        ) catch return error.ArithmeticOverflow;
        try self.preflightExternalAdoptionDestination(out.ptr, out_bytes);
        if (try externalDestinationOverlapsInventory(expected, .{
            .start = @intFromPtr(out.ptr),
            .len = out_bytes,
        })) return error.InvalidAlias;
        if (!externalInventoryMatchesClientExact(expected, self) or
            out.len != expected.screen_source_count)
            return error.InvalidClientState;
        var initialized: usize = 0;
        errdefer for (out[0..initialized]) |*copy| copy.deinit();

        for (self.pending_batches.items) |batch| {
            out[initialized] = .{
                .allocator = allocator,
                .semantic = .{ .completed = .{
                    .stream_id = batch.stream_id,
                    .is_snapshot = batch.is_snapshot,
                } },
                .bytes = try allocator.dupe(u8, batch.bytes),
                .view = undefined,
            };
            out[initialized].view = out[initialized].bytes;
            initialized += 1;
        }
        if (self.partial_batch) |partial| {
            out[initialized] = .{
                .allocator = allocator,
                .semantic = .{ .partial = .{
                    .stream_id = partial.stream_id,
                    .is_snapshot = partial.is_snapshot,
                    .chunk_count = std.math.cast(u8, partial.chunk_count) orelse
                        return error.InvalidPartial,
                } },
                .bytes = try allocator.dupe(u8, partial.bytes.items),
                .view = undefined,
            };
            out[initialized].view = out[initialized].bytes;
            initialized += 1;
        }
        for (self.pending_stream.items) |frame| {
            out[initialized] = .{
                .allocator = allocator,
                .semantic = .{ .frame = frame.header },
                .bytes = try allocator.dupe(u8, frame.payload),
                .view = undefined,
            };
            out[initialized].view = out[initialized].bytes;
            initialized += 1;
        }
    }

    pub fn externalScreenCopiesMatch(
        self: *const Client,
        expected: *const ExternalAdoptionInventory,
        copies: []const ExternalScreenCopy,
    ) bool {
        _ = validateExternalAdoptionClient(
            self,
            expected.target_stream,
            .{},
        ) catch return false;
        if (!externalInventoryMatchesClientExact(expected, self) or
            copies.len != expected.screen_source_count)
            return false;
        var index: usize = 0;
        for (self.pending_batches.items) |batch| {
            const copy = copies[index];
            const semantic = switch (copy.semantic) {
                .completed => |value| value.stream_id == batch.stream_id and
                    value.is_snapshot == batch.is_snapshot,
                else => false,
            };
            if (!semantic or !std.mem.eql(u8, copy.view, batch.bytes)) return false;
            index += 1;
        }
        if (self.partial_batch) |partial| {
            const copy = copies[index];
            const semantic = switch (copy.semantic) {
                .partial => |value| value.stream_id == partial.stream_id and
                    value.is_snapshot == partial.is_snapshot and
                    value.chunk_count == partial.chunk_count,
                else => false,
            };
            if (!semantic or !std.mem.eql(u8, copy.view, partial.bytes.items)) return false;
            index += 1;
        }
        for (self.pending_stream.items) |frame| {
            const copy = copies[index];
            const semantic = switch (copy.semantic) {
                .frame => |header| std.meta.eql(header, frame.header),
                else => false,
            };
            if (!semantic or !std.mem.eql(u8, copy.view, frame.payload)) return false;
            index += 1;
        }
        return index == copies.len;
    }

    pub fn validateExternalAdoptionPlan(
        self: *const Client,
        plan: *const PreparedClientDisarm,
    ) bool {
        if ((plan.lifecycle != .prepared and plan.lifecycle != .sealed) or
            plan.saved_self_address != @intFromPtr(plan) or
            plan.client_address != @intFromPtr(self))
            return false;
        validateExternalAdoptionStructure(self, .require_empty) catch return false;
        const inventory = &(plan.inventory orelse return false);
        _ = validateExternalAdoptionClient(
            self,
            inventory.target_stream,
            .{},
        ) catch return false;
        if (externalPlanRangeOverlapsClient(self, plan) catch return false) return false;
        // Inspect already proved the structural and pairwise-alias invariants. Exact descriptor
        // equality below proves none of those owner ranges moved, resized, or changed identity, so
        // final validation stays allocation-free.
        return externalInventoryMatchesClientExact(inventory, self);
    }

    pub fn externalAdoptionDisarmMetadataBytes(
        self: *const Client,
        plan: *const PreparedClientDisarm,
    ) error{ ArithmeticOverflow, InvalidPlan }!usize {
        if (plan.client_address != @intFromPtr(self)) return error.InvalidPlan;
        return (plan.inventory orelse return error.InvalidPlan).metadataBytes();
    }

    pub fn externalAdoptionDisarmMatchesInventory(
        self: *const Client,
        plan: *const PreparedClientDisarm,
        inventory: *const ExternalAdoptionInventory,
    ) bool {
        if (plan.client_address != @intFromPtr(self)) return false;
        return externalInventoriesEqual(
            &(plan.inventory orelse return false),
            inventory,
        );
    }

    pub fn sealExternalAdoption(
        self: *const Client,
        plan: *PreparedClientDisarm,
    ) ExternalAdoptionCommitError!void {
        if (plan.lifecycle != .prepared) return error.StaleClient;
        if (!self.validateExternalAdoptionPlan(plan)) return error.StaleClient;
        plan.lifecycle = .sealed;
    }

    pub fn validateSealedExternalAdoptionPlan(
        self: *const Client,
        plan: *const PreparedClientDisarm,
    ) bool {
        return plan.lifecycle == .sealed and self.validateExternalAdoptionPlan(plan);
    }

    pub fn prepareExternalAdoptionTake(
        self: *const Client,
        plan: *const PreparedClientDisarm,
        mirror_owner: *const ?ExternalAdoptionInventory,
        mirror_cleanup_owner: *const ?ExternalAdoptionInventory,
        out: *ExternalAdoptionTake,
    ) ExternalAdoptionTakePrepareError!void {
        if (!self.validateSealedExternalAdoptionPlan(plan))
            return error.StaleClient;
        self.preflightExternalAdoptionDestination(
            out,
            @sizeOf(ExternalAdoptionTake),
        ) catch |err| return switch (err) {
            error.OutOfMemory => error.OutOfMemory,
            else => error.InvalidPlan,
        };
        const out_range = externalRangeOfValue(out);
        if (externalRangesOverlap(out_range, externalRangeOfValue(self)) or
            externalRangesOverlap(out_range, externalRangeOfValue(plan)))
            return error.InvalidPlan;
        const inventory = &(plan.inventory orelse return error.InvalidPlan);
        const mirror_inventory = &(mirror_owner.* orelse return error.InvalidPlan);
        const mirror_cleanup_inventory =
            &(mirror_cleanup_owner.* orelse return error.InvalidPlan);
        if (!externalInventoriesEqual(inventory, mirror_inventory) or
            !externalInventoriesEqual(
                mirror_inventory,
                mirror_cleanup_inventory,
            ) or
            !externalInventoriesHaveIndependentStorage(inventory, mirror_inventory))
            return error.InvalidPlan;
        if (externalDestinationOverlapsInventory(inventory, out_range) catch
            return error.InvalidPlan)
            return error.InvalidPlan;
        if (out.lifecycle != .empty or out.saved_self_address != 0)
            return error.InvalidPlan;
        const partial: ?ExternalAdoptionTakenPartial = if (self.partial_batch) |value| .{
            .stream_id = value.stream_id,
            .is_snapshot = value.is_snapshot,
            .bytes = value.bytes,
            .chunk_count = value.chunk_count,
        } else null;
        const inventory_cleanup_seal =
            externalInventoryCleanupSeal(inventory);
        const mirror_inventory_cleanup_seal =
            externalInventoryCleanupSeal(mirror_inventory);
        const inventory_backing_seal =
            externalInventoryBackingSeal(inventory);
        const mirror_inventory_backing_seal =
            externalInventoryBackingSeal(mirror_inventory);
        out.* = .{
            .saved_self_address = @intFromPtr(out),
            .client_address = @intFromPtr(self),
            .plan_address = @intFromPtr(plan),
            .mirror_owner_address = @intFromPtr(mirror_owner),
            .mirror_cleanup_owner_address = @intFromPtr(mirror_cleanup_owner),
            .allocator = self.allocator,
            .cleanup_allocator = self.allocator,
            .allocator_ptr_addr = @intFromPtr(self.allocator.ptr),
            .allocator_vtable_addr = @intFromPtr(self.allocator.vtable),
            .pending_batches = self.pending_batches,
            .cleanup_pending_batches = self.pending_batches,
            .pending_batches_seal = externalArrayDescriptor(self.pending_batches),
            .pending_stream = self.pending_stream,
            .cleanup_pending_stream = self.pending_stream,
            .pending_stream_seal = externalArrayDescriptor(self.pending_stream),
            .pending_events = self.pending_events,
            .cleanup_pending_events = self.pending_events,
            .pending_events_seal = externalArrayDescriptor(self.pending_events),
            .partial = partial,
            .cleanup_partial = partial,
            .partial_seal = inventory.snapshot.partial,
            .plan_inventory = inventory.*,
            .cleanup_plan_inventory = mirror_inventory.*,
            .inventory_cleanup_seal = inventory_cleanup_seal,
            .cleanup_inventory_cleanup_seal = mirror_inventory_cleanup_seal,
            .inventory_backing_seal = inventory_backing_seal,
            .cleanup_inventory_backing_seal = mirror_inventory_backing_seal,
            .lifecycle = .prepared,
        };
        if (!out.validate(
            self,
            plan,
            mirror_owner,
            mirror_cleanup_owner,
        )) {
            out.* = .{};
            return error.InvalidPlan;
        }
    }

    /// Final no-callback suffix after the ledger accepted every screen seed. All heap owners move
    /// by header; cleanup is deferred to the committed take owner. This is public only across the
    /// session-host module boundary and must be called by `ExternalPumpStorage` after it consumes
    /// an `AdoptedCommitPermit`; ordinary callers use the checked preparation/validation APIs.
    fn commitExternalAdoptionTakeImpl(
        self: *Client,
        plan: *PreparedClientDisarm,
        mirror_owner: *?ExternalAdoptionInventory,
        mirror_cleanup_owner: *?ExternalAdoptionInventory,
        take: *ExternalAdoptionTake,
    ) void {
        // The aggregate commit permit validates every descriptor immediately before the ledger
        // barrier. Re-validating here would leave a panic branch after payload ownership has
        // already moved to the ledger, where rollback is no longer possible.
        take.lifecycle = .committed;
        self.pending_batches = .empty;
        self.pending_batch_bytes = 0;
        self.partial_batch = null;
        self.pending_stream = .empty;
        self.pending_stream_bytes = 0;
        self.pending_events = .empty;
        self.pending_event_bytes = 0;
        self.next_request_id = 0;
        plan.inventory = null;
        plan.cleanup_inventory = null;
        mirror_owner.* = null;
        mirror_cleanup_owner.* = null;
        plan.lifecycle = .committed;
    }

    /// `sealExternalAdoption` is the final fallible boundary. This suffix performs no allocation,
    /// user callback, or fallible operation.
    pub fn commitExternalAdoption(
        self: *Client,
        plan: *PreparedClientDisarm,
    ) void {
        if (plan.lifecycle != .sealed or
            plan.saved_self_address != @intFromPtr(plan) or
            plan.client_address != @intFromPtr(self) or
            plan.inventory == null)
            @panic("invalid sealed external adoption plan");
        plan.lifecycle = .committed;

        for (self.pending_batches.items) |batch| batch.deinit();
        self.pending_batches.deinit(self.allocator);
        self.pending_batches = .empty;
        self.pending_batch_bytes = 0;
        if (self.partial_batch) |*partial| partial.bytes.deinit(self.allocator);
        self.partial_batch = null;
        for (self.pending_stream.items) |frame| frame.deinit(self.allocator);
        self.pending_stream.deinit(self.allocator);
        self.pending_stream = .empty;
        self.pending_stream_bytes = 0;
        for (self.pending_events.items) |frame| frame.deinit(self.allocator);
        self.pending_events.deinit(self.allocator);
        self.pending_events = .empty;
        self.pending_event_bytes = 0;
        self.next_request_id = 0;
        plan.inventory.?.deinit();
        plan.inventory = null;
        plan.cleanup_inventory = null;
    }

    /// One-way pre-raw transition. Every allocation is staged before fd flags are touched and an
    /// unprovable rollback poisons the sole-owned connection instead of exposing split mode.
    pub fn enterExternalMode(self: *Client) EnterExternalModeError!void {
        const operation_fence_held = self.beginPublicMutation() catch |err| return switch (err) {
            error.AdminBusy => error.Busy,
            error.ConnectionClosed => error.ConnectionClosed,
            else => unreachable,
        };
        defer if (operation_fence_held) self.endPublicMutation();
        if (operation_fence_held) return error.Busy;
        return self.enterExternalModeWithOps(client_deadline.posix_ops);
    }

    fn enterExternalModeWithOps(
        self: *Client,
        ops: client_deadline.Ops,
    ) EnterExternalModeError!void {
        if (self.unusable) return error.ConnectionClosed;
        if (self.io_mode == .external) return error.AlreadyExternal;
        if (self.pending_outbound != null) return error.Busy;

        const outcome = client_external_mode.transition(
            self.allocator,
            self.fd,
            .{
                .context = ops.context,
                .get_flags = ops.get_flags,
                .set_flags = ops.set_flags,
            },
        ) catch return error.OutOfMemory;
        switch (outcome) {
            .external => |state| self.io_mode = .{ .external = state },
            .flag_failed => return error.FlagFailed,
            .invalid_blocking_flags, .indeterminate => {
                self.poisonWithOps(.local_invariant_violation, ops);
                return error.ConnectionClosed;
            },
        }
    }

    pub fn prepareExternalModeDeinit(self: *Client) bool {
        if (checkedAllocatorReentry(self)) return false;
        switch (self.io_mode) {
            .blocking => {},
            .external => |*state| {
                state.requestTxClose();
                switch (state.tryDeinit(self.allocator)) {
                    .cleaned, .already_dead => {},
                    .busy => return false,
                }
            },
        }
        self.io_mode = .blocking;
        return true;
    }

    pub const ExternalModeDeinitReservationResult = enum {
        reserved,
        already_dead,
        busy,
    };

    pub fn reserveExternalModeDeinit(
        self: *Client,
    ) ExternalModeDeinitReservationResult {
        if (checkedAllocatorReentry(self)) return .busy;
        return switch (self.io_mode) {
            .blocking => .already_dead,
            .external => |*state| blk: {
                state.requestTxClose();
                break :blk switch (state.reserveDeinit()) {
                    .reserved => .reserved,
                    .already_dead => .already_dead,
                    .busy => .busy,
                };
            },
        };
    }

    pub fn finishReservedExternalModeDeinit(self: *Client) bool {
        if (checkedAllocatorReentry(self)) return false;
        switch (self.io_mode) {
            .blocking => return true,
            .external => |*state| switch (state.finishReservedDeinit(self.allocator)) {
                .cleaned, .already_dead => {},
                .busy => return false,
            },
        }
        self.io_mode = .blocking;
        return true;
    }

    pub fn cancelReservedExternalModeDeinit(self: *Client) bool {
        if (checkedAllocatorReentry(self)) return false;
        return switch (self.io_mode) {
            .blocking => true,
            .external => |*state| state.cancelReservedDeinit(),
        };
    }

    pub fn transferReservedExternalModeDeinit(
        self: *Client,
        destination: *Client,
    ) bool {
        if (checkedAllocatorReentry(self) or checkedAllocatorReentry(destination)) return false;
        return switch (self.io_mode) {
            .blocking => destination.io_mode == .blocking,
            .external => |*source_state| switch (destination.io_mode) {
                .blocking => false,
                .external => |*destination_state| source_state.transferReservedDeinit(destination_state),
            },
        };
    }

    const RpcIo = union(enum) {
        blocking,
        deadline: struct {
            absolute: client_deadline.AbsoluteDeadline,
            ops: client_deadline.Ops,
        },
    };

    /// read-only command를 왕복한다. `params_json`은 JSON object 문자열(예: `{"runtime_id":"aa"}`) 또는 null. 반환
    /// payload는 host의 response JSON(owned — caller가 free). typed error 판정은 caller가 payload에서 한다(§10 error 매핑).
    pub fn call(self: *Client, method: []const u8, params_json: ?[]const u8) ClientError![]u8 {
        return self.callWithIo(method, params_json, .blocking) catch |err| switch (err) {
            error.DeadlineExceeded => unreachable,
            else => |client_err| client_err,
        };
    }

    /// Public attach pre-raw RPC. Request storage is complete before the fd enters a temporary
    /// nonblocking lease; write, async demux and exact response share one absolute deadline.
    pub fn callUntil(
        self: *Client,
        method: []const u8,
        params_json: ?[]const u8,
        deadline: client_deadline.AbsoluteDeadline,
    ) DeadlineClientError![]u8 {
        return self.callUntilWithOps(method, params_json, deadline, client_deadline.posix_ops);
    }

    fn callWithIo(
        self: *Client,
        method: []const u8,
        params_json: ?[]const u8,
        io: RpcIo,
    ) DeadlineClientError![]u8 {
        const operation_fence_held = try self.requireBlockingMode();
        defer if (operation_fence_held) self.endPublicMutation();
        return self.callGuardedWithIo(method, params_json, io, false);
    }

    fn callGuardedWithIo(
        self: *Client,
        method: []const u8,
        params_json: ?[]const u8,
        io: RpcIo,
        execution_lease_held: bool,
    ) DeadlineClientError![]u8 {
        // A buffered controller revoke is a connection-wide ordering latch. No sibling RPC may
        // flush an older admitted mutation frame before the owning runtime consumes and fences it.
        if (self.bufferedControllerRevokeForStreamUnchecked(null)) return error.AdminBusy;
        // non-blocking input이 backpressure로 일부만 전송됐어도 뒤 request가 wire에서 추월하면 안 된다.
        try self.flushPendingOutboundBlockingMode(execution_lease_held);
        var prepared: PreparedBlockingRpc = .{};
        self.prepareBlockingRpcGuarded(&prepared, method, params_json) catch |err| return switch (err) {
            error.DestinationOccupied, error.InvalidPreparedRpc, error.MovedOrCopied => error.ProtocolError,
            else => |client_err| client_err,
        };
        const executed = self.executePreparedWithIo(
            &prepared,
            io,
            false,
            null,
            null,
            execution_lease_held,
        ) catch |err| return switch (err) {
            error.InvalidPreparedRpc, error.MovedOrCopied, error.PayloadProvenanceRejected => error.ProtocolError,
            else => |client_err| client_err,
        };
        return executed.payload;
    }

    pub fn callUnderRegisteredOperationExecutionLease(
        self: *Client,
        capability: RegisteredOperationExecutionHandle,
        method: []const u8,
        params_json: ?[]const u8,
    ) ClientError![]u8 {
        try self.requireRegisteredOperationExecutionCapability(capability);
        return self.callGuardedWithIo(method, params_json, .blocking, true) catch |err| switch (err) {
            error.DeadlineExceeded => unreachable,
            else => |client_err| client_err,
        };
    }

    fn callUntilWithOps(
        self: *Client,
        method: []const u8,
        params_json: ?[]const u8,
        deadline: client_deadline.AbsoluteDeadline,
        ops: client_deadline.Ops,
    ) DeadlineClientError![]u8 {
        const operation_fence_held = try self.requireBlockingMode();
        defer if (operation_fence_held) self.endPublicMutation();
        if (self.bufferedControllerRevokeForStreamUnchecked(null)) return error.AdminBusy;
        var prepared: PreparedBlockingRpc = .{};
        self.prepareBlockingRpc(&prepared, method, params_json) catch |err| return switch (err) {
            error.DestinationOccupied, error.InvalidPreparedRpc, error.MovedOrCopied => error.ProtocolError,
            else => |client_err| client_err,
        };
        errdefer self.abortPreparedBlockingRpc(&prepared) catch {};

        const saved_flags = ops.get_flags(ops.context, self.fd) orelse {
            self.poisonWithOps(.local_invariant_violation, ops);
            return error.WriteFailed;
        };
        const nonblocking: c_int = @bitCast(posix.O{ .NONBLOCK = true });
        if (!ops.set_flags(ops.context, self.fd, saved_flags | nonblocking)) {
            self.poisonWithOps(.local_invariant_violation, ops);
            return error.WriteFailed;
        }
        // 큐에 남은 GUI 입력 frame을 **먼저 밀어낸다**. wire 순서를 지키는 방법은 연결을 끊는 것이 아니라 먼저 온
        // 것을 먼저 보내는 것이다. 이전에는 pending이 있으면 곧바로 fail-closed했는데, 그 대가가 지나치게 컸다 —
        // 사용자가 타이핑하는 중(입력 frame이 backpressure로 슬롯에 남은 순간)에 새 Term을 열면 `WriteFailed`로
        // connection이 끊기고, AppSession이 `stage=runtime_death`로 in-process 폴백해 그 세션의 터미널이 앱 종료와
        // 함께 전부 사라졌다. 같은 빌드에서 실행마다 되고 안 되던 간헐성의 정체가 이 타이밍 겹침이었다.
        //
        // 여기는 이미 O_NONBLOCK을 건 뒤라 `writeAllUntil`이 블로킹하지 않고 would_block이면 deadline 안에서
        // writable을 기다린다 — phase budget을 넘기지 않는다. 정말로 못 비우면 그때 fail-closed한다: 부분 write 뒤
        // timeout이면 framing이 이미 깨져 복구가 불가능하므로 connection을 살려 둘 수 없다.
        if (self.pending_outbound) |pending| {
            client_deadline.writeAllUntil(ops, self.fd, pending.frame[pending.offset..], deadline) catch {
                self.poisonWithOps(.outbound_write_ambiguous, ops);
                return error.WriteFailed;
            };
            self.clearPendingOutbound();
        }
        const executed = self.executePreparedWithIo(
            &prepared,
            .{ .deadline = .{ .absolute = deadline, .ops = ops } },
            false,
            null,
            null,
            false,
        ) catch |err| {
            self.poisonWithOps(.response_correlation_lost, ops);
            return switch (err) {
                error.InvalidPreparedRpc, error.MovedOrCopied, error.PayloadProvenanceRejected => error.ProtocolError,
                else => |client_err| client_err,
            };
        };
        const payload = executed.payload;
        if (!ops.set_flags(ops.context, self.fd, saved_flags)) {
            self.allocator.free(payload);
            self.poisonWithOps(.local_invariant_violation, ops);
            return error.ConnectionClosed;
        }
        if (deadline.remainingNs() <= 0) {
            self.allocator.free(payload);
            self.poisonWithOps(.response_correlation_lost, ops);
            return error.DeadlineExceeded;
        }
        return payload;
    }

    fn buildRequestFrame(
        self: *Client,
        method: []const u8,
        params_json: ?[]const u8,
    ) DeadlineClientError![]u8 {
        const req = buildRequest(self.allocator, method, params_json) catch return error.OutOfMemory;
        defer self.allocator.free(req);
        return framing.encodeFrame(
            self.allocator,
            .{ .kind = .request, .request_id = self.next_request_id, .major = self.wire_major },
            req,
        ) catch return error.OutOfMemory;
    }

    fn prepareBlockingRpc(
        self: *Client,
        out: *PreparedBlockingRpc,
        method: []const u8,
        params_json: ?[]const u8,
    ) PreparedBlockingRpcError!void {
        const operation_fence_held = try self.requireBlockingMode();
        defer if (operation_fence_held) self.endPublicMutation();
        return self.prepareBlockingRpcGuarded(out, method, params_json);
    }

    fn prepareBlockingRpcGuarded(
        self: *Client,
        out: *PreparedBlockingRpc,
        method: []const u8,
        params_json: ?[]const u8,
    ) PreparedBlockingRpcError!void {
        const pristine = out.self_addr == 0 and out.lifecycle == .pristine and out.frame.len == 0;
        if (!pristine and !out.reusableTerminalFor(self))
            return error.DestinationOccupied;
        if (self.next_request_id == 0 or self.next_request_id == std.math.maxInt(u64))
            return error.InvalidPreparedRpc;
        const incarnation = try issuePreparedRpcIncarnation();
        const frame_bytes = self.buildRequestFrame(method, params_json) catch |err| return switch (err) {
            error.DeadlineExceeded => unreachable,
            else => |client_err| client_err,
        };
        var digest = std.hash.Wyhash.hash(0, frame_bytes);
        if (digest == 0) digest = 1;
        out.* = .{
            .self_addr = @intFromPtr(out),
            .incarnation = incarnation,
            .client_addr = @intFromPtr(self),
            .request_id = self.next_request_id,
            .frame_digest = digest,
            .frame = frame_bytes,
            .allocator = self.allocator,
            .lifecycle = .prepared,
        };
    }

    fn abortPreparedBlockingRpc(
        self: *Client,
        prepared: *PreparedBlockingRpc,
    ) PreparedBlockingRpcError!void {
        if (prepared.self_addr != @intFromPtr(prepared)) return error.MovedOrCopied;
        if (!prepared.validFor(self)) return error.InvalidPreparedRpc;
        prepared.settle();
    }

    fn executePreparedBlockingRpc(
        self: *Client,
        prepared: *PreparedBlockingRpc,
    ) PreparedBlockingRpcError![]u8 {
        return switch (self.executePreparedBlockingRpcClassified(prepared)) {
            .accepted => |response| response.payload,
            .not_executed, .uncertain => |err| err,
        };
    }

    fn executePreparedBlockingRpcClassified(
        self: *Client,
        prepared: *PreparedBlockingRpc,
    ) PreparedBlockingRpcExecution {
        const response = self.executePreparedWithIo(prepared, .blocking, true, null, null, false) catch |err| {
            const classified: PreparedBlockingRpcError = switch (err) {
                error.DeadlineExceeded, error.PayloadProvenanceRejected => unreachable,
                else => |client_err| client_err,
            };
            return if (prepared.lifecycle == .prepared)
                .{ .not_executed = classified }
            else
                .{ .uncertain = classified };
        };
        return .{ .accepted = response };
    }

    pub fn prepareBlockingRpcStorage(
        self: *Client,
        storage: *PreparedBlockingRpcStorage,
        method: []const u8,
        params_json: ?[]const u8,
    ) PreparedBlockingRpcError!PreparedBlockingRpcIdentity {
        const prepared = preparedRpcFromStorage(storage);
        try self.prepareBlockingRpc(prepared, method, params_json);
        return .{
            .request_id = prepared.request_id,
            .frame_digest = prepared.frame_digest,
            .descriptor = preparedDescriptor(prepared, storage),
        };
    }

    pub fn abortPreparedBlockingRpcStorage(
        self: *Client,
        storage: *PreparedBlockingRpcStorage,
    ) PreparedBlockingRpcError!void {
        // local prepared backing 정리는 connection이 terminal이어도 가능해야 한다. allocator callback
        // 재진입만 막고, 일반 usability gate로 poison 이후 exact abort까지 막지는 않는다.
        const operation_fence_held = try self.beginPublicMutation();
        defer if (operation_fence_held) self.endPublicMutation();
        if (checkedAllocatorReentry(self)) return error.AdminBusy;
        return self.abortPreparedBlockingRpc(preparedRpcFromStorage(storage));
    }

    pub const CanonicalPreparedAbortOutcome = enum {
        reusable,
        terminal,
    };

    /// Settles only the exact scalar descriptor sealed by the node authority. A forged pointer or
    /// allocator is rejected before hashing or free; content drift is safe to hash/free because
    /// descriptor provenance is already exact, but terminalizes the request transaction.
    pub fn abortPreparedBlockingRpcStorageCanonical(
        self: *Client,
        storage: *PreparedBlockingRpcStorage,
        identity: PreparedBlockingRpcIdentity,
    ) PreparedBlockingRpcError!CanonicalPreparedAbortOutcome {
        const operation_fence_held = try self.beginPublicMutation();
        defer if (operation_fence_held) self.endPublicMutation();
        if (checkedAllocatorReentry(self)) return error.AdminBusy;
        return self.abortPreparedBlockingRpcStorageCanonicalUnchecked(storage, identity);
    }

    /// B3-3 cleanup leaf for the exact backing already protected by `lease`. It deliberately does
    /// not reacquire the public mutation fence: the execution lease must remain exclusive until
    /// both request and response authorities have settled.
    pub fn abortPreparedBlockingRpcStorageUnderExecutionLease(
        self: *Client,
        storage: *PreparedBlockingRpcStorage,
        identity: PreparedBlockingRpcIdentity,
        lease: *PreparedRequestExecutionLease,
    ) PreparedBlockingRpcError!CanonicalPreparedAbortOutcome {
        if (checkedAllocatorReentry(self)) return error.AdminBusy;
        if (!self.preparedRequestExecutionLeaseMatches(storage, identity, lease))
            return error.InvalidPreparedRpc;
        return self.abortPreparedBlockingRpcStorageCanonicalUnchecked(storage, identity);
    }

    fn abortPreparedBlockingRpcStorageCanonicalUnchecked(
        self: *Client,
        storage: *PreparedBlockingRpcStorage,
        identity: PreparedBlockingRpcIdentity,
    ) PreparedBlockingRpcError!CanonicalPreparedAbortOutcome {
        const prepared = preparedRpcFromStorage(storage);
        if (!preparedDescriptorRawMatches(prepared, storage, identity.descriptor) or
            !prepared.validFor(self) or prepared.request_id != identity.request_id or
            prepared.frame_digest != identity.frame_digest)
            return error.InvalidPreparedRpc;
        const intact = prepared.frameIntact();
        prepared.settle();
        return if (intact) .reusable else .terminal;
    }

    fn executePreparedBlockingRpcStorageClassified(
        self: *Client,
        storage: *PreparedBlockingRpcStorage,
    ) PreparedBlockingRpcExecution {
        return self.executePreparedBlockingRpcClassified(preparedRpcFromStorage(storage));
    }

    /// Completes pre-existing outbound ownership before the caller captures the allocator used by
    /// this Client/parser domain. No byte from the prepared request is written here.
    pub fn preflightPreparedBlockingRpcStorageExecution(
        self: *Client,
        storage: *PreparedBlockingRpcStorage,
    ) PreparedBlockingRpcError!std.mem.Allocator {
        const operation_fence_held = try self.ensureUsable();
        defer if (operation_fence_held) self.endPublicMutation();
        const prepared = preparedRpcFromStorage(storage);
        if (prepared.self_addr != @intFromPtr(prepared)) return error.MovedOrCopied;
        if (!prepared.validFor(self) or !prepared.frameIntact() or
            prepared.request_id != self.next_request_id)
            return error.InvalidPreparedRpc;
        if (self.bufferedControllerRevokeForStreamUnchecked(null)) return error.AdminBusy;
        const allocator = self.allocator;
        try self.flushPendingOutboundBlocking();
        if (!std.meta.eql(self.allocator, allocator) or !self.parser.usesAllocator(allocator)) {
            self.poison(.local_invariant_violation);
            return error.InvalidPreparedRpc;
        }
        return allocator;
    }

    /// Begins the B3-3 no-interleave window. A bound Client uses the existing operation fence's
    /// atomic execution-lease state; the address latch binds it to this caller-final value.
    pub fn beginPreparedRequestExecution(
        self: *Client,
        storage: *PreparedBlockingRpcStorage,
        identity: PreparedBlockingRpcIdentity,
        lease: *PreparedRequestExecutionLease,
    ) PreparedBlockingRpcError!std.mem.Allocator {
        return self.beginPreparedRequestExecutionMode(storage, identity, lease, null, false);
    }

    pub fn beginPreparedRequestExecutionFromRegisteredOperation(
        self: *Client,
        storage: *PreparedBlockingRpcStorage,
        identity: PreparedBlockingRpcIdentity,
        lease: *PreparedRequestExecutionLease,
        poison_capture: ?*incident_publication_contract.PreparedExecutionPoisonCapture,
    ) PreparedBlockingRpcError!std.mem.Allocator {
        return self.beginPreparedRequestExecutionMode(storage, identity, lease, poison_capture, true);
    }

    fn beginPreparedRequestExecutionMode(
        self: *Client,
        storage: *PreparedBlockingRpcStorage,
        identity: PreparedBlockingRpcIdentity,
        lease: *PreparedRequestExecutionLease,
        poison_capture: ?*incident_publication_contract.PreparedExecutionPoisonCapture,
        upgrade_registered_shared: bool,
    ) PreparedBlockingRpcError!std.mem.Allocator {
        const lease_range = checkedExternalRange(
            @intFromPtr(lease),
            @sizeOf(PreparedRequestExecutionLease),
        ) catch return error.InvalidPreparedRpc;
        const storage_range = checkedExternalRange(
            @intFromPtr(storage),
            @sizeOf(PreparedBlockingRpcStorage),
        ) catch return error.InvalidPreparedRpc;
        if (lease_range == null or storage_range == null or
            externalRangesOverlap(lease_range.?, storage_range.?) or
            (externalRangeOverlapsClient(self, lease_range.?) catch return error.InvalidPreparedRpc))
            return error.InvalidPreparedRpc;
        if (poison_capture) |capture| {
            const capture_range = checkedExternalRange(
                @intFromPtr(capture),
                @sizeOf(incident_publication_contract.PreparedExecutionPoisonCapture),
            ) catch return error.InvalidPreparedRpc;
            if (capture_range == null or externalRangesOverlap(lease_range.?, capture_range.?) or
                externalRangesOverlap(storage_range.?, capture_range.?) or
                (externalRangeOverlapsClient(self, capture_range.?) catch return error.InvalidPreparedRpc))
                return error.InvalidPreparedRpc;
            if (capture.self_addr != @intFromPtr(capture) or
                capture.client_addr != @intFromPtr(self) or
                capture.lease_addr != @intFromPtr(lease) or
                capture.prepared_addr == 0 or capture.operation_id == 0 or
                capture.lifecycle_raw != @intFromEnum(incident_publication_contract.PreparedExecutionPoisonCaptureLifecycle.armed) or
                capture.controller_generation == 0 or
                std.enums.fromInt(connection_incident.SourceSite, capture.source_site_raw) == null or
                std.enums.fromInt(connection_incident.SourceSite, capture.allocator_source_site_raw) == null or
                capture.source_site_raw == capture.allocator_source_site_raw)
                return error.InvalidPreparedRpc;
        }
        if (!identity.descriptor.valid()) return error.InvalidPreparedRpc;
        const frame_range = checkedExternalRange(
            identity.descriptor.frame_addr,
            identity.descriptor.frame_len,
        ) catch return error.InvalidPreparedRpc;
        if (frame_range == null or externalRangesOverlap(lease_range.?, frame_range.?))
            return error.InvalidPreparedRpc;
        if (!lease.pristineExact()) return error.DestinationOccupied;
        if (checkedAllocatorReentry(self)) return error.AdminBusy;
        if (self.ownership == .moved or self.unusable) return error.ConnectionClosed;
        const frozen_fence = self.operation_fence;
        const frozen_fence_addr = if (frozen_fence) |fence| @intFromPtr(fence) else 0;
        const frozen_fence_generation = self.operation_fence_generation;
        const frozen_fence_incarnation = if (frozen_fence) |fence| fence.fence_incarnation else 0;
        const fence_lease_identity = preparedExecutionFenceLeaseIdentity(
            @intFromPtr(self),
            frozen_fence_addr,
            frozen_fence_generation,
            frozen_fence_incarnation,
            @intFromPtr(lease),
        );
        const fence_mode: PreparedRequestExecutionFenceMode = if (frozen_fence) |fence| held: {
            if (upgrade_registered_shared)
                fence.upgradeSingleSharedToExecutionLease(
                    @intFromPtr(self),
                    frozen_fence_generation,
                ) catch |err| return switch (err) {
                    error.AdminBusy => error.AdminBusy,
                    error.InvalidOwner, error.InvalidState => error.ConnectionClosed,
                }
            else
                fence.tryAcquireExecutionLease(
                    @intFromPtr(self),
                    frozen_fence_generation,
                ) catch |err| return switch (err) {
                    error.AdminBusy => error.AdminBusy,
                    error.InvalidOwner, error.InvalidState => error.ConnectionClosed,
                };
            break :held if (upgrade_registered_shared) .upgraded_shared else .acquired;
        } else held: {
            if (upgrade_registered_shared or frozen_fence_generation != 0)
                return error.ConnectionClosed;
            break :held .unbound;
        };
        var release_fence = fence_mode != .unbound;
        errdefer if (release_fence) {
            const fence = frozen_fence orelse unreachable;
            const released = switch (fence_mode) {
                .unbound => unreachable,
                .acquired => fence.releaseExecutionLease(
                    @intFromPtr(self),
                    frozen_fence_generation,
                ),
                .upgraded_shared => fence.downgradeExecutionLeaseToSingleShared(
                    @intFromPtr(self),
                    frozen_fence_generation,
                ),
            };
            if (!released)
                @panic("prepared request execution fence release failed");
        };
        if (self.prepared_request_execution_lease_addr != 0 or
            self.prepared_request_execution_fence_addr != 0 or
            self.prepared_request_execution_fence_incarnation != 0 or
            self.prepared_request_execution_fence_lease_identity != 0 or
            self.prepared_request_execution_fence_mode != .unbound or
            self.ownership == .moved or self.unusable)
            return error.AdminBusy;
        const prepared = preparedRpcFromStorage(storage);
        if (!preparedDescriptorRawMatches(prepared, storage, identity.descriptor) or
            !prepared.validFor(self) or prepared.request_id != identity.request_id or
            prepared.frame_digest != identity.frame_digest or
            !prepared.frameIntact() or prepared.request_id != self.next_request_id)
            return error.InvalidPreparedRpc;
        if (self.bufferedControllerRevokeForStreamUnchecked(null)) return error.AdminBusy;
        const allocator = self.allocator;
        lease.* = .{
            .self_addr = @intFromPtr(lease),
            .client_addr = @intFromPtr(self),
            .storage_addr = @intFromPtr(storage),
            .identity = identity,
            .allocator_ptr = @intFromPtr(allocator.ptr),
            .allocator_vtable = @intFromPtr(allocator.vtable),
            .fd = self.fd,
            .operation_fence_addr = frozen_fence_addr,
            .operation_fence_generation = frozen_fence_generation,
            .operation_fence_incarnation = frozen_fence_incarnation,
            .operation_fence_lease_identity = fence_lease_identity,
            .poison_capture_addr = if (poison_capture) |capture| @intFromPtr(capture) else 0,
            .poison_prepared_addr = if (poison_capture) |capture| capture.prepared_addr else 0,
            .poison_timestamp_ns = if (poison_capture) |capture| capture.timestamp_ns else 0,
            .poison_controller_generation = if (poison_capture) |capture| capture.controller_generation else 0,
            .poison_source_site_raw = if (poison_capture) |capture| capture.source_site_raw else 0,
            .poison_allocator_source_site_raw = if (poison_capture) |capture| capture.allocator_source_site_raw else 0,
            .ownership_raw = @intFromEnum(self.ownership),
            .io_mode_raw = @intFromEnum(std.meta.activeTag(self.io_mode)),
            .progress = .request_zero_clean,
            .lifecycle = .active,
            .fence_held = @intFromBool(fence_mode != .unbound),
            .fence_mode = fence_mode,
        };
        lease.seal = preparedExecutionLeaseSeal(lease);
        self.prepared_request_execution_lease_addr = @intFromPtr(lease);
        self.prepared_request_execution_fence_addr = frozen_fence_addr;
        self.prepared_request_execution_fence_incarnation = frozen_fence_incarnation;
        self.prepared_request_execution_fence_lease_identity = fence_lease_identity;
        self.prepared_request_execution_fence_mode = fence_mode;
        release_fence = false;

        self.flushPendingOutboundForPreparedExecution(lease) catch |err| return err;
        if (!self.preparedRequestExecutionLeaseMatches(storage, identity, lease) or
            !std.meta.eql(self.allocator, allocator) or !self.parser.usesAllocator(allocator) or
            self.pending_outbound != null or self.unusable or self.first_poison_reason != null)
        {
            self.poisonWhilePreparedExecutionHeld(.local_invariant_violation);
            return error.InvalidPreparedRpc;
        }
        return allocator;
    }

    pub fn preparedRequestExecutionLeaseMatches(
        self: *const Client,
        storage: *const PreparedBlockingRpcStorage,
        identity: PreparedBlockingRpcIdentity,
        lease: *const PreparedRequestExecutionLease,
    ) bool {
        if (!self.preparedRequestExecutionLeaseAuthorityMatches(lease) or
            lease.storage_addr != @intFromPtr(storage) or !std.meta.eql(lease.identity, identity))
            return false;
        const prepared = preparedRpcFromStorageConst(storage);
        return preparedDescriptorRawMatches(prepared, storage, identity.descriptor) and
            prepared.validFor(self) and prepared.request_id == identity.request_id and
            prepared.frame_digest == identity.frame_digest and prepared.frameIntact() and
            prepared.request_id == self.next_request_id;
    }

    fn preparedRequestExecutionLeaseAuthorityMatches(
        self: *const Client,
        lease: *const PreparedRequestExecutionLease,
    ) bool {
        if (!preparedExecutionLeaseRawValid(lease) or lease.self_addr != @intFromPtr(lease) or
            lease.lifecycle != .active or lease.client_addr != @intFromPtr(self) or
            lease.allocator_ptr != @intFromPtr(self.allocator.ptr) or
            lease.allocator_vtable != @intFromPtr(self.allocator.vtable) or
            (lease.fd != self.fd and
                !(self.fd == -1 and self.unusable and self.first_poison_reason != null)) or
            lease.operation_fence_addr != self.prepared_request_execution_fence_addr or
            lease.operation_fence_generation != self.operation_fence_generation or
            lease.operation_fence_incarnation != self.prepared_request_execution_fence_incarnation or
            lease.operation_fence_lease_identity != self.prepared_request_execution_fence_lease_identity or
            lease.operation_fence_lease_identity != preparedExecutionFenceLeaseIdentity(
                @intFromPtr(self),
                lease.operation_fence_addr,
                lease.operation_fence_generation,
                lease.operation_fence_incarnation,
                @intFromPtr(lease),
            ) or
            (if (self.operation_fence) |fence| @intFromPtr(fence) else 0) != lease.operation_fence_addr or
            (if (self.operation_fence) |fence| fence.fence_incarnation else 0) != lease.operation_fence_incarnation or
            lease.ownership_raw != @intFromEnum(self.ownership) or
            lease.io_mode_raw != @intFromEnum(std.meta.activeTag(self.io_mode)) or
            lease.fence_mode != self.prepared_request_execution_fence_mode or
            lease.seal != preparedExecutionLeaseSeal(lease) or
            self.prepared_request_execution_lease_addr != @intFromPtr(lease)) return false;
        return true;
    }

    pub fn preparedRequestExecutionPoisonReason(
        self: *const Client,
        lease: *const PreparedRequestExecutionLease,
    ) PreparedBlockingRpcError!?client_poison.ConnectionReason {
        if (!self.preparedRequestExecutionLeaseAuthorityMatches(lease))
            return error.InvalidPreparedRpc;
        if (lease.poison_capture_addr != 0) {
            const capture: *const incident_publication_contract.PreparedExecutionPoisonCapture =
                @ptrFromInt(lease.poison_capture_addr);
            if (capture.self_addr != lease.poison_capture_addr or
                capture.client_addr != @intFromPtr(self) or capture.lease_addr != @intFromPtr(lease) or
                capture.prepared_addr != lease.poison_prepared_addr or
                capture.timestamp_ns != lease.poison_timestamp_ns or
                capture.controller_generation != lease.poison_controller_generation or
                (capture.source_site_raw != lease.poison_source_site_raw and
                    capture.source_site_raw != lease.poison_allocator_source_site_raw) or
                capture.allocator_source_site_raw != lease.poison_allocator_source_site_raw or
                capture.lifecycle_raw != @intFromEnum(incident_publication_contract.PreparedExecutionPoisonCaptureLifecycle.captured) or
                std.enums.fromInt(client_poison.ConnectionReason, capture.reason_raw) == null)
                return error.InvalidPreparedRpc;
            return @enumFromInt(capture.reason_raw);
        }
        return self.first_poison_reason;
    }

    pub fn poisonPreparedRequestExecution(
        self: *Client,
        lease: *PreparedRequestExecutionLease,
        reason: client_poison.ConnectionReason,
    ) PreparedBlockingRpcError!void {
        if (!self.preparedRequestExecutionLeaseAuthorityMatches(lease))
            return error.InvalidPreparedRpc;
        self.poisonWhilePreparedExecutionHeld(reason);
    }

    /// Fail-stop-only suffix for a callback that corrupted its caller-owned lease token. The
    /// canonical Client fields, not the token bytes, prove that the prepared execution fence is
    /// still held. This method deliberately performs no public-fence entry and no allocation.
    pub fn commitPreparedExecutionRecoveryPoisonNoFail(
        self: *Client,
        reason: client_poison.ConnectionReason,
    ) void {
        const lease_addr = self.prepared_request_execution_lease_addr;
        const fence_addr = self.prepared_request_execution_fence_addr;
        const fence_incarnation = self.prepared_request_execution_fence_incarnation;
        const fence_identity = self.prepared_request_execution_fence_lease_identity;
        if (lease_addr == 0 or fence_addr == 0 or fence_incarnation == 0 or fence_identity == 0 or
            self.prepared_request_execution_fence_mode == .unbound or
            (if (self.operation_fence) |fence| @intFromPtr(fence) else 0) != fence_addr or
            (if (self.operation_fence) |fence| fence.fence_incarnation else 0) != fence_incarnation or
            fence_identity != preparedExecutionFenceLeaseIdentity(
                @intFromPtr(self),
                fence_addr,
                self.operation_fence_generation,
                fence_incarnation,
                lease_addr,
            )) @panic("prepared execution recovery authority drifted");
        self.poisonWhilePreparedExecutionHeld(reason);
    }

    pub fn preparedExecutionRecoveryPoisonedForTest(self: *const Client) bool {
        if (!builtin.is_test) unreachable;
        return self.first_poison_reason != null and self.unusable and self.fd == -1;
    }

    /// Completes the fail-stop cleanup from Client-owned canonical identities. Caller-owned
    /// allocator-scope and lease tokens may already be corrupt, so they are only zeroed after the
    /// corresponding canonical state has been consumed.
    pub fn commitPreparedExecutionRecoveryCleanupNoFail(self: *Client) void {
        const active_scope = self.active_generation_allocator_scope orelse
            @panic("prepared execution recovery allocator scope missing");
        if (active_scope.purpose != .rpc_execute or !active_scope.validForClient(self))
            @panic("prepared execution recovery allocator scope drifted");
        self.generation_batch_accounting.ledger.?.endAllocatorScope(
            active_scope.client_addr,
            active_scope.token_addr,
            active_scope.epoch,
            @intFromEnum(active_scope.purpose),
            active_scope.previous_allocator,
            active_scope.installed_allocator,
        ) catch @panic("prepared execution recovery allocator authority drifted");
        self.allocator = active_scope.previous_allocator;
        self.parser.restoreAllocatorAfterDrift(active_scope.previous_allocator);
        self.active_generation_allocator_scope = null;
        const scope: *GenerationAllocatorScope = @ptrFromInt(active_scope.token_addr);
        scope.* = .{ .lifecycle = .restored };

        const lease_addr = self.prepared_request_execution_lease_addr;
        const fence_addr = self.prepared_request_execution_fence_addr;
        const fence_generation = self.operation_fence_generation;
        const fence_incarnation = self.prepared_request_execution_fence_incarnation;
        const fence_identity = self.prepared_request_execution_fence_lease_identity;
        const fence_mode = self.prepared_request_execution_fence_mode;
        if (lease_addr == 0 or fence_addr == 0 or fence_generation == 0 or
            fence_incarnation == 0 or fence_identity == 0 or fence_mode == .unbound or
            fence_identity != preparedExecutionFenceLeaseIdentity(
                @intFromPtr(self),
                fence_addr,
                fence_generation,
                fence_incarnation,
                lease_addr,
            )) @panic("prepared execution recovery fence drifted");
        self.prepared_request_execution_lease_addr = 0;
        self.prepared_request_execution_fence_addr = 0;
        self.prepared_request_execution_fence_incarnation = 0;
        self.prepared_request_execution_fence_lease_identity = 0;
        self.prepared_request_execution_fence_mode = .unbound;
        const lease: *PreparedRequestExecutionLease = @ptrFromInt(lease_addr);
        lease.* = .{};
        const fence: *ClientOperationFence = @ptrFromInt(fence_addr);
        if (fence.fence_incarnation != fence_incarnation)
            @panic("prepared execution recovery fence incarnation drifted");
        const released = switch (fence_mode) {
            .unbound => unreachable,
            .acquired => fence.releaseExecutionLease(@intFromPtr(self), fence_generation),
            .upgraded_shared => fence.downgradeExecutionLeaseToSingleShared(
                @intFromPtr(self),
                fence_generation,
            ),
        };
        if (!released) @panic("prepared execution recovery fence release drifted");
    }

    /// Executes only the request-write half of B3-3. Response correlation/publication remains
    /// closed until B3-4/5; every exit retires the authenticated request backing exactly once.
    pub fn writePreparedRequestExecution(
        self: *Client,
        storage: *PreparedBlockingRpcStorage,
        identity: PreparedBlockingRpcIdentity,
        lease: *PreparedRequestExecutionLease,
    ) PreparedBlockingRpcError!void {
        return self.writePreparedRequestExecutionWithOps(storage, identity, lease, .posix_ops);
    }

    fn writePreparedRequestExecutionWithOps(
        self: *Client,
        storage: *PreparedBlockingRpcStorage,
        identity: PreparedBlockingRpcIdentity,
        lease: *PreparedRequestExecutionLease,
        ops: PreparedExecutionWriteOps,
    ) PreparedBlockingRpcError!void {
        if (!self.preparedRequestExecutionLeaseMatches(storage, identity, lease))
            return error.InvalidPreparedRpc;
        const prepared = preparedRpcFromStorage(storage);
        const frame = prepared.frame;
        const allocator = prepared.allocator;
        prepared.lifecycle = .executing;
        self.next_request_id += 1;
        defer prepared.settleCaptured(allocator, frame);

        var offset: usize = 0;
        while (offset < frame.len) {
            switch (ops.writeFn(ops.context, self.fd, frame[offset..])) {
                .interrupted => continue,
                .would_block, .zero, .failed => {
                    self.poisonWhilePreparedExecutionHeld(.outbound_write_ambiguous);
                    return error.WriteFailed;
                },
                .written => |written| {
                    if (written == 0 or written > frame.len - offset) {
                        self.poisonWhilePreparedExecutionHeld(.local_invariant_violation);
                        return error.WriteFailed;
                    }
                    offset += written;
                    if (!self.setPreparedExecutionProgress(lease, .request_maybe_written))
                        return error.InvalidPreparedRpc;
                },
            }
        }
    }

    /// B3-3 test-private terminal sink: no response payload is accepted or published. The peer
    /// closes after consuming the request, proving the post-write terminal cleanup boundary.
    pub fn observePreparedRequestTerminalSinkEof(
        self: *Client,
        lease: *PreparedRequestExecutionLease,
    ) ClientError!void {
        if (!preparedExecutionLeaseRawValid(lease) or lease.self_addr != @intFromPtr(lease) or
            lease.client_addr != @intFromPtr(self) or lease.lifecycle != .active or
            lease.seal != preparedExecutionLeaseSeal(lease) or
            self.prepared_request_execution_lease_addr != @intFromPtr(lease))
            return error.ProtocolError;
        var byte: [1]u8 = undefined;
        while (true) {
            const rc = c.read(self.fd, &byte, byte.len);
            if (rc < 0 and posix.errno(rc) == .INTR) continue;
            if (rc == 0) {
                self.poisonWhilePreparedExecutionHeld(.connection_eof);
                return error.ConnectionClosed;
            }
            self.poisonWhilePreparedExecutionHeld(if (rc < 0)
                .transport_read_failure
            else
                .peer_contract_violation);
            return if (rc < 0) error.ConnectionClosed else error.ProtocolError;
        }
    }

    pub fn finishPreparedRequestExecution(
        self: *Client,
        lease: *PreparedRequestExecutionLease,
    ) PreparedBlockingRpcError!void {
        if (checkedAllocatorReentry(self)) return error.AdminBusy;
        if (preparedExecutionLeaseRawValid(lease) and
            self.prepared_request_execution_lease_addr == @intFromPtr(lease) and
            lease.self_addr == @intFromPtr(lease) and lease.client_addr == @intFromPtr(self) and
            lease.lifecycle == .active and lease.seal == preparedExecutionLeaseSeal(lease) and
            lease.cleanup_active == 1)
            return error.AdminBusy;
        if (!preparedExecutionLeaseRawValid(lease) or lease.self_addr != @intFromPtr(lease) or
            lease.lifecycle != .active or lease.client_addr != @intFromPtr(self) or
            lease.seal != preparedExecutionLeaseSeal(lease) or
            lease.operation_fence_addr != self.prepared_request_execution_fence_addr or
            lease.operation_fence_generation != self.operation_fence_generation or
            lease.operation_fence_incarnation != self.prepared_request_execution_fence_incarnation or
            lease.operation_fence_lease_identity != self.prepared_request_execution_fence_lease_identity or
            (if (self.operation_fence) |fence| @intFromPtr(fence) else 0) != lease.operation_fence_addr or
            (if (self.operation_fence) |fence| fence.fence_incarnation else 0) != lease.operation_fence_incarnation or
            self.prepared_request_execution_lease_addr != @intFromPtr(lease))
        {
            if (self.prepared_request_execution_lease_addr == @intFromPtr(lease)) {
                self.poisonWhilePreparedExecutionHeld(.local_invariant_violation);
                self.releasePreparedRequestExecutionLeaseCanonical(lease);
            }
            return error.InvalidPreparedRpc;
        }
        self.releasePreparedRequestExecutionLeaseCanonical(lease);
    }

    fn releasePreparedRequestExecutionLeaseCanonical(
        self: *Client,
        lease: *PreparedRequestExecutionLease,
    ) void {
        const fence_mode = self.prepared_request_execution_fence_mode;
        const fence_addr = self.prepared_request_execution_fence_addr;
        const fence_generation = lease.operation_fence_generation;
        const fence_incarnation = self.prepared_request_execution_fence_incarnation;
        const fence_lease_identity = self.prepared_request_execution_fence_lease_identity;
        if (fence_lease_identity != preparedExecutionFenceLeaseIdentity(
            @intFromPtr(self),
            fence_addr,
            fence_generation,
            fence_incarnation,
            @intFromPtr(lease),
        )) @panic("prepared request execution fence identity drifted");
        self.prepared_request_execution_lease_addr = 0;
        self.prepared_request_execution_fence_addr = 0;
        self.prepared_request_execution_fence_incarnation = 0;
        self.prepared_request_execution_fence_lease_identity = 0;
        self.prepared_request_execution_fence_mode = .unbound;
        lease.* = .{};
        if (fence_mode != .unbound) {
            if (fence_addr == 0) @panic("prepared request execution fence address missing");
            const fence: *ClientOperationFence = @ptrFromInt(fence_addr);
            if (fence.fence_incarnation != fence_incarnation) return;
            const released = switch (fence_mode) {
                .unbound => unreachable,
                .acquired => fence.releaseExecutionLease(
                    @intFromPtr(self),
                    fence_generation,
                ),
                .upgraded_shared => fence.downgradeExecutionLeaseToSingleShared(
                    @intFromPtr(self),
                    fence_generation,
                ),
            };
            if (!released)
                @panic("prepared request execution fence release failed");
        }
    }

    fn flushPendingOutboundForPreparedExecution(
        self: *Client,
        lease: *PreparedRequestExecutionLease,
    ) ClientError!void {
        return self.flushPendingOutboundBlockingWithOps(lease, .posix_ops, true);
    }

    fn flushPendingOutboundBlockingWithOps(
        self: *Client,
        lease: ?*PreparedRequestExecutionLease,
        ops: PreparedExecutionWriteOps,
        execution_lease_held: bool,
    ) ClientError!void {
        while (self.pending_outbound) |*pending| {
            const ambiguous_before = pending.offset != 0;
            const remaining = pending.frame[pending.offset..];
            const result = ops.writeFn(ops.context, self.fd, remaining);
            switch (result) {
                .interrupted => continue,
                .would_block, .zero, .failed => {
                    if (ambiguous_before) {
                        if (lease) |active|
                            _ = self.setPreparedExecutionProgress(active, .prior_pending_ambiguous);
                    }
                    if (lease != null or execution_lease_held)
                        self.poisonWhilePreparedExecutionHeld(.outbound_write_ambiguous)
                    else
                        self.poison(.outbound_write_ambiguous);
                    return error.WriteFailed;
                },
                .written => |written| {
                    if (written == 0 or written > remaining.len) {
                        if (ambiguous_before) {
                            if (lease) |active|
                                _ = self.setPreparedExecutionProgress(active, .prior_pending_ambiguous);
                        }
                        if (lease != null or execution_lease_held)
                            self.poisonWhilePreparedExecutionHeld(.local_invariant_violation)
                        else
                            self.poison(.local_invariant_violation);
                        return error.WriteFailed;
                    }
                    pending.offset += written;
                },
            }
            if (pending.offset != pending.frame.len) continue;
            if (lease) |active| {
                active.cleanup_active = 1;
                active.seal = preparedExecutionLeaseSeal(active);
                self.clearPendingOutbound();
                if (self.prepared_request_execution_lease_addr != @intFromPtr(active) or
                    !preparedExecutionLeaseRawValid(active) or active.self_addr != @intFromPtr(active) or
                    active.client_addr != @intFromPtr(self) or active.lifecycle != .active or
                    active.cleanup_active != 1 or active.seal != preparedExecutionLeaseSeal(active))
                {
                    self.poisonWhilePreparedExecutionHeld(.local_invariant_violation);
                    return error.WriteFailed;
                }
                active.cleanup_active = 0;
                active.seal = preparedExecutionLeaseSeal(active);
            } else {
                self.clearPendingOutbound();
            }
        }
    }

    fn setPreparedExecutionProgress(
        self: *Client,
        lease: *PreparedRequestExecutionLease,
        progress: PreparedRequestWireProgress,
    ) bool {
        if (self.prepared_request_execution_lease_addr != @intFromPtr(lease) or
            !preparedExecutionLeaseRawValid(lease) or lease.self_addr != @intFromPtr(lease) or
            lease.client_addr != @intFromPtr(self) or lease.lifecycle != .active or
            lease.seal != preparedExecutionLeaseSeal(lease))
            return false;
        const allowed = lease.progress == progress or
            (lease.progress == .request_zero_clean and progress != .request_zero_clean);
        if (!allowed) {
            self.poisonWhilePreparedExecutionHeld(.local_invariant_violation);
            return false;
        }
        lease.progress = progress;
        lease.seal = preparedExecutionLeaseSeal(lease);
        return true;
    }

    fn capturePreparedExecutionPoison(
        self: *Client,
        reason: client_poison.ConnectionReason,
        source_site_raw: u8,
    ) bool {
        if (self.prepared_request_execution_lease_addr == 0) return false;
        const lease: *PreparedRequestExecutionLease =
            @ptrFromInt(self.prepared_request_execution_lease_addr);
        if (lease.poison_capture_addr == 0) return false;
        if (lease.self_addr != @intFromPtr(lease) or lease.client_addr != @intFromPtr(self) or
            lease.lifecycle != .active or lease.seal != preparedExecutionLeaseSeal(lease))
            @panic("prepared execution poison lease authority drifted");
        const capture: *incident_publication_contract.PreparedExecutionPoisonCapture =
            @ptrFromInt(lease.poison_capture_addr);
        const lifecycle: incident_publication_contract.PreparedExecutionPoisonCaptureLifecycle =
            std.enums.fromInt(
                incident_publication_contract.PreparedExecutionPoisonCaptureLifecycle,
                capture.lifecycle_raw,
            ) orelse @panic("prepared execution poison capture authority drifted");
        if (capture.self_addr != lease.poison_capture_addr or
            capture.client_addr != @intFromPtr(self) or capture.lease_addr != @intFromPtr(lease) or
            capture.prepared_addr != lease.poison_prepared_addr or
            capture.timestamp_ns != lease.poison_timestamp_ns or
            capture.controller_generation != lease.poison_controller_generation or
            capture.allocator_source_site_raw != lease.poison_allocator_source_site_raw or
            (capture.source_site_raw != lease.poison_source_site_raw and
                capture.source_site_raw != lease.poison_allocator_source_site_raw) or
            (source_site_raw != lease.poison_source_site_raw and
                source_site_raw != lease.poison_allocator_source_site_raw) or
            (lifecycle != .armed and lifecycle != .captured))
            @panic("prepared execution poison capture authority drifted");
        if (lifecycle == .captured) {
            // **첫 사유가 이긴다 — 두 번째 사유는 버리되 죽이지 않는다.**
            //
            // 예전에는 다른 사유가 오면 `@panic` 했다. 그런데 사유가 갈리는 것은 예외가 아니라 **구조적으로
            // 필연**이다. 바로 아래 `poisonWhilePreparedExecutionHeld` 는 capture 가 성공하면 곧바로
            // 반환해 `latchFirstPoisonReason` 을 건너뛴다 — 그래서 `first_poison_reason` 은 계속 `null` 이고,
            // 유일하게 `if (self.first_poison_reason == null)` 가드를 둔 호출부(현재 19 곳 중 1 곳)마저
            // 두 번째 poison 을 통과시킨다. 나머지 18 곳은 가드 자체가 없다. 즉 lease 를 쥔 동안 두 번째
            // 사유가 도달하는 것은 정상 경로다: 연결이 끊겨 `connection_eof` 로 잡힌 뒤 정리 과정에서
            // `local_invariant_violation` 이 겹치는 식이다.
            //
            // first-poison-wins 를 실제로 강제하는 것은 호출부가 아니라 **이 capture 자신**이다. 그러니
            // 여기서 할 일은 첫 사유를 지키고 두 번째를 버리는 것이지, 프로세스를 끝내는 것이 아니다.
            //
            // 2026-08-28 실측: `reason drifted` panic 으로 앱이 SIGABRT 로 죽었다(간헐, 같은 세션에서 2 회).
            // session host 는 멀쩡히 살아 있는데 앱만 사라져 사용자가 열어 둔 창을 전부 잃었다. 진단 가치는
            // 남기되(첫 사유와 버린 사유를 함께 기록) 프로세스를 끝내지는 않는다.
            if (capture.reason_raw != @intFromEnum(reason))
                logPoisonReasonDrift(capture.reason_raw, @intFromEnum(reason));
            return true;
        }
        if (capture.source_site_raw != lease.poison_source_site_raw)
            @panic("prepared execution poison source drifted");
        capture.source_site_raw = source_site_raw;
        capture.reason_raw = @intFromEnum(reason);
        capture.lifecycle_raw = @intFromEnum(incident_publication_contract.PreparedExecutionPoisonCaptureLifecycle.captured);
        return true;
    }

    pub fn beginReadPumpPoisonCapture(
        self: *Client,
        capture: *incident_publication_contract.ReadPumpPoisonCapture,
    ) bool {
        if (read_pump_poison_capture_addr != 0 or
            capture.self_addr != @intFromPtr(capture) or
            capture.client_addr != @intFromPtr(self) or
            capture.timestamp_ns < 0 or capture.controller_generation == 0 or
            capture.source_site_raw != @intFromEnum(connection_incident.SourceSite.client_read) or
            capture.reason_raw != 0 or capture.reason_present_raw != 0 or
            capture.lifecycle_raw != @intFromEnum(incident_publication_contract.ReadPumpPoisonCaptureLifecycle.armed))
            return false;
        read_pump_poison_capture_addr = @intFromPtr(capture);
        return true;
    }

    pub fn endReadPumpPoisonCapture(
        self: *Client,
        capture: *incident_publication_contract.ReadPumpPoisonCapture,
    ) void {
        if (read_pump_poison_capture_addr != @intFromPtr(capture) or
            capture.self_addr != @intFromPtr(capture) or
            capture.client_addr != @intFromPtr(self) or
            (capture.lifecycle_raw != @intFromEnum(incident_publication_contract.ReadPumpPoisonCaptureLifecycle.armed) and
                capture.lifecycle_raw != @intFromEnum(incident_publication_contract.ReadPumpPoisonCaptureLifecycle.captured)) or
            (capture.lifecycle_raw == @intFromEnum(incident_publication_contract.ReadPumpPoisonCaptureLifecycle.armed) and
                (capture.reason_present_raw != 0 or capture.reason_raw != 0)) or
            (capture.lifecycle_raw == @intFromEnum(incident_publication_contract.ReadPumpPoisonCaptureLifecycle.captured) and
                (capture.reason_present_raw != 1 or
                    std.enums.fromInt(client_poison.ConnectionReason, capture.reason_raw) == null)))
            @panic("read pump poison capture authority drifted");
        read_pump_poison_capture_addr = 0;
    }

    fn captureReadPumpPoison(
        self: *Client,
        reason: client_poison.ConnectionReason,
    ) bool {
        if (read_pump_poison_capture_addr == 0) return false;
        const capture: *incident_publication_contract.ReadPumpPoisonCapture =
            @ptrFromInt(read_pump_poison_capture_addr);
        const lifecycle = std.enums.fromInt(
            incident_publication_contract.ReadPumpPoisonCaptureLifecycle,
            capture.lifecycle_raw,
        ) orelse @panic("read pump poison capture lifecycle drifted");
        if (capture.self_addr != read_pump_poison_capture_addr or
            capture.client_addr != @intFromPtr(self) or capture.batch_adapter_addr == 0 or
            capture.slot_addr == 0 or capture.timestamp_ns < 0 or
            capture.controller_generation == 0 or
            capture.source_site_raw != @intFromEnum(connection_incident.SourceSite.client_read) or
            (lifecycle != .armed and lifecycle != .captured) or
            (lifecycle == .armed and (capture.reason_present_raw != 0 or capture.reason_raw != 0)))
            @panic("read pump poison capture authority drifted");
        if (lifecycle == .captured) {
            // `captured` 인데 사유가 실려 있지 않은 것은 **손상**이다 — lifecycle 과 payload 가 갈렸다는 뜻이라
            // 계속 진행하면 무엇을 publish 할지 알 수 없다. 여기서는 멈춘다.
            if (capture.reason_present_raw != 1) @panic("read pump poison capture lost its reason");
            // 사유가 **다른** 것은 손상이 아니다. `poisonAllocator` 경로도 capture 가 성공하면 곧바로
            // 반환해 `latchFirstPoisonReason` 을 건너뛰므로, 한 armed 창 안에 두 번째 사유가 도달하는 것은
            // prepared execution 쪽과 똑같이 정상 경로다. 그쪽은 이 자리에서 죽는 바람에 2026-08-28 에
            // 앱이 SIGABRT 로 사라졌다(같은 세션에서 2 회). 같은 구조를 남겨 두지 않는다 — 첫 사유를 지키고
            // 두 번째는 기록만 하고 버린다.
            if (capture.reason_raw != @intFromEnum(reason))
                logReadPumpPoisonReasonDrift(capture.reason_raw, @intFromEnum(reason));
            return true;
        }
        capture.reason_raw = @intFromEnum(reason);
        capture.reason_present_raw = 1;
        capture.lifecycle_raw = @intFromEnum(incident_publication_contract.ReadPumpPoisonCaptureLifecycle.captured);
        return true;
    }

    fn poisonWhilePreparedExecutionHeld(
        self: *Client,
        reason: client_poison.ConnectionReason,
    ) void {
        if (self.prepared_request_execution_lease_addr != 0) {
            const lease: *const PreparedRequestExecutionLease =
                @ptrFromInt(self.prepared_request_execution_lease_addr);
            if (self.capturePreparedExecutionPoison(reason, lease.poison_source_site_raw)) return;
        }
        self.latchFirstPoisonReason(reason);
        if (self.poisonAndTakeFd()) |fd| _ = c.close(fd);
    }

    fn poisonMutationIo(
        self: *Client,
        reason: client_poison.ConnectionReason,
        execution_lease_held: bool,
    ) void {
        if (execution_lease_held)
            self.poisonWhilePreparedExecutionHeld(reason)
        else
            self.poison(reason);
    }

    pub fn executePreparedBlockingRpcStorageWithAllocator(
        self: *Client,
        storage: *PreparedBlockingRpcStorage,
        allocator: std.mem.Allocator,
    ) PreparedBlockingRpcExecution {
        return switch (self.executePreparedBlockingRpcStorageWithAllocatorInternal(
            storage,
            allocator,
            null,
        )) {
            .accepted => |response| .{ .accepted = response },
            .not_executed => |err| .{ .not_executed = switch (err) {
                error.PayloadProvenanceRejected => unreachable,
                else => |legacy_err| legacy_err,
            } },
            .uncertain => |err| .{ .uncertain = switch (err) {
                error.PayloadProvenanceRejected => unreachable,
                else => |legacy_err| legacy_err,
            } },
        };
    }

    pub fn executePreparedBlockingRpcStorageWithAllocatorObserved(
        self: *Client,
        storage: *PreparedBlockingRpcStorage,
        allocator: std.mem.Allocator,
        observer: framing.PayloadAllocationObserver,
    ) ObservedPreparedBlockingRpcExecution {
        return self.executePreparedBlockingRpcStorageWithAllocatorInternal(
            storage,
            allocator,
            observer,
        );
    }

    /// 앱 종료 admin request의 전송 여부 분류와 절대 deadline을 한 경계에서 보존한다. timeout 시 prepared가
    /// 그대로면 재시도 가능한 미전송이고, executing 이후면 destructive retry를 막아야 하는 uncertain이다.
    pub fn executePreparedBlockingRpcStorageUntil(
        self: *Client,
        storage: *PreparedBlockingRpcStorage,
        allocator: std.mem.Allocator,
        deadline: client_deadline.AbsoluteDeadline,
    ) DeadlinePreparedBlockingRpcExecution {
        const result = self.executePreparedBlockingRpcStorageUntilObserved(
            storage,
            allocator,
            deadline,
            null,
        );
        return switch (result) {
            .accepted => |value| .{ .accepted = value },
            .not_executed => |err| .{ .not_executed = switch (err) {
                error.PayloadProvenanceRejected => error.ProtocolError,
                else => |typed| typed,
            } },
            .uncertain => |err| .{ .uncertain = switch (err) {
                error.PayloadProvenanceRejected => error.ProtocolError,
                else => |typed| typed,
            } },
        };
    }

    /// GenerationAttachment의 guarded response allocator도 같은 absolute deadline 아래 실행한다.
    /// observer를 보존해야 provenance 위반을 일반 protocol error로 세탁하지 않고 owner 경계에서 fail-stop할 수 있다.
    pub fn executePreparedBlockingRpcStorageUntilObserved(
        self: *Client,
        storage: *PreparedBlockingRpcStorage,
        allocator: std.mem.Allocator,
        deadline: client_deadline.AbsoluteDeadline,
        observer: ?framing.PayloadAllocationObserver,
    ) DeadlineObservedPreparedBlockingRpcExecution {
        // 이미 끝난 종료 deadline은 Client fence나 fd flag를 건드리기 전에 미전송으로 닫는다. caller는 같은
        // prepared backing을 canonical abort할 수 있고, 다음 독립 operation에서 connection을 계속 사용할 수 있다.
        if (deadline.remainingNs() <= 0) return .{ .not_executed = error.DeadlineExceeded };
        const operation_fence_held = self.beginPublicMutation() catch |err|
            return .{ .not_executed = switch (err) {
                error.AdminBusy => error.AdminBusy,
                else => error.ConnectionClosed,
            } };
        defer if (operation_fence_held) self.endPublicMutation();
        if (checkedAllocatorReentry(self) or self.bufferedControllerRevokeForStreamUnchecked(null))
            return .{ .not_executed = error.AdminBusy };
        const prepared = preparedRpcFromStorage(storage);
        if (self.pending_outbound != null or !std.meta.eql(self.allocator, allocator) or
            !self.parser.usesAllocator(allocator)) return .{ .not_executed = error.InvalidPreparedRpc };
        const ops = client_deadline.posix_ops;
        const saved_flags = ops.get_flags(ops.context, self.fd) orelse {
            self.poison(.local_invariant_violation);
            return .{ .not_executed = error.WriteFailed };
        };
        const nonblocking: c_int = @bitCast(posix.O{ .NONBLOCK = true });
        if (!ops.set_flags(ops.context, self.fd, saved_flags | nonblocking)) {
            self.poison(.local_invariant_violation);
            return .{ .not_executed = error.WriteFailed };
        }
        const execution_fd = self.fd;
        const response = self.executePreparedWithIo(
            prepared,
            .{ .deadline = .{ .absolute = deadline, .ops = ops } },
            false,
            allocator,
            observer,
            false,
        ) catch |err| {
            const classified = err;
            const request_not_executed = prepared.lifecycle == .prepared;
            if (self.fd == execution_fd and !ops.set_flags(ops.context, self.fd, saved_flags)) {
                self.poison(.local_invariant_violation);
                return if (request_not_executed)
                    .{ .not_executed = error.ConnectionClosed }
                else
                    .{ .uncertain = error.ConnectionClosed };
            }
            if (self.fd != execution_fd and !(self.fd == -1 and self.unusable)) {
                self.poison(.local_invariant_violation);
                return if (request_not_executed)
                    .{ .not_executed = error.ConnectionClosed }
                else
                    .{ .uncertain = error.ConnectionClosed };
            }
            if (request_not_executed) return .{ .not_executed = classified };
            if (self.fd == execution_fd) self.poison(.response_correlation_lost);
            return .{ .uncertain = classified };
        };
        if (!ops.set_flags(ops.context, self.fd, saved_flags)) {
            response.payload_allocator.free(response.payload);
            self.poison(.local_invariant_violation);
            return .{ .uncertain = error.ConnectionClosed };
        }
        if (deadline.remainingNs() <= 0) {
            response.payload_allocator.free(response.payload);
            self.poison(.response_correlation_lost);
            return .{ .uncertain = error.DeadlineExceeded };
        }
        return .{ .accepted = response };
    }

    fn executePreparedBlockingRpcStorageWithAllocatorInternal(
        self: *Client,
        storage: *PreparedBlockingRpcStorage,
        allocator: std.mem.Allocator,
        observer: ?framing.PayloadAllocationObserver,
    ) ObservedPreparedBlockingRpcExecution {
        const operation_fence_held = self.beginPublicMutation() catch |err|
            return .{ .not_executed = switch (err) {
                error.AdminBusy => error.AdminBusy,
                else => error.ConnectionClosed,
            } };
        defer if (operation_fence_held) self.endPublicMutation();
        if (checkedAllocatorReentry(self))
            return .{ .not_executed = error.AdminBusy };
        if (self.bufferedControllerRevokeForStreamUnchecked(null))
            return .{ .not_executed = error.AdminBusy };
        const prepared = preparedRpcFromStorage(storage);
        if (self.pending_outbound != null or
            !std.meta.eql(self.allocator, allocator) or
            !self.parser.usesAllocator(allocator))
            return .{ .not_executed = error.InvalidPreparedRpc };
        const response = self.executePreparedWithIo(
            prepared,
            .blocking,
            false,
            allocator,
            observer,
            false,
        ) catch |err| {
            const classified: ObservedPreparedBlockingRpcExecutionError = switch (err) {
                error.DeadlineExceeded => unreachable,
                else => |client_err| client_err,
            };
            return if (prepared.lifecycle == .prepared)
                .{ .not_executed = classified }
            else
                .{ .uncertain = classified };
        };
        return .{ .accepted = response };
    }

    pub fn preparedBlockingRpcStorageMatches(
        self: *const Client,
        storage: *const PreparedBlockingRpcStorage,
        identity: PreparedBlockingRpcIdentity,
    ) bool {
        const operation_fence_held = self.beginPublicMutation() catch return false;
        defer if (operation_fence_held) self.endPublicMutation();
        const prepared = preparedRpcFromStorageConst(storage);
        return preparedDescriptorRawMatches(prepared, storage, identity.descriptor) and
            prepared.validFor(self) and prepared.request_id == identity.request_id and
            prepared.frame_digest == identity.frame_digest;
    }

    pub fn preparedBlockingRpcStorageSettled(
        storage: *const PreparedBlockingRpcStorage,
    ) bool {
        const prepared = preparedRpcFromStorageConst(storage);
        if (!preparedLifecycleRawValid(prepared)) return false;
        return prepared.frame.len == 0 and prepared.client_addr == 0 and
            (prepared.lifecycle == .pristine or prepared.lifecycle == .terminal);
    }

    fn executePreparedWithIo(
        self: *Client,
        prepared: *PreparedBlockingRpc,
        io: RpcIo,
        flush_pending: bool,
        expected_payload_allocator: ?std.mem.Allocator,
        payload_observer: ?framing.PayloadAllocationObserver,
        execution_lease_held: bool,
    ) (DeadlineClientError || error{ InvalidPreparedRpc, MovedOrCopied, PayloadProvenanceRejected })!ExecutedBlockingRpcResponse {
        if (prepared.self_addr != @intFromPtr(prepared)) return error.MovedOrCopied;
        if (!prepared.validFor(self) or !prepared.frameIntact() or
            prepared.request_id != self.next_request_id)
            return error.InvalidPreparedRpc;
        if (flush_pending) try self.flushPendingOutboundBlockingMode(execution_lease_held);

        prepared.lifecycle = .executing;
        const request_id = prepared.request_id;
        const frame_bytes = prepared.frame;
        const frame_allocator = prepared.allocator;
        var request_settled = false;
        self.next_request_id += 1;
        defer if (!request_settled) prepared.settleCaptured(frame_allocator, frame_bytes);
        switch (io) {
            .blocking => socket_server.writeAll(self.fd, frame_bytes) catch {
                // request prefix가 이미 kernel에 들어갔을 수 있다. 이 connection은 frame 경계를 다시 찾을 수 없으므로
                // 이후 RPC를 허용하지 않고 EOF로 모든 host-side attachment를 정리한다.
                if (execution_lease_held)
                    self.poisonWhilePreparedExecutionHeld(.outbound_write_ambiguous)
                else
                    self.poison(.outbound_write_ambiguous);
                return error.WriteFailed;
            },
            .deadline => |bounded| client_deadline.writeAllUntil(
                bounded.ops,
                self.fd,
                frame_bytes,
                bounded.absolute,
            ) catch |err| return switch (err) {
                error.Timeout => error.DeadlineExceeded,
                error.WriteFailed, error.Closed => error.WriteFailed,
                else => error.WriteFailed,
            },
        }

        // No response-side allocation or parser callback may retain the request-frame owner.
        // Retire it from the authenticated local descriptor immediately after the request write.
        prepared.settleCaptured(frame_allocator, frame_bytes);
        request_settled = true;

        return self.readCorrelatedPreparedResponse(
            request_id,
            io,
            expected_payload_allocator,
            payload_observer,
            execution_lease_held,
        );
    }

    /// Reads only the blocking response half for a request already written under `lease`.
    /// The lease seals the consumed request id and allocator domain, so this path cannot replay
    /// request bytes or advance `next_request_id` a second time.
    pub fn readPreparedResponseUnderExecutionLease(
        self: *Client,
        lease: *PreparedRequestExecutionLease,
        expected_payload_allocator: std.mem.Allocator,
        payload_observer: ?framing.PayloadAllocationObserver,
    ) (ClientError || error{ InvalidPreparedRpc, PayloadProvenanceRejected })!ExecutedBlockingRpcResponse {
        if (!self.preparedRequestExecutionLeaseAuthorityMatches(lease) or
            lease.progress != .request_maybe_written or lease.response_read_started != 0 or
            !std.meta.eql(expected_payload_allocator, self.allocator) or
            !self.parser.usesAllocator(expected_payload_allocator) or
            lease.identity.request_id == std.math.maxInt(u64) or
            self.next_request_id != lease.identity.request_id + 1)
            return error.InvalidPreparedRpc;
        lease.response_read_started = 1;
        lease.seal = preparedExecutionLeaseSeal(lease);
        const response = self.readCorrelatedPreparedResponse(
            lease.identity.request_id,
            .blocking,
            expected_payload_allocator,
            payload_observer,
            true,
        ) catch |err| {
            if (self.first_poison_reason == null) self.poisonWhilePreparedExecutionHeld(switch (err) {
                error.ConnectionClosed => .connection_eof,
                error.OutOfMemory => .local_resource_exhausted,
                error.PayloadProvenanceRejected => .local_invariant_violation,
                error.ProtocolError => .frame_malformed,
                else => .local_invariant_violation,
            });
            // Connection poison canonicalizes ownership/io mode while the execution fence remains
            // held. Peer/resource failures must keep that canonical lease finishable; otherwise a
            // normal terminal unwind is misclassified as caller-token drift and aborts the process.
            switch (err) {
                error.ConnectionClosed, error.OutOfMemory, error.ProtocolError => {
                    lease.ownership_raw = @intFromEnum(self.ownership);
                    lease.io_mode_raw = @intFromEnum(std.meta.activeTag(self.io_mode));
                    lease.seal = preparedExecutionLeaseSeal(lease);
                },
                else => {},
            }
            return switch (err) {
                error.DeadlineExceeded => unreachable,
                else => |read_err| read_err,
            };
        };
        // The strict prepared-execution owner has no canonical empty response representation.
        // Keep legacy/deadline correlated reads unchanged and reject empty only at this boundary.
        if (response.payload.len == 0) {
            // **왜 빈 응답이 왔는지 남긴다.** 이 판정은 `frame_malformed` → `ProtocolError` 로 나가고,
            // `remote_term_backend.drainRemoteNow` 의 복구 목록(`GenerationGap`·`MalformedRow`)에 없어
            // **세션 종료**로 처리된다 — resync 를 시도조차 하지 않으므로 화면이 마지막 상태로 굳고
            // 앱 재시작 말고는 복구 수단이 없다(2026-08-27 실측: 장시간 sleep 뒤 「화면이 깨져 보인다」).
            //
            // 설계상 빈 응답은 존재할 수 없다. 그런데 실제로 왔다면 host 가 정말 빈 것을 보냈거나, 읽기가
            // 중단돼 우리가 빈 것으로 읽은 것이다. 둘은 고치는 자리가 다르므로 request_id 와 연결 상태를
            // 함께 남겨 다음 재발에서 갈리게 한다.
            logEmptyPreparedResponse(self, lease.identity.request_id);
            if (payload_observer) |active| {
                if (response.payload_observation_generation != 0)
                    active.discard_fn(active.context, response.payload_observation_generation);
            }
            response.payload_allocator.free(response.payload);
            self.poisonWhilePreparedExecutionHeld(.frame_malformed);
            lease.ownership_raw = @intFromEnum(self.ownership);
            lease.io_mode_raw = @intFromEnum(std.meta.activeTag(self.io_mode));
            lease.seal = preparedExecutionLeaseSeal(lease);
            return error.ProtocolError;
        }
        return response;
    }

    /// Revalidates every Client-owned response publication invariant after allocator/parser
    /// callbacks have returned and before an external response owner is initialized.
    pub fn revalidatePreparedResponsePublication(
        self: *const Client,
        lease: *const PreparedRequestExecutionLease,
        expected_payload_allocator: std.mem.Allocator,
    ) PreparedBlockingRpcError!void {
        if (!self.preparedRequestExecutionLeaseAuthorityMatches(lease) or
            lease.progress != .request_maybe_written or lease.response_read_started != 1 or
            !std.meta.eql(expected_payload_allocator, self.allocator) or
            !self.parser.usesAllocator(expected_payload_allocator) or
            lease.identity.request_id == std.math.maxInt(u64) or
            self.next_request_id != lease.identity.request_id + 1 or self.fd < 0 or
            self.unusable or self.first_poison_reason != null)
            return error.InvalidPreparedRpc;
    }

    fn readCorrelatedPreparedResponse(
        self: *Client,
        request_id: u64,
        io: RpcIo,
        expected_payload_allocator: ?std.mem.Allocator,
        payload_observer: ?framing.PayloadAllocationObserver,
        execution_lease_held: bool,
    ) (DeadlineClientError || error{PayloadProvenanceRejected})!ExecutedBlockingRpcResponse {
        // 응답을 기다리는 동안 host가 비동기로 push하는 stream frame(delta_chunk/snapshot_chunk)은 **버퍼에 쌓는다** — 드롭하면
        // 그 사이 화면 갱신이 유실된다(§9 delta는 증분이라 한 배치만 놓쳐도 desync). 다음 `readStreamBatch`가 이 버퍼부터 소비한다.
        while (true) {
            var actual_payload_allocator = self.allocator;
            const resp = switch (io) {
                .blocking => if (execution_lease_held)
                    try self.readFrameWithAllocatorObservedUnderExecutionLease(
                        &actual_payload_allocator,
                        payload_observer,
                    )
                else
                    try self.readFrameWithAllocatorObserved(
                        &actual_payload_allocator,
                        payload_observer,
                    ),
                .deadline => |bounded| try self.readFrameUntilEstablishedObserved(
                    bounded.absolute,
                    bounded.ops,
                    &actual_payload_allocator,
                    payload_observer,
                ),
            };
            if (expected_payload_allocator) |expected| {
                if (!std.meta.eql(actual_payload_allocator, expected) or
                    !std.meta.eql(self.allocator, expected) or
                    !self.parser.usesAllocator(expected))
                {
                    // The allocation callback changed the Client/parser allocator domain. The
                    // frame's actual owner is now outside this request's sealed domain: do not
                    // publish, queue, classify, or free the bounded payload.
                    if (execution_lease_held)
                        self.poisonWhilePreparedExecutionHeld(.local_invariant_violation)
                    else
                        self.poison(.local_invariant_violation);
                    return error.PayloadProvenanceRejected;
                }
            }
            const buffered_out_of_band = self.bufferOutOfBandFrame(
                resp,
                expected_payload_allocator,
                payload_observer,
                execution_lease_held,
            ) catch |err| return err;
            if (buffered_out_of_band) continue;
            // kind와 request_id를 함께 확인한다 — out-of-order frame을 이 call의 응답으로 오귀속하지 않는다.
            if (resp.header.kind != .response or resp.header.request_id != request_id) {
                if (execution_lease_held)
                    self.poisonWhilePreparedExecutionHeld(.response_correlation_lost)
                else
                    self.poison(.response_correlation_lost);
                discardFramePayloadObservation(payload_observer, resp);
                resp.deinit(self.allocator);
                return error.ProtocolError;
            }
            if (rpcDeadlineExpired(io)) {
                discardFramePayloadObservation(payload_observer, resp);
                resp.deinit(self.allocator);
                return error.DeadlineExceeded;
            }
            self.last_success_request_id = request_id;
            // FrameParser already returned an owned payload. Transfer it directly so a committed
            // mutating response cannot be consumed and then lost to a second allocation failure.
            return .{
                .payload = resp.payload,
                .payload_allocator = actual_payload_allocator,
                .response_request_id = resp.header.request_id,
                .payload_observation_generation = resp.payload_observation_generation,
            };
        }
    }

    fn rpcDeadlineExpired(io: RpcIo) bool {
        return switch (io) {
            .blocking => false,
            .deadline => |bounded| bounded.absolute.remainingNs() <= 0,
        };
    }

    fn discardFramePayloadObservation(
        observer: ?framing.PayloadAllocationObserver,
        frame: framing.Frame,
    ) void {
        const active = observer orelse return;
        if (frame.payload_observation_generation == 0) return;
        active.discard_fn(active.context, frame.payload_observation_generation);
    }

    /// Buffer a frame that may legally interleave with an RPC response. Returning false transfers
    /// ownership back to the caller, which must classify the response/control frame.
    fn bufferOutOfBandFrame(
        self: *Client,
        frame: framing.Frame,
        expected_allocator: ?std.mem.Allocator,
        payload_observer: ?framing.PayloadAllocationObserver,
        execution_lease_held: bool,
    ) ClientError!bool {
        const allocator = expected_allocator orelse self.allocator;
        defer if (expected_allocator != null and
            (!std.meta.eql(self.allocator, allocator) or !self.parser.usesAllocator(allocator)))
        {
            self.allocator = allocator;
            self.parser.restoreAllocatorAfterDrift(allocator);
            self.poisonMutationIo(.local_invariant_violation, execution_lease_held);
        };
        if (frame.header.kind == .screen_frontier_barrier) {
            discardFramePayloadObservation(payload_observer, frame);
            try self.bufferCatchupBarrierFrame(frame, allocator, execution_lease_held);
            return true;
        }
        if (frame.header.kind == .delta_chunk or frame.header.kind == .snapshot_chunk) {
            const manual_allocator_guard = expected_allocator != null and
                self.operation_fence == null;
            if (manual_allocator_guard and !self.enterGenerationAllocatorCallback())
                return error.AdminBusy;
            defer if (manual_allocator_guard)
                self.leaveGenerationAllocatorCallbackUnchecked();
            discardFramePayloadObservation(payload_observer, frame);
            if (self.pending_stream.items.len >= protocol.max_client_screen_items or
                self.screenInboxBytes() +| frame.payload.len > protocol.max_client_screen_inbox)
            {
                frame.deinit(allocator);
                self.poisonMutationIo(.event_queue_overflow, execution_lease_held);
                return error.EventQueueFull;
            }
            var durable_frame = frame;
            durable_frame.payload_observation_generation = 0;
            self.pending_stream.append(allocator, durable_frame) catch {
                frame.deinit(allocator);
                // The frame is already consumed from the socket. Losing it would break the next
                // stream delta base, so the whole shared connection must fail closed.
                self.poisonMutationIo(.local_resource_exhausted, execution_lease_held);
                return error.OutOfMemory;
            };
            self.pending_stream_bytes += frame.payload.len;
            return true;
        }
        if (frame.header.kind == .event) {
            const manual_allocator_guard = expected_allocator != null and
                self.operation_fence == null;
            if (manual_allocator_guard and !self.enterGenerationAllocatorCallback())
                return error.AdminBusy;
            defer if (manual_allocator_guard)
                self.leaveGenerationAllocatorCallbackUnchecked();
            var canonical_frame = frame;
            const event_allocator = self.canonicalEventAllocator() catch {
                discardFramePayloadObservation(payload_observer, frame);
                frame.deinit(allocator);
                self.poisonMutationIo(.local_invariant_violation, execution_lease_held);
                return error.ProtocolError;
            };
            if (!allocatorEql(allocator, event_allocator)) {
                const payload = event_allocator.dupe(u8, frame.payload) catch {
                    discardFramePayloadObservation(payload_observer, frame);
                    frame.deinit(allocator);
                    self.poisonMutationIo(.local_resource_exhausted, execution_lease_held);
                    return error.OutOfMemory;
                };
                discardFramePayloadObservation(payload_observer, frame);
                frame.deinit(allocator);
                canonical_frame.payload = payload;
                canonical_frame.payload_observation_generation = 0;
            } else {
                discardFramePayloadObservation(payload_observer, frame);
            }
            self.bufferEventWithAllocator(canonical_frame, event_allocator) catch |err| {
                if (execution_lease_held and self.first_poison_reason == null)
                    self.poisonMutationIo(switch (err) {
                        error.OutOfMemory => .local_resource_exhausted,
                        error.EventQueueFull => .event_queue_overflow,
                        else => .peer_contract_violation,
                    }, true);
                return err;
            };
            return true;
        }
        return false;
    }

    fn bufferCatchupBarrierFrame(
        self: *Client,
        frame: framing.Frame,
        allocator: std.mem.Allocator,
        execution_lease_held: bool,
    ) ClientError!void {
        defer frame.deinit(allocator);
        if (!self.runtime_catchup_barrier_v1 or frame.header.request_id != 0 or
            frame.header.stream_id == 0 or frame.header.flags != 0 or
            frame.payload.len != catchup_barrier_contract.payload_size)
        {
            self.poisonMutationIo(.peer_contract_violation, execution_lease_held);
            return error.ProtocolError;
        }
        const fixed: *const [catchup_barrier_contract.payload_size]u8 =
            @ptrCast(frame.payload.ptr);
        const barrier = catchup_barrier_contract.Barrier.decode(fixed) catch {
            self.poisonMutationIo(.frame_malformed, execution_lease_held);
            return error.ProtocolError;
        };
        for (self.pending_catchup_barriers.items) |existing| {
            if (existing.stream_id == frame.header.stream_id or
                std.meta.eql(existing.barrier.identity, barrier.identity))
            {
                self.poisonMutationIo(.peer_contract_violation, execution_lease_held);
                return error.ProtocolError;
            }
        }
        if (self.partial_batch) |partial| if (partial.stream_id == frame.header.stream_id) {
            self.poisonMutationIo(.peer_contract_violation, execution_lease_held);
            return error.ProtocolError;
        };
        if (self.pending_catchup_barriers.items.len >= protocol.max_client_screen_items) {
            self.poisonMutationIo(.event_queue_overflow, execution_lease_held);
            return error.EventQueueFull;
        }
        var preceding: u32 = 0;
        for (self.pending_batches.items) |batch| if (batch.stream_id == frame.header.stream_id) {
            preceding = std.math.add(u32, preceding, 1) catch {
                self.poisonMutationIo(.local_invariant_violation, execution_lease_held);
                return error.ProtocolError;
            };
        };
        // A blocking RPC owns the socket reader. Screen frames that preceded this barrier on
        // the wire can therefore still be in the raw pending-stream inbox rather than in
        // `pending_batches`. Freeze the cut at barrier admission, before later same-stream
        // frames can arrive while the RPC waits for its correlated response.
        var target_batch_open = false;
        for (self.pending_stream.items) |pending| {
            if (pending.header.stream_id != frame.header.stream_id) continue;
            if (pending.header.kind != .snapshot_chunk and pending.header.kind != .delta_chunk) {
                self.poisonMutationIo(.local_invariant_violation, execution_lease_held);
                return error.ProtocolError;
            }
            if (!target_batch_open) {
                target_batch_open = true;
            }
            if (protocol.Flags.hasEndStream(pending.header.flags)) {
                preceding = std.math.add(u32, preceding, 1) catch {
                    self.poisonMutationIo(.local_invariant_violation, execution_lease_held);
                    return error.ProtocolError;
                };
                target_batch_open = false;
            }
        }
        if (target_batch_open) {
            self.poisonMutationIo(.peer_contract_violation, execution_lease_held);
            return error.ProtocolError;
        }
        self.pending_catchup_barriers.append(self.allocator, .{
            .stream_id = frame.header.stream_id,
            .barrier = barrier,
            .preceding_screen_batches = preceding,
        }) catch {
            self.poisonMutationIo(.local_resource_exhausted, execution_lease_held);
            return error.OutOfMemory;
        };
    }

    /// Drain only complete frames already resident in the parser; this never reads the socket.
    /// Publication gates use it so a response coalesced with an authority revoke cannot publish
    /// stale controller state.
    pub fn refreshBufferedAuthorityEvidence(self: *Client) ClientError!void {
        const operation_fence_held = try self.requireBlockingMode();
        defer if (operation_fence_held) self.endPublicMutation();
        while (self.parser.bufferState() == .complete_or_error) {
            const maybe = self.parser.next() catch |err| {
                self.poison(if (err == error.OutOfMemory)
                    .local_resource_exhausted
                else
                    .frame_malformed);
                return switch (err) {
                    error.OutOfMemory => error.OutOfMemory,
                    else => error.ProtocolError,
                };
            };
            const owned = maybe orelse continue;
            const frame = try self.requireWireMajor(owned);
            if (try self.bufferOutOfBandFrame(frame, null, null, false)) continue;
            frame.deinit(self.allocator);
            self.poison(.peer_contract_violation);
            return error.ProtocolError;
        }
    }

    /// 새 request byte보다 먼저 현재 readable RX를 canonical out-of-band owner로 옮긴다.
    /// 의미 처리는 caller가 소유하며, 이 단계에서 response/control을 만나면 상관관계 없는 wire로 닫는다.
    pub fn ingestReadableOutOfBandEvidence(self: *Client) ClientError!void {
        const operation_fence_held = try self.requireBlockingMode();
        defer if (operation_fence_held) self.endPublicMutation();
        while (true) {
            const frame = if (self.parser.next() catch |err| {
                self.poison(if (err == error.OutOfMemory) .local_resource_exhausted else .frame_malformed);
                return switch (err) {
                    error.OutOfMemory => error.OutOfMemory,
                    else => error.ProtocolError,
                };
            }) |owned|
                try self.requireWireMajor(owned)
            else {
                if (!pollReadableOrTerminal(self.fd)) return;
                var buf: [4096]u8 = undefined;
                const count = c.read(self.fd, &buf, buf.len);
                if (count < 0) {
                    if (posix.errno(count) == .INTR) continue;
                    if (posix.errno(count) == .AGAIN or posix.errno(count) == .TIMEDOUT) return;
                    self.poison(.transport_read_failure);
                    return error.ConnectionClosed;
                }
                if (count == 0) {
                    self.poison(if (self.parser.bufferedBytes() == 0) .connection_eof else .frame_malformed);
                    return if (self.parser.bufferedBytes() == 0) error.ConnectionClosed else error.ProtocolError;
                }
                self.parser.push(buf[0..@intCast(count)]) catch {
                    self.poison(.local_resource_exhausted);
                    return error.OutOfMemory;
                };
                continue;
            };
            if (try self.bufferOutOfBandFrame(frame, null, null, false)) continue;
            frame.deinit(self.allocator);
            self.poison(.peer_contract_violation);
            return error.ProtocolError;
        }
    }

    /// ID-only inventory를 한 authority generation 아래 끝까지 모은다. 중간 page가 stale/error면 이미 모은 prefix를
    /// 절대 반환하지 않고 typed unavailable로 강등한다. Recovery projection의 malformed response는 canonical exact
    /// manifest attach가 같은 adapter에서 계속 가능하도록 connection 전체를 poison하지 않는다.
    pub fn runtimeInventory(self: *Client) ClientError!RuntimeInventory {
        const operation_fence_held = try self.requireBlockingMode();
        defer if (operation_fence_held) self.endPublicMutation();
        var consumed: u8 = 0;
        return self.runtimeInventoryBounded(protocol.max_inventory_pages, &consumed);
    }

    /// shutdown barrier는 connection별 상대 timeout을 만들지 않고 모든 inventory page가 같은 절대 deadline을
    /// 소비한다. 어느 page라도 write 뒤 불확실해지면 앞 page prefix를 membership 증거로 반환하지 않는다.
    pub fn runtimeInventoryUntil(
        self: *Client,
        deadline: client_deadline.AbsoluteDeadline,
    ) DeadlineRuntimeInventoryExecution {
        if (deadline.remainingNs() <= 0) return .{ .not_executed = error.DeadlineExceeded };
        const operation_fence_held = self.requireBlockingMode() catch |err|
            return .{ .not_executed = switch (err) {
                error.AdminBusy => error.AdminBusy,
                else => error.ConnectionClosed,
            } };
        defer if (operation_fence_held) self.endPublicMutation();
        if (!self.runtime_inventory_v1) return .{ .inventory = .{ .unavailable = .{
            .reason = .unsupported,
            .page_count = 0,
        } } };
        var ids: std.ArrayListUnmanaged(u128) = .empty;
        errdefer ids.deinit(self.allocator);
        var cursor: []const u8 = "";
        var cursor_buf: [32]u8 = undefined;
        var generation: u64 = 0;
        var expected_total: ?usize = null;
        var page_count: usize = 0;

        while (true) {
            page_count += 1;
            if (page_count > protocol.max_inventory_pages) {
                ids.deinit(self.allocator);
                return .{ .inventory = .{ .unavailable = .{
                    .reason = .malformed,
                    .page_count = @intCast(page_count - 1),
                } } };
            }
            var params: std.Io.Writer.Allocating = .init(self.allocator);
            defer params.deinit();
            var js: std.json.Stringify = .{ .writer = &params.writer, .options = .{} };
            js.write(.{
                .cursor = cursor,
                .limit = @as(u16, @intCast(protocol.max_inventory_page_runtimes)),
                .membership_generation = generation,
            }) catch {
                ids.deinit(self.allocator);
                return .{ .not_executed = error.OutOfMemory };
            };
            var storage: PreparedBlockingRpcStorage = .{};
            _ = self.prepareBlockingRpcStorage(&storage, "runtime.inventory", params.written()) catch |err| {
                ids.deinit(self.allocator);
                return .{ .not_executed = err };
            };
            const execution = self.executePreparedBlockingRpcStorageUntil(&storage, self.allocator, deadline);
            const response = switch (execution) {
                .accepted => |accepted| accepted,
                .not_executed => |err| {
                    self.abortPreparedBlockingRpcStorage(&storage) catch {};
                    ids.deinit(self.allocator);
                    return .{ .not_executed = err };
                },
                .uncertain => |err| {
                    ids.deinit(self.allocator);
                    return .{ .uncertain = err };
                },
            };
            defer response.payload_allocator.free(response.payload);
            if (parseInventoryError(response.payload)) |code| {
                ids.deinit(self.allocator);
                return .{ .inventory = .{ .unavailable = .{
                    .reason = inventoryUnavailableFor(code),
                    .page_count = @intCast(page_count),
                } } };
            }
            const page = parseInventoryPage(self.allocator, response.payload) catch |err| {
                ids.deinit(self.allocator);
                return switch (err) {
                    error.OutOfMemory => .{ .not_executed = error.OutOfMemory },
                    error.Malformed => .{ .inventory = .{ .unavailable = .{
                        .reason = .malformed,
                        .page_count = @intCast(page_count),
                    } } },
                };
            };
            defer page.deinit(self.allocator);
            if (page.upgrade_epoch != self.upgrade_epoch or page.authority_generation != self.authority_generation) {
                ids.deinit(self.allocator);
                return .{ .inventory = .{ .unavailable = .{
                    .reason = .authority_changed,
                    .page_count = @intCast(page_count),
                } } };
            }
            if (generation == 0) {
                generation = page.membership_generation;
                expected_total = page.total;
            } else if (page.membership_generation != generation or page.total != expected_total.?) {
                ids.deinit(self.allocator);
                return .{ .inventory = .{ .unavailable = .{
                    .reason = .malformed,
                    .page_count = @intCast(page_count),
                } } };
            }
            if (!std.mem.eql(u8, page.cursor, cursor) or ids.items.len + page.runtime_ids.len > page.total or
                (ids.items.len != 0 and page.runtime_ids.len != 0 and ids.items[ids.items.len - 1] >= page.runtime_ids[0]))
            {
                ids.deinit(self.allocator);
                return .{ .inventory = .{ .unavailable = .{
                    .reason = .malformed,
                    .page_count = @intCast(page_count),
                } } };
            }
            ids.appendSlice(self.allocator, page.runtime_ids) catch {
                ids.deinit(self.allocator);
                return .{ .not_executed = error.OutOfMemory };
            };
            if (page.done) {
                if (page.next_cursor.len != 0 or ids.items.len != page.total) {
                    ids.deinit(self.allocator);
                    return .{ .inventory = .{ .unavailable = .{
                        .reason = .malformed,
                        .page_count = @intCast(page_count),
                    } } };
                }
                return .{ .inventory = .{ .complete = .{
                    .membership_generation = generation,
                    .upgrade_epoch = page.upgrade_epoch,
                    .authority_generation = page.authority_generation,
                    .page_count = @intCast(page_count),
                    .runtime_ids = ids.toOwnedSlice(self.allocator) catch {
                        ids.deinit(self.allocator);
                        return .{ .not_executed = error.OutOfMemory };
                    },
                } } };
            }
            if (page.runtime_ids.len != protocol.max_inventory_page_runtimes or ids.items.len >= page.total or
                page.runtime_ids[page.runtime_ids.len - 1] != (parseExactInventoryId(page.next_cursor) orelse {
                    ids.deinit(self.allocator);
                    return .{ .inventory = .{ .unavailable = .{
                        .reason = .malformed,
                        .page_count = @intCast(page_count),
                    } } };
                }))
            {
                ids.deinit(self.allocator);
                return .{ .inventory = .{ .unavailable = .{
                    .reason = .malformed,
                    .page_count = @intCast(page_count),
                } } };
            }
            @memcpy(&cursor_buf, page.next_cursor);
            cursor = &cursor_buf;
        }
    }

    pub fn runtimeInventoryBounded(
        self: *Client,
        max_pages: usize,
        consumed: *u8,
    ) ClientError!RuntimeInventory {
        const operation_fence_held = try self.requireBlockingMode();
        defer if (operation_fence_held) self.endPublicMutation();
        consumed.* = 0;
        if (!self.runtime_inventory_v1) return .{ .unavailable = .{ .reason = .unsupported, .page_count = 0 } };
        var ids: std.ArrayListUnmanaged(u128) = .empty;
        errdefer ids.deinit(self.allocator);
        var cursor: []const u8 = "";
        var cursor_buf: [32]u8 = undefined;
        var generation: u64 = 0;
        var expected_total: ?usize = null;
        var page_count: usize = 0;

        while (true) {
            page_count += 1;
            if (page_count > protocol.max_inventory_pages or page_count > max_pages) {
                ids.deinit(self.allocator);
                return .{ .unavailable = .{
                    .reason = if (page_count > max_pages) .cap_exceeded else .malformed,
                    .page_count = @intCast(page_count - 1),
                } };
            }
            consumed.* = @intCast(page_count);
            var params: std.Io.Writer.Allocating = .init(self.allocator);
            defer params.deinit();
            var js: std.json.Stringify = .{ .writer = &params.writer, .options = .{} };
            js.write(.{
                .cursor = cursor,
                .limit = @as(u16, @intCast(protocol.max_inventory_page_runtimes)),
                .membership_generation = generation,
            }) catch return error.OutOfMemory;
            const response = try self.call("runtime.inventory", params.written());
            defer self.allocator.free(response);
            if (parseInventoryError(response)) |code| {
                ids.deinit(self.allocator);
                return .{ .unavailable = .{
                    .reason = inventoryUnavailableFor(code),
                    .page_count = @intCast(page_count),
                } };
            }

            const page = parseInventoryPage(self.allocator, response) catch |err| switch (err) {
                error.OutOfMemory => return error.OutOfMemory,
                error.Malformed => {
                    ids.deinit(self.allocator);
                    return .{ .unavailable = .{ .reason = .malformed, .page_count = @intCast(page_count) } };
                },
            };
            defer page.deinit(self.allocator);
            if (page.upgrade_epoch != self.upgrade_epoch or
                page.authority_generation != self.authority_generation)
            {
                ids.deinit(self.allocator);
                return .{ .unavailable = .{ .reason = .authority_changed, .page_count = @intCast(page_count) } };
            }
            if (generation == 0) {
                generation = page.membership_generation;
                expected_total = page.total;
            } else if (page.membership_generation != generation or page.total != expected_total.?) {
                ids.deinit(self.allocator);
                return .{ .unavailable = .{ .reason = .malformed, .page_count = @intCast(page_count) } };
            }
            if (!std.mem.eql(u8, page.cursor, cursor) or ids.items.len + page.runtime_ids.len > page.total) {
                ids.deinit(self.allocator);
                return .{ .unavailable = .{ .reason = .malformed, .page_count = @intCast(page_count) } };
            }
            if (ids.items.len != 0 and page.runtime_ids.len != 0 and
                ids.items[ids.items.len - 1] >= page.runtime_ids[0])
            {
                ids.deinit(self.allocator);
                return .{ .unavailable = .{ .reason = .malformed, .page_count = @intCast(page_count) } };
            }
            ids.appendSlice(self.allocator, page.runtime_ids) catch return error.OutOfMemory;
            if (page.done) {
                if (page.next_cursor.len != 0 or ids.items.len != page.total) {
                    ids.deinit(self.allocator);
                    return .{ .unavailable = .{ .reason = .malformed, .page_count = @intCast(page_count) } };
                }
                return .{ .complete = .{
                    .membership_generation = generation,
                    .upgrade_epoch = page.upgrade_epoch,
                    .authority_generation = page.authority_generation,
                    .page_count = @intCast(page_count),
                    .runtime_ids = ids.toOwnedSlice(self.allocator) catch return error.OutOfMemory,
                } };
            }
            if (page.runtime_ids.len != protocol.max_inventory_page_runtimes or
                ids.items.len >= page.total or
                page.runtime_ids[page.runtime_ids.len - 1] != (parseExactInventoryId(page.next_cursor) orelse {
                    ids.deinit(self.allocator);
                    return .{ .unavailable = .{ .reason = .malformed, .page_count = @intCast(page_count) } };
                }))
            {
                ids.deinit(self.allocator);
                return .{ .unavailable = .{ .reason = .malformed, .page_count = @intCast(page_count) } };
            }
            @memcpy(&cursor_buf, page.next_cursor);
            cursor = &cursor_buf;
        }
    }

    pub const PrepareUpgradeOutcome = union(enum) {
        /// Host가 accepted response를 전량 보낸 뒤 이 connection을 닫는다. 이후 status/attach는 새 connection이어야 한다.
        accepted_reconnect_required,
        completed: upgrade_wire.AttemptReport,
        rejected,
    };

    pub fn prepareUpgrade(self: *Client, request: upgrade_wire.PrepareRequest) ClientError!PrepareUpgradeOutcome {
        const operation_fence_held = try self.requireBlockingMode();
        defer if (operation_fence_held) self.endPublicMutation();
        if (!self.host_exec_upgrade_v1) return error.IncompatibleVersion;
        var out: std.Io.Writer.Allocating = .init(self.allocator);
        defer out.deinit();
        var js: std.json.Stringify = .{ .writer = &out.writer, .options = .{} };
        var attempt_buf: [32]u8 = undefined;
        const attempt = std.fmt.bufPrint(&attempt_buf, "{x:0>32}", .{request.attempt_id}) catch
            return error.ProtocolError;
        const sha = std.fmt.bytesToHex(request.target_sha256, .lower);
        js.write(.{
            .attempt_id = attempt,
            .target_path = request.target_path,
            .target_build_id = request.target_build_id,
            .target_sha256 = &sha,
            .handoff_reader_min = request.handoff_reader_min,
            .handoff_reader_max = request.handoff_reader_max,
        }) catch return error.OutOfMemory;
        const response = try self.call("host.upgrade.prepare", out.written());
        defer self.allocator.free(response);
        return switch (parsePrepareUpgradeResponse(response, request.attempt_id)) {
            .accepted => {
                self.poison(.planned_upgrade_reconnect);
                return .accepted_reconnect_required;
            },
            .completed => |report| .{ .completed = report },
            .rejected => .rejected,
            .malformed => {
                self.poison(.peer_contract_violation);
                return error.ProtocolError;
            },
        };
    }

    pub fn upgradeStatus(self: *Client, attempt_id: u128) ClientError!?upgrade_wire.AttemptReport {
        const operation_fence_held = try self.requireBlockingMode();
        defer if (operation_fence_held) self.endPublicMutation();
        var attempt_buf: [32]u8 = undefined;
        const attempt = std.fmt.bufPrint(&attempt_buf, "{x:0>32}", .{attempt_id}) catch
            return error.ProtocolError;
        var out: std.Io.Writer.Allocating = .init(self.allocator);
        defer out.deinit();
        var js: std.json.Stringify = .{ .writer = &out.writer, .options = .{} };
        js.write(.{ .attempt_id = attempt }) catch return error.OutOfMemory;
        const response = try self.call("host.upgrade.status", out.written());
        defer self.allocator.free(response);
        if (parseAttemptStatus(response)) |report| return report;
        if (responseHasTypedError(response)) return null;
        self.poison(.peer_contract_violation);
        return error.ProtocolError;
    }

    /// attach 직후 host가 보내는 `snapshot_chunk` stream을 `end_stream`까지 읽어 record 바이트를 이어 돌려준다(§10 attach
    /// 순서: response → snapshot_chunk*). 반환 바이트는 caller 소유(screen_stream.RecordStream으로 순회). **attach 응답을
    /// 받은 뒤 다음 request 전에 반드시 이걸로 stream을 비운다** — 안 그러면 leftover chunk가 다음 응답으로 오독된다.
    const StreamIo = union(enum) {
        polling,
        deadline: struct {
            absolute: client_deadline.AbsoluteDeadline,
            ops: client_deadline.Ops,
        },
    };

    pub fn readSnapshot(self: *Client, stream_id: u64) ClientError![]u8 {
        return self.readSnapshotWithIo(stream_id, .polling) catch |err| switch (err) {
            error.DeadlineExceeded => unreachable,
            else => |client_err| client_err,
        };
    }

    pub fn readSnapshotUntil(
        self: *Client,
        stream_id: u64,
        deadline: client_deadline.AbsoluteDeadline,
    ) DeadlineClientError![]u8 {
        return self.readSnapshotUntilWithOps(
            stream_id,
            deadline,
            client_deadline.posix_ops,
        );
    }

    fn readSnapshotUntilWithOps(
        self: *Client,
        stream_id: u64,
        deadline: client_deadline.AbsoluteDeadline,
        ops: client_deadline.Ops,
    ) DeadlineClientError![]u8 {
        const operation_fence_held = try self.requireBlockingMode();
        defer if (operation_fence_held) self.endPublicMutation();
        const saved_flags = ops.get_flags(ops.context, self.fd) orelse {
            self.poisonWithOps(.local_invariant_violation, ops);
            return error.ConnectionClosed;
        };
        const nonblocking: c_int = @bitCast(posix.O{ .NONBLOCK = true });
        if (!ops.set_flags(ops.context, self.fd, saved_flags | nonblocking)) {
            self.poisonWithOps(.local_invariant_violation, ops);
            return error.ConnectionClosed;
        }
        const bytes = self.readSnapshotWithIo(
            stream_id,
            .{ .deadline = .{ .absolute = deadline, .ops = ops } },
        ) catch |err| {
            self.poisonWithOps(.response_correlation_lost, ops);
            return err;
        };
        if (!ops.set_flags(ops.context, self.fd, saved_flags)) {
            self.allocator.free(bytes);
            self.poisonWithOps(.local_invariant_violation, ops);
            return error.ConnectionClosed;
        }
        if (deadline.remainingNs() <= 0) {
            self.allocator.free(bytes);
            self.poisonWithOps(.response_correlation_lost, ops);
            return error.DeadlineExceeded;
        }
        return bytes;
    }

    fn readSnapshotWithIo(
        self: *Client,
        stream_id: u64,
        io: StreamIo,
    ) DeadlineClientError![]u8 {
        const operation_fence_held = try self.requireBlockingMode();
        defer if (operation_fence_held) self.endPublicMutation();
        var attempts: usize = 0;
        while (true) {
            if (try self.readStreamBatchWithIo(stream_id, io)) |batch| {
                if (!batch.is_snapshot) {
                    batch.deinit();
                    self.poison(.peer_contract_violation);
                    return error.ProtocolError;
                }
                if (deadlineExpired(io)) {
                    batch.deinit();
                    return error.DeadlineExceeded;
                }
                return batch.bytes;
            }
            switch (io) {
                .deadline => return error.DeadlineExceeded,
                .polling => {
                    if (attempts >= 249) {
                        self.poison(.read_timeout);
                        return error.ConnectionClosed;
                    }
                    attempts += 1;
                    _ = usleepMs(20);
                },
            }
        }
    }

    /// `want_stream_id`의 다음 **화면 stream 배치**를 논블로킹으로 돌려준다(caller가 batch를 `deinit()`). 여러 원격 runtime이 이
    /// connection 하나를 공유하므로 소켓엔 여러 stream의 배치가 섞여 온다 — 이 함수가 **stream_id로 demux**한다: 버퍼(§멀티
    /// runtime `pending_batches`)에 내 배치가 있으면 그걸 먼저(도착 순서), 없으면 소켓에서 완성 배치를 읽되 **다른 stream의
    /// 것이면 버리지 않고 버퍼에 넣고 계속** 읽어 내 배치를 찾는다. 소켓이 idle이면(내 배치 없음) `null`(그 사이 읽힌 남의 배치는
    /// 버퍼에 남아 그 runtime의 pump가 소비). 예전엔 pumpDelta가 남의 배치를 free해 두 번째 이후 터미널 화면이 영구 유실됐다
    /// (code-review #1). delta/snapshot 둘 다 받아 `is_snapshot`으로 리셋/증분을 가른다. `call`이 버퍼한 frame을 소켓보다 먼저 쓴다.
    pub fn readStreamBatch(self: *Client, want_stream_id: u64) ClientError!?StreamBatch {
        return self.readStreamBatchWithIo(want_stream_id, .polling) catch |err| switch (err) {
            error.DeadlineExceeded => unreachable,
            else => |client_err| client_err,
        };
    }

    const GenerationTransferSource = enum { pending, direct };

    pub const PreparedGenerationAccountingConsume = struct {
        client_addr: usize,
        transfer_id: u64,
        byte_count: usize,
        ledger_slot: u16,
    };

    fn reserveGenerationTransfer(
        self: *Client,
        byte_count: usize,
        source: GenerationTransferSource,
        transfer_id: u64,
    ) (ClientError || generation_batch_registry.Error)!generation_batch_registry.AccountingReceipt {
        if (!self.generation_batch_accounting.valid(@intFromPtr(self))) return error.InvalidState;
        if (byte_count == 0) return error.InvalidDescriptor;
        const accounting = &self.generation_batch_accounting;
        const ledger = accounting.ledger orelse return error.InvalidState;
        const total_items = self.pending_batches.items.len +| ledger.item_count;
        if ((source == .direct and total_items >= protocol.max_client_screen_items) or
            (source == .pending and total_items > protocol.max_client_screen_items))
            return error.EventQueueFull;
        if (source == .direct and
            self.screenInboxBytes() +| byte_count > protocol.max_client_screen_inbox)
            return error.EventQueueFull;
        if (ledger.item_count == generation_batch_registry.max_entries)
            return error.CapacityExhausted;
        if (transfer_id == 0 or transfer_id <= accounting.last_transfer_id)
            return error.InvalidIdentity;
        const next_bytes = std.math.add(usize, ledger.byte_count, byte_count) catch
            return error.InvalidState;
        if (next_bytes > protocol.max_client_screen_inbox) return error.EventQueueFull;

        try ledger.reserve(transfer_id, byte_count);
        // 검증 뒤에는 allocation/callback 없이 charge를 먼저 publish한다. direct parser의 마지막 frame
        // payload free가 allocator callback을 재진입시켜도 resident cap이 낮아 보이는 순간이 없다.
        accounting.last_transfer_id = transfer_id;
        return .{
            .client_addr = @intFromPtr(self),
            .transfer_id = transfer_id,
            .byte_count = byte_count,
        };
    }

    pub fn prepareGenerationAccountingConsume(
        self: *Client,
        receipt: generation_batch_registry.AccountingReceipt,
    ) generation_batch_registry.Error!PreparedGenerationAccountingConsume {
        if (!self.generation_batch_accounting.valid(@intFromPtr(self)) or
            receipt.client_addr != @intFromPtr(self) or
            receipt.transfer_id == 0 or receipt.byte_count == 0)
            return error.InvalidDescriptor;
        if (receipt.transfer_id > self.generation_batch_accounting.last_transfer_id)
            return error.InvalidDescriptor;
        const ledger = self.generation_batch_accounting.ledger.?;
        if (ledger.item_count == 0 or ledger.byte_count < receipt.byte_count or
            ledger.releasing_item_count == ledger.item_count or
            ledger.releasing_byte_count +| receipt.byte_count > ledger.byte_count)
            return error.InvalidState;
        const exact = try ledger.prepareConsume(receipt);
        return .{
            .client_addr = receipt.client_addr,
            .transfer_id = receipt.transfer_id,
            .byte_count = receipt.byte_count,
            .ledger_slot = exact.ledger_slot,
        };
    }

    pub fn consumeGenerationAccountingUnchecked(
        self: *Client,
        prepared: PreparedGenerationAccountingConsume,
    ) void {
        // 모든 identity/counter 검증과 releasing reservation은 allocator callback 전에 끝났다.
        // 이 suffix는 callback을 다시 부르거나 상태를 재검증하지 않고 예약된 scalar만 tombstone한다.
        self.generation_batch_accounting.ledger.?.consumeUnchecked(.{
            .ledger_slot = prepared.ledger_slot,
            .transfer_id = prepared.transfer_id,
            .byte_count = prepared.byte_count,
        });
    }

    pub const GenerationBatchReadResult = enum { committed, idle, terminal };

    /// Generation GUI 전용 closed take. 성공 시 payload owner와 resident charge를 `out`으로 함께
    /// 옮기며, caller는 node registry에 이를 무할당 publish한다.
    pub fn readGenerationBatch(
        self: *Client,
        out: *generation_batch_registry.OwnedBatch,
        want_stream_id: u64,
        transfer_id: u64,
    ) (ClientError || generation_batch_registry.Error)!GenerationBatchReadResult {
        const operation_fence_held = try self.requireBlockingMode();
        defer if (operation_fence_held) self.endPublicMutation();
        if (checkedAllocatorReentry(self)) return error.AdminBusy;
        if (self.unusable) return .terminal;
        if (want_stream_id == 0) return error.InvalidStream;
        if (transfer_id == 0 or transfer_id <= self.generation_batch_accounting.last_transfer_id)
            return error.InvalidIdentity;
        if (!out.pristine()) return error.DestinationOccupied;

        // Buffered owner는 charge publication 뒤 allocation/callback 없는 suffix에서 queue를 tombstone한다.
        for (self.pending_batches.items, 0..) |batch, index| {
            if (batch.stream_id != want_stream_id) continue;
            const receipt = try self.reserveGenerationTransfer(batch.bytes.len, .pending, transfer_id);
            const owned = self.pending_batches.orderedRemove(index);
            self.pending_batch_bytes -= owned.bytes.len;
            generation_batch_registry.OwnedBatch.initTransferredUnchecked(
                out,
                owned.is_snapshot,
                owned.stream_id,
                owned.bytes,
                owned.allocator,
                receipt,
            );
            return .committed;
        }

        while (true) {
            const maybe_batch = self.readOneBatchWithIo(.polling, .{
                .stream_id = want_stream_id,
                .transfer_id = transfer_id,
                .out = out,
            }, .public) catch |err| switch (err) {
                error.ConnectionClosed => return .terminal,
                error.DeadlineExceeded => unreachable,
                else => |typed| return typed,
            };
            if (!out.pristine()) return .committed;
            const batch = maybe_batch orelse return .idle;
            try self.bufferPendingScreenBatch(batch);
        }
    }

    fn readStreamBatchWithIo(
        self: *Client,
        want_stream_id: u64,
        io: StreamIo,
    ) DeadlineClientError!?StreamBatch {
        const operation_fence_held = try self.requireBlockingMode();
        defer if (operation_fence_held) self.endPublicMutation();
        // 1) 이 stream 앞으로 이미 버퍼된 배치(다른 runtime의 pump가 소켓을 비우며 넣어 둔 것)를 도착 순서대로 먼저 준다.
        for (self.pending_batches.items, 0..) |b, i| {
            if (b.stream_id == want_stream_id) {
                const owned = self.pending_batches.orderedRemove(i);
                self.pending_batch_bytes -= owned.bytes.len;
                if (deadlineExpired(io)) {
                    owned.deinit();
                    return error.DeadlineExceeded;
                }
                return owned;
            }
        }
        // 2) 소켓에서 완성 배치를 읽는다. 내 것이면 반환, 남의 것이면 버퍼하고 계속(내 것/idle까지).
        while (true) {
            const batch = (self.readOneBatchWithIo(io, null, .public) catch |err| switch (err) {
                error.CapacityExhausted,
                error.DestinationOccupied,
                error.IdentityExhausted,
                error.InvalidDescriptor,
                error.InvalidIdentity,
                error.InvalidReservation,
                error.InvalidState,
                error.InvalidStream,
                error.MovedOrCopied,
                => unreachable,
                else => |typed| return typed,
            }) orelse return null; // idle — 내 배치 없음.
            if (batch.stream_id == want_stream_id) {
                if (deadlineExpired(io)) {
                    batch.deinit();
                    return error.DeadlineExceeded;
                }
                return batch;
            }
            // 남의 stream 배치 — 그 runtime pump가 소비하도록 canonical inbox에 보존한다.
            try self.bufferPendingScreenBatch(batch);
        }
    }

    fn bufferPendingScreenBatch(self: *Client, batch: StreamBatch) ClientError!void {
        const ledger_items = if (self.generation_batch_accounting.ledger) |ledger|
            ledger.item_count
        else
            0;
        if (self.pending_batches.items.len +| ledger_items >= protocol.max_client_screen_items or
            self.screenInboxBytes() +| batch.bytes.len > protocol.max_client_screen_inbox)
        {
            batch.deinit();
            self.poison(.event_queue_overflow);
            return error.EventQueueFull;
        }
        self.pending_batches.append(self.allocator, batch) catch {
            batch.deinit();
            self.poison(.local_resource_exhausted);
            return error.OutOfMemory;
        };
        self.pending_batch_bytes += batch.bytes.len;
    }

    /// 소켓/`pending_stream`에서 완성 stream 배치 하나를 `end_stream`까지 읽어 돌려준다(stream_id 무관). **논블로킹**: 배치가
    /// 아직 없으면 `null`(recv timeout을 세션 종료로 오인 안 함, §9). host는 grid/alt 변화 시 delta 대신 fresh snapshot을 push한다
    /// (SnapshotRequired). demux는 상위 `readStreamBatch`가 한다 — 여기선 순수하게 "다음 배치 하나".
    fn readOneBatch(self: *Client) ClientError!?StreamBatch {
        return self.readOneBatchWithIo(.polling, null, .public) catch |err| switch (err) {
            error.DeadlineExceeded => unreachable,
            error.CapacityExhausted,
            error.DestinationOccupied,
            error.IdentityExhausted,
            error.InvalidDescriptor,
            error.InvalidIdentity,
            error.InvalidReservation,
            error.InvalidState,
            error.InvalidStream,
            error.MovedOrCopied,
            => unreachable,
            else => |client_err| client_err,
        };
    }

    const GenerationReadDestination = struct {
        stream_id: u64,
        transfer_id: u64,
        out: *generation_batch_registry.OwnedBatch,
    };

    const StreamFenceMode = enum { public, registered_execution };

    fn readOneBatchWithIo(
        self: *Client,
        io: StreamIo,
        generation: ?GenerationReadDestination,
        fence_mode: StreamFenceMode,
    ) (DeadlineClientError || generation_batch_registry.Error)!?StreamBatch {
        if (generation) |destination| {
            if (destination.stream_id == 0) return error.InvalidStream;
            if (destination.transfer_id == 0) return error.InvalidIdentity;
            if (!destination.out.pristine()) return error.DestinationOccupied;
        }
        const allocator = self.allocator;
        var state = self.partial_batch orelse PartialBatch{
            .stream_id = 0,
            .is_snapshot = false,
        };
        self.partial_batch = null;
        errdefer state.bytes.deinit(allocator);
        var started = state.stream_id != 0;
        while (true) {
            var actual_payload_allocator = allocator;
            const frame = (try self.nextStreamFrameWithIo(
                started,
                io,
                &actual_payload_allocator,
                fence_mode,
            )) orelse {
                if (started) {
                    self.partial_batch = state;
                    return null;
                }
                state.bytes.deinit(allocator);
                return null;
            };
            if (!std.meta.eql(actual_payload_allocator, allocator) or
                !std.meta.eql(self.allocator, allocator) or
                !self.parser.usesAllocator(allocator))
            {
                frame.deinit(actual_payload_allocator);
                self.poison(.local_invariant_violation);
                return error.InvalidState;
            }
            if (frame.header.kind == .event) {
                if (started or frame.header.request_id != 0 or frame.header.flags != 0) {
                    frame.deinit(allocator);
                    self.poison(.frame_malformed);
                    return error.ProtocolError;
                }
                try self.bufferCanonicalEvent(frame);
                continue;
            }
            var frame_live = true;
            defer if (frame_live) frame.deinit(allocator);
            if (frame.header.kind == .screen_frontier_barrier) {
                if (started) {
                    self.poison(.peer_contract_violation);
                    return error.ProtocolError;
                }
                // `bufferCatchupBarrierFrame` consumes the frame payload on every outcome,
                // including append OOM and malformed/duplicate rejection.
                frame_live = false;
                try self.bufferCatchupBarrierFrame(frame, allocator, false);
                // A barrier is a terminal marker for a catch-up owner, not an empty screen
                // batch. Return to the typed consumer so it can validate the exact identity.
                return null;
            }
            if (frame.header.kind != .snapshot_chunk and frame.header.kind != .delta_chunk) {
                self.poison(.peer_contract_violation);
                return error.ProtocolError;
            }
            if (frame.header.request_id != 0) {
                self.poison(.response_correlation_lost);
                return error.ProtocolError;
            }
            if (!started) {
                if (frame.header.stream_id == 0) {
                    self.poison(.peer_contract_violation);
                    return error.ProtocolError;
                }
                state.stream_id = frame.header.stream_id;
                state.is_snapshot = frame.header.kind == .snapshot_chunk;
                started = true;
            } else if (frame.header.stream_id != state.stream_id or
                (frame.header.kind == .snapshot_chunk) != state.is_snapshot)
            {
                self.poison(.peer_contract_violation);
                return error.ProtocolError;
            }
            if (frame.header.flags & ~protocol.Flags.end_stream != 0 or
                state.chunk_count >= protocol.max_viewport_snapshot / protocol.max_binary_chunk or
                state.bytes.items.len +| frame.payload.len > protocol.max_viewport_snapshot or
                self.screenInboxBytes() +| state.bytes.items.len +| frame.payload.len >
                    protocol.max_client_screen_inbox)
            {
                self.poison(.frame_malformed);
                return error.ProtocolError;
            }
            state.chunk_count += 1;
            const next_len = state.bytes.items.len + frame.payload.len;
            state.bytes.ensureTotalCapacityPrecise(allocator, next_len) catch {
                self.poison(.local_resource_exhausted);
                return error.OutOfMemory;
            };
            state.bytes.appendSliceAssumeCapacity(frame.payload);
            if (protocol.Flags.hasEndStream(frame.header.flags)) {
                if (!std.meta.eql(allocator, self.allocator)) {
                    self.poison(.local_invariant_violation);
                    return error.InvalidState;
                }
                if (generation) |destination| if (state.stream_id == destination.stream_id) {
                    const receipt = self.reserveGenerationTransfer(
                        state.bytes.items.len,
                        .direct,
                        destination.transfer_id,
                    ) catch |err| {
                        self.poison(switch (err) {
                            error.EventQueueFull, error.CapacityExhausted => .event_queue_overflow,
                            error.OutOfMemory => .local_resource_exhausted,
                            else => .local_invariant_violation,
                        });
                        return err;
                    };
                    const bytes = state.bytes.toOwnedSlice(allocator) catch {
                        // Charge를 유지한 채 backing free callback을 먼저 끝내고, 그 뒤 no-fail accounting
                        // suffix를 실행한다. OOM cleanup 재진입도 resident cap을 우회하지 못한다.
                        const prepared = self.prepareGenerationAccountingConsume(receipt) catch
                            @panic("generation accounting receipt drifted during direct rollback");
                        state.bytes.deinit(allocator);
                        state.bytes = .empty;
                        self.consumeGenerationAccountingUnchecked(prepared);
                        self.poison(.local_resource_exhausted);
                        return error.OutOfMemory;
                    };
                    frame.deinit(allocator);
                    frame_live = false;
                    if (!std.meta.eql(allocator, self.allocator)) {
                        const prepared = self.prepareGenerationAccountingConsume(receipt) catch
                            @panic("generation accounting receipt drifted after frame cleanup");
                        allocator.free(bytes);
                        self.consumeGenerationAccountingUnchecked(prepared);
                        self.poison(.local_invariant_violation);
                        return error.InvalidState;
                    }
                    generation_batch_registry.OwnedBatch.initTransferredUnchecked(
                        destination.out,
                        state.is_snapshot,
                        state.stream_id,
                        bytes,
                        allocator,
                        receipt,
                    );
                    return null;
                };
                const bytes = state.bytes.toOwnedSlice(allocator) catch {
                    self.poison(.local_resource_exhausted);
                    return error.OutOfMemory;
                };
                frame.deinit(allocator);
                frame_live = false;
                if (!std.meta.eql(allocator, self.allocator)) {
                    allocator.free(bytes);
                    self.poison(.local_invariant_violation);
                    return error.InvalidState;
                }
                return .{
                    .is_snapshot = state.is_snapshot,
                    .stream_id = state.stream_id,
                    .bytes = bytes,
                    .allocator = allocator,
                };
            }
        }
    }

    /// CR4 candidate가 요청한 exact barrier를 기존 multi-stream demux 아래에서 기다린다.
    /// 선행 screen batch는 target/sibling 구분 없이 canonical pending batch inbox에 보존하며,
    /// socket idle은 성공으로 바꾸지 않고 하나의 absolute deadline을 끝까지 소비한다.
    pub fn readCatchupBarrierUntil(
        self: *Client,
        stream_id: u64,
        expected: catchup_barrier_contract.CatchupIdentity,
        deadline: client_deadline.AbsoluteDeadline,
    ) DeadlineClientError!catchup_barrier_contract.Barrier {
        return (try self.readCatchupBarrierPlanUntilWithOps(
            stream_id,
            expected,
            deadline,
            client_deadline.posix_ops,
        )).barrier;
    }

    pub const CatchupBarrierPlan = struct {
        barrier: catchup_barrier_contract.Barrier,
        preceding_screen_batches: u32,
    };

    pub fn readCatchupBarrierPlanUntil(
        self: *Client,
        stream_id: u64,
        expected: catchup_barrier_contract.CatchupIdentity,
        deadline: client_deadline.AbsoluteDeadline,
    ) DeadlineClientError!CatchupBarrierPlan {
        return self.readCatchupBarrierPlanUntilWithOps(
            stream_id,
            expected,
            deadline,
            client_deadline.posix_ops,
        );
    }

    fn readCatchupBarrierUntilWithOps(
        self: *Client,
        stream_id: u64,
        expected: catchup_barrier_contract.CatchupIdentity,
        deadline: client_deadline.AbsoluteDeadline,
        ops: client_deadline.Ops,
    ) DeadlineClientError!catchup_barrier_contract.Barrier {
        return (try self.readCatchupBarrierPlanUntilWithOps(
            stream_id,
            expected,
            deadline,
            ops,
        )).barrier;
    }

    fn readCatchupBarrierPlanUntilWithOps(
        self: *Client,
        stream_id: u64,
        expected: catchup_barrier_contract.CatchupIdentity,
        deadline: client_deadline.AbsoluteDeadline,
        ops: client_deadline.Ops,
    ) DeadlineClientError!CatchupBarrierPlan {
        const operation_fence_held = try self.requireBlockingMode();
        defer if (operation_fence_held) self.endPublicMutation();
        if (!self.runtime_catchup_barrier_v1) {
            self.poison(.peer_contract_violation);
            return error.ProtocolError;
        }
        if (stream_id == 0 or !expected.valid()) return error.ProtocolError;
        const saved_flags = ops.get_flags(ops.context, self.fd) orelse {
            self.poisonWithOps(.local_invariant_violation, ops);
            return error.ConnectionClosed;
        };
        const nonblocking: c_int = @bitCast(posix.O{ .NONBLOCK = true });
        if (!ops.set_flags(ops.context, self.fd, saved_flags | nonblocking)) {
            self.poisonWithOps(.local_invariant_violation, ops);
            return error.ConnectionClosed;
        }
        const plan = self.readCatchupBarrierWithIo(
            stream_id,
            expected,
            deadline,
            ops,
        ) catch |err| {
            if (self.fd >= 0 and !ops.set_flags(ops.context, self.fd, saved_flags)) {
                self.poisonWithOps(.local_invariant_violation, ops);
                return error.ConnectionClosed;
            }
            return err;
        };
        if (!ops.set_flags(ops.context, self.fd, saved_flags)) {
            self.poisonWithOps(.local_invariant_violation, ops);
            return error.ConnectionClosed;
        }
        if (deadline.remainingNs() <= 0) {
            self.poisonWithOps(.read_timeout, ops);
            return error.DeadlineExceeded;
        }
        return plan;
    }

    fn readCatchupBarrierWithIo(
        self: *Client,
        stream_id: u64,
        expected: catchup_barrier_contract.CatchupIdentity,
        deadline: client_deadline.AbsoluteDeadline,
        ops: client_deadline.Ops,
    ) DeadlineClientError!CatchupBarrierPlan {
        const io: StreamIo = .{ .deadline = .{
            .absolute = deadline,
            .ops = ops,
        } };
        while (true) {
            for (self.pending_catchup_barriers.items, 0..) |buffered, index| {
                if (buffered.stream_id != stream_id) continue;
                if (!std.meta.eql(buffered.barrier.identity, expected)) {
                    _ = self.pending_catchup_barriers.orderedRemove(index);
                    self.poison(.peer_contract_violation);
                    return error.ProtocolError;
                }
                if (deadlineExpired(io)) {
                    self.poisonWithOps(.read_timeout, ops);
                    return error.DeadlineExceeded;
                }
                const owned = self.pending_catchup_barriers.orderedRemove(index);
                return .{
                    .barrier = owned.barrier,
                    .preceding_screen_batches = owned.preceding_screen_batches,
                };
            }
            const maybe_batch = self.readOneBatchWithIo(io, null, .public) catch |err| switch (err) {
                error.CapacityExhausted,
                error.DestinationOccupied,
                error.IdentityExhausted,
                error.InvalidDescriptor,
                error.InvalidIdentity,
                error.InvalidReservation,
                error.InvalidState,
                error.InvalidStream,
                error.MovedOrCopied,
                => unreachable,
                else => |typed| return typed,
            };
            if (maybe_batch) |batch| try self.bufferPendingScreenBatch(batch);
            // In deadline mode a true socket idle cannot return null: readSomeUntil either
            // produces bytes or a typed timeout. Null here means a barrier was just buffered.
        }
    }

    /// `stream_id` 앞으로 버퍼된 demux 배치를 모두 버린다(runtime이 detach/remove될 때 그 runtime의 pump가 다신 안 도므로
    /// 잔여 배치가 영구히 쌓이지 않게 — RemoteRuntime.deinit/detachClientSide가 부른다). 없으면 no-op.
    pub fn dropBufferedStream(self: *Client, stream_id: u64) void {
        const operation_fence_held = self.beginPublicMutation() catch return;
        defer if (operation_fence_held) self.endPublicMutation();
        if (checkedAllocatorReentry(self)) return;
        // Validate every GUI event before changing earlier batch/stream owners. A corrupted event
        // must not turn a per-stream drop into a mismatched free or a partially mutated graph.
        if (self.pending_events.items.len != 0 and
            !(self.connection_profile != null and
                self.connection_profile.?.requiresStrictExternalEvents()) and
            !self.validateGenerationEventQueue())
        {
            self.poison(.local_invariant_violation);
            return;
        }
        const event_allocator = if (self.connection_profile != null and
            self.connection_profile.?.requiresStrictExternalEvents())
            self.allocator
        else
            self.canonicalEventAllocator() catch {
                self.poison(.local_invariant_violation);
                return;
            };
        var i: usize = 0;
        while (i < self.pending_batches.items.len) {
            if (self.pending_batches.items[i].stream_id == stream_id) {
                const b = self.pending_batches.orderedRemove(i);
                self.pending_batch_bytes -= b.bytes.len;
                b.deinit();
            } else i += 1;
        }
        if (self.partial_batch) |*partial| {
            if (partial.stream_id == stream_id) {
                partial.bytes.deinit(self.allocator);
                self.partial_batch = null;
            }
        }
        i = 0;
        while (i < self.pending_stream.items.len) {
            if (self.pending_stream.items[i].header.stream_id == stream_id) {
                const frame = self.pending_stream.orderedRemove(i);
                self.pending_stream_bytes -= frame.payload.len;
                frame.deinit(self.allocator);
            } else i += 1;
        }
        i = 0;
        while (i < self.pending_events.items.len) {
            if (self.pending_events.items[i].header.stream_id == stream_id) {
                const frame = self.pending_events.orderedRemove(i);
                self.pending_event_bytes -= frame.payload.len;
                frame.deinit(event_allocator);
            } else i += 1;
        }
        i = 0;
        while (i < self.pending_catchup_barriers.items.len) {
            if (self.pending_catchup_barriers.items[i].stream_id == stream_id) {
                _ = self.pending_catchup_barriers.orderedRemove(i);
            } else i += 1;
        }
    }

    fn screenInboxBytes(self: *const Client) usize {
        const partial = if (self.partial_batch) |batch| batch.bytes.items.len else 0;
        return self.pending_stream_bytes +| self.pending_batch_bytes +|
            (if (self.generation_batch_accounting.ledger) |ledger| ledger.byte_count else 0) +| partial;
    }

    fn validateGenerationEventQueue(self: *const Client) bool {
        const event_allocator = self.canonicalEventAllocator() catch return false;
        if (self.pending_events.items.len > self.pending_events.capacity or
            self.pending_events.items.len > max_pending_event_count or
            (self.connection_profile != null and
                self.connection_profile.?.requiresStrictExternalEvents()))
            return false;
        var total_bytes: usize = 0;
        for (self.pending_events.items) |event| {
            if (event.header.major != self.wire_major or event.header.kind != .event or
                event.header.request_id != 0 or event.header.stream_id == 0 or
                event.header.flags != 0 or event.header.payload_len != event.payload.len or
                event.payload.len > protocol.max_control_json or event.preflight == null or
                !event.sealMatches(event_allocator))
                return false;
            switch (event.preflight.?) {
                .accepted, .unknown => {},
                .foreign, .malformed, .resource_exhausted => return false,
            }
            total_bytes = std.math.add(usize, total_bytes, event.payload.len) catch return false;
        }
        return total_bytes == self.pending_event_bytes;
    }

    /// Freezes the target stream's first GUI event without changing queue ownership. The caller
    /// may reserve binding authority after this returns, then commit against the exact same queue.
    pub fn prepareGenerationEventTake(
        self: *Client,
        stream_id: u64,
        out: *PreparedGenerationEventTake,
    ) GenerationEventPrepareError!GenerationEventTakeKind {
        const operation_fence_held = self.beginPublicMutation() catch return error.Busy;
        defer if (operation_fence_held) self.endPublicMutation();
        if (checkedAllocatorReentry(self)) return error.Busy;
        if (!out.pristine()) return error.DestinationOccupied;
        if (stream_id == 0 or !self.validateGenerationEventQueue()) return error.Corrupt;
        if (self.unusable) return error.Terminal;
        for (self.pending_events.items, 0..) |event, index| {
            if (event.header.stream_id != stream_id) continue;
            const kind: GenerationEventTakeKind = switch (event.preflight.?) {
                .accepted => |accepted| if (accepted.event == .ended)
                    .ended_pending
                else
                    .ordinary,
                .unknown => .ordinary,
                else => unreachable,
            };
            out.* = .{
                .self_addr = @intFromPtr(out),
                .client_addr = @intFromPtr(self),
                .stream_id = stream_id,
                .event_index = @intCast(index),
                .queue_addr = @intFromPtr(self.pending_events.items.ptr),
                .queue_len = self.pending_events.items.len,
                .queue_capacity = self.pending_events.capacity,
                .queue_bytes = self.pending_event_bytes,
                .payload_addr = @intFromPtr(event.payload.ptr),
                .payload_len = event.payload.len,
                .header = event.header,
                .payload_digest = runtime_event_wire.payloadDigest(event.payload),
                .kind = kind,
                .lifecycle = .prepared,
            };
            return kind;
        }
        return .idle;
    }

    pub fn commitGenerationEventTake(
        self: *Client,
        prepared: *PreparedGenerationEventTake,
        out: *?OwnedGenerationEvent,
    ) GenerationEventCommitError!void {
        const operation_fence_held = self.beginPublicMutation() catch return error.Busy;
        defer if (operation_fence_held) self.endPublicMutation();
        if (checkedAllocatorReentry(self)) return error.Busy;
        const validated = try self.validateGenerationEventTakeCore(prepared, out);
        self.commitValidatedGenerationEventTakeCore(prepared, out, validated);
    }

    fn validateGenerationEventTakeCore(
        self: *Client,
        prepared: *PreparedGenerationEventTake,
        out: *?OwnedGenerationEvent,
    ) GenerationEventHeldError!ValidatedGenerationEventTake {
        if (out.* != null or prepared.self_addr != @intFromPtr(prepared) or
            prepared.client_addr != @intFromPtr(self) or prepared.stream_id == 0 or
            prepared.lifecycle != .prepared or prepared.kind != .ordinary)
            return error.InvalidPrepared;
        if (self.unusable) return error.Terminal;
        if (!self.validateGenerationEventQueue() or
            prepared.queue_addr != @intFromPtr(self.pending_events.items.ptr) or
            prepared.queue_len != self.pending_events.items.len or
            prepared.queue_capacity != self.pending_events.capacity or
            prepared.queue_bytes != self.pending_event_bytes)
            return error.Corrupt;
        const index: usize = prepared.event_index;
        if (index >= self.pending_events.items.len) return error.Corrupt;
        const event = self.pending_events.items[index];
        if (event.header.stream_id != prepared.stream_id or
            !std.meta.eql(event.header, prepared.header) or
            @intFromPtr(event.payload.ptr) != prepared.payload_addr or
            event.payload.len != prepared.payload_len)
            return error.Corrupt;
        const digest = runtime_event_wire.payloadDigest(event.payload);
        if (!std.mem.eql(u8, &digest, &prepared.payload_digest)) return error.Corrupt;
        for (self.pending_events.items[0..index]) |prior|
            if (prior.header.stream_id == prepared.stream_id) return error.Corrupt;
        return .{
            .event_index = prepared.event_index,
            .payload = event.payload,
            .preflight = event.preflight.?,
            .payload_digest = digest,
        };
    }

    fn commitValidatedGenerationEventTakeCore(
        self: *Client,
        prepared: *PreparedGenerationEventTake,
        out: *?OwnedGenerationEvent,
        validated: ValidatedGenerationEventTake,
    ) void {
        const index: usize = validated.event_index;
        const event = self.pending_events.items[index];
        if (@intFromPtr(event.payload.ptr) != @intFromPtr(validated.payload.ptr) or
            event.payload.len != validated.payload.len or
            !std.mem.eql(u8, &validated.payload_digest, &prepared.payload_digest))
            @panic("validated generation event changed under mutation fence");
        const owned = self.pending_events.orderedRemove(index);
        const payload_allocator = owned.admission_seal.?.allocator;
        self.pending_event_bytes -= owned.payload.len;
        prepared.lifecycle = .consumed;
        out.* = .{
            .header = owned.header,
            .payload = owned.payload,
            .payload_allocator = payload_allocator,
            .preflight = owned.preflight.?,
        };
    }

    pub fn validateGenerationEventTakeUnderRegisteredOperationExecutionLease(
        self: *Client,
        capability: RegisteredOperationExecutionHandle,
        prepared: *PreparedGenerationEventTake,
        out: *?OwnedGenerationEvent,
    ) GenerationEventHeldError!ValidatedGenerationEventTake {
        self.requireRegisteredOperationExecutionCapability(capability) catch
            return error.InvalidPrepared;
        return self.validateGenerationEventTakeCore(prepared, out);
    }

    pub fn commitGenerationEventTakeUnderRegisteredOperationExecutionLease(
        self: *Client,
        capability: RegisteredOperationExecutionHandle,
        prepared: *PreparedGenerationEventTake,
        out: *?OwnedGenerationEvent,
        validated: ValidatedGenerationEventTake,
    ) GenerationEventHeldError!void {
        const current = try self.validateGenerationEventTakeUnderRegisteredOperationExecutionLease(
            capability,
            prepared,
            out,
        );
        if (current.event_index != validated.event_index or
            @intFromPtr(current.payload.ptr) != @intFromPtr(validated.payload.ptr) or
            current.payload.len != validated.payload.len or
            !std.mem.eql(u8, &current.payload_digest, &validated.payload_digest))
            return error.Corrupt;
        self.commitValidatedGenerationEventTakeCore(prepared, out, current);
    }

    pub fn abortGenerationEventTakeDuringRegisteredOperation(
        self: *const Client,
        prepared: *PreparedGenerationEventTake,
    ) void {
        self.abortGenerationEventTake(prepared);
    }

    pub fn abortGenerationEventTakeUnderRegisteredOperationExecutionLease(
        self: *Client,
        capability: RegisteredOperationExecutionHandle,
        prepared: *PreparedGenerationEventTake,
    ) void {
        self.requireRegisteredOperationExecutionCapability(capability) catch
            @panic("generation event held abort requires exact execution capability");
        if (prepared.self_addr == @intFromPtr(prepared) and
            prepared.client_addr == @intFromPtr(self) and prepared.lifecycle == .prepared)
            prepared.* = .{};
    }

    pub fn abortGenerationEventTake(
        self: *const Client,
        prepared: *PreparedGenerationEventTake,
    ) void {
        const operation_fence_held = self.beginPublicMutation() catch return;
        defer if (operation_fence_held) self.endPublicMutation();
        if (prepared.self_addr == @intFromPtr(prepared) and
            prepared.client_addr == @intFromPtr(self) and prepared.lifecycle == .prepared)
            prepared.* = .{};
    }

    /// stream의 다음 full-state/control event를 소유권째 꺼낸다. caller는 적용 뒤
    /// `Client.releaseEvent`로 반환한다. Admission seal 불일치는 손상된 route를 caller에게 넘기지 않고
    /// connection-wide ProtocolError로 닫는다.
    pub fn takeEventForStream(self: *Client, stream_id: u64) ClientError!?BufferedEvent {
        const operation_fence_held = try self.beginPublicMutation();
        defer if (operation_fence_held) self.endPublicMutation();
        if (checkedAllocatorReentry(self)) return error.AdminBusy;
        // poison 전에 쌓인 event도 어느 stream의 누락보다 최신인지 증명할 수 없다. 일부 runtime만 한 번 더 전진시키지 않고
        // 모든 shared runtime이 다음 pump에서 같은 ConnectionClosed를 보게 한다.
        if (self.unusable) return null;
        const event_allocator = self.canonicalEventAllocator() catch {
            self.poison(.local_invariant_violation);
            return error.ProtocolError;
        };
        // A sealed GUI event whose header/preflight/payload pairing drifted is connection-wide
        // ambiguous. Its header is no longer routing evidence, so consume/free it here and report
        // a typed terminal before any runtime can project the corrupted parsed view.
        for (self.pending_events.items, 0..) |frame, i| {
            if (!frame.sealMatches(event_allocator)) {
                const owned = self.pending_events.orderedRemove(i);
                self.pending_event_bytes -= owned.payload.len;
                owned.deinit(event_allocator);
                self.poison(.local_invariant_violation);
                return error.ProtocolError;
            }
        }
        for (self.pending_events.items, 0..) |frame, i| {
            if (frame.header.stream_id == stream_id) {
                const owned = self.pending_events.orderedRemove(i);
                self.pending_event_bytes -= owned.payload.len;
                return owned;
            }
        }
        return null;
    }

    /// 현재 stream의 첫 event가 admission 시점에 검증된 `runtime.ended`인지 무할당으로 판정한다.
    /// payload를 다시 파싱하거나 hash하지 않으며 큐와 counter를 변경하지 않는다. 반환 index는
    /// 후속 트랜잭션이 같은 permit 아래 전체 owner graph를 재검증하기 위한 비권위적 힌트다.
    pub fn peekEndedEventForStream(
        self: *const Client,
        stream_id: u64,
    ) error{InvalidClientState}!EndedEventPeek {
        const operation_fence_held = self.beginPublicMutation() catch
            return error.InvalidClientState;
        defer if (operation_fence_held) self.endPublicMutation();
        if (stream_id == 0 or
            self.pending_events.items.len > self.pending_events.capacity or
            self.pending_events.items.len > max_pending_event_count)
            return error.InvalidClientState;
        const event_allocator = self.canonicalEventAllocator() catch
            return error.InvalidClientState;

        for (self.pending_events.items, 0..) |frame, index| {
            if (frame.header.stream_id != stream_id) continue;
            if (frame.header.kind != .event or
                frame.header.request_id != 0 or
                frame.header.flags != 0 or
                frame.header.payload_len != frame.payload.len)
                return error.InvalidClientState;

            return switch (frame.preflight orelse return error.InvalidClientState) {
                .accepted => |accepted| blk: {
                    if (!frame.acceptedSealMetadataMatches(accepted, event_allocator))
                        return error.InvalidClientState;
                    break :blk if (accepted.event == .ended)
                        .{ .candidate = .{ .event_index = @intCast(index) } }
                    else
                        .not_ended;
                },
                .unknown => if (frame.unknownSealMetadataMatches(event_allocator))
                    .not_ended
                else
                    error.InvalidClientState,
                .foreign, .malformed, .resource_exhausted => error.InvalidClientState,
            };
        }
        return .not_ended;
    }

    /// ended purge의 느린 경로가 사용할 전체 Client-owned queue inventory를 만든다.
    /// 이 단계는 owner를 옮기거나 해제하지 않으며, `out`의 마지막 publish 전까지 권위를 만들지 않는다.
    pub fn prepareEndedPurgeInventory(
        self: *const Client,
        target_stream: u64,
        hint: EndedEventHint,
        scratch: *EndedPurgeScratch,
        out: *PreparedEndedPurgeInventory,
    ) EndedPurgePrepareError!void {
        const operation_fence_held = self.beginPublicMutation() catch
            return error.InvalidSource;
        defer if (operation_fence_held) self.endPublicMutation();
        if (out.lifecycle != .empty or out.self_addr != 0 or
            scratch.lifecycle != .empty or target_stream == 0)
            return error.DestinationOccupied;
        const event_allocator = self.canonicalEventAllocator() catch
            return error.InvalidSource;
        const client_start = @intFromPtr(self);
        const scratch_start = @intFromPtr(scratch);
        const out_start = @intFromPtr(out);
        const client_end = std.math.add(usize, client_start, @sizeOf(Client)) catch
            return error.ArithmeticOverflow;
        const scratch_end = std.math.add(usize, scratch_start, @sizeOf(EndedPurgeScratch)) catch
            return error.ArithmeticOverflow;
        const out_end = std.math.add(usize, out_start, @sizeOf(PreparedEndedPurgeInventory)) catch
            return error.ArithmeticOverflow;
        if (rawRangesOverlap(client_start, client_end, scratch_start, scratch_end) or
            rawRangesOverlap(client_start, client_end, out_start, out_end) or
            rawRangesOverlap(scratch_start, scratch_end, out_start, out_end))
            return error.InvalidAlias;

        validateExternalAdoptionStructure(self, .require_empty) catch return error.InvalidSource;
        if (!std.meta.eql(self.parser.allocator, self.allocator)) return error.InvalidSource;
        const outer_descriptors = [4]ExternalArrayDescriptor{
            externalArrayDescriptor(self.parser.buf),
            externalArrayDescriptor(self.pending_batches),
            externalArrayDescriptor(self.pending_stream),
            externalArrayDescriptor(self.pending_events),
        };
        try validateEndedPurgeOuterRanges(self, scratch, out, null);
        scratch.parser_backing = outer_descriptors[0];
        scratch.batch_backing = outer_descriptors[1];
        scratch.stream_backing = outer_descriptors[2];
        scratch.event_backing = outer_descriptors[3];

        // Once every outer backing is proven, enumerate the complete Client owner SSOT before
        // queue semantics, hint traversal, or payload hashing can give a forged alias precedence.
        _ = try validateEndedPurgeOwnerRanges(
            self,
            scratch,
            out,
            null,
            &scratch.range_order,
        );

        const event_index: usize = hint.event_index;
        if (event_index >= self.pending_events.items.len) return error.InvalidHint;
        for (self.pending_events.items[0..event_index]) |event|
            if (event.header.stream_id == target_stream) return error.InvalidHint;
        const ended = self.pending_events.items[event_index];
        if (ended.header.stream_id != target_stream or ended.header.kind != .event or
            ended.header.request_id != 0 or ended.header.flags != 0 or
            ended.header.payload_len != ended.payload.len)
            return error.InvalidHint;
        const ended_preflight = switch (ended.preflight orelse return error.InvalidHint) {
            .accepted => |accepted| accepted,
            else => return error.InvalidHint,
        };
        if (ended_preflight.event != .ended or
            !ended.acceptedSealMetadataMatches(ended_preflight, event_allocator))
            return error.InvalidHint;

        scratch.batch_targets = .initEmpty();
        scratch.stream_targets = .initEmpty();
        scratch.event_targets = .initEmpty();
        scratch.partial = null;
        scratch.partial_target = false;

        var batch_bytes: usize = 0;
        var stream_bytes: usize = 0;
        var event_bytes: usize = 0;
        var target_bytes: usize = 0;
        var target_batch_count: usize = 0;
        var target_stream_count: usize = 0;
        var target_event_count: usize = 0;
        var demux_owned_extent_bytes: usize = 0;

        for (self.pending_batches.items, 0..) |batch, index| {
            if (!std.meta.eql(batch.allocator, self.allocator) or
                batch.stream_id == 0 or batch.bytes.len > protocol.max_viewport_snapshot)
                return error.InvalidSource;
            const descriptor = externalBatchDescriptor(batch);
            try endedPurgeRangeOutsideProtected(
                try endedPurgeCheckedPayloadRange(descriptor.bytes_address, descriptor.bytes_len),
                self,
                scratch,
                out,
                null,
            );
            scratch.batches[index] = descriptor;
            batch_bytes = std.math.add(usize, batch_bytes, batch.bytes.len) catch
                return error.ArithmeticOverflow;
            if (batch.stream_id == target_stream) {
                scratch.batch_targets.set(index);
                target_batch_count += 1;
                target_bytes = std.math.add(usize, target_bytes, batch.bytes.len) catch
                    return error.ArithmeticOverflow;
            }
        }
        if (batch_bytes != self.pending_batch_bytes) return error.InvalidSource;

        for (self.pending_stream.items, 0..) |frame, index| {
            if ((frame.header.kind != .snapshot_chunk and frame.header.kind != .delta_chunk) or
                frame.header.major != self.wire_major or frame.header.request_id != 0 or
                frame.header.stream_id == 0 or
                frame.header.flags & ~protocol.Flags.end_stream != 0 or
                frame.header.payload_len != frame.payload.len or
                frame.payload.len > protocol.max_binary_chunk)
                return error.InvalidSource;
            const descriptor = externalFrameDescriptor(frame);
            try endedPurgeRangeOutsideProtected(
                try endedPurgeCheckedPayloadRange(descriptor.payload_address, descriptor.payload_len),
                self,
                scratch,
                out,
                null,
            );
            scratch.stream[index] = descriptor;
            stream_bytes = std.math.add(usize, stream_bytes, frame.payload.len) catch
                return error.ArithmeticOverflow;
            if (frame.header.stream_id == target_stream) {
                scratch.stream_targets.set(index);
                target_stream_count += 1;
                target_bytes = std.math.add(usize, target_bytes, frame.payload.len) catch
                    return error.ArithmeticOverflow;
            }
        }
        if (stream_bytes != self.pending_stream_bytes) return error.InvalidSource;

        for (self.pending_events.items, 0..) |event, index| {
            if (event.header.major != self.wire_major or event.header.kind != .event or
                event.header.request_id != 0 or event.header.stream_id == 0 or
                event.header.flags != 0 or event.header.payload_len != event.payload.len or
                event.payload.len > protocol.max_control_json)
                return error.InvalidSource;
            _ = switch (event.preflight orelse return error.InvalidSource) {
                .accepted => |value| value,
                else => return error.InvalidSource,
            };
            if (!event.sealMatches(event_allocator)) return error.InvalidSource;
            const descriptor = externalFrameDescriptor(event);
            try endedPurgeRangeOutsideProtected(
                try endedPurgeCheckedPayloadRange(descriptor.payload_address, descriptor.payload_len),
                self,
                scratch,
                out,
                null,
            );
            scratch.events[index] = descriptor;
            event_bytes = std.math.add(usize, event_bytes, event.payload.len) catch
                return error.ArithmeticOverflow;
            if (event.header.stream_id == target_stream) {
                scratch.event_targets.set(index);
                target_event_count += 1;
                target_bytes = std.math.add(usize, target_bytes, event.payload.len) catch
                    return error.ArithmeticOverflow;
            }
        }
        if (event_bytes != self.pending_event_bytes or target_event_count != 1 or
            !scratch.event_targets.isSet(event_index))
            return error.InvalidSource;

        inline for (.{
            .{ self.pending_batches.capacity, @sizeOf(StreamBatch) },
            .{ self.pending_stream.capacity, @sizeOf(framing.Frame) },
            .{ self.pending_events.capacity, @sizeOf(BufferedEvent) },
        }) |entry| {
            const backing_bytes = std.math.mul(usize, entry[0], entry[1]) catch
                return error.ArithmeticOverflow;
            demux_owned_extent_bytes = std.math.add(usize, demux_owned_extent_bytes, backing_bytes) catch
                return error.ArithmeticOverflow;
        }
        inline for (.{ batch_bytes, stream_bytes, event_bytes }) |payload_bytes|
            demux_owned_extent_bytes = std.math.add(usize, demux_owned_extent_bytes, payload_bytes) catch
                return error.ArithmeticOverflow;

        if (self.partial_batch) |partial| {
            if (partial.stream_id == 0 or partial.chunk_count == 0 or
                partial.bytes.items.len > partial.bytes.capacity or
                partial.bytes.items.len > protocol.max_viewport_snapshot)
                return error.InvalidSource;
            const descriptor: ExternalPartialDescriptor = .{
                .stream_id = partial.stream_id,
                .is_snapshot = partial.is_snapshot,
                .bytes = externalArrayDescriptor(partial.bytes),
                .chunk_count = partial.chunk_count,
            };
            try endedPurgeRangeOutsideProtected(
                try endedPurgeCheckedPayloadRange(descriptor.bytes.address, descriptor.bytes.capacity),
                self,
                scratch,
                out,
                null,
            );
            scratch.partial = descriptor;
            if (partial.stream_id == target_stream) {
                scratch.partial_target = true;
                target_bytes = std.math.add(usize, target_bytes, partial.bytes.items.len) catch
                    return error.ArithmeticOverflow;
            }
            demux_owned_extent_bytes = std.math.add(
                usize,
                demux_owned_extent_bytes,
                partial.bytes.capacity,
            ) catch return error.ArithmeticOverflow;
        }

        var batch_writer = owner_seal.Writer.init("maru.ended-purge.batch.v1");
        var stream_writer = owner_seal.Writer.init("maru.ended-purge.stream.v1");
        var event_writer = owner_seal.Writer.init("maru.ended-purge.event.v1");
        var partial_writer = owner_seal.Writer.init("maru.ended-purge.partial.v1");
        for (self.pending_batches.items, 0..) |batch, index|
            writeEndedPurgeBatchSeal(&batch_writer, scratch.batches[index], batch.bytes);
        for (self.pending_stream.items, 0..) |frame, index|
            writeEndedPurgeFrameSeal(&stream_writer, scratch.stream[index], frame.payload);
        for (self.pending_events.items, 0..) |event, index| {
            if (!event.sealMatches(event_allocator)) return error.InvalidSource;
            writeEndedPurgeFrameSeal(&event_writer, scratch.events[index], event.payload);
        }
        if (self.partial_batch) |partial|
            writeEndedPurgePartialSeal(&partial_writer, scratch.partial.?, partial.bytes.items);

        const build_id = self.build_id orelse &.{};
        scratch.build_id = .{
            .address = externalOwnedSliceAddress(u8, build_id),
            .len = build_id.len,
            .capacity = build_id.len,
        };
        scratch.client_lifecycle = .{
            .address = externalOwnedSliceAddress(u8, self.lifecycle),
            .len = self.lifecycle.len,
            .capacity = self.lifecycle.len,
        };
        scratch.pending_outbound = if (self.pending_outbound) |pending| .{
            .frame_address = externalOwnedSliceAddress(u8, pending.frame),
            .frame_len = pending.frame.len,
            .stream_id = pending.stream_id,
            .offset = pending.offset,
        } else null;
        scratch.lifecycle = .inventory_prepared;
        out.* = .{
            .self_addr = out_start,
            .client_addr = client_start,
            .scratch_addr = scratch_start,
            .target_stream = target_stream,
            .hint_index = hint.event_index,
            .batches = externalArrayDescriptor(self.pending_batches),
            .stream = externalArrayDescriptor(self.pending_stream),
            .events = externalArrayDescriptor(self.pending_events),
            .partial = scratch.partial,
            .batch_payload_bytes = batch_bytes,
            .stream_payload_bytes = stream_bytes,
            .event_payload_bytes = event_bytes,
            .target_batch_count = target_batch_count,
            .target_stream_count = target_stream_count,
            .target_event_count = target_event_count,
            .target_payload_bytes = target_bytes,
            .demux_owned_extent_bytes = demux_owned_extent_bytes,
            .batch_seal = batch_writer.finish(),
            .stream_seal = stream_writer.finish(),
            .event_seal = event_writer.finish(),
            .partial_seal = partial_writer.finish(),
            .target_map_seal = endedPurgeTargetMapSeal(scratch),
            .lifecycle = .prepared,
        };
    }

    fn endedPurgeCompleteOwnerSeal(
        self: *const Client,
        operation_generation: u64,
        scratch: *const EndedPurgeScratch,
        inventory: *const PreparedEndedPurgeInventory,
        prepared: *PreparedEndedPurgeCommit,
        include_survivor_seal: bool,
        observed_socket: ?FdSocketIdentity,
    ) EndedPurgeCommitError!void {
        if (operation_generation == 0 or prepared.self_addr != 0 or
            prepared.client_addr != 0 or prepared.scratch_addr != 0 or
            prepared.inventory_addr != 0 or prepared.target_stream != 0 or
            prepared.captured_fd != -1 or prepared.complete_owned_extent_bytes != 0 or
            !std.mem.allEqual(u8, &prepared.finalization_seal, 0) or
            prepared.lifecycle != .pristine)
            return error.InvalidState;

        const socket = observed_socket orelse fdSocketIdentity(self.fd) orelse return error.Corrupt;

        var total = inventory.demux_owned_extent_bytes;
        inline for (.{
            self.parser.buf.capacity,
            scratch.build_id.len,
            scratch.client_lifecycle.len,
            if (scratch.pending_outbound) |pending| pending.frame_len else 0,
        }) |owned_bytes| total = std.math.add(usize, total, owned_bytes) catch
            return error.ArithmeticOverflow;
        if (total > ended_purge_quarantine.max_ended_purge_quarantine_bytes)
            return error.Corrupt;

        var complete = owner_seal.Writer.init("maru.ended-purge.complete-owner.v1");
        complete.writeUsize(@intFromPtr(self));
        complete.writeU64(operation_generation);
        complete.writeUsize(@intFromPtr(self.allocator.ptr));
        complete.writeUsize(@intFromPtr(self.allocator.vtable));
        complete.writeU64(@intCast(self.fd));
        complete.writeU64(socket.stat.device);
        complete.writeU64(socket.stat.inode);
        complete.writeU64(socket.stat.mode_type);
        complete.writeU64(@intCast(socket.socket_type));
        complete.writeUsize(total);
        complete.writeU16(self.wire_major);
        complete.writeU16(self.parser.expected_major);
        complete.writeUsize(self.parser.head);
        inline for (.{
            scratch.parser_backing,
            scratch.batch_backing,
            scratch.stream_backing,
            scratch.event_backing,
            scratch.build_id,
            scratch.client_lifecycle,
        }) |descriptor| {
            complete.writeUsize(descriptor.address);
            complete.writeUsize(descriptor.len);
            complete.writeUsize(descriptor.capacity);
        }
        complete.writeBytes(self.build_id orelse &.{});
        complete.writeBytes(self.lifecycle);
        if (scratch.pending_outbound) |pending| {
            complete.writeBool(true);
            complete.writeUsize(pending.frame_address);
            complete.writeUsize(pending.frame_len);
            complete.writeU64(pending.stream_id);
            complete.writeUsize(pending.offset);
            complete.writeBytes(self.pending_outbound.?.frame);
        } else complete.writeBool(false);
        inline for (.{
            inventory.batch_seal,
            inventory.stream_seal,
            inventory.event_seal,
            inventory.partial_seal,
            inventory.target_map_seal,
        }) |digest| complete.writeBytes(&digest);

        if (!include_survivor_seal) {
            prepared.captured_fd = self.fd;
            prepared.complete_owned_extent_bytes = total;
            prepared.complete_owner_seal = complete.finish();
            return;
        }

        var survivors = owner_seal.Writer.init("maru.ended-purge.pre-callback-survivor.v1");
        survivors.writeU64(operation_generation);
        survivors.writeBytes(self.build_id orelse &.{});
        survivors.writeBytes(self.lifecycle);
        survivors.writeUsize(scratch.parser_backing.address);
        survivors.writeUsize(scratch.parser_backing.len);
        survivors.writeUsize(scratch.parser_backing.capacity);
        survivors.writeBytes(self.parser.buf.items);
        if (self.pending_outbound) |pending| {
            survivors.writeBool(true);
            survivors.writeU64(pending.stream_id);
            survivors.writeUsize(pending.offset);
            survivors.writeBytes(pending.frame);
        } else survivors.writeBool(false);
        for (self.pending_batches.items, 0..) |batch, index|
            if (!scratch.batch_targets.isSet(index))
                writeEndedPurgeBatchSeal(&survivors, scratch.batches[index], batch.bytes);
        for (self.pending_stream.items, 0..) |frame, index|
            if (!scratch.stream_targets.isSet(index))
                writeEndedPurgeFrameSeal(&survivors, scratch.stream[index], frame.payload);
        for (self.pending_events.items, 0..) |event, index|
            if (!scratch.event_targets.isSet(index))
                writeEndedPurgeFrameSeal(&survivors, scratch.events[index], event.payload);
        if (!scratch.partial_target) if (self.partial_batch) |partial|
            writeEndedPurgePartialSeal(&survivors, scratch.partial.?, partial.bytes.items);

        prepared.captured_fd = self.fd;
        prepared.complete_owned_extent_bytes = total;
        prepared.complete_owner_seal = complete.finish();
        prepared.pre_callback_survivor_seal = survivors.finish();
    }

    pub fn prepareEndedPurgeCommit(
        self: *Client,
        target_stream: u64,
        operation_generation: u64,
        scratch: *EndedPurgeScratch,
        inventory: *const PreparedEndedPurgeInventory,
        out: *PreparedEndedPurgeCommit,
    ) EndedPurgeCommitError!void {
        const actual_pid = operation_thread_identity.currentProcessId();
        if (actual_pid == 0) return error.InvalidOwner;
        // This TLS gate must precede every Client graph read. A hostile allocator callback may
        // have drifted pointer-bearing descriptors before attempting a nested prepare.
        if (generationAllocatorCallbackActive()) return error.InvalidState;
        const fence = self.operation_fence orelse return error.InvalidOwner;
        if (fence.owner_process_id != actual_pid) return error.InvalidOwner;
        if (!fence.identityMatches(@intFromPtr(self), self.operation_fence_generation))
            return error.InvalidOwner;
        if (fence.intruded(@intFromPtr(self), self.operation_fence_generation))
            return error.InvalidState;
        if (self.ownership != .standalone or self.unusable or
            self.first_poison_reason != null or
            operation_generation == 0 or target_stream == 0 or
            self.io_mode != .blocking)
            return error.InvalidState;
        const event_allocator = self.canonicalEventAllocator() catch
            return error.Corrupt;

        const client_range = externalRangeOfValue(self);
        const scratch_range = externalRangeOfValue(scratch);
        const inventory_range = externalRangeOfValue(inventory);
        const out_range = externalRangeOfValue(out);
        const object_ranges = [_]ExternalRange{
            client_range,
            scratch_range,
            inventory_range,
            out_range,
        };
        for (object_ranges, 0..) |range, index|
            for (object_ranges[0..index]) |prior|
                if (externalRangesOverlap(range, prior)) return error.InvalidOwner;
        validateEndedPurgeOuterRanges(self, scratch, inventory, out_range) catch |err|
            return switch (err) {
                error.ArithmeticOverflow => error.ArithmeticOverflow,
                else => error.Corrupt,
            };
        var range_order: [max_external_owner_range_count]u16 = undefined;
        _ = validateEndedPurgeOwnerRanges(
            self,
            scratch,
            inventory,
            out_range,
            &range_order,
        ) catch |err| return switch (err) {
            error.ArithmeticOverflow => error.ArithmeticOverflow,
            else => error.Corrupt,
        };
        if (!std.meta.eql(out.*, PreparedEndedPurgeCommit{}))
            return error.DestinationOccupied;
        if (!inventory.validPreparedAtFinalAddress() or
            inventory.client_addr != @intFromPtr(self) or
            inventory.scratch_addr != @intFromPtr(scratch) or
            inventory.target_stream != target_stream or
            scratch.lifecycle != .inventory_prepared)
            return error.InvalidOwner;
        if (!self.prepareDeinitGraph(true)) return error.InvalidState;

        validateExternalAdoptionStructure(self, .require_empty) catch return error.Corrupt;
        if (!std.meta.eql(self.parser.allocator, self.allocator) or
            self.parser.head > self.parser.buf.items.len)
            return error.Corrupt;
        const current_parser = externalArrayDescriptor(self.parser.buf);
        const current_batches = externalArrayDescriptor(self.pending_batches);
        const current_stream = externalArrayDescriptor(self.pending_stream);
        const current_events = externalArrayDescriptor(self.pending_events);
        const build_id = self.build_id orelse &.{};
        const current_build_id = ExternalArrayDescriptor{
            .address = externalOwnedSliceAddress(u8, build_id),
            .len = build_id.len,
            .capacity = build_id.len,
        };
        const current_lifecycle = ExternalArrayDescriptor{
            .address = externalOwnedSliceAddress(u8, self.lifecycle),
            .len = self.lifecycle.len,
            .capacity = self.lifecycle.len,
        };
        const current_pending: ?EndedPurgeScratch.PendingOutboundDescriptor =
            if (self.pending_outbound) |pending| .{
                .frame_address = externalOwnedSliceAddress(u8, pending.frame),
                .frame_len = pending.frame.len,
                .stream_id = pending.stream_id,
                .offset = pending.offset,
            } else null;
        const current_partial: ?ExternalPartialDescriptor = if (self.partial_batch) |partial| .{
            .stream_id = partial.stream_id,
            .is_snapshot = partial.is_snapshot,
            .bytes = externalArrayDescriptor(partial.bytes),
            .chunk_count = partial.chunk_count,
        } else null;
        if (!std.meta.eql(scratch.parser_backing, current_parser) or
            !std.meta.eql(scratch.batch_backing, current_batches) or
            !std.meta.eql(scratch.stream_backing, current_stream) or
            !std.meta.eql(scratch.event_backing, current_events) or
            !std.meta.eql(scratch.build_id, current_build_id) or
            !std.meta.eql(scratch.client_lifecycle, current_lifecycle) or
            !std.meta.eql(scratch.pending_outbound, current_pending) or
            !std.meta.eql(scratch.partial, current_partial) or
            !std.meta.eql(inventory.batches, current_batches) or
            !std.meta.eql(inventory.stream, current_stream) or
            !std.meta.eql(inventory.events, current_events) or
            !std.meta.eql(inventory.partial, current_partial))
            return error.Corrupt;
        if (current_pending) |pending| {
            if (pending.offset > pending.frame_len or pending.stream_id == 0)
                return error.Corrupt;
            _ = checkedExternalRange(pending.frame_address, pending.frame_len) catch |err|
                return switch (err) {
                    error.ArithmeticOverflow => error.ArithmeticOverflow,
                    else => error.Corrupt,
                };
        }

        var current_demux_extent: usize = 0;
        inline for (.{
            .{ self.pending_batches.capacity, @sizeOf(StreamBatch) },
            .{ self.pending_stream.capacity, @sizeOf(framing.Frame) },
            .{ self.pending_events.capacity, @sizeOf(BufferedEvent) },
        }) |entry| {
            const backing_bytes = std.math.mul(usize, entry[0], entry[1]) catch
                return error.ArithmeticOverflow;
            current_demux_extent = std.math.add(
                usize,
                current_demux_extent,
                backing_bytes,
            ) catch return error.ArithmeticOverflow;
        }
        inline for (.{
            self.pending_batch_bytes,
            self.pending_stream_bytes,
            self.pending_event_bytes,
            if (self.partial_batch) |partial| partial.bytes.capacity else 0,
        }) |owned_bytes| current_demux_extent = std.math.add(
            usize,
            current_demux_extent,
            owned_bytes,
        ) catch return error.ArithmeticOverflow;
        if (current_demux_extent != inventory.demux_owned_extent_bytes)
            return error.Corrupt;

        var candidate: PreparedEndedPurgeCommit = .{};
        try self.endedPurgeCompleteOwnerSeal(
            operation_generation,
            scratch,
            inventory,
            &candidate,
            true,
            null,
        );

        var batch_writer = owner_seal.Writer.init("maru.ended-purge.batch.v1");
        var stream_writer = owner_seal.Writer.init("maru.ended-purge.stream.v1");
        var event_writer = owner_seal.Writer.init("maru.ended-purge.event.v1");
        var partial_writer = owner_seal.Writer.init("maru.ended-purge.partial.v1");
        var batch_bytes: usize = 0;
        var stream_bytes: usize = 0;
        var event_bytes: usize = 0;
        var target_batch_bytes: usize = 0;
        var target_stream_bytes: usize = 0;
        var target_event_bytes: usize = 0;
        for (self.pending_batches.items, 0..) |batch, index| {
            if (!std.meta.eql(batch.allocator, self.allocator)) return error.Corrupt;
            writeEndedPurgeBatchSeal(&batch_writer, scratch.batches[index], batch.bytes);
            batch_bytes = std.math.add(usize, batch_bytes, batch.bytes.len) catch
                return error.ArithmeticOverflow;
            if (scratch.batch_targets.isSet(index))
                target_batch_bytes = std.math.add(
                    usize,
                    target_batch_bytes,
                    batch.bytes.len,
                ) catch return error.ArithmeticOverflow;
        }
        for (self.pending_stream.items, 0..) |frame, index| {
            writeEndedPurgeFrameSeal(&stream_writer, scratch.stream[index], frame.payload);
            stream_bytes = std.math.add(usize, stream_bytes, frame.payload.len) catch
                return error.ArithmeticOverflow;
            if (scratch.stream_targets.isSet(index))
                target_stream_bytes = std.math.add(
                    usize,
                    target_stream_bytes,
                    frame.payload.len,
                ) catch return error.ArithmeticOverflow;
        }
        for (self.pending_events.items, 0..) |event, index| {
            if (!event.sealMatches(event_allocator)) return error.Corrupt;
            writeEndedPurgeFrameSeal(&event_writer, scratch.events[index], event.payload);
            event_bytes = std.math.add(usize, event_bytes, event.payload.len) catch
                return error.ArithmeticOverflow;
            if (scratch.event_targets.isSet(index))
                target_event_bytes = std.math.add(
                    usize,
                    target_event_bytes,
                    event.payload.len,
                ) catch return error.ArithmeticOverflow;
        }
        if (self.partial_batch) |partial|
            writeEndedPurgePartialSeal(&partial_writer, scratch.partial.?, partial.bytes.items);
        const current_batch_seal = batch_writer.finish();
        const current_stream_seal = stream_writer.finish();
        const current_event_seal = event_writer.finish();
        const current_partial_seal = partial_writer.finish();
        const current_target_map_seal = endedPurgeTargetMapSeal(scratch);
        var current_target_payload_bytes = std.math.add(
            usize,
            target_batch_bytes,
            target_stream_bytes,
        ) catch return error.ArithmeticOverflow;
        current_target_payload_bytes = std.math.add(
            usize,
            current_target_payload_bytes,
            target_event_bytes,
        ) catch return error.ArithmeticOverflow;
        if (scratch.partial_target) current_target_payload_bytes = std.math.add(
            usize,
            current_target_payload_bytes,
            if (self.partial_batch) |partial| partial.bytes.items.len else 0,
        ) catch return error.ArithmeticOverflow;
        if (batch_bytes != inventory.batch_payload_bytes or
            stream_bytes != inventory.stream_payload_bytes or
            event_bytes != inventory.event_payload_bytes or
            batch_bytes != self.pending_batch_bytes or
            stream_bytes != self.pending_stream_bytes or
            event_bytes != self.pending_event_bytes or
            current_target_payload_bytes != inventory.target_payload_bytes or
            !std.mem.eql(u8, &inventory.batch_seal, &current_batch_seal) or
            !std.mem.eql(u8, &inventory.stream_seal, &current_stream_seal) or
            !std.mem.eql(u8, &inventory.event_seal, &current_event_seal) or
            !std.mem.eql(u8, &inventory.partial_seal, &current_partial_seal) or
            !std.mem.eql(u8, &inventory.target_map_seal, &current_target_map_seal))
            return error.Corrupt;

        ended_purge_transaction.buildQueuePlan(
            protocol.max_client_screen_items,
            &scratch.batch_targets,
            .{
                .source_count = self.pending_batches.items.len,
                .claimed_target_count = inventory.target_batch_count,
                .source_bytes = batch_bytes,
                .target_bytes = target_batch_bytes,
            },
            &candidate.batch_plan,
        ) catch |err| return switch (err) {
            error.ArithmeticOverflow => error.ArithmeticOverflow,
            error.DestinationOccupied => error.DestinationOccupied,
            else => error.Corrupt,
        };
        ended_purge_transaction.buildQueuePlan(
            protocol.max_client_screen_items,
            &scratch.stream_targets,
            .{
                .source_count = self.pending_stream.items.len,
                .claimed_target_count = inventory.target_stream_count,
                .source_bytes = stream_bytes,
                .target_bytes = target_stream_bytes,
            },
            &candidate.stream_plan,
        ) catch |err| return switch (err) {
            error.ArithmeticOverflow => error.ArithmeticOverflow,
            error.DestinationOccupied => error.DestinationOccupied,
            else => error.Corrupt,
        };
        ended_purge_transaction.buildQueuePlan(
            max_pending_event_count,
            &scratch.event_targets,
            .{
                .source_count = self.pending_events.items.len,
                .claimed_target_count = inventory.target_event_count,
                .source_bytes = event_bytes,
                .target_bytes = target_event_bytes,
            },
            &candidate.event_plan,
        ) catch |err| return switch (err) {
            error.ArithmeticOverflow => error.ArithmeticOverflow,
            error.DestinationOccupied => error.DestinationOccupied,
            else => error.Corrupt,
        };
        var partial_targets = std.StaticBitSet(1).initEmpty();
        if (scratch.partial_target) partial_targets.set(0);
        const partial_count: usize = @intFromBool(self.partial_batch != null);
        const partial_bytes = if (self.partial_batch) |partial| partial.bytes.items.len else 0;
        ended_purge_transaction.buildQueuePlan(
            1,
            &partial_targets,
            .{
                .source_count = partial_count,
                .claimed_target_count = @intFromBool(scratch.partial_target),
                .source_bytes = partial_bytes,
                .target_bytes = if (scratch.partial_target) partial_bytes else 0,
            },
            &candidate.partial_plan,
        ) catch |err| return switch (err) {
            error.ArithmeticOverflow => error.ArithmeticOverflow,
            error.DestinationOccupied => error.DestinationOccupied,
            else => error.Corrupt,
        };

        candidate.self_addr = @intFromPtr(out);
        candidate.client_addr = @intFromPtr(self);
        candidate.scratch_addr = @intFromPtr(scratch);
        candidate.inventory_addr = @intFromPtr(inventory);
        candidate.target_stream = target_stream;
        candidate.lifecycle = .prepared;
        // All expensive/fallible validation above ran under the exclusive fence. A competing
        // public call records intrusion instead of entering; recheck immediately before the
        // no-fail publication suffix so stale preparation authority is never minted.
        if (fence.owner_process_id != actual_pid)
            return error.InvalidOwner;
        if (!fence.sealExclusiveForPublication(
            @intFromPtr(self),
            self.operation_fence_generation,
        ))
            return error.InvalidState;
        scratch.lifecycle = .commit_frozen;
        out.* = candidate;
    }

    fn publishEndedPurgeCompaction(
        self: *Client,
        frozen: *const EndedPurgeScratch,
        prepared: *const PreparedEndedPurgeCommit,
    ) void {
        const batch_plan = prepared.batch_plan.rawPlannedScalars() catch
            @panic("ended purge batch plan state drifted");
        var batch_survivor: usize = 0;
        for (0..batch_plan.source_count) |source| {
            if (frozen.batch_targets.isSet(source)) continue;
            if (batch_survivor != source)
                self.pending_batches.items[batch_survivor] = self.pending_batches.items[source];
            batch_survivor += 1;
        }
        self.pending_batches.items.len = batch_plan.survivor_count;
        self.pending_batch_bytes = batch_plan.survivor_bytes;

        const stream_plan = prepared.stream_plan.rawPlannedScalars() catch
            @panic("ended purge stream plan state drifted");
        var stream_survivor: usize = 0;
        for (0..stream_plan.source_count) |source| {
            if (frozen.stream_targets.isSet(source)) continue;
            if (stream_survivor != source)
                self.pending_stream.items[stream_survivor] = self.pending_stream.items[source];
            stream_survivor += 1;
        }
        self.pending_stream.items.len = stream_plan.survivor_count;
        self.pending_stream_bytes = stream_plan.survivor_bytes;

        const event_plan = prepared.event_plan.rawPlannedScalars() catch
            @panic("ended purge event plan state drifted");
        var event_survivor: usize = 0;
        for (0..event_plan.source_count) |source| {
            if (frozen.event_targets.isSet(source)) continue;
            if (event_survivor != source)
                self.pending_events.items[event_survivor] = self.pending_events.items[source];
            event_survivor += 1;
        }
        self.pending_events.items.len = event_plan.survivor_count;
        self.pending_event_bytes = event_plan.survivor_bytes;

        if (frozen.partial_target) self.partial_batch = null;
    }

    fn cleanupEndedPurgeTargetDirect(
        self: *Client,
        allocator: std.mem.Allocator,
        address: usize,
        len: usize,
        ordinal: *usize,
    ) void {
        ordinal.* += 1;
        if (len == 0) return;
        if (checked_allocator_owner_addr != 0)
            @panic("ended purge allocator callback latch was already held");
        checked_allocator_owner_addr = @intFromPtr(self);
        allocator.free(externalOwnedBytes(address, len));
        checked_allocator_owner_addr = 0;
    }

    fn endedPurgePostValidate(
        self: *const Client,
        operation_generation: u64,
        frozen: *const EndedPurgeScratch,
        inventory: *const PreparedEndedPurgeInventory,
        prepared: *const PreparedEndedPurgeCommit,
    ) bool {
        const event_allocator = self.canonicalEventAllocator() catch return false;
        if (operation_generation == 0 or self.fd != prepared.captured_fd or
            self.ownership != .standalone or self.unusable or
            self.first_poison_reason != null)
            return false;
        const socket = fdSocketIdentity(self.fd) orelse return false;
        if (externalArrayDescriptor(self.parser.buf).address != frozen.parser_backing.address or
            externalArrayDescriptor(self.parser.buf).capacity != frozen.parser_backing.capacity or
            externalArrayDescriptor(self.pending_batches).address != frozen.batch_backing.address or
            externalArrayDescriptor(self.pending_batches).capacity != frozen.batch_backing.capacity or
            externalArrayDescriptor(self.pending_stream).address != frozen.stream_backing.address or
            externalArrayDescriptor(self.pending_stream).capacity != frozen.stream_backing.capacity or
            externalArrayDescriptor(self.pending_events).address != frozen.event_backing.address or
            externalArrayDescriptor(self.pending_events).capacity != frozen.event_backing.capacity)
            return false;
        const batch_plan = prepared.batch_plan.rawPlannedScalars() catch return false;
        const stream_plan = prepared.stream_plan.rawPlannedScalars() catch return false;
        const event_plan = prepared.event_plan.rawPlannedScalars() catch return false;
        if (self.pending_batches.items.len != batch_plan.survivor_count or
            self.pending_stream.items.len != stream_plan.survivor_count or
            self.pending_events.items.len != event_plan.survivor_count or
            self.pending_batch_bytes != batch_plan.survivor_bytes or
            self.pending_stream_bytes != stream_plan.survivor_bytes or
            self.pending_event_bytes != event_plan.survivor_bytes or
            (frozen.partial_target and self.partial_batch != null) or
            (!frozen.partial_target and
                (self.partial_batch != null) != (frozen.partial != null)))
            return false;

        const build_id = self.build_id orelse &.{};
        const build_descriptor = ExternalArrayDescriptor{
            .address = externalOwnedSliceAddress(u8, build_id),
            .len = build_id.len,
            .capacity = build_id.len,
        };
        const lifecycle_descriptor = ExternalArrayDescriptor{
            .address = externalOwnedSliceAddress(u8, self.lifecycle),
            .len = self.lifecycle.len,
            .capacity = self.lifecycle.len,
        };
        const pending_descriptor: ?EndedPurgeScratch.PendingOutboundDescriptor =
            if (self.pending_outbound) |pending| .{
                .frame_address = externalOwnedSliceAddress(u8, pending.frame),
                .frame_len = pending.frame.len,
                .stream_id = pending.stream_id,
                .offset = pending.offset,
            } else null;
        if (!std.meta.eql(build_descriptor, frozen.build_id) or
            !std.meta.eql(lifecycle_descriptor, frozen.client_lifecycle) or
            !std.meta.eql(pending_descriptor, frozen.pending_outbound))
            return false;

        // Rebuild the complete scalar/owner transcript after callbacks. This comparison binds the
        // original allocator, parser, socket dev/inode/type and every retained complete-graph
        // descriptor without dereferencing a freed target payload.
        var current_complete: PreparedEndedPurgeCommit = .{};
        self.endedPurgeCompleteOwnerSeal(
            operation_generation,
            frozen,
            inventory,
            &current_complete,
            false,
            socket,
        ) catch return false;
        if (current_complete.captured_fd != prepared.captured_fd or
            current_complete.complete_owned_extent_bytes != prepared.complete_owned_extent_bytes or
            !std.mem.eql(
                u8,
                &current_complete.complete_owner_seal,
                &prepared.complete_owner_seal,
            ))
            return false;

        var survivors = owner_seal.Writer.init("maru.ended-purge.pre-callback-survivor.v1");
        survivors.writeU64(operation_generation);
        survivors.writeBytes(build_id);
        survivors.writeBytes(self.lifecycle);
        survivors.writeUsize(frozen.parser_backing.address);
        survivors.writeUsize(frozen.parser_backing.len);
        survivors.writeUsize(frozen.parser_backing.capacity);
        survivors.writeBytes(self.parser.buf.items);
        if (self.pending_outbound) |pending| {
            survivors.writeBool(true);
            survivors.writeU64(pending.stream_id);
            survivors.writeUsize(pending.offset);
            survivors.writeBytes(pending.frame);
        } else survivors.writeBool(false);
        var survivor_ordinal: usize = 0;
        for (0..batch_plan.source_count) |source| {
            if (frozen.batch_targets.isSet(source)) continue;
            const batch = self.pending_batches.items[survivor_ordinal];
            const descriptor = frozen.batches[source];
            if (!std.meta.eql(externalBatchDescriptor(batch), descriptor)) return false;
            writeEndedPurgeBatchSeal(&survivors, descriptor, batch.bytes);
            survivor_ordinal += 1;
        }
        survivor_ordinal = 0;
        for (0..stream_plan.source_count) |source| {
            if (frozen.stream_targets.isSet(source)) continue;
            const frame = self.pending_stream.items[survivor_ordinal];
            const descriptor = frozen.stream[source];
            if (!std.meta.eql(externalFrameDescriptor(frame), descriptor)) return false;
            writeEndedPurgeFrameSeal(&survivors, descriptor, frame.payload);
            survivor_ordinal += 1;
        }
        survivor_ordinal = 0;
        for (0..event_plan.source_count) |source| {
            if (frozen.event_targets.isSet(source)) continue;
            const event = self.pending_events.items[survivor_ordinal];
            const descriptor = frozen.events[source];
            if (!std.meta.eql(externalFrameDescriptor(event), descriptor) or
                !event.sealMatches(event_allocator))
                return false;
            writeEndedPurgeFrameSeal(&survivors, descriptor, event.payload);
            survivor_ordinal += 1;
        }
        if (!frozen.partial_target) if (self.partial_batch) |partial| {
            const descriptor = frozen.partial orelse return false;
            const current = ExternalPartialDescriptor{
                .stream_id = partial.stream_id,
                .is_snapshot = partial.is_snapshot,
                .bytes = externalArrayDescriptor(partial.bytes),
                .chunk_count = partial.chunk_count,
            };
            if (!std.meta.eql(current, descriptor)) return false;
            writeEndedPurgePartialSeal(&survivors, descriptor, partial.bytes.items);
        };
        const digest = survivors.finish();
        return std.mem.eql(u8, &digest, &prepared.pre_callback_survivor_seal);
    }

    fn tombstoneEndedPurgeOwnedGraph(self: *Client) void {
        self.fd = -1;
        self.build_id = null;
        self.lifecycle = &.{};
        self.pending_outbound = null;
        self.parser.buf = .empty;
        self.parser.head = 0;
        self.pending_batches = .empty;
        self.pending_stream = .empty;
        self.pending_events = .empty;
        self.partial_batch = null;
        self.pending_batch_bytes = 0;
        self.pending_stream_bytes = 0;
        self.pending_event_bytes = 0;
    }

    fn endedPurgeFinalizationSeal(
        self: *const Client,
        operation_generation: u64,
        prepared: *const PreparedEndedPurgeCommit,
    ) owner_seal.Digest {
        const fence = self.operation_fence orelse
            @panic("ended purge finalization seal lost its fence");
        var writer = owner_seal.Writer.init("maru.ended-purge.finalization.v1");
        writer.writeUsize(prepared.self_addr);
        writer.writeUsize(prepared.client_addr);
        writer.writeUsize(prepared.scratch_addr);
        writer.writeUsize(prepared.inventory_addr);
        writer.writeU64(prepared.target_stream);
        writer.writeU64(@bitCast(@as(i64, prepared.captured_fd)));
        writer.writeUsize(prepared.complete_owned_extent_bytes);
        writer.writeBytes(&prepared.complete_owner_seal);
        writer.writeBytes(&prepared.pre_callback_survivor_seal);
        inline for (.{
            prepared.batch_plan,
            prepared.stream_plan,
            prepared.event_plan,
            prepared.partial_plan,
        }) |plan| {
            writer.writeU8(plan.state);
            writer.writeUsize(plan.scalars.source_count);
            writer.writeUsize(plan.scalars.target_count);
            writer.writeUsize(plan.scalars.survivor_count);
            writer.writeUsize(plan.scalars.source_bytes);
            writer.writeUsize(plan.scalars.target_bytes);
            writer.writeUsize(plan.scalars.survivor_bytes);
        }
        inline for (.{
            prepared.batch_cleanup_ordinal,
            prepared.stream_cleanup_ordinal,
            prepared.event_cleanup_ordinal,
            prepared.partial_cleanup_ordinal,
        }) |ordinal| writer.writeUsize(ordinal);
        writer.writeU8(@intFromEnum(prepared.lifecycle));
        writer.writeU64(operation_generation);
        writer.writeUsize(fence.self_addr);
        writer.writeUsize(fence.client_addr);
        writer.writeU64(fence.owner_process_id);
        writer.writeU64(fence.slot_incarnation);
        writer.writeU64(fence.node_incarnation);
        writer.writeU64(fence.fence_generation);
        writer.writeU64(self.operation_fence_generation);
        return writer.finish();
    }

    fn endedPurgeRawFinalizerStateValid(
        prepared: *const PreparedEndedPurgeCommit,
    ) bool {
        const lifecycle_tag = @as(*const u8, @ptrCast(&prepared.lifecycle)).*;
        return lifecycle_tag == @intFromEnum(
            PreparedEndedPurgeCommit.Lifecycle.finalization_pending,
        ) and prepared.batch_plan.state == ended_purge_transaction.QueuePlan.planned_state and
            prepared.stream_plan.state == ended_purge_transaction.QueuePlan.planned_state and
            prepared.event_plan.state == ended_purge_transaction.QueuePlan.planned_state and
            prepared.partial_plan.state == ended_purge_transaction.QueuePlan.planned_state;
    }

    pub fn commitEndedPurgePrepared(
        self: *Client,
        operation_generation: u64,
        scratch: *EndedPurgeScratch,
        inventory: *const PreparedEndedPurgeInventory,
        prepared: *PreparedEndedPurgeCommit,
    ) EndedPurgeClientCommitOutcome {
        const fence = self.operation_fence orelse @panic("ended purge commit lost its fence");
        if (operation_generation == 0 or
            prepared.lifecycle != .prepared or
            prepared.self_addr != @intFromPtr(prepared) or
            prepared.client_addr != @intFromPtr(self) or
            prepared.scratch_addr != @intFromPtr(scratch) or
            prepared.inventory_addr != @intFromPtr(inventory) or
            prepared.batch_cleanup_ordinal != 0 or
            prepared.stream_cleanup_ordinal != 0 or
            prepared.event_cleanup_ordinal != 0 or
            prepared.partial_cleanup_ordinal != 0 or
            scratch.lifecycle != .commit_frozen or
            !inventory.validPreparedAtFinalAddress() or
            inventory.client_addr != @intFromPtr(self) or
            inventory.scratch_addr != @intFromPtr(scratch) or
            fence.state.load(.acquire) != ClientOperationFence.exclusive_bit |
                ClientOperationFence.publication_bit)
            @panic("ended purge commit authority drifted before no-fail suffix");

        const frozen: *const EndedPurgeScratch = scratch;
        const cleanup_allocator = self.allocator;
        const event_allocator = self.canonicalEventAllocator() catch
            @panic("ended purge event allocator authority drifted before cleanup");
        var range_order: [max_external_owner_range_count]u16 = undefined;
        validateEndedPurgeOuterRanges(
            self,
            scratch,
            inventory,
            externalRangeOfValue(prepared),
        ) catch @panic("ended purge outer owner graph drifted before cleanup");
        _ = validateEndedPurgeOwnerRanges(
            self,
            scratch,
            inventory,
            externalRangeOfValue(prepared),
            &range_order,
        ) catch @panic("ended purge owner graph drifted before cleanup");
        if (!std.meta.eql(externalArrayDescriptor(self.parser.buf), frozen.parser_backing) or
            !std.meta.eql(externalArrayDescriptor(self.pending_batches), frozen.batch_backing) or
            !std.meta.eql(externalArrayDescriptor(self.pending_stream), frozen.stream_backing) or
            !std.meta.eql(externalArrayDescriptor(self.pending_events), frozen.event_backing))
            @panic("ended purge owner descriptor drifted before cleanup");

        var batch_writer = owner_seal.Writer.init("maru.ended-purge.batch.v1");
        var stream_writer = owner_seal.Writer.init("maru.ended-purge.stream.v1");
        var event_writer = owner_seal.Writer.init("maru.ended-purge.event.v1");
        var partial_writer = owner_seal.Writer.init("maru.ended-purge.partial.v1");
        for (self.pending_batches.items, 0..) |batch, index| {
            const descriptor = externalBatchDescriptor(batch);
            if (!std.meta.eql(descriptor, frozen.batches[index]))
                @panic("ended purge batch descriptor drifted before cleanup");
            writeEndedPurgeBatchSeal(&batch_writer, descriptor, batch.bytes);
        }
        for (self.pending_stream.items, 0..) |frame, index| {
            const descriptor = externalFrameDescriptor(frame);
            if (!std.meta.eql(descriptor, frozen.stream[index]))
                @panic("ended purge stream descriptor drifted before cleanup");
            writeEndedPurgeFrameSeal(&stream_writer, descriptor, frame.payload);
        }
        for (self.pending_events.items, 0..) |event, index| {
            const descriptor = externalFrameDescriptor(event);
            if (!std.meta.eql(descriptor, frozen.events[index]) or
                !event.sealMatches(event_allocator))
                @panic("ended purge event descriptor drifted before cleanup");
            writeEndedPurgeFrameSeal(&event_writer, descriptor, event.payload);
        }
        if (self.partial_batch) |partial| {
            const descriptor = ExternalPartialDescriptor{
                .stream_id = partial.stream_id,
                .is_snapshot = partial.is_snapshot,
                .bytes = externalArrayDescriptor(partial.bytes),
                .chunk_count = partial.chunk_count,
            };
            if (!std.meta.eql(frozen.partial, descriptor))
                @panic("ended purge partial descriptor drifted before cleanup");
            writeEndedPurgePartialSeal(&partial_writer, descriptor, partial.bytes.items);
        } else if (frozen.partial != null) {
            @panic("ended purge partial owner disappeared before cleanup");
        }
        const current_target_map_seal = endedPurgeTargetMapSeal(frozen);
        const current_batch_seal = batch_writer.finish();
        const current_stream_seal = stream_writer.finish();
        const current_event_seal = event_writer.finish();
        const current_partial_seal = partial_writer.finish();
        if (!std.mem.eql(u8, &current_batch_seal, &inventory.batch_seal) or
            !std.mem.eql(u8, &current_stream_seal, &inventory.stream_seal) or
            !std.mem.eql(u8, &current_event_seal, &inventory.event_seal) or
            !std.mem.eql(u8, &current_partial_seal, &inventory.partial_seal) or
            !std.mem.eql(u8, &current_target_map_seal, &inventory.target_map_seal))
            @panic("ended purge sealed queue graph drifted before cleanup");
        var current_complete: PreparedEndedPurgeCommit = .{};
        self.endedPurgeCompleteOwnerSeal(
            operation_generation,
            frozen,
            inventory,
            &current_complete,
            false,
            null,
        ) catch @panic("ended purge complete owner graph drifted before cleanup");
        if (current_complete.captured_fd != prepared.captured_fd or
            current_complete.complete_owned_extent_bytes != prepared.complete_owned_extent_bytes or
            !std.mem.eql(
                u8,
                &current_complete.complete_owner_seal,
                &prepared.complete_owner_seal,
            ))
            @panic("ended purge complete owner seal mismatch before cleanup");
        const batch_plan = prepared.batch_plan.rawPlannedScalars() catch
            @panic("ended purge batch plan state drifted");
        const stream_plan = prepared.stream_plan.rawPlannedScalars() catch
            @panic("ended purge stream plan state drifted");
        const event_plan = prepared.event_plan.rawPlannedScalars() catch
            @panic("ended purge event plan state drifted");
        const partial_plan = prepared.partial_plan.rawPlannedScalars() catch
            @panic("ended purge partial plan state drifted");
        var batch_cursor = ended_purge_transaction.DispositionCursor(
            protocol.max_client_screen_items,
        ).init(batch_plan, &frozen.batch_targets) catch
            @panic("ended purge batch plan drifted");
        while (batch_cursor.next() catch @panic("ended purge batch cursor drifted")) |_| {}
        var stream_cursor = ended_purge_transaction.DispositionCursor(
            protocol.max_client_screen_items,
        ).init(stream_plan, &frozen.stream_targets) catch
            @panic("ended purge stream plan drifted");
        while (stream_cursor.next() catch @panic("ended purge stream cursor drifted")) |_| {}
        var event_cursor = ended_purge_transaction.DispositionCursor(
            max_pending_event_count,
        ).init(event_plan, &frozen.event_targets) catch
            @panic("ended purge event plan drifted");
        while (event_cursor.next() catch @panic("ended purge event cursor drifted")) |_| {}
        var partial_targets = std.StaticBitSet(1).initEmpty();
        if (frozen.partial_target) partial_targets.set(0);
        var partial_cursor = ended_purge_transaction.DispositionCursor(1).init(
            partial_plan,
            &partial_targets,
        ) catch @panic("ended purge partial plan drifted");
        while (partial_cursor.next() catch @panic("ended purge partial cursor drifted")) |_| {}

        scratch.lifecycle = .consumed;
        self.publishEndedPurgeCompaction(frozen, prepared);
        var expected_cleanup_ordinal: usize = 0;
        for (0..batch_plan.source_count) |source| if (frozen.batch_targets.isSet(source)) {
            if (prepared.batch_cleanup_ordinal != expected_cleanup_ordinal)
                @panic("ended purge batch cleanup ordinal drifted");
            const descriptor = frozen.batches[source];
            self.cleanupEndedPurgeTargetDirect(
                descriptor.allocator,
                descriptor.bytes_address,
                descriptor.bytes_len,
                &prepared.batch_cleanup_ordinal,
            );
            expected_cleanup_ordinal += 1;
        };
        if (expected_cleanup_ordinal != batch_plan.target_count)
            @panic("ended purge batch cleanup count drifted");
        expected_cleanup_ordinal = 0;
        for (0..stream_plan.source_count) |source| if (frozen.stream_targets.isSet(source)) {
            if (prepared.stream_cleanup_ordinal != expected_cleanup_ordinal)
                @panic("ended purge stream cleanup ordinal drifted");
            const descriptor = frozen.stream[source];
            self.cleanupEndedPurgeTargetDirect(
                cleanup_allocator,
                descriptor.payload_address,
                descriptor.payload_len,
                &prepared.stream_cleanup_ordinal,
            );
            expected_cleanup_ordinal += 1;
        };
        if (expected_cleanup_ordinal != stream_plan.target_count)
            @panic("ended purge stream cleanup count drifted");
        expected_cleanup_ordinal = 0;
        for (0..event_plan.source_count) |source| if (frozen.event_targets.isSet(source)) {
            if (prepared.event_cleanup_ordinal != expected_cleanup_ordinal)
                @panic("ended purge event cleanup ordinal drifted");
            const descriptor = frozen.events[source];
            self.cleanupEndedPurgeTargetDirect(
                event_allocator,
                descriptor.payload_address,
                descriptor.payload_len,
                &prepared.event_cleanup_ordinal,
            );
            expected_cleanup_ordinal += 1;
        };
        if (expected_cleanup_ordinal != event_plan.target_count)
            @panic("ended purge event cleanup count drifted");
        expected_cleanup_ordinal = 0;
        if (frozen.partial_target) {
            const descriptor = frozen.partial orelse
                @panic("ended purge partial target lost its descriptor");
            self.cleanupEndedPurgeTargetDirect(
                cleanup_allocator,
                descriptor.bytes.address,
                descriptor.bytes.capacity,
                &prepared.partial_cleanup_ordinal,
            );
            expected_cleanup_ordinal = 1;
        }
        if (expected_cleanup_ordinal != partial_plan.target_count)
            @panic("ended purge partial cleanup count drifted");

        if (self.endedPurgePostValidate(
            operation_generation,
            frozen,
            inventory,
            prepared,
        )) {
            prepared.lifecycle = .consumed;
            return .clean;
        }
        self.tombstoneEndedPurgeOwnedGraph();
        prepared.lifecycle = .finalization_pending;
        prepared.finalization_seal = self.endedPurgeFinalizationSeal(
            operation_generation,
            prepared,
        );
        return .drift_pending_finalize;
    }

    fn publishEndedPurgeNoFreePoison(self: *Client) void {
        self.ownership = .quarantined_no_free;
        self.markPoisonedForDeferredCleanup(.external_transfer_quarantined);
    }

    pub fn finalizeEndedPurgeNoFreePoison(
        self: *Client,
        operation_generation: u64,
        prepared: *PreparedEndedPurgeCommit,
        quarantine_proof: ended_purge_quarantine.ConsumedCommitProof,
    ) void {
        const actual_pid: u64 = operation_thread_identity.currentProcessId();
        // The consumed proof is the only object inspected before the process-domain gate. In a
        // fork child, reject before touching inherited Client/fence atomics or interpreting any
        // callback-writable enum/tag state.
        if (actual_pid == 0 or quarantine_proof.process_id != actual_pid)
            @panic("ended purge finalizer process domain mismatch");
        if (!endedPurgeRawFinalizerStateValid(prepared))
            @panic("ended purge finalizer raw state mismatch");
        const fence = self.operation_fence orelse
            @panic("ended purge finalizer lost its fence");
        const current_finalization_seal = self.endedPurgeFinalizationSeal(
            operation_generation,
            prepared,
        );
        if (operation_generation == 0 or
            prepared.lifecycle != .finalization_pending or
            prepared.self_addr != @intFromPtr(prepared) or
            prepared.client_addr != @intFromPtr(self) or
            prepared.complete_owned_extent_bytes == 0 or
            std.mem.allEqual(u8, &prepared.finalization_seal, 0) or
            self.ownership != .standalone or self.first_poison_reason != null or
            fence.owner_process_id != actual_pid or
            !fence.identityMatches(@intFromPtr(self), self.operation_fence_generation) or
            fence.state.load(.acquire) != ClientOperationFence.exclusive_bit |
                ClientOperationFence.publication_bit or
            !quarantine_proof.matches(
                actual_pid,
                fence.node_incarnation,
                operation_generation,
                prepared.complete_owned_extent_bytes,
            ) or
            !std.mem.eql(
                u8,
                &prepared.finalization_seal,
                &current_finalization_seal,
            ))
            @panic("ended purge finalizer authority mismatch");

        self.publishEndedPurgeNoFreePoison();
        prepared.lifecycle = .consumed;
        if (!fence.commitExclusiveTerminal(
            @intFromPtr(self),
            self.operation_fence_generation,
        )) @panic("ended purge finalizer terminal publication failed");
    }

    /// Releases an event through the allocator that admitted it. Consumers must not assume their
    /// projection allocator is identical to the shared Client transport allocator.
    pub fn releaseEvent(self: *Client, event: BufferedEvent) void {
        const operation_fence_held = self.beginPublicMutation() catch return;
        defer if (operation_fence_held) self.endPublicMutation();
        if (checkedAllocatorReentry(self)) return;
        const event_allocator = self.canonicalEventAllocator() catch {
            self.poison(.local_invariant_violation);
            return;
        };
        event.deinit(event_allocator);
    }

    /// full-state event는 같은 stream+종류의 이전 pending을 최신으로 교체한다. 악성/버그 host가 임의 stream id를
    /// 쏟아 count/byte cap을 넘기면 oldest를 버리지 않고 shared connection 전체를 poison해 모든 runtime을 fail-closed한다.
    /// Legacy unit-fixture adapter. The product demux never calls this function: malformed
    /// headers must reach `bufferCanonicalEvent` unchanged so test builds and product builds
    /// exercise the same ingress contract.
    fn bufferLegacyEventForTest(self: *Client, frame: framing.Frame) ClientError!void {
        if (!builtin.is_test) unreachable;
        var normalized = frame;
        if (normalized.header.major == 0)
            normalized.header.major = self.wire_major;
        if (normalized.header.payload_len == 0)
            normalized.header.payload_len = @intCast(normalized.payload.len);
        return self.bufferCanonicalEvent(normalized);
    }

    fn bufferCanonicalEvent(self: *Client, frame: framing.Frame) ClientError!void {
        if (frame.header.major != self.wire_major or
            frame.header.payload_len != frame.payload.len)
        {
            frame.deinit(self.allocator);
            self.poison(.local_invariant_violation);
            return error.ProtocolError;
        }
        const parser_allocator = self.allocator;
        const event_allocator = self.canonicalEventAllocator() catch {
            frame.deinit(parser_allocator);
            self.poison(.local_invariant_violation);
            return error.ProtocolError;
        };
        if (!allocatorEql(parser_allocator, event_allocator)) {
            const payload = event_allocator.dupe(u8, frame.payload) catch {
                frame.deinit(parser_allocator);
                self.poison(.local_resource_exhausted);
                return error.OutOfMemory;
            };
            var canonical = frame;
            canonical.payload = payload;
            frame.deinit(parser_allocator);
            return self.bufferEventWithAllocator(canonical, event_allocator);
        }
        return self.bufferEventWithAllocator(frame, event_allocator);
    }

    pub fn bufferGenerationEventForTest(
        self: *Client,
        stream_id: u64,
        payload: []const u8,
    ) ClientError!void {
        if (!builtin.is_test) return error.ProtocolError;
        const operation_fence_held = try self.beginPublicMutation();
        defer if (operation_fence_held) self.endPublicMutation();
        const event_allocator = self.canonicalEventAllocator() catch {
            self.poison(.local_invariant_violation);
            return error.ProtocolError;
        };
        const owned = event_allocator.dupe(u8, payload) catch return error.OutOfMemory;
        return self.bufferEventWithAllocator(.{
            .header = .{
                .kind = .event,
                .stream_id = stream_id,
                .payload_len = @intCast(owned.len),
                .major = self.wire_major,
            },
            .payload = owned,
        }, event_allocator);
    }

    fn bufferEventWithAllocator(
        self: *Client,
        frame: framing.Frame,
        allocator: std.mem.Allocator,
    ) ClientError!void {
        if (frame.header.kind != .event or frame.header.request_id != 0 or
            frame.header.stream_id == 0 or frame.header.flags != 0)
        {
            frame.deinit(allocator);
            self.poison(.peer_contract_violation);
            return error.ProtocolError;
        }
        if (self.connection_profile != null and
            self.connection_profile.?.requiresStrictExternalEvents())
        {
            return self.appendRawEvent(frame, allocator);
        }
        // GUI-generation events must enter and leave through the canonical Client allocator.
        // Merely recording a foreign allocator in the seal would publish poisoned ownership and
        // make replacement or teardown choose between a mismatched free and a leak.
        const event_allocator = self.canonicalEventAllocator() catch {
            frame.deinit(allocator);
            self.poison(.local_invariant_violation);
            return error.ProtocolError;
        };
        if (!allocatorEql(allocator, event_allocator)) {
            frame.deinit(allocator);
            self.poison(.local_invariant_violation);
            return error.ProtocolError;
        }
        const verdict = runtime_event_wire.preflightEventObserved(
            frame.payload,
            .{},
            self.event_parse_observer,
        );
        const accepted_event: ?runtime_event_wire.Event = switch (verdict) {
            .accepted => |accepted| accepted.event,
            .unknown => null,
            .foreign => {
                frame.deinit(allocator);
                self.poison(.peer_contract_violation);
                return error.ProtocolError;
            },
            .malformed => {
                // GUI fresh ingress preserves the historical malformed-drop policy. It must not
                // publish/coalesce or evict a previously admitted latest event.
                frame.deinit(allocator);
                return;
            },
            .resource_exhausted => {
                frame.deinit(allocator);
                self.poison(.peer_contract_violation);
                return error.ProtocolError;
            },
        };
        const metadata_revision: ?u64 = if (accepted_event) |event| switch (event) {
            .metadata => |metadata| blk: {
                if (self.metadata_support == .unsupported) {
                    frame.deinit(allocator);
                    self.poison(.peer_contract_violation);
                    return error.ProtocolError;
                }
                break :blk metadata.revision;
            },
            else => null,
        } else null;
        const resized: ?resize_wire.Event = if (accepted_event) |event| switch (event) {
            .resized => |value| value,
            else => null,
        } else null;
        const runtime_ended = if (accepted_event) |event| event == .ended else false;
        if (accepted_event) |event| switch (event) {
            .revoked => |revoked| {
                // The header is already sufficient routing evidence at ingress. Queueing a
                // payload that revokes another stream would leave both stream-local latches able
                // to skip it before the later attachment-aware classifier runs.
                if (revoked.stream_id != frame.header.stream_id) {
                    frame.deinit(allocator);
                    self.poison(.peer_contract_violation);
                    return error.ProtocolError;
                }
            },
            else => {},
        };
        const buffered: BufferedEvent = .{
            .header = frame.header,
            .payload = frame.payload,
            .preflight = verdict,
            .admission_seal = switch (verdict) {
                .accepted => |accepted| BufferedEvent.seal(
                    frame.header,
                    frame.payload,
                    .{ .accepted = accepted },
                    allocator,
                ),
                .unknown => BufferedEvent.seal(
                    frame.header,
                    frame.payload,
                    .unknown,
                    allocator,
                ),
                else => null,
            },
        };
        // No replacement/supersession decision may inspect a previously admitted header or
        // parsed scalar until its independent admission copy has rebound all three components.
        for (self.pending_events.items) |old| {
            if (!old.sealMatches(event_allocator)) {
                buffered.deinit(allocator);
                self.poison(.local_invariant_violation);
                return error.ProtocolError;
            }
        }
        if (runtime_ended) {
            // Ended terminally supersedes every pending full-state/control event for this stream.
            // With 256 live attachments this replacement must not become a 257th queue item and
            // poison otherwise healthy sibling runtimes.
            const ended_stream = frame.header.stream_id;
            var ended_index: usize = 0;
            while (ended_index < self.pending_events.items.len) {
                if (self.pending_events.items[ended_index].header.stream_id == ended_stream) {
                    const replaced = self.pending_events.orderedRemove(ended_index);
                    self.pending_event_bytes -= replaced.payload.len;
                    replaced.deinit(allocator);
                } else ended_index += 1;
            }
        }
        for (self.pending_events.items, 0..) |old, i| {
            if (metadata_revision != null and
                old.header.stream_id == frame.header.stream_id)
            {
                const old_metadata: ?runtime_event_wire.MetadataView = if (old.preflight) |old_verdict| switch (old_verdict) {
                    .accepted => |old_accepted| switch (old_accepted.event) {
                        .metadata => |metadata| metadata,
                        else => null,
                    },
                    else => null,
                } else null;
                if (old_metadata) |old_value| {
                    if (metadata_revision.? < old_value.revision) {
                        buffered.deinit(allocator);
                        return;
                    }
                    if (metadata_revision.? == old_value.revision) {
                        const next_value = switch (accepted_event.?) {
                            .metadata => |metadata| metadata,
                            else => unreachable,
                        };
                        if (!runtime_event_wire.metadataSemanticEqlExact(
                            old.payload,
                            &old_value,
                            buffered.payload,
                            &next_value,
                        )) {
                            buffered.deinit(allocator);
                            self.poison(.peer_contract_violation);
                            return error.ProtocolError;
                        }
                        buffered.deinit(allocator);
                        return;
                    }
                    const replaced = self.pending_events.items[i];
                    const next_bytes = self.pending_event_bytes - replaced.payload.len +|
                        buffered.payload.len;
                    if (next_bytes > protocol.max_client_queue) {
                        buffered.deinit(allocator);
                        self.poison(.event_queue_overflow);
                        return error.EventQueueFull;
                    }
                    self.pending_events.items[i] = buffered;
                    self.pending_event_bytes = next_bytes;
                    replaced.deinit(allocator);
                    return;
                }
            }
            if (resized != null and old.header.stream_id == frame.header.stream_id) {
                const old_resize: ?resize_wire.Event = if (old.preflight) |old_verdict| switch (old_verdict) {
                    .accepted => |old_accepted| switch (old_accepted.event) {
                        .resized => |value| value,
                        else => null,
                    },
                    else => null,
                } else null;
                if (old_resize) |old_value| {
                    if (resized.?.runtime_id != old_value.runtime_id) {
                        buffered.deinit(allocator);
                        self.poison(.peer_contract_violation);
                        return error.ProtocolError;
                    }
                    if (resized.?.resize_generation < old_value.resize_generation) {
                        buffered.deinit(allocator);
                        return;
                    }
                    if (resized.?.resize_generation == old_value.resize_generation) {
                        if (resized.?.cols != old_value.cols or
                            resized.?.rows != old_value.rows)
                        {
                            buffered.deinit(allocator);
                            self.poison(.peer_contract_violation);
                            return error.ProtocolError;
                        }
                        buffered.deinit(allocator);
                        return;
                    }
                    const replaced = self.pending_events.items[i];
                    const next_bytes =
                        self.pending_event_bytes - replaced.payload.len +| buffered.payload.len;
                    if (next_bytes > protocol.max_client_queue) {
                        buffered.deinit(allocator);
                        self.poison(.event_queue_overflow);
                        return error.EventQueueFull;
                    }
                    self.pending_events.items[i] = buffered;
                    self.pending_event_bytes = next_bytes;
                    replaced.deinit(allocator);
                    return;
                }
            }
        }
        return self.appendBufferedEvent(buffered, allocator);
    }

    /// Strict external attach는 identity/authority/baseline을 adoption 전에는 아직 갖지 않는다. 따라서 header/cap
    /// 이외의 semantic 판단, coalesce, supersession 없이 arrival-order bytes를 그대로 보존한다.
    fn appendRawEvent(
        self: *Client,
        frame: framing.Frame,
        allocator: std.mem.Allocator,
    ) ClientError!void {
        return self.appendBufferedEvent(.{
            .header = frame.header,
            .payload = frame.payload,
            .preflight = null,
        }, allocator);
    }

    fn appendBufferedEvent(
        self: *Client,
        event: BufferedEvent,
        allocator: std.mem.Allocator,
    ) ClientError!void {
        if (self.pending_events.items.len >= max_pending_event_count or
            self.pending_event_bytes +| event.payload.len > protocol.max_client_queue)
        {
            // Eviction 금지: server는 event를 만들 때 이미 subscription base/revision을 전진시켰다. 해당 stream의 최신
            // full-state를 조용히 버리면 같은 상태를 다시 보내지 않는다. 어느 shared stream이 누락됐든 connection 전체를
            // 닫아 모든 runtime이 fail-closed하고, 다음 attach의 initial metadata에서만 복구한다.
            event.deinit(allocator);
            self.poison(.event_queue_overflow);
            return error.EventQueueFull;
        }
        self.pending_events.append(allocator, event) catch {
            event.deinit(allocator);
            self.poison(.local_resource_exhausted);
            return error.OutOfMemory;
        };
        self.pending_event_bytes += event.payload.len;
    }

    /// stream 배치를 잇는 다음 stream frame을 준다. 우선순위: `call`이 버퍼한 frame → parser에 남은 완성 frame → 소켓 read.
    /// 첫 frame과 continuation 모두 `pollReadable`로 논블로킹 확인하고, 데이터가 없으면 partial batch를 caller가 보존하도록
    /// `null`을 돌려준다. UI frame pump에서 socket timeout까지 기다리지 않는다.
    fn nextStreamFrame(self: *Client, _: bool) ClientError!?framing.Frame {
        return self.nextStreamFrameWithIo(false, .polling, null, .public) catch |err| switch (err) {
            error.DeadlineExceeded => unreachable,
            else => |client_err| client_err,
        };
    }

    fn nextStreamFrameWithIo(
        self: *Client,
        _: bool,
        io: StreamIo,
        payload_allocator_out: ?*std.mem.Allocator,
        fence_mode: StreamFenceMode,
    ) DeadlineClientError!?framing.Frame {
        const operation_fence_held = switch (fence_mode) {
            .public => try self.ensureUsable(),
            .registered_execution => blk: {
                if (checkedAllocatorReentry(self)) return error.AdminBusy;
                if (self.ownership == .moved or self.unusable) return error.ConnectionClosed;
                break :blk false;
            },
        };
        defer if (operation_fence_held) self.endPublicMutation();
        if (payload_allocator_out) |out| out.* = self.allocator;
        if (self.pending_stream.items.len > 0) {
            const owned = self.pending_stream.orderedRemove(0);
            self.pending_stream_bytes -= owned.payload.len;
            const frame = try self.requireWireMajor(owned);
            if (deadlineExpired(io)) {
                frame.deinit(if (payload_allocator_out) |out| out.* else self.allocator);
                return error.DeadlineExceeded;
            }
            return frame;
        }
        var buf: [4096]u8 = undefined;
        while (true) {
            if (self.parser.nextWithAllocator(payload_allocator_out) catch |err| {
                self.poison(if (err == error.OutOfMemory)
                    .local_resource_exhausted
                else
                    .frame_malformed);
                return switch (err) {
                    error.OutOfMemory => error.OutOfMemory,
                    else => error.ProtocolError,
                };
            }) |owned| {
                const frame = try self.requireWireMajor(owned);
                if (deadlineExpired(io)) {
                    frame.deinit(if (payload_allocator_out) |out| out.* else self.allocator);
                    return error.DeadlineExceeded;
                }
                return frame;
            }
            // Partial batches live across pump calls, so neither the first nor a continuation may
            // enter the socket's 5s blocking read timeout on the UI frame loop.
            const count = switch (io) {
                .polling => blk: {
                    if (!pollReadable(self.fd)) return null;
                    const n = c.read(self.fd, &buf, buf.len);
                    if (n < 0) {
                        if (posix.errno(n) == .INTR) continue; // 시그널 인터럽트는 재시도.
                        if (posix.errno(n) == .AGAIN or posix.errno(n) == .TIMEDOUT) return null;
                        self.poison(.transport_read_failure);
                        return error.ConnectionClosed;
                    }
                    if (n == 0) {
                        self.poison(.connection_eof);
                        return error.ConnectionClosed;
                    }
                    break :blk @as(usize, @intCast(n));
                },
                .deadline => |bounded| client_deadline.readSomeUntil(
                    bounded.ops,
                    self.fd,
                    &buf,
                    bounded.absolute,
                ) catch |err| {
                    const reason: client_poison.ConnectionReason = switch (err) {
                        error.Timeout => .read_timeout,
                        error.Closed => if (self.parser.bufferedBytes() == 0)
                            .connection_eof
                        else
                            .frame_malformed,
                        error.ReadFailed => .transport_read_failure,
                        else => .transport_read_failure,
                    };
                    self.poisonWithOps(reason, bounded.ops);
                    return switch (err) {
                        error.Timeout => error.DeadlineExceeded,
                        error.Closed, error.ReadFailed => error.ConnectionClosed,
                        else => error.ConnectionClosed,
                    };
                },
            };
            self.parser.push(buf[0..count]) catch {
                self.poison(.local_resource_exhausted);
                return error.OutOfMemory;
            };
        }
    }

    fn deadlineExpired(io: StreamIo) bool {
        return switch (io) {
            .polling => false,
            .deadline => |bounded| bounded.absolute.remainingNs() <= 0,
        };
    }

    /// terminal input bytes를 attach된 `stream_id`로 보낸다(§9 `input_bytes` — 응답 없는 fire-and-forget). controller만
    /// 유효하고, host는 비controller/미attach stream의 input을 조용히 버린다. attach 응답의 stream_id를 그대로 쓴다.
    pub fn sendInput(self: *Client, stream_id: u64, bytes: []const u8) ClientError!void {
        const operation_fence_held = try self.requireBlockingMode();
        defer if (operation_fence_held) self.endPublicMutation();
        return self.sendInputGuarded(stream_id, bytes, false);
    }

    fn sendInputGuarded(self: *Client, stream_id: u64, bytes: []const u8, execution_lease_held: bool) ClientError!void {
        // 앞 tick의 non-blocking frame부터 끝낸 뒤 새 blocking input을 쓴다. 같은 stream뿐 아니라 connection을 공유하는
        // 여러 runtime 사이에서도 실제 socket write 순서를 보존한다.
        try self.flushPendingOutboundBlockingMode(execution_lease_held);
        // input frame의 wire cap은 1 MiB다. paste가 이를 넘는 것은 정상 입력이므로 encode 실패/드롭하지 않고 순서대로
        // 여러 frame으로 나눈다. 빈 입력은 전송할 것이 없다.
        var offset: usize = 0;
        while (offset < bytes.len) {
            const end = inputChunkEnd(offset, bytes.len);
            const frame_bytes = framing.encodeFrame(self.allocator, .{
                .kind = .input_bytes,
                .stream_id = stream_id,
                .major = self.wire_major,
            }, bytes[offset..end]) catch
                return error.OutOfMemory;
            socket_server.writeAll(self.fd, frame_bytes) catch {
                self.allocator.free(frame_bytes);
                // frame prefix가 이미 kernel에 들어갔을 수 있어 같은 connection에서 재시도하면 framing/입력이 중복된다.
                self.poisonMutationIo(.outbound_write_ambiguous, execution_lease_held);
                return error.WriteFailed;
            };
            self.allocator.free(frame_bytes);
            offset = end;
        }
    }

    pub fn sendInputUnderRegisteredOperationExecutionLease(
        self: *Client,
        capability: RegisteredOperationExecutionHandle,
        stream_id: u64,
        bytes: []const u8,
    ) ClientError!void {
        try self.requireRegisteredOperationExecutionCapability(capability);
        return self.sendInputGuarded(stream_id, bytes, true);
    }

    /// terminal input을 UI thread에서 **실제로 논블로킹** 전송한다. 반환값은 socket에 즉시 쓴 바이트가 아니라 이 connection이
    /// 소유권을 인수한 payload 바이트 수다. 기존 pending frame이 아직 막혀 있으면 0, 새 frame을 pending 슬롯에 넣었으면
    /// DONTWAIT flush가 0/partial/full 어느 경우든 그 payload 길이를 반환한다 — caller가 동일 입력을 재전송하지 않게 한다.
    pub fn sendInputNonBlocking(self: *Client, stream_id: u64, bytes: []const u8) ClientError!usize {
        const operation_fence_held = try self.requireBlockingMode();
        defer if (operation_fence_held) self.endPublicMutation();
        return self.sendInputNonBlockingGuarded(stream_id, bytes, false);
    }

    fn sendInputNonBlockingGuarded(self: *Client, stream_id: u64, bytes: []const u8, execution_lease_held: bool) ClientError!usize {
        // 기존 frame을 먼저 밀어 FIFO를 지킨다. 여전히 막혔으면 새 payload는 caller가 계속 소유한다.
        if (!(try self.pumpPendingOutputGuarded(execution_lease_held))) return 0;
        if (bytes.len == 0) return 0;

        const accepted = inputChunkEnd(0, bytes.len);
        const frame = framing.encodeFrame(
            self.allocator,
            .{ .kind = .input_bytes, .stream_id = stream_id, .major = self.wire_major },
            bytes[0..accepted],
        ) catch return error.OutOfMemory;
        std.debug.assert(self.pending_outbound == null);
        self.pending_outbound = .{ .frame = frame, .stream_id = stream_id };

        // EAGAIN/partial write여도 frame 소유권은 이미 client로 넘어왔다. hard error만 connection을 fail-closed한다.
        _ = try self.pumpPendingOutputGuarded(execution_lease_held);
        return accepted;
    }

    pub fn sendInputNonBlockingUnderRegisteredOperationExecutionLease(
        self: *Client,
        capability: RegisteredOperationExecutionHandle,
        stream_id: u64,
        bytes: []const u8,
    ) ClientError!usize {
        try self.requireRegisteredOperationExecutionCapability(capability);
        return self.sendInputNonBlockingGuarded(stream_id, bytes, true);
    }

    /// AppKit callback에서 host viewport를 live bottom으로 되돌리는 fire-and-forget frame을 bounded
    /// outbound 슬롯에 admission한다. true면 frame 소유권을 인수했고, false면 기존 frame이 backpressure로
    /// 남아 caller가 stream-local sticky intent를 유지해야 한다. 구 host에는 절대 동기 RPC fallback하지 않는다.
    pub fn sendScrollToBottomNonBlocking(self: *Client, stream_id: u64) ClientError!bool {
        const operation_fence_held = try self.requireBlockingMode();
        defer if (operation_fence_held) self.endPublicMutation();
        return self.sendScrollToBottomNonBlockingGuarded(stream_id, false);
    }

    fn sendScrollToBottomNonBlockingGuarded(self: *Client, stream_id: u64, execution_lease_held: bool) ClientError!bool {
        if (!self.async_scroll_to_bottom_v1) return false;
        if (!(try self.pumpPendingOutputGuarded(execution_lease_held))) return false;
        const frame = framing.encodeFrame(
            self.allocator,
            .{ .kind = .scroll_to_bottom, .stream_id = stream_id, .major = self.wire_major },
            "",
        ) catch return error.OutOfMemory;
        std.debug.assert(self.pending_outbound == null);
        self.pending_outbound = .{ .frame = frame, .stream_id = stream_id };
        _ = try self.pumpPendingOutputGuarded(execution_lease_held);
        return true;
    }

    pub fn sendScrollToBottomNonBlockingUnderRegisteredOperationExecutionLease(
        self: *Client,
        capability: RegisteredOperationExecutionHandle,
        stream_id: u64,
    ) ClientError!bool {
        try self.requireRegisteredOperationExecutionCapability(capability);
        return self.sendScrollToBottomNonBlockingGuarded(stream_id, true);
    }

    /// Coalesced invalidation recovery control for the UI frame pump. It shares the one bounded
    /// pending outbound slot with input/core commands and never waits for a response.
    pub fn sendResyncNonBlocking(self: *Client, stream_id: u64) ClientError!bool {
        const operation_fence_held = try self.requireBlockingMode();
        defer if (operation_fence_held) self.endPublicMutation();
        return self.sendResyncNonBlockingGuarded(stream_id, false);
    }

    fn sendResyncNonBlockingGuarded(self: *Client, stream_id: u64, execution_lease_held: bool) ClientError!bool {
        if (!(try self.pumpPendingOutputGuarded(execution_lease_held))) return false;
        const frame = framing.encodeFrame(
            self.allocator,
            .{ .kind = .stream_ack, .stream_id = stream_id, .major = self.wire_major },
            "{\"action\":\"resync\"}",
        ) catch return error.OutOfMemory;
        std.debug.assert(self.pending_outbound == null);
        self.pending_outbound = .{ .frame = frame, .stream_id = stream_id };
        _ = try self.pumpPendingOutputGuarded(execution_lease_held);
        return true;
    }

    pub fn sendResyncNonBlockingUnderRegisteredOperationExecutionLease(
        self: *Client,
        capability: RegisteredOperationExecutionHandle,
        stream_id: u64,
    ) ClientError!bool {
        try self.requireRegisteredOperationExecutionCapability(capability);
        return self.sendResyncNonBlockingGuarded(stream_id, true);
    }

    /// host core command JSON을 응답 없는 stream frame으로 admission한다. true면 Client가 frame 소유권을
    /// 인수했고, false면 기존 outbound frame의 backpressure 때문에 caller가 bounded sticky queue에서 재시도해야 한다.
    pub fn sendCoreCommandNonBlocking(self: *Client, stream_id: u64, payload: []const u8) ClientError!bool {
        const operation_fence_held = try self.requireBlockingMode();
        defer if (operation_fence_held) self.endPublicMutation();
        return self.sendCoreCommandNonBlockingGuarded(stream_id, payload, false);
    }

    fn sendCoreCommandNonBlockingGuarded(self: *Client, stream_id: u64, payload: []const u8, execution_lease_held: bool) ClientError!bool {
        if (!self.runtime_core_command_v1) return false;
        if (!(try self.pumpPendingOutputGuarded(execution_lease_held))) return false;
        const frame = framing.encodeFrame(
            self.allocator,
            .{ .kind = .core_command, .stream_id = stream_id, .major = self.wire_major },
            payload,
        ) catch return error.OutOfMemory;
        std.debug.assert(self.pending_outbound == null);
        self.pending_outbound = .{ .frame = frame, .stream_id = stream_id };
        _ = try self.pumpPendingOutputGuarded(execution_lease_held);
        return true;
    }

    pub fn sendCoreCommandNonBlockingUnderRegisteredOperationExecutionLease(
        self: *Client,
        capability: RegisteredOperationExecutionHandle,
        stream_id: u64,
        payload: []const u8,
    ) ClientError!bool {
        try self.requireRegisteredOperationExecutionCapability(capability);
        return self.sendCoreCommandNonBlockingGuarded(stream_id, payload, true);
    }

    /// 이미 RemoteRuntime의 ordered input FIFO가 소유한 scroll barrier를 후속 blocking RPC보다 먼저 보낸다.
    /// `call`과 마찬가지로 기존 nonblocking frame을 먼저 끝내므로 connection wire 순서는 보존된다.
    pub fn sendScrollToBottom(self: *Client, stream_id: u64) ClientError!void {
        const operation_fence_held = try self.requireBlockingMode();
        defer if (operation_fence_held) self.endPublicMutation();
        return self.sendScrollToBottomGuardedWithOps(stream_id, .posix_ops, false);
    }

    fn sendScrollToBottomWithOps(
        self: *Client,
        stream_id: u64,
        ops: PreparedExecutionWriteOps,
    ) ClientError!void {
        const operation_fence_held = try self.requireBlockingMode();
        defer if (operation_fence_held) self.endPublicMutation();
        return self.sendScrollToBottomGuardedWithOps(stream_id, ops, false);
    }

    fn sendScrollToBottomGuardedWithOps(
        self: *Client,
        stream_id: u64,
        ops: PreparedExecutionWriteOps,
        execution_lease_held: bool,
    ) ClientError!void {
        if (!self.async_scroll_to_bottom_v1) return;
        try self.flushPendingOutboundBlockingMode(execution_lease_held);
        const frame = framing.encodeFrame(
            self.allocator,
            .{ .kind = .scroll_to_bottom, .stream_id = stream_id, .major = self.wire_major },
            "",
        ) catch return error.OutOfMemory;
        defer self.allocator.free(frame);
        try self.writeBlockingStreamFrameWithOps(frame, ops, execution_lease_held);
    }

    pub fn sendScrollToBottomUnderRegisteredOperationExecutionLease(
        self: *Client,
        capability: RegisteredOperationExecutionHandle,
        stream_id: u64,
    ) ClientError!void {
        try self.requireRegisteredOperationExecutionCapability(capability);
        return self.sendScrollToBottomGuardedWithOps(stream_id, .posix_ops, true);
    }

    /// RemoteRuntime의 ordered queue를 뒤따르는 blocking RPC 직전에 남은 core frame을 전량 보낸다. 응답은 없지만
    /// 기존 pending frame을 먼저 끝내므로 connection wire FIFO를 보존한다.
    pub fn sendCoreCommand(self: *Client, stream_id: u64, payload: []const u8) ClientError!void {
        const operation_fence_held = try self.requireBlockingMode();
        defer if (operation_fence_held) self.endPublicMutation();
        return self.sendCoreCommandGuardedWithOps(stream_id, payload, .posix_ops, false);
    }

    fn sendCoreCommandWithOps(
        self: *Client,
        stream_id: u64,
        payload: []const u8,
        ops: PreparedExecutionWriteOps,
    ) ClientError!void {
        const operation_fence_held = try self.requireBlockingMode();
        defer if (operation_fence_held) self.endPublicMutation();
        return self.sendCoreCommandGuardedWithOps(stream_id, payload, ops, false);
    }

    fn sendCoreCommandGuardedWithOps(
        self: *Client,
        stream_id: u64,
        payload: []const u8,
        ops: PreparedExecutionWriteOps,
        execution_lease_held: bool,
    ) ClientError!void {
        if (!self.runtime_core_command_v1) return;
        try self.flushPendingOutboundBlockingMode(execution_lease_held);
        const frame = framing.encodeFrame(
            self.allocator,
            .{ .kind = .core_command, .stream_id = stream_id, .major = self.wire_major },
            payload,
        ) catch return error.OutOfMemory;
        defer self.allocator.free(frame);
        try self.writeBlockingStreamFrameWithOps(frame, ops, execution_lease_held);
    }

    pub fn sendCoreCommandUnderRegisteredOperationExecutionLease(
        self: *Client,
        capability: RegisteredOperationExecutionHandle,
        stream_id: u64,
        payload: []const u8,
    ) ClientError!void {
        try self.requireRegisteredOperationExecutionCapability(capability);
        return self.sendCoreCommandGuardedWithOps(stream_id, payload, .posix_ops, true);
    }

    fn writeBlockingStreamFrameWithOps(
        self: *Client,
        frame: []const u8,
        ops: PreparedExecutionWriteOps,
        execution_lease_held: bool,
    ) ClientError!void {
        var offset: usize = 0;
        while (offset < frame.len) {
            switch (ops.writeFn(ops.context, self.fd, frame[offset..])) {
                .interrupted => continue,
                .would_block, .zero, .failed => {
                    self.poisonMutationIo(.outbound_write_ambiguous, execution_lease_held);
                    return error.WriteFailed;
                },
                .written => |written| {
                    if (written == 0 or written > frame.len - offset) {
                        self.poisonMutationIo(.local_invariant_violation, execution_lease_held);
                        return error.WriteFailed;
                    }
                    offset += written;
                },
            }
        }
    }

    /// pending outbound frame의 남은 wire bytes를 blocking으로 전량 보낸다. 부분 write마다 offset을 진전시켜 오류 뒤 같은 prefix를
    /// 다시 보낼 가능성을 없앤다. hard error면 이 socket은 framing 경계를 복구할 수 없으므로 connection을 닫는다.
    fn flushPendingOutboundBlocking(self: *Client) ClientError!void {
        return self.flushPendingOutboundBlockingMode(false);
    }

    fn flushPendingOutboundBlockingMode(
        self: *Client,
        execution_lease_held: bool,
    ) ClientError!void {
        return self.flushPendingOutboundBlockingWithOps(null, .posix_ops, execution_lease_held);
    }

    /// MSG_DONTWAIT로 pending frame을 가능한 만큼 민다. true면 슬롯이 비었고 새 payload를 받을 수 있다. EAGAIN은 정상
    /// backpressure라 false이며, 다른 오류는 partial frame 뒤 framing 복구가 불가능하므로 connection을 닫는다. Darwin은
    /// MSG_DONTWAIT만으로 blocking socket의 send가 멈추는 동작이 보장되지 않아 helper가 호출 구간에 O_NONBLOCK도 함께 건다.
    pub fn pumpPendingOutput(self: *Client) ClientError!bool {
        const operation_fence_held = try self.requireBlockingMode();
        defer if (operation_fence_held) self.endPublicMutation();
        return self.pumpPendingOutputGuarded(false);
    }

    fn pumpPendingOutputGuarded(self: *Client, execution_lease_held: bool) ClientError!bool {
        while (self.pending_outbound) |*pending| {
            const remaining = pending.frame[pending.offset..];
            switch (try self.sendDontWait(remaining, execution_lease_held)) {
                .would_block => return false,
                .written => |written| {
                    pending.offset += written;
                    if (pending.offset == pending.frame.len) self.clearPendingOutbound();
                },
            }
        }
        return true;
    }

    pub fn pumpPendingOutputUnderRegisteredOperationExecutionLease(
        self: *Client,
        capability: RegisteredOperationExecutionHandle,
    ) ClientError!bool {
        try self.requireRegisteredOperationExecutionCapability(capability);
        return self.pumpPendingOutputGuarded(true);
    }

    /// Active generation events block every TX admission, but the shared socket still has to
    /// demultiplex incoming frames so sibling runtimes do not stall behind the event owner. The
    /// caller must already own ClientSlot's registered-operation execution lease; this path reads
    /// only RX and preserves any completed screen batch in the canonical bounded inbox.
    pub fn pumpRxDemuxUnderRegisteredOperationExecutionLease(
        self: *Client,
        capability: RegisteredOperationExecutionHandle,
    ) ClientError!void {
        try self.requireRegisteredOperationExecutionCapability(capability);
        if (self.ownership == .moved or self.unusable) return error.ConnectionClosed;
        const batch = self.readOneBatchWithIo(.polling, null, .registered_execution) catch |err| switch (err) {
            error.DeadlineExceeded => unreachable,
            error.CapacityExhausted,
            error.DestinationOccupied,
            error.IdentityExhausted,
            error.InvalidDescriptor,
            error.InvalidIdentity,
            error.InvalidReservation,
            error.InvalidState,
            error.InvalidStream,
            error.MovedOrCopied,
            => unreachable,
            else => |client_err| return client_err,
        };
        if (batch) |owned| try self.bufferPendingScreenBatch(owned);
    }

    pub const RevokeFence = enum {
        no_pending_stream_frame,
        cancelled_before_write,
        partial_frame_requires_close,
    };

    /// Revoke may race a frame already admitted by a previous UI turn. A zero-byte frame can be
    /// removed without changing the wire; a partial frame cannot be truncated without corrupting
    /// framing and requires connection fail-close. Another stream's frame is unrelated and stays.
    pub fn fenceRevokedStream(self: *Client, stream_id: u64) ClientError!RevokeFence {
        const operation_fence_held = try self.requireBlockingMode();
        defer if (operation_fence_held) self.endPublicMutation();
        const pending = self.pending_outbound orelse return .no_pending_stream_frame;
        if (pending.stream_id != stream_id) return .no_pending_stream_frame;
        if (pending.offset != 0) return .partial_frame_requires_close;
        self.clearPendingOutbound();
        return .cancelled_before_write;
    }

    /// A shared GUI connection must let the owning RemoteRuntime consume every buffered revoke
    /// before any sibling admits or flushes mutation. This is a connection-wide priority latch;
    /// the stream-local consumer still performs strict decode and generation transition.
    pub fn hasBufferedControllerRevoke(self: *const Client) bool {
        return self.hasBufferedControllerRevokeForStream(null);
    }

    /// 권위 판정용 stream-local latch. foreign revoke는 shared wire 진행만 멈추지만 이 stream의
    /// revoke는 role cache가 아직 controller여도 새 mutation을 받아서는 안 된다.
    pub fn hasBufferedControllerRevokeForStream(self: *const Client, stream_id: ?u64) bool {
        // Busy is conservative for an admission latch: callers stop mutation without observing
        // the event graph while an exclusive owner is compacting it.
        const operation_fence_held = self.beginPublicMutation() catch return true;
        defer if (operation_fence_held) self.endPublicMutation();
        return self.bufferedControllerRevokeForStreamUnchecked(stream_id);
    }

    fn bufferedControllerRevokeForStreamUnchecked(
        self: *const Client,
        stream_id: ?u64,
    ) bool {
        const event_allocator = self.canonicalEventAllocator() catch return true;
        for (self.pending_events.items) |frame| {
            if (!frame.sealMatches(event_allocator)) return true;
            const verdict = frame.preflight orelse
                runtime_event_wire.preflightEvent(frame.payload, .{});
            switch (verdict) {
                .accepted => |accepted| {
                    switch (accepted.event) {
                        .revoked => |revoked| {
                            // Header/payload disagreement is itself authority-ambiguous and must
                            // close every mutation latch. Otherwise global sees every revoke while
                            // a stream-local query closes for either exact routing identity.
                            if (revoked.stream_id != frame.header.stream_id) return true;
                            if (stream_id) |expected| {
                                if (frame.header.stream_id == expected) return true;
                            } else return true;
                        },
                        else => {},
                    }
                },
                else => {},
            }
        }
        return false;
    }

    const NonblockingSend = union(enum) {
        written: usize,
        would_block,
    };

    /// macOS에서 실 non-blocking을 보장하기 위해 send 구간에만 descriptor O_NONBLOCK을 켰다가 원 flags로 되돌린다.
    /// Client outbound/read는 GUI frame thread에서 직렬 호출한다는 현재 계약에 기대며, flags 복원 실패 시 이후 blocking
    /// call의 의미가 바뀌므로 같은 connection을 계속 쓰지 않고 fail-closed한다.
    fn sendDontWait(self: *Client, bytes: []const u8, execution_lease_held: bool) ClientError!NonblockingSend {
        const flags = c.fcntl(self.fd, c.F.GETFL, @as(c_int, 0));
        if (flags < 0) {
            self.poisonMutationIo(.local_invariant_violation, execution_lease_held);
            return error.WriteFailed;
        }
        const nonblock_flag: c_int = @bitCast(posix.O{ .NONBLOCK = true });
        const changed = flags & nonblock_flag == 0;
        if (changed and c.fcntl(self.fd, c.F.SETFL, flags | nonblock_flag) < 0) {
            self.poisonMutationIo(.local_invariant_violation, execution_lease_held);
            return error.WriteFailed;
        }

        var rc: isize = undefined;
        var send_errno: ?posix.E = null;
        while (true) {
            rc = c.send(self.fd, bytes.ptr, bytes.len, posix.MSG.DONTWAIT);
            if (rc >= 0) break;
            send_errno = posix.errno(rc);
            if (send_errno.? == .INTR) continue;
            break;
        }

        if (changed and c.fcntl(self.fd, c.F.SETFL, flags) < 0) {
            self.poisonMutationIo(.local_invariant_violation, execution_lease_held);
            return error.WriteFailed;
        }
        if (rc > 0) return .{ .written = @intCast(rc) };
        if (rc < 0 and send_errno.? == .AGAIN) return .would_block;
        self.poisonMutationIo(.outbound_write_ambiguous, execution_lease_held);
        return error.WriteFailed;
    }

    fn clearPendingOutbound(self: *Client) void {
        const pending = self.pending_outbound orelse return;
        const allocator = self.allocator;
        self.pending_outbound = null;
        allocator.free(pending.frame);
    }

    /// 다음 완성 frame을 읽는다(partial read 재조립). EOF/timeout는 ConnectionClosed, codec 위반은 ProtocolError.
    fn readFrame(self: *Client) ClientError!framing.Frame {
        return self.readFrameWithAllocator(null);
    }

    fn readFrameWithAllocator(
        self: *Client,
        payload_allocator_out: ?*std.mem.Allocator,
    ) ClientError!framing.Frame {
        return self.readFrameWithAllocatorObserved(payload_allocator_out, null);
    }

    fn readFrameWithAllocatorObserved(
        self: *Client,
        payload_allocator_out: ?*std.mem.Allocator,
        observer: ?framing.PayloadAllocationObserver,
    ) ClientError!framing.Frame {
        const operation_fence_held = try self.ensureUsable();
        defer if (operation_fence_held) self.endPublicMutation();
        return self.readFrameWithAllocatorObservedUnchecked(
            payload_allocator_out,
            observer,
            false,
        );
    }

    fn readFrameWithAllocatorObservedUnderExecutionLease(
        self: *Client,
        payload_allocator_out: ?*std.mem.Allocator,
        observer: ?framing.PayloadAllocationObserver,
    ) ClientError!framing.Frame {
        return self.readFrameWithAllocatorObservedUnchecked(
            payload_allocator_out,
            observer,
            true,
        );
    }

    fn readFrameWithAllocatorObservedUnchecked(
        self: *Client,
        payload_allocator_out: ?*std.mem.Allocator,
        observer: ?framing.PayloadAllocationObserver,
        execution_lease_held: bool,
    ) ClientError!framing.Frame {
        var buf: [4096]u8 = undefined;
        while (true) {
            const maybe_frame = if (observer) |active|
                self.parser.nextWithPayloadObserver(payload_allocator_out, active)
            else
                self.parser.nextWithAllocator(payload_allocator_out);
            if (maybe_frame catch |err| {
                self.poisonFrameRead(switch (err) {
                    error.OutOfMemory => .local_resource_exhausted,
                    error.PayloadIdentityExhausted, error.PayloadProvenanceRejected => .local_invariant_violation,
                    else => .frame_malformed,
                }, execution_lease_held);
                return switch (err) {
                    error.OutOfMemory => error.OutOfMemory,
                    else => error.ProtocolError,
                };
            }) |frame|
                return self.requireWireMajor(frame) catch |err| {
                    self.poisonFrameRead(.peer_contract_violation, execution_lease_held);
                    return err;
                };
            const n = c.read(self.fd, &buf, buf.len);
            if (n < 0) {
                const read_errno = posix.errno(n);
                if (read_errno == .INTR) continue;
                self.poisonFrameRead(if (read_errno == .AGAIN or read_errno == .TIMEDOUT)
                    .read_timeout
                else
                    .transport_read_failure, execution_lease_held);
                return if (read_errno == .AGAIN or read_errno == .TIMEDOUT)
                    error.EndpointTransient
                else
                    error.ConnectionClosed;
            }
            if (n == 0) {
                const partial = self.parser.bufferedBytes() != 0;
                self.poisonFrameRead(
                    if (partial) .frame_malformed else .connection_eof,
                    execution_lease_held,
                );
                return if (partial) error.ProtocolError else error.ConnectionClosed;
            }
            self.parser.push(buf[0..@intCast(n)]) catch {
                // 이미 socket에서 소비한 바이트를 parser에 보존하지 못했다. 다음 frame 경계를 복구할 수 없다.
                self.poisonFrameRead(.local_resource_exhausted, execution_lease_held);
                return error.OutOfMemory;
            };
        }
    }

    fn poisonFrameRead(
        self: *Client,
        reason: client_poison.ConnectionReason,
        execution_lease_held: bool,
    ) void {
        if (execution_lease_held)
            self.poisonWhilePreparedExecutionHeld(reason)
        else
            self.poison(reason);
    }

    /// Handshake-only incremental read. The socket remains nonblocking and every retry consumes
    /// the caller's one absolute phase deadline; unlike `readFrame`, this never creates a fresh
    /// timeout or mutates the established-client poison state.
    fn readFrameUntil(
        self: *Client,
        deadline: client_deadline.AbsoluteDeadline,
        ops: client_deadline.Ops,
    ) DeadlineClientError!framing.Frame {
        return self.readFrameUntilMode(deadline, ops, false, null, null) catch |err| switch (err) {
            error.PayloadProvenanceRejected => unreachable,
            else => |typed| return typed,
        };
    }

    /// Established RPCs use the handshake reader's one-deadline mechanics, but unlike handshake
    /// negotiation they must preserve the first connection-fatal transport/framing cause.
    fn readFrameUntilEstablished(
        self: *Client,
        deadline: client_deadline.AbsoluteDeadline,
        ops: client_deadline.Ops,
    ) DeadlineClientError!framing.Frame {
        return self.readFrameUntilMode(deadline, ops, true, null, null) catch |err| switch (err) {
            error.PayloadProvenanceRejected => unreachable,
            else => |typed| return typed,
        };
    }

    fn readFrameUntilEstablishedObserved(
        self: *Client,
        deadline: client_deadline.AbsoluteDeadline,
        ops: client_deadline.Ops,
        payload_allocator_out: ?*std.mem.Allocator,
        observer: ?framing.PayloadAllocationObserver,
    ) (DeadlineClientError || error{PayloadProvenanceRejected})!framing.Frame {
        return self.readFrameUntilMode(
            deadline,
            ops,
            true,
            payload_allocator_out,
            observer,
        );
    }

    fn readFrameUntilMode(
        self: *Client,
        deadline: client_deadline.AbsoluteDeadline,
        ops: client_deadline.Ops,
        poison_established: bool,
        payload_allocator_out: ?*std.mem.Allocator,
        observer: ?framing.PayloadAllocationObserver,
    ) (DeadlineClientError || error{PayloadProvenanceRejected})!framing.Frame {
        var buf: [4096]u8 = undefined;
        while (true) {
            if (deadline.remainingNs() <= 0) {
                if (poison_established) self.poisonWithOps(.read_timeout, ops);
                return error.DeadlineExceeded;
            }
            const maybe_frame = if (observer) |active|
                self.parser.nextWithPayloadObserver(payload_allocator_out, active)
            else if (payload_allocator_out != null)
                self.parser.nextWithAllocator(payload_allocator_out)
            else
                self.parser.next();
            if (maybe_frame catch |err| {
                if (poison_established) self.poisonWithOps(
                    switch (err) {
                        error.OutOfMemory => .local_resource_exhausted,
                        error.PayloadIdentityExhausted, error.PayloadProvenanceRejected => .local_invariant_violation,
                        else => .frame_malformed,
                    },
                    ops,
                );
                return switch (err) {
                    error.OutOfMemory => error.OutOfMemory,
                    error.PayloadProvenanceRejected => error.PayloadProvenanceRejected,
                    else => error.ProtocolError,
                };
            }) |frame| {
                if (deadline.remainingNs() <= 0) {
                    discardFramePayloadObservation(observer, frame);
                    const actual_allocator = if (payload_allocator_out) |out|
                        out.*
                    else
                        self.allocator;
                    frame.deinit(actual_allocator);
                    if (poison_established) self.poisonWithOps(.read_timeout, ops);
                    return error.DeadlineExceeded;
                }
                if (frame.header.major != self.wire_major) {
                    discardFramePayloadObservation(observer, frame);
                    const actual_allocator = if (payload_allocator_out) |out|
                        out.*
                    else
                        self.allocator;
                    frame.deinit(actual_allocator);
                    if (poison_established)
                        self.poisonWithOps(.peer_contract_violation, ops)
                    else
                        self.poison(.peer_contract_violation);
                    return error.ProtocolError;
                }
                return frame;
            }
            const n = client_deadline.readSomeUntil(
                ops,
                self.fd,
                &buf,
                deadline,
            ) catch |err| {
                if (poison_established) self.poisonWithOps(switch (err) {
                    error.Timeout => .read_timeout,
                    error.Closed => if (self.parser.bufferedBytes() == 0)
                        .connection_eof
                    else
                        .frame_malformed,
                    error.ReadFailed => .transport_read_failure,
                    else => .transport_read_failure,
                }, ops);
                return deadlineHelloError(err);
            };
            self.parser.push(buf[0..n]) catch {
                if (poison_established) self.poisonWithOps(.local_resource_exhausted, ops);
                return error.OutOfMemory;
            };
        }
    }

    /// parser·call 중 임시 stream queue 어느 경로에서 꺼낸 frame이든 같은 major gate를 거친다. 잘못된 major의
    /// payload는 caller에게 넘기지 않고 여기서 회수한다.
    fn requireWireMajor(self: *Client, frame: framing.Frame) ClientError!framing.Frame {
        if (frame.header.major != self.wire_major) {
            frame.deinit(self.allocator);
            self.poison(.peer_contract_violation);
            return error.ProtocolError;
        }
        return frame;
    }

    fn ensureUsable(self: *const Client) ClientError!bool {
        const operation_fence_held = try self.beginPublicMutation();
        errdefer if (operation_fence_held) self.endPublicMutation();
        if (checkedAllocatorReentry(self)) return error.AdminBusy;
        if (self.ownership == .moved or self.unusable) return error.ConnectionClosed;
        return operation_fence_held;
    }

    pub fn bindOperationFence(
        self: *Client,
        fence: *ClientOperationFence,
        fence_generation: u64,
    ) bool {
        if (self.operation_fence != null or self.operation_fence_generation != 0 or
            !fence.identityMatches(@intFromPtr(self), fence_generation))
            return false;
        self.operation_fence = fence;
        self.operation_fence_generation = fence_generation;
        return true;
    }

    pub fn tryAcquireEndedPurgeExclusive(
        self: *Client,
    ) error{ InvalidOwner, InvalidState, AdminBusy }!void {
        const fence = self.operation_fence orelse return error.InvalidState;
        return fence.tryAcquireExclusive(@intFromPtr(self), self.operation_fence_generation);
    }

    /// ClientSlot teardown acquires this before reading any mutable node-owned graph. Product
    /// source-boundary tests keep the acquire/release/commit path inside ClientSlot.tryDeinit.
    pub fn tryAcquireClientSlotTeardownExclusive(
        self: *Client,
    ) error{ InvalidOwner, InvalidState, AdminBusy }!void {
        const fence = self.operation_fence orelse return error.InvalidState;
        return fence.tryAcquireExclusive(@intFromPtr(self), self.operation_fence_generation);
    }

    pub fn abortClientSlotTeardownExclusive(self: *Client) bool {
        const fence = self.operation_fence orelse return false;
        return fence.abortExclusive(@intFromPtr(self), self.operation_fence_generation);
    }

    pub fn tryDeinitClientSlotExclusiveHeld(self: *Client) bool {
        const fence = self.operation_fence orelse return false;
        if (fence.intruded(@intFromPtr(self), self.operation_fence_generation)) return false;
        if (!self.prepareDeinitGraph(true)) return false;
        self.finishDeinitGraph();
        const client_addr = @intFromPtr(self);
        const operation_fence_generation = self.operation_fence_generation;
        if (!fence.commitExclusiveTerminal(client_addr, operation_fence_generation))
            @panic("ClientSlot Client deinit operation fence commit failed");
        self.* = undefined;
        return true;
    }

    pub fn endedPurgeFenceIntruded(self: *const Client) bool {
        const fence = self.operation_fence orelse return true;
        return fence.intruded(@intFromPtr(self), self.operation_fence_generation);
    }

    /// ClientSlot-only aggregate gate. Slot registry transactions use this around the publication
    /// of blockers that Client teardown preflights, so exclusive teardown cannot pass a stale
    /// all-idle snapshot. Source-boundary tests keep callers inside client_slot.zig.
    pub fn beginClientSlotOperation(self: *Client) ClientError!void {
        if (!(try self.beginPublicMutation())) return error.ConnectionClosed;
    }

    pub fn endClientSlotOperation(self: *Client) bool {
        if (self.operation_fence == null) return false;
        self.endPublicMutation();
        return true;
    }

    fn requireRegisteredOperationExecutionCapability(
        self: *const Client,
        handle: RegisteredOperationExecutionHandle,
    ) ClientError!void {
        // TLS and caller-final token checks precede every mutable Client graph read. The fence
        // then proves that this exact address/thread/identity owns the active execution lease.
        if (generationAllocatorCallbackActive()) return error.AdminBusy;
        var guard: PinnedExecutionCapabilityGuard = .{};
        if (!initRegisteredOperationExecutionCapabilityGuard(
            &guard,
            handle,
            @intFromPtr(self),
        )) return error.ConnectionClosed;
        defer guard.deinit();
        const capability = guard.capability.?;
        const fence = self.operation_fence orelse return error.ConnectionClosed;
        if (!fence.executionCapabilityMatches(
            @intFromPtr(self),
            self.operation_fence_generation,
            capability,
        )) return error.ConnectionClosed;
    }

    pub fn beginRegisteredOperationExecutionLease(
        self: *Client,
        capability: *RegisteredOperationExecutionCapability,
        receipt: *RegisteredOperationExecutionMintReceipt,
    ) ClientError!RegisteredOperationExecutionHandle {
        const owner_thread_id: u64 = @intCast(std.Thread.getCurrentId());
        if (generationAllocatorCallbackActive() or !capability.pristineExact())
            return error.AdminBusy;
        const authorization = operation_thread_identity.consumeMintReceipt(
            receipt,
            @intFromPtr(self),
        ) orelse return error.AdminBusy;
        const fence = self.operation_fence orelse return error.ConnectionClosed;
        fence.upgradeSingleSharedToExecutionLease(
            @intFromPtr(self),
            self.operation_fence_generation,
        ) catch |err| return switch (err) {
            error.AdminBusy => error.AdminBusy,
            error.InvalidOwner, error.InvalidState => error.ConnectionClosed,
        };
        errdefer if (!fence.downgradeExecutionLeaseToSingleShared(
            @intFromPtr(self),
            self.operation_fence_generation,
        )) @panic("registered operation execution fence rollback failed");
        const lease_identity = fence.issueExecutionCapabilityIdentity() orelse
            return error.ConnectionClosed;
        if (owner_thread_id == 0 or fence.execution_capability_addr.load(.acquire) != 0)
            return error.ConnectionClosed;
        capability.self_addr = @intFromPtr(capability);
        capability.client_addr = @intFromPtr(self);
        capability.fence_generation = self.operation_fence_generation;
        capability.fence_incarnation = fence.fence_incarnation;
        capability.lease_identity = lease_identity;
        capability.owner_process_id = authorization.owner_process_id;
        capability.owner_process_nonce = authorization.owner_process_nonce;
        capability.owner_thread_id = owner_thread_id;
        capability.owner_thread_incarnation = authorization.owner_thread_incarnation;
        capability.operation_identity = authorization.operation_identity;
        capability.live = true;
        capability.seal = capability.digest();
        var capability_committed = false;
        errdefer if (!capability_committed) capability.resetPristine();
        fence.execution_capability_identity.store(lease_identity, .monotonic);
        fence.execution_owner_thread_id.store(owner_thread_id, .monotonic);
        fence.execution_owner_thread_incarnation.store(authorization.owner_thread_incarnation, .monotonic);
        fence.execution_capability_addr.store(@intFromPtr(capability), .monotonic);
        var publication_committed = false;
        errdefer if (!publication_committed) {
            capability.publication_identity.store(0, .release);
            fence.execution_owner_thread_incarnation.store(0, .release);
            fence.execution_owner_thread_id.store(0, .release);
            fence.execution_capability_identity.store(0, .release);
            fence.execution_capability_addr.store(0, .release);
        };
        if (builtin.is_test and
            execution_capability_publication_test_hook.armed.swap(false, .acq_rel))
        {
            execution_capability_publication_test_hook.reached.store(true, .release);
            if (!ExecutionCapabilityPublicationTestHook.waitUntil(
                &execution_capability_publication_test_hook.proceed,
            )) @panic("execution capability publication test hook timed out");
        }
        capability.publication_identity.store(lease_identity, .release);
        const handle = operation_thread_identity.publishCapability(.{
            .capability_addr = @intFromPtr(capability),
            .publication_identity = lease_identity,
            .operation_identity = authorization.operation_identity,
            .client_addr = @intFromPtr(self),
            .fence_generation = self.operation_fence_generation,
            .fence_incarnation = fence.fence_incarnation,
            .owner_process_id = authorization.owner_process_id,
            .owner_process_nonce = authorization.owner_process_nonce,
            .owner_thread_id = owner_thread_id,
            .owner_thread_incarnation = authorization.owner_thread_incarnation,
        }) catch return error.AdminBusy;
        publication_committed = true;
        capability_committed = true;
        return handle;
    }

    pub fn setNextExecutionCapabilityIdentityForTest(self: *Client, value: u64) void {
        if (!builtin.is_test) unreachable;
        const fence = self.operation_fence orelse @panic("missing operation fence");
        fence.next_execution_capability_identity.store(value, .release);
    }

    pub fn nextExecutionCapabilityIdentityForTest(self: *const Client) u64 {
        if (!builtin.is_test) unreachable;
        const fence = self.operation_fence orelse @panic("missing operation fence");
        return fence.next_execution_capability_identity.load(.acquire);
    }

    pub fn endRegisteredOperationExecutionLease(
        self: *Client,
        handle: RegisteredOperationExecutionHandle,
    ) void {
        var guard: PinnedExecutionCapabilityGuard = .{};
        if (!initRegisteredOperationExecutionCapabilityGuard(
            &guard,
            handle,
            @intFromPtr(self),
        )) @panic("registered operation execution capability unpublished or foreign");
        defer guard.deinit();
        const capability = @constCast(guard.capability.?);
        const fence = self.operation_fence orelse
            @panic("registered operation execution fence disappeared");
        if (!fence.executionCapabilityMatches(
            @intFromPtr(self),
            self.operation_fence_generation,
            capability,
        )) @panic("registered operation execution capability drifted");
        if (!guard.close())
            @panic("registered operation execution capability close failed");
        if (capability.publication_identity.cmpxchgStrong(
            capability.lease_identity,
            0,
            .acq_rel,
            .acquire,
        ) != null) @panic("registered operation execution capability consume failed");
        fence.execution_owner_thread_incarnation.store(0, .release);
        fence.execution_owner_thread_id.store(0, .release);
        fence.execution_capability_identity.store(0, .release);
        fence.execution_capability_addr.store(0, .release);
        // The registry has retired this publication and drained all pinned readers. The body may
        // now leave scope; publication_identity == 0 remains the local consumed marker.
        if (!fence.downgradeExecutionLeaseToSingleShared(
            @intFromPtr(self),
            self.operation_fence_generation,
        )) @panic("registered operation execution fence release failed");
    }

    pub fn bufferedControllerRevokeUnderRegisteredOperationExecutionLease(
        self: *const Client,
        capability: RegisteredOperationExecutionHandle,
    ) ClientError!bool {
        try self.requireRegisteredOperationExecutionCapability(capability);
        return self.bufferedControllerRevokeForStreamUnchecked(null);
    }

    /// ClientSlot confirmed-poison owner only. The registered shared pin is upgraded to an
    /// execution lease so allocator callbacks and foreign-thread raw Client aliases cannot enter
    /// any public wire mutation until fd and pending-owner disposition are complete.
    pub fn beginConfirmedGenerationPoisonExclusive(self: *Client) ClientError!void {
        const fence = self.operation_fence orelse return error.ConnectionClosed;
        return fence.upgradeSingleSharedToExecutionLease(
            @intFromPtr(self),
            self.operation_fence_generation,
        ) catch |err| switch (err) {
            error.AdminBusy => error.AdminBusy,
            error.InvalidOwner, error.InvalidState => error.ConnectionClosed,
        };
    }

    pub fn endConfirmedGenerationPoisonExclusive(self: *Client) void {
        const fence = self.operation_fence orelse
            @panic("confirmed poison execution fence disappeared");
        if (!fence.downgradeExecutionLeaseToSingleShared(
            @intFromPtr(self),
            self.operation_fence_generation,
        )) @panic("confirmed poison execution fence release failed");
    }

    pub fn releaseEndedPurgeExclusiveClean(self: *Client) bool {
        const fence = self.operation_fence orelse return false;
        return fence.releaseExclusiveClean(@intFromPtr(self), self.operation_fence_generation);
    }

    pub fn commitEndedPurgeExclusiveTerminal(self: *Client) bool {
        const fence = self.operation_fence orelse return false;
        return fence.commitExclusiveTerminal(@intFromPtr(self), self.operation_fence_generation);
    }

    fn beginPublicMutation(self: *const Client) ClientError!bool {
        if (self.prepared_request_execution_lease_addr != 0 or
            self.prepared_request_execution_fence_addr != 0 or
            self.prepared_request_execution_fence_incarnation != 0 or
            self.prepared_request_execution_fence_lease_identity != 0 or
            self.prepared_request_execution_fence_mode != .unbound) return error.AdminBusy;
        const fence = self.operation_fence orelse {
            if (self.operation_fence_generation != 0) return error.ConnectionClosed;
            return false;
        };
        fence.tryEnterShared(@intFromPtr(self), self.operation_fence_generation) catch |err|
            return switch (err) {
                error.AdminBusy, error.CounterOverflow => error.AdminBusy,
                error.InvalidOwner, error.InvalidState => error.ConnectionClosed,
            };
        return true;
    }

    fn endPublicMutation(self: *const Client) void {
        const fence = self.operation_fence orelse
            @panic("bound Client operation fence disappeared");
        if (!fence.leaveShared(@intFromPtr(self), self.operation_fence_generation))
            @panic("Client operation fence shared release failed");
    }

    fn checkedAllocatorReentry(_: *const Client) bool {
        // allocator callback은 Client별이 아니라 thread-local이다. Client A의 callback 안에서는 Client B도
        // 막아야 한다. 그렇지 않으면 B가 wire byte를 소비한 뒤 interleaved OOB frame을 이미 소유한 상태에서야
        // active latch를 발견한다. 이 thread에 checked allocator owner가 하나라도 있으면 모든 public Client
        // 진입점은 wire/callback/free 전에 거부한다.
        return generationAllocatorCallbackActive();
    }

    fn exactAllocatorCallbackOwner(self: *const Client) bool {
        return checked_allocator_owner_addr == @intFromPtr(self);
    }

    pub fn enterGenerationAllocatorCallback(self: *Client) bool {
        if (checked_allocator_owner_addr != 0) return false;
        checked_allocator_owner_addr = @intFromPtr(self);
        return true;
    }

    pub fn rejectGenerationAllocatorCallbackReentry(self: *const Client) ClientError!void {
        if (checkedAllocatorReentry(self)) return error.AdminBusy;
    }

    pub fn leaveGenerationAllocatorCallbackUnchecked(_: *Client) void {
        checked_allocator_owner_addr = 0;
    }

    fn requireBlockingMode(self: *const Client) ClientError!bool {
        const operation_fence_held = try self.ensureUsable();
        errdefer if (operation_fence_held) self.endPublicMutation();
        if (self.io_mode == .external) return error.ExternalMode;
        return operation_fence_held;
    }

    fn poisonWithOps(
        self: *Client,
        reason: client_poison.ConnectionReason,
        ops: client_deadline.Ops,
    ) void {
        self.latchFirstPoisonReason(reason);
        if (self.poisonAndTakeFd()) |fd| ops.close(ops.context, fd);
    }

    fn poisonAndTakeFd(self: *Client) ?c.fd_t {
        // pending frame은 connection 소유 메모리다. 이미 unusable이어도 deinit 전 명시 invalidate가 재진입할 수 있으므로
        // 항상 회수 helper를 거친다. fd를 먼저 Client에서 떼어낸 뒤 정확히 한 close strategy만 실행한다.
        if (!self.prepareExternalModeDeinit()) return null;
        self.clearPendingOutbound();
        if (self.unusable) return null;
        self.unusable = true;
        if (self.fd < 0) return null;
        const fd = self.fd;
        self.fd = -1;
        return fd;
    }

    fn latchFirstPoisonReason(self: *Client, reason: client_poison.ConnectionReason) void {
        if (self.first_poison_reason == null) {
            self.first_poison_reason = reason;
        }
    }

    /// External transfer normalization may already hold the RX owner lease, so it cannot run the
    /// ordinary close path reentrantly. Latch the exact cause and make the Client terminal; the
    /// existing final owner teardown releases the fd and external storage after the lease returns.
    fn markPoisonedForDeferredCleanup(
        self: *Client,
        reason: client_poison.ConnectionReason,
    ) void {
        self.latchFirstPoisonReason(reason);
        self.unusable = true;
    }

    pub fn markDeferredPoisonForTest(
        self: *Client,
        reason: client_poison.ConnectionReason,
    ) ClientError!void {
        if (!builtin.is_test) return error.ConnectionClosed;
        const operation_fence_held = try self.beginPublicMutation();
        defer if (operation_fence_held) self.endPublicMutation();
        self.markPoisonedForDeferredCleanup(reason);
    }

    /// ClientSlot-only fail-closed publication while its registered shared operation keeps the
    /// canonical node alive. The final owner closes the fd after that operation is released.
    pub fn poisonDuringClientSlotOperationNoFail(
        self: *Client,
        reason: client_poison.ConnectionReason,
    ) void {
        if (self.operation_fence == null)
            @panic("ClientSlot deferred poison requires an operation fence");
        self.markPoisonedForDeferredCleanup(reason);
    }

    /// Incident publication commit 뒤 ClientSlot-held operation에서만 쓰는 no-reread suffix다.
    /// first reason은 coordinator가 이미 게시했으므로 여기서는 다시 latch하지 않는다.
    pub fn terminalizePublishedIncidentChecked(
        self: *Client,
        reason: client_poison.ConnectionReason,
    ) error{InvalidOwner}!?c.fd_t {
        if (self.operation_fence == null or self.first_poison_reason != reason) return error.InvalidOwner;
        return self.poisonAndTakeFd();
    }

    pub fn terminalReasonInvariant(self: *const Client) bool {
        const operation_fence_held = self.beginPublicMutation() catch return false;
        defer if (operation_fence_held) self.endPublicMutation();
        return !self.unusable or self.ownership == .moved or self.first_poison_reason != null;
    }

    /// poison 이 **어디서** 불렸는지 남긴다.
    ///
    /// `local_invariant_violation` 하나로 접히는 자리가 이 파일에만 74 곳이다. incident 는 결론(`reason`)과
    /// 대략의 구역(`source_site`)만 담고 DTO 의 scalar 집합이 고정이라 호출 지점을 실을 자리가 없다.
    /// 2026-08-27 실측: incident 22 건이 전부 `local_invariant_violation`·`client_read` 로 같아 74 곳 중
    /// 어디인지 좁히지 못했다. 호출자 주소 한 개면 `atos`/`llvm-symbolizer` 로 그 자리를 곧장 짚는다.
    ///
    /// 판정에는 관여하지 않는다 — fail-closed 는 그대로이고 사유만 적는다.
    /// prepared 응답이 **빈 payload** 로 왔다. 그 자체가 계약 위반이라 여기서 사유를 남긴다.
    fn logEmptyPreparedResponse(self: *const Client, request_id: u64) void {
        if (builtin.is_test) return;
        std.log.err(
            "empty prepared response: request_id={d} host={x:0>32} wire_major={d} lifecycle={s} last_success_request_id={d}",
            .{ request_id, self.host_id, self.wire_major, self.lifecycle, self.last_success_request_id },
        );
    }

    /// 이미 캡처된 poison 에 **다른 사유**가 뒤따랐다. 첫 사유를 유지하고 두 번째는 버리되, 그 사실을 남긴다.
    /// 사유가 갈리는 것 자체는 정상이지만(정리 중 2 차 실패), 어떤 조합이 실제로 일어나는지는 알아야 한다.
    /// read pump 쪽 짝. prepared execution 과 사유 공간이 달라 로그를 섞지 않는다.
    fn logReadPumpPoisonReasonDrift(kept_raw: u8, dropped_raw: u8) void {
        if (builtin.is_test) return;
        std.log.err(
            "read pump poison reason drift: kept={d} dropped={d}",
            .{ kept_raw, dropped_raw },
        );
    }

    fn logPoisonReasonDrift(kept_raw: u8, dropped_raw: u8) void {
        if (builtin.is_test) return;
        std.log.err(
            "prepared execution poison reason drift: kept={d} dropped={d}",
            .{ kept_raw, dropped_raw },
        );
    }

    fn logPoisonCallSite(reason: client_poison.ConnectionReason, ra: usize) void {
        if (builtin.is_test) return;
        std.log.err("client poison: reason={s} return_address=0x{x}", .{ @tagName(reason), ra });
    }

    /// lifecycle cleanup frame조차 할당할 수 없는 경우 host가 EOF로 attachment를 정리하도록 shared connection을
    /// 명시적으로 닫는 fail-closed fallback.
    pub fn poison(self: *Client, reason: client_poison.ConnectionReason) void {
        logPoisonCallSite(reason, @returnAddress());
        // A checked allocator callback inside managed prepared execution cannot reacquire the
        // operation fence. It may only write the caller-final capture already sealed into that
        // lease; post-operation publication remains the sole Client/ring mutation owner.
        if (self.exactAllocatorCallbackOwner() and self.prepared_request_execution_lease_addr != 0) {
            const lease: *const PreparedRequestExecutionLease =
                @ptrFromInt(self.prepared_request_execution_lease_addr);
            if (self.capturePreparedExecutionPoison(reason, lease.poison_allocator_source_site_raw))
                return;
        }
        if (self.captureReadPumpPoison(reason)) return;
        // The cross-thread fence must win over the same-thread allocator diagnostic. During an
        // exclusive cleanup callback even the deferred poison path may not touch Client storage;
        // the rejected shared entry records intrusion and the owner converges to quarantine.
        const operation_fence_held = self.beginPublicMutation() catch return;
        defer if (operation_fence_held) self.endPublicMutation();
        if (checkedAllocatorReentry(self)) {
            self.markPoisonedForDeferredCleanup(reason);
            return;
        }
        self.latchFirstPoisonReason(reason);
        if (self.poisonAndTakeFd()) |fd| _ = c.close(fd);
        std.debug.assert(self.terminalReasonInvariant());
    }

    /// app-quit graph가 backend와 allocator를 살려 둔 채 shared data socket만 먼저 끊을 때 쓴다.
    /// 이 단계가 실패하면 뒤 owner를 추측해 파괴할 수 없으므로 caller는 graph destroy를 진행하지 않는다.
    pub fn canTerminalizeSharedConnectionNoDestroy(self: *Client) bool {
        const operation_fence_held = self.beginPublicMutation() catch return false;
        defer if (operation_fence_held) self.endPublicMutation();
        return !checkedAllocatorReentry(self) and self.ownership != .moved;
    }

    pub fn terminalizeSharedConnectionNoDestroy(self: *Client) bool {
        const operation_fence_held = self.beginPublicMutation() catch return false;
        defer if (operation_fence_held) self.endPublicMutation();
        if (checkedAllocatorReentry(self)) return false;
        self.latchFirstPoisonReason(.connection_eof);
        if (self.poisonAndTakeFd()) |fd| _ = c.close(fd);
        return self.unusable and self.fd == -1 and self.pending_outbound == null;
    }

    pub fn firstPoisonReason(self: *const Client) ?client_poison.ConnectionReason {
        const operation_fence_held = self.beginPublicMutation() catch return null;
        defer if (operation_fence_held) self.endPublicMutation();
        return self.first_poison_reason;
    }
};

test "CR4a client demux는 sibling screen과 barrier를 보존하고 exact identity만 소비한다" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    var fds: [2]c.fd_t = undefined;
    try std.testing.expectEqual(@as(c_int, 0), c.socketpair(posix.AF.UNIX, posix.SOCK.STREAM, 0, &fds));
    defer _ = c.close(fds[1]);
    var client = makeConnectedTestClient(allocator, fds[0]);
    client.runtime_catchup_barrier_v1 = true;
    defer client.deinit();

    const sibling_screen = try framing.encodeFrame(
        allocator,
        .{ .kind = .delta_chunk, .stream_id = 9, .flags = protocol.Flags.end_stream },
        "sibling-screen",
    );
    defer allocator.free(sibling_screen);
    try socket_server.writeAll(fds[1], sibling_screen);

    const target_identity: catchup_barrier_contract.CatchupIdentity = .{
        .subscription = .{ .value = 11 },
        .runtime_id = 12,
        .connection = .{ .monotonic_id = 13, .slot_generation = 14 },
        .host_id = 15,
        .request_nonce = 16,
    };
    var sibling_identity = target_identity;
    sibling_identity.subscription.value = 21;
    sibling_identity.runtime_id = 22;
    sibling_identity.request_nonce = 23;
    const sibling_barrier: catchup_barrier_contract.Barrier = .{
        .identity = sibling_identity,
        .target = .{ .generation = 3, .sequence = 7 },
    };
    const target_barrier: catchup_barrier_contract.Barrier = .{
        .identity = target_identity,
        .target = .{ .generation = 4, .sequence = 8 },
    };
    inline for (.{
        .{ @as(u64, 8), sibling_barrier },
        .{ @as(u64, 7), target_barrier },
    }) |entry| {
        const payload = try entry[1].encode();
        const wire_frame = try framing.encodeFrame(
            allocator,
            .{ .kind = .screen_frontier_barrier, .stream_id = entry[0] },
            &payload,
        );
        defer allocator.free(wire_frame);
        try socket_server.writeAll(fds[1], wire_frame);
    }

    const deadline = try client_deadline.AbsoluteDeadline.after(std.testing.io, std.time.ns_per_s);
    try std.testing.expectEqualDeep(
        target_barrier,
        try client.readCatchupBarrierUntil(7, target_identity, deadline),
    );
    try std.testing.expectEqual(@as(usize, 1), client.pending_batches.items.len);
    try std.testing.expectEqual(@as(u64, 9), client.pending_batches.items[0].stream_id);
    try std.testing.expectEqualStrings("sibling-screen", client.pending_batches.items[0].bytes);
    try std.testing.expectEqual(@as(usize, 1), client.pending_catchup_barriers.items.len);
    try std.testing.expectEqual(@as(u64, 8), client.pending_catchup_barriers.items[0].stream_id);
    try std.testing.expectEqualDeep(
        sibling_barrier,
        try client.readCatchupBarrierUntil(8, sibling_identity, deadline),
    );
    try std.testing.expectEqual(@as(usize, 0), client.pending_catchup_barriers.items.len);
}

test "CR4a client demux는 capability와 identity drift를 barrier 소비 전에 거부한다" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const identity: catchup_barrier_contract.CatchupIdentity = .{
        .subscription = .{ .value = 31 },
        .runtime_id = 32,
        .connection = .{ .monotonic_id = 33, .slot_generation = 34 },
        .host_id = 35,
        .request_nonce = 36,
    };
    const barrier: catchup_barrier_contract.Barrier = .{
        .identity = identity,
        .target = .{ .generation = 1, .sequence = 2 },
    };
    inline for (.{ @as(u8, 0), 1, 2, 3 }) |hostile| {
        var fds: [2]c.fd_t = undefined;
        try std.testing.expectEqual(@as(c_int, 0), c.socketpair(posix.AF.UNIX, posix.SOCK.STREAM, 0, &fds));
        defer _ = c.close(fds[1]);
        var client = makeConnectedTestClient(allocator, fds[0]);
        client.runtime_catchup_barrier_v1 = hostile != 0;
        defer client.deinit();
        if (hostile == 2) {
            client.partial_batch = .{ .stream_id = 7, .is_snapshot = false };
            try client.partial_batch.?.bytes.appendSlice(allocator, "unfinished-target");
        } else if (hostile == 3) {
            const unfinished = try allocator.dupe(u8, "unfinished-raw-target");
            try client.pending_stream.append(allocator, .{
                .header = .{ .kind = .delta_chunk, .stream_id = 7 },
                .payload = unfinished,
            });
            client.pending_stream_bytes = unfinished.len;
        }
        const payload = try barrier.encode();
        const wire_frame = try framing.encodeFrame(
            allocator,
            .{ .kind = .screen_frontier_barrier, .stream_id = 7 },
            &payload,
        );
        defer allocator.free(wire_frame);
        try socket_server.writeAll(fds[1], wire_frame);
        var expected = identity;
        if (hostile == 1) expected.runtime_id += 1;
        const deadline = try client_deadline.AbsoluteDeadline.after(std.testing.io, std.time.ns_per_s);
        try std.testing.expectError(
            error.ProtocolError,
            client.readCatchupBarrierUntil(7, expected, deadline),
        );
        try std.testing.expect(client.unusable);
        try std.testing.expectEqual(
            client_poison.ConnectionReason.peer_contract_violation,
            client.firstPoisonReason().?,
        );
        try std.testing.expectEqual(@as(usize, 0), client.pending_catchup_barriers.items.len);
    }
}

test "CR4a client demux는 duplicate cap과 append OOM을 fail close한다" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const base_identity: catchup_barrier_contract.CatchupIdentity = .{
        .subscription = .{ .value = 51 },
        .runtime_id = 52,
        .connection = .{ .monotonic_id = 53, .slot_generation = 54 },
        .host_id = 55,
        .request_nonce = 56,
    };

    inline for (.{ false, true }) |same_stream| {
        var fds: [2]c.fd_t = undefined;
        try std.testing.expectEqual(
            @as(c_int, 0),
            c.socketpair(posix.AF.UNIX, posix.SOCK.STREAM, 0, &fds),
        );
        defer _ = c.close(fds[1]);
        var client = makeConnectedTestClient(allocator, fds[0]);
        client.runtime_catchup_barrier_v1 = true;
        defer client.deinit();
        try client.pending_catchup_barriers.append(allocator, .{
            .stream_id = 7,
            .barrier = .{
                .identity = base_identity,
                .target = .{ .generation = 1, .sequence = 2 },
            },
        });
        var incoming_identity = base_identity;
        if (same_stream) incoming_identity.request_nonce += 1;
        const incoming: catchup_barrier_contract.Barrier = .{
            .identity = incoming_identity,
            .target = .{ .generation = 1, .sequence = 3 },
        };
        const incoming_payload = try incoming.encode();
        const owned_payload = try allocator.dupe(u8, &incoming_payload);
        try std.testing.expectError(
            error.ProtocolError,
            client.bufferCatchupBarrierFrame(.{
                .header = .{
                    .kind = .screen_frontier_barrier,
                    .stream_id = if (same_stream) 7 else 8,
                    .payload_len = catchup_barrier_contract.payload_size,
                },
                .payload = owned_payload,
            }, allocator, false),
        );
        try std.testing.expect(client.unusable);
        try std.testing.expectEqual(@as(c.fd_t, -1), client.fd);
        try std.testing.expectEqual(@as(usize, 1), client.pending_catchup_barriers.items.len);
    }

    var cap_fds: [2]c.fd_t = undefined;
    try std.testing.expectEqual(
        @as(c_int, 0),
        c.socketpair(posix.AF.UNIX, posix.SOCK.STREAM, 0, &cap_fds),
    );
    defer _ = c.close(cap_fds[1]);
    var cap_client = makeConnectedTestClient(allocator, cap_fds[0]);
    cap_client.runtime_catchup_barrier_v1 = true;
    defer cap_client.deinit();
    try cap_client.pending_catchup_barriers.ensureTotalCapacityPrecise(
        allocator,
        protocol.max_client_screen_items,
    );
    for (0..protocol.max_client_screen_items) |index| {
        var identity = base_identity;
        identity.subscription.value += index;
        identity.request_nonce += index;
        cap_client.pending_catchup_barriers.appendAssumeCapacity(.{
            .stream_id = index + 1,
            .barrier = .{
                .identity = identity,
                .target = .{ .generation = 1, .sequence = index },
            },
        });
    }
    var cap_identity = base_identity;
    cap_identity.subscription.value += protocol.max_client_screen_items;
    cap_identity.request_nonce += protocol.max_client_screen_items;
    const cap_payload = try (catchup_barrier_contract.Barrier{
        .identity = cap_identity,
        .target = .{ .generation = 1, .sequence = protocol.max_client_screen_items },
    }).encode();
    const cap_owned = try allocator.dupe(u8, &cap_payload);
    try std.testing.expectError(
        error.EventQueueFull,
        cap_client.bufferCatchupBarrierFrame(.{
            .header = .{
                .kind = .screen_frontier_barrier,
                .stream_id = protocol.max_client_screen_items + 1,
                .payload_len = catchup_barrier_contract.payload_size,
            },
            .payload = cap_owned,
        }, allocator, false),
    );
    try std.testing.expect(cap_client.unusable);
    try std.testing.expectEqual(
        protocol.max_client_screen_items,
        cap_client.pending_catchup_barriers.items.len,
    );

    var oom_fds: [2]c.fd_t = undefined;
    try std.testing.expectEqual(
        @as(c_int, 0),
        c.socketpair(posix.AF.UNIX, posix.SOCK.STREAM, 0, &oom_fds),
    );
    defer _ = c.close(oom_fds[1]);
    var failing = std.testing.FailingAllocator.init(allocator, .{ .fail_index = 0 });
    var oom_client = makeConnectedTestClient(failing.allocator(), oom_fds[0]);
    oom_client.runtime_catchup_barrier_v1 = true;
    defer oom_client.deinit();
    const oom_payload = try (catchup_barrier_contract.Barrier{
        .identity = base_identity,
        .target = .{ .generation = 1, .sequence = 2 },
    }).encode();
    const oom_owned = try allocator.dupe(u8, &oom_payload);
    try std.testing.expectError(
        error.OutOfMemory,
        oom_client.bufferCatchupBarrierFrame(.{
            .header = .{
                .kind = .screen_frontier_barrier,
                .stream_id = 7,
                .payload_len = catchup_barrier_contract.payload_size,
            },
            .payload = oom_owned,
        }, allocator, false),
    );
    try std.testing.expect(oom_client.unusable);
    try std.testing.expectEqual(@as(usize, 0), oom_client.pending_catchup_barriers.items.len);
}

test "CR4a client demux는 socket flags를 success와 restore failure에서 exact 정산한다" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    const identity: catchup_barrier_contract.CatchupIdentity = .{
        .subscription = .{ .value = 61 },
        .runtime_id = 62,
        .connection = .{ .monotonic_id = 63, .slot_generation = 64 },
        .host_id = 65,
        .request_nonce = 66,
    };
    const barrier: catchup_barrier_contract.Barrier = .{
        .identity = identity,
        .target = .{ .generation = 2, .sequence = 3 },
    };
    inline for (.{ false, true }) |fail_restore| {
        var fds: [2]c.fd_t = undefined;
        try std.testing.expectEqual(
            @as(c_int, 0),
            c.socketpair(posix.AF.UNIX, posix.SOCK.STREAM, 0, &fds),
        );
        defer _ = c.close(fds[1]);
        var client = makeConnectedTestClient(allocator, fds[0]);
        client.runtime_catchup_barrier_v1 = true;
        defer client.deinit();
        try client.pending_catchup_barriers.append(allocator, .{
            .stream_id = 7,
            .barrier = barrier,
        });
        const flags_before = c.fcntl(fds[0], c.F.GETFL, @as(c_int, 0));
        try std.testing.expect(flags_before >= 0);
        var fixture = ConnectedSocketFixture{
            .fd = fds[0],
            .clock_now_ns = 1,
            .fail_restore_flags = fail_restore,
        };
        const deadline = client_deadline.AbsoluteDeadline.fromInjected(
            .{ .context = &fixture, .now_ns = ConnectedSocketFixture.clock },
            100,
        );
        if (fail_restore) {
            try std.testing.expectError(
                error.ConnectionClosed,
                client.readCatchupBarrierUntilWithOps(7, identity, deadline, fixture.ops()),
            );
            try std.testing.expect(client.unusable);
            try std.testing.expectEqual(@as(usize, 1), fixture.close_calls);
        } else {
            try std.testing.expectEqualDeep(
                barrier,
                try client.readCatchupBarrierUntilWithOps(7, identity, deadline, fixture.ops()),
            );
            try std.testing.expectEqual(
                flags_before,
                c.fcntl(fds[0], c.F.GETFL, @as(c_int, 0)),
            );
            try std.testing.expect(!client.unusable);
        }
        try std.testing.expectEqual(@as(usize, 1), fixture.get_flags_calls);
        try std.testing.expectEqual(@as(usize, 2), fixture.set_flags_calls);
    }
}

test "CR4a client demux는 blocking RPC 중 barrier를 canonical inbox에 보존한다" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    var fds: [2]c.fd_t = undefined;
    try std.testing.expectEqual(@as(c_int, 0), c.socketpair(posix.AF.UNIX, posix.SOCK.STREAM, 0, &fds));
    defer _ = c.close(fds[1]);
    var client = makeConnectedTestClient(allocator, fds[0]);
    client.runtime_catchup_barrier_v1 = true;
    defer client.deinit();
    const identity: catchup_barrier_contract.CatchupIdentity = .{
        .subscription = .{ .value = 41 },
        .runtime_id = 42,
        .connection = .{ .monotonic_id = 43, .slot_generation = 44 },
        .host_id = 45,
        .request_nonce = 46,
    };
    const barrier: catchup_barrier_contract.Barrier = .{
        .identity = identity,
        .target = .{ .generation = 5, .sequence = 9 },
    };
    const payload = try barrier.encode();
    const barrier_wire = try framing.encodeFrame(
        allocator,
        .{ .kind = .screen_frontier_barrier, .stream_id = 7 },
        &payload,
    );
    defer allocator.free(barrier_wire);
    const screen_before_wire = try framing.encodeFrame(
        allocator,
        .{ .kind = .delta_chunk, .stream_id = 7, .flags = protocol.Flags.end_stream },
        "screen-before-barrier",
    );
    defer allocator.free(screen_before_wire);
    const screen_after_wire = try framing.encodeFrame(
        allocator,
        .{ .kind = .delta_chunk, .stream_id = 7, .flags = protocol.Flags.end_stream },
        "screen-after-barrier",
    );
    defer allocator.free(screen_after_wire);
    const response_wire = try framing.encodeFrame(
        allocator,
        .{ .kind = .response, .request_id = 1 },
        "{\"result\":{}}",
    );
    defer allocator.free(response_wire);
    try socket_server.writeAll(fds[1], screen_before_wire);
    try socket_server.writeAll(fds[1], barrier_wire);
    try socket_server.writeAll(fds[1], screen_after_wire);
    try socket_server.writeAll(fds[1], response_wire);
    const response = try client.call("host.info", "{}");
    defer allocator.free(response);
    try std.testing.expectEqualStrings("{\"result\":{}}", response);
    try std.testing.expectEqual(@as(usize, 1), client.pending_catchup_barriers.items.len);
    const deadline = try client_deadline.AbsoluteDeadline.after(std.testing.io, std.time.ns_per_s);
    const plan = try client.readCatchupBarrierPlanUntil(7, identity, deadline);
    try std.testing.expectEqualDeep(barrier, plan.barrier);
    try std.testing.expectEqual(@as(u32, 1), plan.preceding_screen_batches);
    try std.testing.expectEqual(@as(usize, 2), client.pending_stream.items.len);
    const before = (try client.readStreamBatch(7)).?;
    defer before.deinit();
    try std.testing.expectEqualStrings("screen-before-barrier", before.bytes);
    const after = (try client.readStreamBatch(7)).?;
    defer after.deinit();
    try std.testing.expectEqualStrings("screen-after-barrier", after.bytes);
    try std.testing.expectEqual(@as(usize, 0), client.pending_catchup_barriers.items.len);
}

test "CR4a client demux는 partial barrier를 단일 absolute deadline에서 fail close한다" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    const allocator = std.testing.allocator;
    var fds: [2]c.fd_t = undefined;
    try std.testing.expectEqual(@as(c_int, 0), c.socketpair(posix.AF.UNIX, posix.SOCK.STREAM, 0, &fds));
    defer _ = c.close(fds[1]);
    var client = makeConnectedTestClient(allocator, fds[0]);
    client.runtime_catchup_barrier_v1 = true;
    defer client.deinit();
    const identity: catchup_barrier_contract.CatchupIdentity = .{
        .subscription = .{ .value = 41 },
        .runtime_id = 42,
        .connection = .{ .monotonic_id = 43, .slot_generation = 44 },
        .host_id = 45,
        .request_nonce = 46,
    };
    const barrier: catchup_barrier_contract.Barrier = .{
        .identity = identity,
        .target = .{ .generation = 5, .sequence = 9 },
    };
    const payload = try barrier.encode();
    const wire = try framing.encodeFrame(
        allocator,
        .{ .kind = .screen_frontier_barrier, .stream_id = 7 },
        &payload,
    );
    defer allocator.free(wire);
    try socket_server.writeAll(fds[1], wire[0..1]);
    const deadline = try client_deadline.AbsoluteDeadline.after(
        std.testing.io,
        10 * std.time.ns_per_ms,
    );
    try std.testing.expectError(
        error.DeadlineExceeded,
        client.readCatchupBarrierUntil(7, identity, deadline),
    );
    try std.testing.expect(client.unusable);
    try std.testing.expectEqual(@as(c.fd_t, -1), client.fd);
    try std.testing.expectEqual(@as(usize, 0), client.pending_catchup_barriers.items.len);

    var buffered_fds: [2]c.fd_t = undefined;
    try std.testing.expectEqual(
        @as(c_int, 0),
        c.socketpair(posix.AF.UNIX, posix.SOCK.STREAM, 0, &buffered_fds),
    );
    defer _ = c.close(buffered_fds[1]);
    var buffered_client = makeConnectedTestClient(allocator, buffered_fds[0]);
    buffered_client.runtime_catchup_barrier_v1 = true;
    defer buffered_client.deinit();
    try buffered_client.pending_catchup_barriers.append(allocator, .{
        .stream_id = 7,
        .barrier = barrier,
    });
    const ClockState = struct {
        now_ns: i128,

        fn now(context: *anyopaque) i128 {
            const self: *@This() = @ptrCast(@alignCast(context));
            return self.now_ns;
        }
    };
    var clock = ClockState{ .now_ns = 20 };
    const expired = client_deadline.AbsoluteDeadline.fromInjected(
        .{ .context = &clock, .now_ns = ClockState.now },
        20,
    );
    try std.testing.expectError(
        error.DeadlineExceeded,
        buffered_client.readCatchupBarrierUntil(7, identity, expired),
    );
    try std.testing.expect(buffered_client.unusable);
    try std.testing.expectEqual(@as(c.fd_t, -1), buffered_client.fd);
    try std.testing.expectError(
        error.ConnectionClosed,
        buffered_client.readCatchupBarrierUntil(7, identity, expired),
    );
}

