}

const PreparedRpcReentrantFreeAllocator = struct {
    parent: std.mem.Allocator,
    client: ?*Client = null,
    prepared: ?*PreparedBlockingRpc = null,
    armed: bool = false,
    reentered: bool = false,
    free_calls: usize = 0,
    reentry_error: ?PreparedBlockingRpcError = null,

    fn allocator(self: *@This()) std.mem.Allocator {
        return .{ .ptr = self, .vtable = &.{
            .alloc = alloc,
            .resize = resize,
            .remap = remap,
            .free = free,
        } };
    }

    fn alloc(ctx: *anyopaque, len: usize, alignment: std.mem.Alignment, ret_addr: usize) ?[*]u8 {
        const self: *@This() = @ptrCast(@alignCast(ctx));
        return self.parent.vtable.alloc(self.parent.ptr, len, alignment, ret_addr);
    }

    fn resize(ctx: *anyopaque, memory: []u8, alignment: std.mem.Alignment, new_len: usize, ret_addr: usize) bool {
        const self: *@This() = @ptrCast(@alignCast(ctx));
        return self.parent.vtable.resize(self.parent.ptr, memory, alignment, new_len, ret_addr);
    }

    fn remap(ctx: *anyopaque, memory: []u8, alignment: std.mem.Alignment, new_len: usize, ret_addr: usize) ?[*]u8 {
        const self: *@This() = @ptrCast(@alignCast(ctx));
        return self.parent.vtable.remap(self.parent.ptr, memory, alignment, new_len, ret_addr);
    }

    fn free(ctx: *anyopaque, memory: []u8, alignment: std.mem.Alignment, ret_addr: usize) void {
        const self: *@This() = @ptrCast(@alignCast(ctx));
        self.free_calls += 1;
        if (self.armed and !self.reentered) {
            self.reentered = true;
            self.client.?.abortPreparedBlockingRpc(self.prepared.?) catch |err| {
                self.reentry_error = err;
            };
        }
        self.parent.vtable.free(self.parent.ptr, memory, alignment, ret_addr);
    }
};

const PreparedRpcAllocatorDriftProbe = struct {
    parent: std.mem.Allocator,
    client: ?*Client = null,
    replacement: std.mem.Allocator,
    armed: bool = false,
    drifted: bool = false,
    pending_was_null_during_free: bool = false,
    execution_lease: ?*PreparedRequestExecutionLease = null,
    finish_error: ?PreparedBlockingRpcError = null,

    fn allocator(self: *@This()) std.mem.Allocator {
        return .{ .ptr = self, .vtable = &.{
            .alloc = alloc,
            .resize = resize,
            .remap = remap,
            .free = free,
        } };
    }

    fn alloc(ctx: *anyopaque, len: usize, alignment: std.mem.Alignment, ret_addr: usize) ?[*]u8 {
        const self: *@This() = @ptrCast(@alignCast(ctx));
        return self.parent.vtable.alloc(self.parent.ptr, len, alignment, ret_addr);
    }

    fn resize(ctx: *anyopaque, memory: []u8, alignment: std.mem.Alignment, new_len: usize, ret_addr: usize) bool {
        const self: *@This() = @ptrCast(@alignCast(ctx));
        return self.parent.vtable.resize(self.parent.ptr, memory, alignment, new_len, ret_addr);
    }

    fn remap(ctx: *anyopaque, memory: []u8, alignment: std.mem.Alignment, new_len: usize, ret_addr: usize) ?[*]u8 {
        const self: *@This() = @ptrCast(@alignCast(ctx));
        return self.parent.vtable.remap(self.parent.ptr, memory, alignment, new_len, ret_addr);
    }

    fn free(ctx: *anyopaque, memory: []u8, alignment: std.mem.Alignment, ret_addr: usize) void {
        const self: *@This() = @ptrCast(@alignCast(ctx));
        if (self.armed and !self.drifted) {
            self.drifted = true;
            self.pending_was_null_during_free = self.client.?.pending_outbound == null;
            if (self.execution_lease) |lease|
                self.client.?.finishPreparedRequestExecution(lease) catch |err| {
                    self.finish_error = err;
                };
            self.client.?.allocator = self.replacement;
        }
        self.parent.vtable.free(self.parent.ptr, memory, alignment, ret_addr);
    }
};

const PreparedExecutionWriteProbe = struct {
    results: []const PreparedExecutionWriteResult,
    index: usize = 0,
    calls: usize = 0,
    requested_lengths: [8]usize = [_]usize{0} ** 8,
    requested_ptrs: [8]usize = [_]usize{0} ** 8,

    fn ops(self: *@This()) PreparedExecutionWriteOps {
        return .{ .context = self, .writeFn = write };
    }

    fn write(ctx: ?*anyopaque, _: c.fd_t, bytes: []const u8) PreparedExecutionWriteResult {
        const self: *@This() = @ptrCast(@alignCast(ctx.?));
        if (self.calls < self.requested_lengths.len) {
            self.requested_lengths[self.calls] = bytes.len;
            self.requested_ptrs[self.calls] = @intFromPtr(bytes.ptr);
        }
        self.calls += 1;
        if (self.index >= self.results.len) return .failed;
        const result = self.results[self.index];
        self.index += 1;
        return switch (result) {
            .written => |count| if (count <= bytes.len) result else .{ .written = count },
            else => result,
        };
    }
};

const CrossClientOobReentryAllocator = struct {
    parent: std.mem.Allocator,
    foreign: ?*Client = null,
    foreign_storage: ?*PreparedBlockingRpcStorage = null,
    armed: bool = false,
    reentered: bool = false,
    reentry_error: ?PreparedBlockingRpcError = null,

    fn allocator(self: *@This()) std.mem.Allocator {
        return .{ .ptr = self, .vtable = &.{
            .alloc = alloc,
            .resize = resize,
            .remap = remap,
            .free = free,
        } };
    }

    fn alloc(ctx: *anyopaque, len: usize, alignment: std.mem.Alignment, ret_addr: usize) ?[*]u8 {
        const self: *@This() = @ptrCast(@alignCast(ctx));
        if (self.armed and !self.reentered) {
            self.reentered = true;
            _ = self.foreign.?.prepareBlockingRpcStorage(
                self.foreign_storage.?,
                "host.info",
                null,
            ) catch |err| {
                self.reentry_error = err;
            };
        }
        return self.parent.vtable.alloc(self.parent.ptr, len, alignment, ret_addr);
    }

    fn resize(ctx: *anyopaque, memory: []u8, alignment: std.mem.Alignment, new_len: usize, ret_addr: usize) bool {
        const self: *@This() = @ptrCast(@alignCast(ctx));
        return self.parent.vtable.resize(self.parent.ptr, memory, alignment, new_len, ret_addr);
    }

    fn remap(ctx: *anyopaque, memory: []u8, alignment: std.mem.Alignment, new_len: usize, ret_addr: usize) ?[*]u8 {
        const self: *@This() = @ptrCast(@alignCast(ctx));
        return self.parent.vtable.remap(self.parent.ptr, memory, alignment, new_len, ret_addr);
    }

    fn free(ctx: *anyopaque, memory: []u8, alignment: std.mem.Alignment, ret_addr: usize) void {
        const self: *@This() = @ptrCast(@alignCast(ctx));
        self.parent.vtable.free(self.parent.ptr, memory, alignment, ret_addr);
    }
};

