    defer _ = c.close(fds[1]);
    socket_server.setNoSigPipe(fds[0]);
    var client: Client = .{
        .allocator = allocator,
        .fd = fds[0],
        .host_id = 0xB346,
        .parser = framing.FrameParser.init(allocator),
    };
