    while (raw <= std.math.maxInt(u8)) : (raw += 1) {
        storage = .{};
        @as(*u8, @ptrCast(&prepared.lifecycle)).* = @intCast(raw);
        const valid = raw == @intFromEnum(PreparedBlockingRpcLifecycle.pristine) or
            raw == @intFromEnum(PreparedBlockingRpcLifecycle.terminal);
