    );
    try std.testing.expect(client.unusable);
    try std.testing.expectEqual(@as(c.fd_t, -1), client.fd);
    try std.testing.expectEqual(
        client_poison.ConnectionReason.read_timeout,
        client.firstPoisonReason().?,
    );
}

