    try client.bufferLegacyEventForTest(.{
        .header = .{ .kind = .event, .stream_id = 7 },
        .payload = try allocator.dupe(u8, admitted),
    });
    try std.testing.expectError(error.ProtocolError, client.bufferLegacyEventForTest(.{
        .header = .{ .kind = .event, .stream_id = 7 },
        .payload = try allocator.dupe(u8, conflict),
    }));
    try std.testing.expect(client.unusable);
    try std.testing.expectEqual(@as(usize, 1), client.pending_events.items.len);
    try std.testing.expectEqualStrings(admitted, client.pending_events.items[0].payload);
}

test "client fails closed when one stream receives resize events for different runtimes" {
    const allocator = std.testing.allocator;
    const runtime_a =
        \\{"event":"runtime.resized","data":{"runtime_id":"000000000000000000000000000000aa","cols":100,"rows":30,"resize_generation":4,"reason":"controller"}}
    ;
    const runtime_b =
        \\{"event":"runtime.resized","data":{"runtime_id":"000000000000000000000000000000bb","cols":120,"rows":40,"resize_generation":9,"reason":"controller"}}
    ;
    for ([_][2][]const u8{
        .{ runtime_a, runtime_b },
        .{ runtime_b, runtime_a },
    }) |order| {
        var client = Client{
            .allocator = allocator,
            .fd = -1,
            .host_id = 0,
            .parser = framing.FrameParser.init(allocator),
        };
        defer client.parser.deinit();
        defer {
            for (client.pending_events.items) |frame| frame.deinit(allocator);
            client.pending_events.deinit(allocator);
        }
        try client.bufferLegacyEventForTest(.{
            .header = .{ .kind = .event, .stream_id = 7 },
            .payload = try allocator.dupe(u8, order[0]),
        });
        try std.testing.expectError(error.ProtocolError, client.bufferLegacyEventForTest(.{
            .header = .{ .kind = .event, .stream_id = 7 },
            .payload = try allocator.dupe(u8, order[1]),
        }));
        try std.testing.expect(client.unusable);
        try std.testing.expectEqual(@as(usize, 1), client.pending_events.items.len);
        try std.testing.expectEqualStrings(order[0], client.pending_events.items[0].payload);
    }
}

test "client event queue overflow poisons every runtime sharing the connection" {
    const allocator = std.testing.allocator;
    var client = Client{
        .allocator = allocator,
        .fd = -1,
        .host_id = 0,
        .parser = framing.FrameParser.init(allocator),
    };
    defer client.parser.deinit();
    defer client.pending_stream.deinit(allocator);
    defer {
        for (client.pending_events.items) |frame| frame.deinit(allocator);
        client.pending_events.deinit(allocator);
    }
    defer client.pending_batches.deinit(allocator);

    for (0..max_pending_event_count) |i| {
        try client.bufferLegacyEventForTest(.{
            .header = .{ .kind = .event, .stream_id = @intCast(i + 1) },
            .payload = try allocator.dupe(u8, "{\"event\":\"other\"}"),
        });
    }
    const first_payload = client.pending_events.items[0].payload;
    try std.testing.expectError(error.EventQueueFull, client.bufferLegacyEventForTest(.{
        .header = .{ .kind = .event, .stream_id = max_pending_event_count + 1 },
        .payload = try allocator.dupe(u8, "{\"event\":\"overflow\"}"),
    }));
    try std.testing.expectEqual(max_pending_event_count, client.pending_events.items.len);
    try std.testing.expectEqualStrings("{\"event\":\"other\"}", first_payload);
    // Overflow frame은 stream 999였지만 어느 subscription base가 전진했는지 client가 증명할 수 없다. 기존 stream 1의
    // pending event도 적용하지 않고, stream 1/2 양쪽 pump와 input/RPC가 모두 동일 connection failure를 보게 한다.
    try std.testing.expect((try client.takeEventForStream(1)) == null);
    try std.testing.expectError(error.ConnectionClosed, client.readStreamBatch(1));
    try std.testing.expectError(error.ConnectionClosed, client.readStreamBatch(2));
    try std.testing.expectError(error.ConnectionClosed, client.sendInput(1, "x"));
    try std.testing.expectError(error.ConnectionClosed, client.call("host.info", null));
}

test "client ended event replaces same-stream metadata at exact event cap" {
    const allocator = std.testing.allocator;
    const metadata =
        \\{"event":"runtime.metadata","metadata_revision":1,"metadata":{"cwd":"/one","window_title":"one","ssh_remote_dest":null,
        \\"semantic_state":0,"alt_active":false,"app_cursor_keys":false,"alternate_scroll":true,"observer_generation":1,
        \\"title_generation":1,"cols":80,"rows":24,"foreground_available":false,"foreground_pgid":null,"processes":[]}}
    ;
    var client = Client{
        .allocator = allocator,
        .fd = -1,
        .host_id = 0,
        .metadata_support = .supported,
        .parser = framing.FrameParser.init(allocator),
    };
    defer client.parser.deinit();
    defer client.pending_stream.deinit(allocator);
    defer {
        for (client.pending_events.items) |frame| frame.deinit(allocator);
        client.pending_events.deinit(allocator);
    }
    defer client.pending_batches.deinit(allocator);

    for (0..256) |i| try client.bufferLegacyEventForTest(.{
        .header = .{ .kind = .event, .stream_id = @intCast(i + 1) },
        .payload = try allocator.dupe(u8, metadata),
    });
    try std.testing.expectEqual(@as(usize, 256), client.pending_events.items.len);
    try client.bufferLegacyEventForTest(.{
        .header = .{ .kind = .event, .stream_id = 1 },
        .payload = try allocator.dupe(u8, "{\"event\":\"runtime.ended\"}"),
