const TransferNormalizeMutationAllocator = struct {
    parent: std.mem.Allocator,
    target: ?*framing.FrameParser = null,
    armed: bool = false,
    mutated: bool = false,

    fn allocator(self: *TransferNormalizeMutationAllocator) std.mem.Allocator {
        return .{ .ptr = self, .vtable = &.{
            .alloc = alloc,
            .resize = resize,
            .remap = remap,
            .free = free,
        } };
    }

    fn alloc(
        context: *anyopaque,
        len: usize,
        alignment: std.mem.Alignment,
        ret_addr: usize,
    ) ?[*]u8 {
        const self: *TransferNormalizeMutationAllocator = @ptrCast(@alignCast(context));
        return self.parent.vtable.alloc(self.parent.ptr, len, alignment, ret_addr);
    }

    fn resize(
        context: *anyopaque,
        memory: []u8,
        alignment: std.mem.Alignment,
        new_len: usize,
        ret_addr: usize,
    ) bool {
        const self: *TransferNormalizeMutationAllocator = @ptrCast(@alignCast(context));
        return self.parent.vtable.resize(
            self.parent.ptr,
            memory,
            alignment,
            new_len,
            ret_addr,
        );
    }

    fn remap(
        context: *anyopaque,
        memory: []u8,
        alignment: std.mem.Alignment,
        new_len: usize,
        ret_addr: usize,
    ) ?[*]u8 {
        const self: *TransferNormalizeMutationAllocator = @ptrCast(@alignCast(context));
        return self.parent.vtable.remap(
            self.parent.ptr,
            memory,
            alignment,
            new_len,
            ret_addr,
        );
    }

    fn free(
        context: *anyopaque,
        memory: []u8,
        alignment: std.mem.Alignment,
        ret_addr: usize,
    ) void {
        const self: *TransferNormalizeMutationAllocator = @ptrCast(@alignCast(context));
        if (self.armed and !self.mutated) {
            self.mutated = true;
            self.target.?.expected_major +%= 1;
        }
        self.parent.vtable.free(self.parent.ptr, memory, alignment, ret_addr);
    }
};

const ProofForgedAllocator = struct {
    free_calls: usize = 0,

    fn allocator(self: *ProofForgedAllocator) std.mem.Allocator {
        return .{ .ptr = self, .vtable = &.{
            .alloc = alloc,
            .resize = resize,
            .remap = remap,
            .free = free,
        } };
    }

    fn alloc(_: *anyopaque, _: usize, _: std.mem.Alignment, _: usize) ?[*]u8 {
        return null;
    }

    fn resize(
        _: *anyopaque,
        _: []u8,
        _: std.mem.Alignment,
        _: usize,
        _: usize,
    ) bool {
        return false;
    }

    fn remap(
        _: *anyopaque,
        _: []u8,
        _: std.mem.Alignment,
        _: usize,
        _: usize,
    ) ?[*]u8 {
        return null;
    }

    fn free(
        context: *anyopaque,
        _: []u8,
        _: std.mem.Alignment,
        _: usize,
    ) void {
        const self: *ProofForgedAllocator = @ptrCast(@alignCast(context));
        self.free_calls += 1;
    }
};

const FreeCountingAllocator = struct {
    parent: std.mem.Allocator,
    alloc_calls: usize = 0,
    free_calls: usize = 0,
    mutate_on_free_a: ?*usize = null,
    mutate_on_free_b: ?*usize = null,
    mutate_allocator_on_free_a: ?*std.mem.Allocator = null,
    mutate_allocator_on_free_b: ?*std.mem.Allocator = null,
    mutation_allocator: ?std.mem.Allocator = null,
    mutation_value: usize = 0,
    mutation_fired: bool = false,

    fn allocator(self: *FreeCountingAllocator) std.mem.Allocator {
        return .{ .ptr = self, .vtable = &.{
            .alloc = alloc,
            .resize = resize,
            .remap = remap,
            .free = free,
        } };
    }

    fn alloc(
        context: *anyopaque,
        len: usize,
        alignment: std.mem.Alignment,
        ret_addr: usize,
    ) ?[*]u8 {
        const self: *FreeCountingAllocator = @ptrCast(@alignCast(context));
        self.alloc_calls += 1;
        return self.parent.vtable.alloc(
            self.parent.ptr,
            len,
            alignment,
            ret_addr,
        );
    }

    fn resize(
        context: *anyopaque,
        memory: []u8,
        alignment: std.mem.Alignment,
        new_len: usize,
        ret_addr: usize,
    ) bool {
        const self: *FreeCountingAllocator = @ptrCast(@alignCast(context));
        return self.parent.vtable.resize(
            self.parent.ptr,
            memory,
            alignment,
            new_len,
            ret_addr,
        );
    }

    fn remap(
        context: *anyopaque,
        memory: []u8,
        alignment: std.mem.Alignment,
        new_len: usize,
        ret_addr: usize,
    ) ?[*]u8 {
        const self: *FreeCountingAllocator = @ptrCast(@alignCast(context));
        return self.parent.vtable.remap(
            self.parent.ptr,
            memory,
            alignment,
            new_len,
            ret_addr,
        );
    }

    fn free(
        context: *anyopaque,
        memory: []u8,
        alignment: std.mem.Alignment,
        ret_addr: usize,
    ) void {
        const self: *FreeCountingAllocator = @ptrCast(@alignCast(context));
        self.free_calls += 1;
        if (!self.mutation_fired) {
            self.mutation_fired = true;
            if (self.mutate_on_free_a) |target|
                target.* = self.mutation_value;
            if (self.mutate_on_free_b) |target|
                target.* = self.mutation_value;
            if (self.mutate_allocator_on_free_a) |target|
                target.* = self.mutation_allocator.?;
            if (self.mutate_allocator_on_free_b) |target|
                target.* = self.mutation_allocator.?;
        }
        self.parent.vtable.free(
            self.parent.ptr,
            memory,
            alignment,
            ret_addr,
        );
    }
};

fn recvTimeout(fd: c.fd_t) !posix.timeval {
    var value = std.mem.zeroes(posix.timeval);
    var len: c.socklen_t = @sizeOf(posix.timeval);
    if (c.getsockopt(
        fd,
        c.SOL.SOCKET,
        c.SO.RCVTIMEO,
        &value,
        &len,
    ) != 0 or len != @sizeOf(posix.timeval)) return error.UnexpectedSocketOption;
    return value;
}

test "external owner proof cleanup trusts only sealed allocator and range mirrors" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;
    var fds: [2]c.fd_t = undefined;
    try std.testing.expectEqual(
        @as(c_int, 0),
        c.socketpair(posix.AF.UNIX, posix.SOCK.STREAM, 0, &fds),
    );
    defer _ = c.close(fds[1]);
    var client = makeConnectedTestClient(std.testing.allocator, fds[0]);
    defer client.deinit();
    try client.enterExternalMode();
    client.connection_profile = .cli_attach;
    client.compatibility_profile = compatibility.profileForMajor(protocol.version_major).?;
    var first_target: u8 = 0;
    var second_target: u8 = 0;

    var allocator_proof: PreparedExternalOwnerRangeProof = .{};
    try client.prepareExternalOwnerRangeProof(
        &allocator_proof,
        &first_target,
        @sizeOf(u8),
        &second_target,
        @sizeOf(u8),
    );
    const canonical_allocator = allocator_proof.allocator;
    var forged_allocator = ProofForgedAllocator{};
    allocator_proof.allocator = forged_allocator.allocator();
    allocator_proof.cleanup_allocator = allocator_proof.allocator;
    allocator_proof.deinit();
    try std.testing.expectEqual(@as(usize, 0), forged_allocator.free_calls);
    try std.testing.expectEqual(
        ExternalOwnerRangeProofLifecycle.prepared,
        allocator_proof.lifecycle,
    );
    allocator_proof.cleanup_allocator = canonical_allocator;
    allocator_proof.deinit();
    try std.testing.expectEqual(
        ExternalOwnerRangeProofLifecycle.aborted,
        allocator_proof.lifecycle,
    );
    allocator_proof.deinit();

    var range_proof: PreparedExternalOwnerRangeProof = .{};
    try client.prepareExternalOwnerRangeProof(
        &range_proof,
        &first_target,
        @sizeOf(u8),
        &second_target,
        @sizeOf(u8),
    );
    const canonical_ranges = range_proof.ranges;
    const forged_ranges = try std.testing.allocator.alloc(
        ExternalRange,
        canonical_ranges.len,
    );
    defer std.testing.allocator.free(forged_ranges);
    range_proof.ranges = forged_ranges;
    range_proof.cleanup_ranges = forged_ranges;
    range_proof.deinit();
    try std.testing.expectEqual(
        ExternalOwnerRangeProofLifecycle.prepared,
        range_proof.lifecycle,
    );
    range_proof.cleanup_ranges = canonical_ranges;
    range_proof.deinit();
    try std.testing.expectEqual(
        ExternalOwnerRangeProofLifecycle.aborted,
        range_proof.lifecycle,
    );
    range_proof.deinit();
}

test "external mode prechecks perform no allocation or fd inspection" {
    if (builtin.os.tag != .macos) return error.SkipZigTest;

    var unusable = makeConnectedTestClient(std.testing.allocator, -1);
    defer unusable.deinit();
    unusable.poison(.local_invariant_violation);
    var unusable_fixture = ConnectedSocketFixture{ .fd = -1 };
    try std.testing.expectError(
        error.ConnectionClosed,
        unusable.enterExternalModeWithOps(unusable_fixture.ops()),
    );
    try std.testing.expectEqual(@as(usize, 0), unusable_fixture.get_flags_calls);
    try std.testing.expectEqual(@as(usize, 0), unusable_fixture.set_flags_calls);

    var fds: [2]c.fd_t = undefined;
    try std.testing.expectEqual(
        @as(c_int, 0),
        c.socketpair(posix.AF.UNIX, posix.SOCK.STREAM, 0, &fds),
    );
    defer _ = c.close(fds[1]);
    var external = makeConnectedTestClient(std.testing.allocator, fds[0]);
    defer external.deinit();
    var external_fixture = ConnectedSocketFixture{ .fd = fds[0] };
    try external.enterExternalModeWithOps(external_fixture.ops());
    external_fixture.get_flags_calls = 0;
    external_fixture.set_flags_calls = 0;
    try std.testing.expectError(
        error.AlreadyExternal,
        external.enterExternalModeWithOps(external_fixture.ops()),
    );
    try std.testing.expectEqual(@as(usize, 0), external_fixture.get_flags_calls);
    try std.testing.expectEqual(@as(usize, 0), external_fixture.set_flags_calls);

    var failing = testing.FailingAllocator.init(std.testing.allocator, .{});
    const allocator = failing.allocator();
    var busy = makeConnectedTestClient(allocator, -1);
    defer busy.deinit();
    busy.pending_outbound = .{
        .frame = try allocator.dupe(u8, "pending"),
        .stream_id = 7,
    };
    failing.fail_index = failing.alloc_index;
    var busy_fixture = ConnectedSocketFixture{ .fd = -1 };
    try std.testing.expectError(
        error.Busy,
        busy.enterExternalModeWithOps(busy_fixture.ops()),
    );
    try std.testing.expect(!failing.has_induced_failure);
    try std.testing.expectEqual(@as(usize, 0), busy_fixture.get_flags_calls);
    try std.testing.expectEqual(@as(usize, 0), busy_fixture.set_flags_calls);
    busy.pending_outbound.?.offset = 1;
    try std.testing.expectError(
        error.Busy,
        busy.enterExternalModeWithOps(busy_fixture.ops()),
    );
    try std.testing.expect(!failing.has_induced_failure);
}

